#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_AIN0 0x4000  // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0200 // ±4.096V range
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the ADS1115
int ads1115_init() {
    // Construct the configuration register value
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t ads1115_read_adc() {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

// Function to convert the ADC value to amperes
float convert_to_amperes(int16_t adc_value) {
    // Sensitivity of the MLX91219 sensor (example value, check datasheet)
    float sensitivity = 0.04; // 40mV/A

    // Full-scale range of the ADS1115 (±4.096V)
    float full_scale_range = 4.096;

    // Number of ADC counts
    int16_t num_counts = 32768; // 2^15 for 16-bit ADC

    // Calculate the current in amperes
    float current = (float)adc_value / num_counts * full_scale_range / sensitivity;

    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the ADS1115
    if (ads1115_init() != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the ADC value
        int16_t adc_value = ads1115_read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break; // Exit loop on error
        }

        // Convert the ADC value to amperes
        float current = convert_to_amperes(adc_value);

        // Log the current value
        printf("Current: %.3f A\n", current);

        // Wait for 500ms
        gpioDelay(500000); // 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

