#include <string.h>

// Define constants
#define FLAME_SENSOR_PIN 4  // BCM GPIO 4
#define BUZZER_PIN 27       // BCM GPIO 27
#define ADS1115_ADDRESS 0x48 // I2C address of ADS1115
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_GAIN 2        // +/- 6.144V
#define ADS1115_PGA_CONFIG 0x00 // +/- 4.096V
#define ADS1115_MODE_SINGLE 0x01 // Single-shot mode
#define ADS1115_DR_128SPS 0x80  // 128 SPS
#define FIRE_THRESHOLD_TEMP 60.0 // Temperature threshold in Celsius
#define FIRE_THRESHOLD_FLAME 0   // Flame sensor output (LOW = detected)
#define DEBOUNCE_DELAY 50       // Debounce delay in milliseconds
#define LOG_FILE "fire_log.txt"

// Global variables
static volatile bool running = true;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
int init_wiringPi();
int init_i2c(int address);
int config_ads1115();
int read_flame_sensor();
int read_temperature();
float convert_to_celsius(int raw_value);
void activate_buzzer(int duration_ms);
void log_fire_event(const char *message);
void signal_handler(int signal);

// Function to initialize wiringPi
int init_wiringPi() {
  if (wiringPiSetupGpio() == -1) {
    fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
    return -1;
  }
  pinMode(FLAME_SENSOR_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW); // Ensure buzzer is off initially
  return 0;
}

// Function to initialize I2C
int init_i2c(int address) {
  int fd = wiringPiI2CSetup(address);
  if (fd == -1) {
    fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
    return -1;
  }
  return fd;
}

// Function to configure the ADS1115
int config_ads1115() {
  int config = (ADS1115_MODE_SINGLE << 15) | (ADS1115_DR_128SPS << 12) | (ADS1115_PGA_CONFIG << 9) | (ADS1115_GAIN << 12);
  if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_CONFIG_REG, config) == -1) {
    fprintf(stderr, "Error writing to ADS1115 config register: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
  int value = digitalRead(FLAME_SENSOR_PIN);
  delay(DEBOUNCE_DELAY);
  return value;
}

// Function to read the temperature from the ADS1115
int read_temperature() {
  int raw_value = wiringPiI2CReadReg16(i2c_fd, ADS1115_CONVERSION_REG);
  if (raw_value == -1) {
    fprintf(stderr, "Error reading from ADS1115 conversion register: %s\n", strerror(errno));
    return -1;
  }
  // The ADS1115 returns the value in big-endian format, so we need to swap the bytes
  raw_value = (raw_value << 8) | (raw_value >> 8);
  return raw_value;
}

// Function to convert the raw ADC value to Celsius
float convert_to_celsius(int raw_value) {
  // Assuming a linear relationship between ADC value and temperature
  // You'll need to calibrate this based on your specific LM393 and thermistor setup
  // This is a placeholder conversion
  float voltage = (float)raw_value * 4.096 / 32768.0; // Assuming +/- 4.096V range
  float temperature = (voltage - 0.5) * 100.0; // Example conversion (adjust as needed)
  return temperature;
}

// Function to activate the buzzer
void activate_buzzer(int duration_ms) {
  digitalWrite(BUZZER_PIN, HIGH);
  delay(duration_ms);
  digitalWrite(BUZZER_PIN, LOW);
}

// Function to log fire events to a file
void log_fire_event(const char *message) {
  time_t t = time(NULL);
  struct tm tm = *localtime(&t);
  fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
  fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
  running = false;
  printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
  // Set up signal handling
  signal(SIGINT, signal_handler);

  // Initialize wiringPi
  if (init_wiringPi() == -1) {
    return 1;
  }

  // Initialize I2C
  i2c_fd = init_i2c(ADS1115_ADDRESS);
  if (i2c_fd == -1) {
    return 1;
  }

  // Configure ADS1115
  if (config_ads1115() == -1) {
    return 1;
  }

  // Open the log file
  log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    return 1;
  }

  printf("Fire detection system started. Press Ctrl+C to exit.\n");

  // Main loop
  while (running) {
    // Read sensor values
    int flame_detected = (read_flame_sensor() == 0); // LOW indicates flame
    int raw_temp = read_temperature();
    float temperature = 0.0;

    if (raw_temp != -1) {
      temperature = convert_to_celsius(raw_temp);
    }

    // Check for fire condition
    if (flame_detected && (raw_temp != -1 && temperature > FIRE_THRESHOLD_TEMP)) {
      log_fire_event("Fire detected!");
      activate_buzzer(2000); // Activate buzzer for 2 seconds
    } else if (flame_detected) {
      log_fire_event("Flame detected!");
    } else if (raw_temp != -1 && temperature > FIRE_THRESHOLD_TEMP) {
      char temp_str[50];
      snprintf(temp_str, sizeof(temp_str), "Temperature: %.2f °C", temperature);
      log_fire_event(temp_str);
    }

    delay(100); // Poll every 100 ms
  }

  // Cleanup
  digitalWrite(BUZZER_PIN, LOW); // Turn off buzzer
  fclose(log_file);
  close(i2c_fd);
  printf("Exiting.\n");
  return 0;
}

