#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 5.0 // Amperes
#define SENSOR_PRESENT_MIN 100
#define SENSOR_PRESENT_MAX 900
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_adc(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void control_fan(float current);
void signal_handler(int signal);

// SPI Initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// ADC Reading function
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Current Conversion function
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // You'll need to calibrate this based on your sensor's datasheet
    // Example: 0 ADC = 0A, 1023 ADC = 10A
    float current = (float)adc_value * 10.0 / 1023.0;
    return current;
}

// Logging function
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fan Control function
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Check for sensor present condition
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or invalid reading\n");
            log_current(-1.0); // Log -1.0 to indicate sensor issue
        } else {
            float current = adc_to_current(adc_value);
            log_current(current);
            control_fan(current);
            printf("Current: %.2f A\n", current);
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    fclose(log_file);
    close(spi_fd);
    gpioTerminate();

    return 0;
}

