// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE0 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000

// Define temperature sensor parameters
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1024.0
#define ADC_VREF 3.3
#define TEMPERATURE_OFFSET 0.0
#define TEMPERATURE_SCALE 10.0

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
void log_data(int flame_present, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CE0, 0); // Assert chip select
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CE0, 1); // De-assert chip select

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    float voltage = (adc_value / ADC_RESOLUTION) * ADC_VREF;
    float temperature = (voltage - TEMPERATURE_OFFSET) / TEMPERATURE_SCALE;
    return temperature;
}

// Function to log data to a CSV file
void log_data(int flame_present, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_present, temperature);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CE0, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open flame_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,FlamePresent,TemperatureC\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_present = read_flame_sensor();

        // Read temperature sensor
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip logging this iteration
        }

        float temperature = convert_adc_to_temperature(adc_value);

        // Log data
        log_data(flame_present, temperature);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();
    fclose(fp);

    return 0;
}

