#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define CO_THRESHOLD 25.0
#define LOG_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *co_log_file = NULL;
FILE *alert_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t ox;
    uint16_t red;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
float convert_ox_to_ppm(uint16_t ox);
void log_co_data(float co_ppm);
void log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-4514
sensor_data_t read_sensor_data() {
    char buf[4];
    sensor_data_t data;
    int result = i2cReadDevice(i2c_handle, buf, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.ox = 0; // Indicate error
        data.red = 0;
        return data;
    }

    data.ox = (buf[0] << 8) | buf[1];
    data.red = (buf[2] << 8) | buf[3];

    return data;
}

// Convert OX value to CO concentration in ppm (example calibration)
float convert_ox_to_ppm(uint16_t ox) {
    // This is a placeholder.  A real implementation would use
    // calibration data from the sensor's datasheet.
    // Example linear conversion (replace with actual calibration):
    return (float)ox * 0.01; // Example: 1 unit of OX = 0.01 ppm CO
}

// Log CO data to file
void log_co_data(float co_ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (co_log_file != NULL) {
        fprintf(co_log_file, "%s, %.2f ppm\n", timestamp, co_ppm);
        fflush(co_log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: CO log file not opened.\n");
    }
}

// Log alert to file
void log_alert(float co_ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (alert_log_file != NULL) {
        fprintf(alert_log_file, "%s, ALERT: CO concentration exceeded threshold (%.2f ppm > %.2f ppm)\n", timestamp, co_ppm, CO_THRESHOLD);
        fflush(alert_log_file);
    } else {
        fprintf(stderr, "Error: Alert log file not opened.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (co_log_file != NULL) {
        fclose(co_log_file);
    }
    if (alert_log_file != NULL) {
        fclose(alert_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log files
    co_log_file = fopen("co_log.txt", "a");
    if (co_log_file == NULL) {
        fprintf(stderr, "Error opening co_log.txt\n");
        cleanup();
        return 1;
    }

    alert_log_file = fopen("alert_log.txt", "a");
    if (alert_log_file == NULL) {
        fprintf(stderr, "Error opening alert_log.txt\n");
        cleanup();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data();

        if (sensor_data.ox != 0 && sensor_data.red != 0) {
            float co_ppm = convert_ox_to_ppm(sensor_data.ox);
            log_co_data(co_ppm);

            if (co_ppm >= CO_THRESHOLD) {
                log_alert(co_ppm);
            }
        } else {
            fprintf(stderr, "Error: Invalid sensor data. Skipping logging.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, LOG_INTERVAL, 0); // Sleep for LOG_INTERVAL seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

