#define MIC1_ADDR 0x68
#define MIC2_ADDR 0x69

// Define the number of bytes to read from each microphone
#define NUM_BYTES 2

// Define the log file name
#define LOG_FILE "audio_log.txt"

// Global variables for I2C handles and program state
int mic1_handle = -1;
int mic2_handle = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold microphone data
typedef struct {
    int handle;
    int address;
} microphone_t;

// Function prototypes
int i2c_setup(int bus, int addr);
int i2c_read_bytes(int handle, char *buf, int count);
int i2c_close(int handle);
float convert_to_db(int raw_value);
float calculate_average(float db1, float db2);
void log_data(float average_db);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// I2C read bytes function
int i2c_read_bytes(int handle, char *buf, int count) {
