    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return result;
}

// I2C close function
int i2c_close(int handle) {
    int result = i2cClose(handle);
    if (result < 0) {
        fprintf(stderr, "Error closing I2C device: %d\n", result);
        return -1;
    }
    return result;
}

// Convert raw value to dB (example formula, adjust as needed)
float convert_to_db(int raw_value) {
    // This is a placeholder.  You'll need to calibrate
    // the microphones and determine the appropriate formula.
    // The IMP23ABSU outputs a voltage proportional to the
    // sound pressure level.  You'll need to convert this
    // voltage to a dB SPL value.
    // Example: db = 20 * log10(voltage / reference_voltage)
    // where reference_voltage is a known voltage corresponding to 0 dB.
    // Assuming raw_value is a voltage reading, this is a simplified example.
    return (float)raw_value * 0.1; // Example conversion
}

// Calculate the average dB level
float calculate_average(float db1, float db2) {
    return (db1 + db2) / 2.0;
}

