    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C for both microphones
    mic1_handle = i2c_setup(1, MIC1_ADDR);
    if (mic1_handle < 0) {
        gpioTerminate();
        return 1;
    }

    mic2_handle = i2c_setup(1, MIC2_ADDR);
    if (mic2_handle < 0) {
        i2c_close(mic1_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        char buf1[NUM_BYTES];
        char buf2[NUM_BYTES];
        int raw_value1, raw_value2;
        float db1, db2, average_db;

        // Read data from microphone 1
        if (i2c_read_bytes(mic1_handle, buf1, NUM_BYTES) == NUM_BYTES) {
            raw_value1 = (buf1[0] << 8) | buf1[1]; // Assuming 16-bit data
            db1 = convert_to_db(raw_value1);
        } else {
            db1 = -999.0; // Log error value
        }

        // Read data from microphone 2
        if (i2c_read_bytes(mic2_handle, buf2, NUM_BYTES) == NUM_BYTES) {
            raw_value2 = (buf2[0] << 8) | buf2[1]; // Assuming 16-bit data
            db2 = convert_to_db(raw_value2);
        } else {
            db2 = -999.0; // Log error value
        }

        // Calculate average dB level
        average_db = calculate_average(db1, db2);

        // Log data
        log_data(average_db);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C handles
    i2c_close(mic1_handle);
    i2c_close(mic2_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

