#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 27
#define SPI_CE0 8
#define SPI_CE1 9
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define sampling window
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_RATE_MS 1

// Define number of samples per channel
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_RATE_MS)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
} MicrophoneData;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_adc(int channel);
double calculate_rms(int *samples, int num_samples);
int log_data(double mic1_rms, double mic2_rms);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_CE1, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(SPI_CE0, 0); // Select the MCP3008
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(SPI_CE0, 1); // Deselect the MCP3008

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Calculate RMS level
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Log data to file
int log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    MicrophoneData data;

    printf("Sampling audio... Press Ctrl+C to stop.\n");

    while (!terminate) {
        // Read ADC values
        data.mic1_samples[SAMPLE_RATE_MS / SAMPLE_RATE_MS] = read_adc(0);
        data.mic2_samples[SAMPLE_RATE_MS / SAMPLE_RATE_MS] = read_adc(1);

        // Calculate RMS levels
        double mic1_rms = calculate_rms(data.mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(data.mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Control LED based on RMS threshold
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(500);   // Wait 500ms
            control_led(0); // Turn off LED
        }

        gpioDelay(SAMPLE_RATE_MS); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

