    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Log data to file
int log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    MicrophoneData data;

    printf("Sampling audio... Press Ctrl+C to stop.\n");

    while (!terminate) {
        // Read ADC values
        data.mic1_samples[SAMPLE_RATE_MS / SAMPLE_RATE_MS] = read_adc(0);
        data.mic2_samples[SAMPLE_RATE_MS / SAMPLE_RATE_MS] = read_adc(1);

        // Calculate RMS levels
        double mic1_rms = calculate_rms(data.mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(data.mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Control LED based on RMS threshold
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(500);   // Wait 500ms
            control_led(0); // Turn off LED
        }

        gpioDelay(SAMPLE_RATE_MS); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

