#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Configuration
#define I2C_ADDR 0x48
#define I2C_BUS 1
#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define CURRENT_THRESHOLD 50.0
#define ADC_CONFIG_REG 0x01
#define ADC_CONFIG_VALUE 0xC203 // Single-ended A0, +/-4.096V, Continuous mode, 128 SPS
#define ADC_DATA_REG 0x00

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_adc(int fd);
float convert_to_current(int adc_value);
void update_buffer(float current);
float calculate_average();
void control_led(float average_current);
void signal_handler(int signal);

// Initialize I2C
int init_i2c(int bus, int addr) {
    int fd = wiringPiI2CSetup(addr);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Read ADC value
int read_adc(int fd) {
    int16_t adc_value;

    // Write configuration register
    if (wiringPiI2CWriteReg16(fd, ADC_CONFIG_REG, ADC_CONFIG_VALUE) == -1) {
        fprintf(stderr, "Error writing to ADC config register: %s\n", strerror(errno));
        return -1;
    }

    // Read ADC value
    adc_value = wiringPiI2CReadReg16(fd, ADC_DATA_REG);
    if (adc_value == -1) {
        fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
        return -1;
    }

    // The ADC returns the value in big-endian format, so we need to swap the bytes.
    adc_value = (adc_value >> 8) | (adc_value << 8);

    return adc_value;
}

// Convert ADC value to current (Amps)
float convert_to_current(int adc_value) {
    // Sensitivity of MLX91204 (example value, check datasheet)
    float sensitivity = 0.04; // V/A
    float v_ref = 4.096; // Reference voltage

    // Convert ADC value to voltage
    float voltage = (adc_value * v_ref) / 32768.0;

    // Convert voltage to current
    float current = voltage / sensitivity;

    return current;
}

// Update circular buffer
void update_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    digitalWrite(LED_PIN, LOW); // Turn off LED
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Configure LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially turn off the LED

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(i2c_fd);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC, retrying in %d ms.\n", SAMPLE_PERIOD_MS);
            delay(SAMPLE_PERIOD_MS);
            continue; // Retry
        }

        // Convert to current
        float current = convert_to_current(adc_value);

        // Update buffer
        update_buffer(current);

        // Calculate average
        float average_current = calculate_average();

        // Control LED
        control_led(average_current);

        // Print current and average (optional)
        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        // Delay for sampling rate
        delay(SAMPLE_PERIOD_MS);
    }

    return 0;
}

