#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define TCS34725_ID 0x92

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_raw_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// TCS34725 initialization function
int tcs34725_init(int i2c_handle) {
    int retries = 0;
    int status;

    // Enable the sensor (PON and AEN)
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03); // PON + AEN
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to ENABLE register (PON): %d, retrying...\n", status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to enable sensor after multiple retries.\n");
        return -1;
    }

    // Set integration time (ATIME) - 2.4ms
    retries = 0;
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5); // 2.4ms
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to ATIME register: %d, retrying...\n", status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to set integration time after multiple retries.\n");
        return -1;
    }

    // Set gain (AGAIN) - 60x
    retries = 0;
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01); // 60x gain
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CONTROL register: %d, retrying...\n", status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to set gain after multiple retries.\n");
        return -1;
    }

    // Verify sensor ID
    uint8_t id;
    retries = 0;
    while (retries < 3) {
        status = i2cReadByteData(i2c_handle, TCS34725_ID);
        if (status >= 0) {
            id = (uint8_t)status;
            break;
        } else {
            fprintf(stderr, "Error reading ID register: %d, retrying...\n", status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to read sensor ID after multiple retries.\n");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    return 0;
}

// Function to read raw color data from the sensor
int tcs34725_read_raw_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 0;
    int status;

    while (retries < 3) {
        *clear = i2cReadWordData(i2c_handle, TCS34725_CDATA);
        *red = i2cReadWordData(i2c_handle, TCS34725_RDATA);
        *green = i2cReadWordData(i2c_handle, TCS34725_GDATA);
        *blue = i2cReadWordData(i2c_handle, TCS34725_BDATA);

        if (*clear >= 0 && *red >= 0 && *green >= 0 && *blue >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading color data, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    if (retries == 3) {
        fprintf(stderr, "Failed to read color data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int status;
    uint16_t clear, red, green, blue;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read color data
        if (tcs34725_read_raw_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            // Log the data
            if (log_data(log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading color data, skipping logging\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

