#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc(int channel);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
void control_led(int state);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the ADS1115 ADC
int read_adc(int channel) {
    int16_t raw_value;
    int retries = 3;
    int delay_ms = 10;

    // Configure the ADS1115 for single-ended read
    uint16_t config = 0x4003; // AIN0 single-ended, 4.096V, 128 SPS, start single conversion
    if (channel == 1) {
        config = 0x4003; // AIN1 single-ended, 4.096V, 128 SPS, start single conversion
    }

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10);

    // Read the conversion register
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, (char*)&raw_value, 2) == 2) {
            return raw_value;
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Failed to read ADC after multiple retries\n");
    return -1;
}

// Function to convert raw pressure data to kPa
float convert_pressure(int raw_pressure) {
    // Assuming a linear relationship between raw value and pressure
    // You'll need to calibrate this based on your specific sensor and ADC setup
    // Example:  raw_pressure = 0 corresponds to 0 kPa, raw_pressure = 32767 corresponds to 100 kPa
    float pressure = (float)raw_pressure / 32767.0 * 100.0;
    return pressure;
}

// Function to convert raw temperature data to Celsius
float convert_temperature(int raw_temperature) {
    // Assuming a linear relationship between raw value and temperature
    // You'll need to calibrate this based on your specific sensor and ADC setup
    // Example:  raw_temperature = 0 corresponds to -40°C, raw_temperature = 32767 corresponds to 125°C
    float temperature = (float)raw_temperature / 32767.0 * 165.0 - 40.0;
    return temperature;
}

// Function to control the warning LED
void control_led(int state) {
    gpioWrite(GPIO_LED, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int raw_pressure = read_adc(0);
        int raw_temperature = read_adc(1);

        if (raw_pressure == -1 || raw_temperature == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert raw values to pressure and temperature
        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Print sensor data
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Control LED based on pressure threshold
        if (pressure > PRESSURE_THRESHOLD) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

