    char *log_file;
} Config;

Config config = {
    MOTOR_SHUTDOWN_PIN,
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    MCP3008_CHANNEL,
    CURRENT_THRESHOLD,
    LOG_FILE
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Convert ADC value to current
        float current = convert_adc_to_current(adc_value);

        // Log current
        if (log_current(current) != 0) {
            fprintf(stderr, "Failed to log current. Continuing.\n");
        }

        // Check for overcurrent condition
        if (current > config.current_threshold) {
            shutdown_motor();
            terminate = 1; // Exit the loop after shutdown
        }

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.shutdown_pin, PI_OUTPUT);
    gpioWrite(config.shutdown_pin, 0); // Ensure motor is off initially

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to current (Amperes)
float convert_adc_to_current(int adc_value) {
    // Assuming MLX91209 sensitivity of 66mV/A and 3.3V reference
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float current = voltage / 0.066; // 66mV = 0.066V
    return current;
}

// Log current to file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f A\n", timestamp, current);
    fflush(log_file);

    return 0;
}

// Shutdown motor
void shutdown_motor() {
    gpioWrite(config.shutdown_pin, 1); // Set GPIO HIGH to shutdown motor
    fprintf(log_file, "%s, OVERCURRENT, %.2f A\n", "OVERCURRENT", 0.0); // Log OVERCURRENT event
    fflush(log_file);
    fprintf(stderr, "%s, OVERCURRENT, %.2f A\n", "OVERCURRENT", 0.0);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d. Terminating.\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.shutdown_pin, 0); // Reset GPIO to LOW
    gpioTerminate();
}

