#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define AIN0_CHANNEL 0
#define SAMPLE_RATE 1 // Hz
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int config_register;
    int conversion_register;
    int ain_channel;
    int sample_rate;
    double pressure_min;
    double pressure_max;
    char *log_file;
} config_t;

// Function prototypes
int initialize_i2c(config_t *config);
int configure_ads1115(config_t *config);
int16_t read_adc(config_t *config);
double convert_to_pressure(int16_t adc_value);
int validate_pressure(double pressure);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int initialize_i2c(config_t *config) {
    i2c_handle = i2cOpen(config->i2c_bus, config->ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115
int configure_ads1115(config_t *config) {
    // Configure for single-ended AIN0, 4.096V range, 128 SPS, start single conversion
    uint16_t config_value = 0x4003; // Single-ended AIN0, 4.096V, 128 SPS, start single conversion
    char buf[3];
    buf[0] = config->config_register;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
