#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3208 channel
#define MCP3208_CHANNEL 0

// Define GPIO pins
#define CE0_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9

// Define temperature range
#define MIN_TEMP -40.0
#define MAX_TEMP 125.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float convert_to_celsius(int adc_value);
void log_temperature(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Structure to hold GPIO configuration
typedef struct {
    int ce0;
    int sclk;
    int mosi;
    int miso;
} gpio_config_t;

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins (not strictly needed with pigpio, but good practice)
    gpioSetMode(CE0_PIN, PI_OUTPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }
    fseek(log_file, 0, SEEK_END);

    return 0;
}

// Read data from MCP3208 ADC
int read_mcp3208(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

