    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure CS GPIO as output
    gpioSetMode(CS_GPIO, PI_OUTPUT);
    gpioWrite(CS_GPIO, 1); // De-assert CS initially

    printf("Accelerometer data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();

        // Validate ADC readings
        if (data.x >= 0 && data.x <= 1023 && data.y >= 0 && data.y <= 1023 && data.z >= 0 && data.z <= 1023) {
            log_data(data);
            check_impact(data);
        } else {
            fprintf(stderr, "Invalid ADC reading: X=%d, Y=%d, Z=%d\n", data.x, data.y, data.z);
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay to achieve desired sampling rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

