#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int ir_adc;
    int red_adc;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1172 sensor
int initialize_sensor() {
    // Placeholder for Si1172 initialization sequence
    // Replace with actual initialization commands based on the datasheet
    // This example assumes a simple initialization sequence
    char init_data[] = {0x01, 0x02}; // Example initialization data
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Small delay after initialization
    return 0;
}

// Function to read data from the Si1172 sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[4]; // 2 bytes for IR, 2 bytes for RED
    int result;

    // Read IR data (2 bytes)
    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.ir_adc = -1; // Indicate error
        data.red_adc = -1;
        return data;
    }

    // Combine bytes to form 16-bit values
    data.ir_adc = (buffer[1] << 8) | buffer[0];
    data.red_adc = (buffer[3] << 8) | buffer[2];

    return data;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.ir_adc, data.red_adc, 0);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IR_ADC,RED_ADC,Error\n");
        fflush(log_file);
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.ir_adc == -1 || data.red_adc == -1) {
            // Log error if sensor read failed
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

            fprintf(log_file, "%s,ERROR,ERROR,1\n", timestamp);
            fflush(log_file);
        } else {
            // Log the data
            log_data(data);
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

