    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        float flow_rate = convert_to_flow_rate(adc_value);
        if (flow_rate < 0) {
            fprintf(stderr, "Sensor absent\n");
            continue; // Skip to the next iteration
        }

        if (validate_flow_rate(flow_rate) != 0) {
            continue; // Skip to the next iteration
        }

        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

