// Define constants
#define I2C_BUS 1
#define ICP10125_ADDR 0x68
#define HIGH_PRECISION_CMD 0x00
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration parameters (replace with actual values from your sensor)
float c0 = 100000.0; // Example value
float c1 = 1.0;      // Example value
float c00 = 100.0;   // Example value
float c10 = 0.1;     // Example value
float c01 = 0.01;    // Example value
float c11 = 0.001;   // Example value

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int convert_data(uint8_t *data, float *temperature, float *pressure);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cWriteByte(i2c_handle, HIGH_PRECISION_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(20); // Wait for conversion (adjust as needed)

    result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and pressure
int convert_data(uint8_t *data, float *temperature, float *pressure) {
    int32_t raw_pressure = (data[0] << 8) | data[1];
    int32_t raw_temperature = (data[3] << 8) | data[4];

    *pressure = c0 + c1 * raw_pressure;
    *temperature = c00 + c10 * raw_temperature + c01 * raw_pressure + c11 * raw_pressure * raw_temperature;

    return 0;
}

// Function to log data to a file
int log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to display data on the console
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor_data[DATA_LENGTH];
    float temperature, pressure;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            if (convert_data(sensor_data, &temperature, &pressure) == 0) {
                log_data(temperature, pressure);
                display_data(temperature, pressure);
            } else {
                fprintf(stderr, "Error converting data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in milliseconds
            continue; // Retry reading
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay between samples
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

