#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SAMPLES 100
#define GAIN_DEFAULT 100

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t mic1_samples[NUM_SAMPLES];
    int16_t mic2_samples[NUM_SAMPLES];
    int16_t cancelled_samples[NUM_SAMPLES];
} MicrophoneData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
int16_t convert_adc_to_int16(int adc_value, int gain);
void apply_noise_cancellation(int16_t *mic1_samples, int16_t *mic2_samples, int16_t *cancelled_samples, int num_samples);
void print_csv(int16_t *mic1_samples, int16_t *mic2_samples, int16_t *cancelled_samples, int num_samples);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to signed 16-bit integer
int16_t convert_adc_to_int16(int adc_value, int gain) {
    // Scale ADC value based on gain (adjust as needed for your setup)
    int16_t int16_value = (int16_t)((float)adc_value * (gain / 100.0) * 32767.0 / 1023.0); // Assuming 10-bit ADC
