#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define SAMPLE_INTERVAL_MS 500
#define ADC_CHANNEL 0
#define VREF 3.3 // Reference voltage for MCP3008
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float compensate_temperature(float voltage, float temperature);
int detect_flame(float compensated_voltage);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);
float read_ambient_temperature();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (start bit, single-ended, channel number)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code %d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to compensate voltage based on temperature
float compensate_temperature(float voltage, float temperature) {
    // Simple linear compensation (adjust as needed)
    float compensated_voltage = voltage + (temperature - 25.0) * 0.01; // Example: 0.01V per degree Celsius
    return compensated_voltage;
}

// Function to detect flame based on compensated voltage
int detect_flame(float compensated_voltage) {
    return (compensated_voltage > 1.0) ? 1 : 0; // Example threshold: 1.0V
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s, using default 25.0°C\n", TEMPERATURE_FILE);
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Error: Invalid temperature data in file %s, using default 25.0°C\n", TEMPERATURE_FILE);
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Initially OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_adc = -1;
        float voltage = 0.0;
        float compensated_voltage = 0.0;
        int flame_detected = 0;
        float temperature = 0.0;
        int retries = 0;

        // Read ambient temperature
        temperature = read_ambient_temperature();

        // Read ADC value with retries
        while (retries < MAX_RETRIES) {
            raw_adc = read_mcp3008(ADC_CHANNEL);
            if (raw_adc >= 0 && raw_adc <= 1023) {
                break; // Success
            } else {
                fprintf(stderr, "Error: Invalid ADC value (%d), retrying (%d/%d)\n", raw_adc, retries + 1, MAX_RETRIES);
                retries++;
                gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is OFF on error
                gpioDelay(100); // Small delay before retry
            }
        }

        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is OFF on error
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue; // Skip to next iteration
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(raw_adc);

        // Compensate temperature
        compensated_voltage = compensate_temperature(voltage, temperature);

        // Detect flame
        flame_detected = detect_flame(compensated_voltage);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

