int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the LED based on water level
void control_led(float water_level) {
    static int led_on = 0; // Track LED state

    if (water_level > HIGH_THRESHOLD && !led_on) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        led_on = 1;
        printf("LED ON\n");
    } else if (water_level < LOW_THRESHOLD && led_on) {
        gpioWrite(LED_PIN, 0); // Turn LED off
        led_on = 0;
        printf("LED OFF\n");
    }
