        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue; // Skip to the next iteration
        }

        // Calculate water level percentage
        float water_level = calculate_water_level(adc_value);

        // Control the LED
        control_led(water_level);

        // Log water level to JSON file
        log_water_level(water_level);

        // Print water level to stdout
        printf("Water Level: %.2f%%\n", water_level);

        // Sleep for 5 seconds
        gpioDelay(5000); // 5000 ms = 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(json_file);
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Water level monitoring stopped.\n");

    return 0;
}

