#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define log file name
#define LOG_FILE "airflow_log.csv"

// Define sampling interval (milliseconds)
#define SAMPLING_INTERVAL 100

// Define AWM7300V calibration parameters (example values, adjust as needed)
#define ZERO_FLOW_VOLTAGE 0.5 // Volts
#define FULL_SCALE_FLOW 200.0  // LPM
#define FULL_SCALE_VOLTAGE 3.3 // Volts

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    char *log_file_name;
    int sampling_interval;
    float zero_flow_voltage;
    float full_scale_flow;
    float full_scale_voltage;
} config_t;

// Function prototypes
int initialize_spi(config_t *config);
int read_mcp3008(int channel);
float convert_to_lpm(int adc_value, config_t *config);
char *format_iso8601_timestamp();
int log_data(char *timestamp, float lpm, config_t *config);
void signal_handler(int signal);
void cleanup(config_t *config);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi(config_t *config) {
    spi_handle = spiOpen(config->spi_channel, config->spi_speed, config->spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to Liters Per Minute (LPM)
float convert_to_lpm(int adc_value, config_t *config) {
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float flow = (voltage - config->zero_flow_voltage) / (config->full_scale_voltage - config->zero_flow_voltage) * config->full_scale_flow;
    return flow;
}

// Format timestamp in ISO 8601 format
char *format_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to CSV file
int log_data(char *timestamp, float lpm, config_t *config) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, lpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup(config_t *config) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .spi_mode = SPI_MODE,
        .mcp3008_channel = MCP3008_CHANNEL,
        .log_file_name = LOG_FILE,
        .sampling_interval = SAMPLING_INTERVAL,
        .zero_flow_voltage = ZERO_FLOW_VOLTAGE,
        .full_scale_flow = FULL_SCALE_FLOW,
        .full_scale_voltage = FULL_SCALE_VOLTAGE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(&config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file_name);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Airflow (LPM)\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d ms\n", config.sampling_interval);
            gpioDelay(config.sampling_interval * 1000); // Delay in microseconds
            continue;
        }

        // Convert to LPM
        float lpm = convert_to_lpm(adc_value, &config);

        // Get timestamp
        char *timestamp = format_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, lpm, &config) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        free(timestamp); // Free the allocated memory

        // Delay for the specified sampling interval
        gpioDelay(config.sampling_interval * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup(&config);
    return 0;
}

