    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(&config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file_name);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Airflow (LPM)\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d ms\n", config.sampling_interval);
            gpioDelay(config.sampling_interval * 1000); // Delay in microseconds
            continue;
        }

        // Convert to LPM
        float lpm = convert_to_lpm(adc_value, &config);

        // Get timestamp
        char *timestamp = format_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, lpm, &config) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        free(timestamp); // Free the allocated memory

        // Delay for the specified sampling interval
        gpioDelay(config.sampling_interval * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup(&config);
    return 0;
}

