// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    char *log_file;
    int sample_interval;
} Config;

Config config = {SPI_CHANNEL, SPI_SPEED, LOG_FILE, DEFAULT_SAMPLE_INTERVAL};

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        config.sample_interval = atoi(argv[1]);
        if (config.sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default: %d seconds\n", DEFAULT_SAMPLE_INTERVAL);
            config.sample_interval = DEFAULT_SAMPLE_INTERVAL;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", config.log_file);
        cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log data
        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        sleep(config.sample_interval);
    }

    // Cleanup and exit
    cleanup();
    gpioTerminate();
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Log data to file
int log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d, %.2f\n", timestamp, (int)(moisture_percentage * 100), moisture_percentage);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

