#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)

// Define ADC parameters
#define ADC_CHANNEL 0

// Define pressure range
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

// Define stuck voltage thresholds
#define STICKY_LOW_VOLTAGE 0.0
#define STICKY_HIGH_VOLTAGE 3.3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float adc_to_pressure(int adc_value);
void log_data(float pressure);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_pin;
    int adc_channel;
    float min_pressure;
    float max_pressure;
    float sticky_low_voltage;
    float sticky_high_voltage;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    CS_PIN,
    ADC_CHANNEL,
    MIN_PRESSURE,
    MAX_PRESSURE,
    STICKY_LOW_VOLTAGE,
    STICKY_HIGH_VOLTAGE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);

        // Convert ADC value to pressure
        float pressure = adc_to_pressure(adc_value);

        // Log data
        log_data(pressure);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to pressure (linear mapping)
float adc_to_pressure(int adc_value) {
    float pressure = (float)adc_value / 1023.0 * (config.max_pressure - config.min_pressure) + config.min_pressure;
    return pressure;
}

// Log data to console with ISO-8601 timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program...\n", signal);
    terminate = 1;
}

