#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI bits per word
#define SPI_BITS_PER_WORD 8

// SPI max speed
#define SPI_MAX_SPEED 1000000 // 1 MHz

// MCP3008 channel to read
#define MCP3008_CHANNEL 0

// Global variable for SPI file descriptor
int spi_fd = -1;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t tx_buf[], uint8_t rx_buf[], int len);
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_moisture_percentage(float percentage);
void signal_handler(int sig);

// Structure to hold SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t max_speed;
} spi_config_t;

// Function to initialize the SPI interface
int spi_init(void) {
    spi_config_t config;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    config.fd = spi_fd;
    config.mode = SPI_MODE;
    config.bits_per_word = SPI_BITS_PER_WORD;
    config.max_speed = SPI_MAX_SPEED;

    return 0;
}

// Function to perform SPI transfer
int spi_transfer(uint8_t tx_buf[], uint8_t rx_buf[], int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
