#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_BUS 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3f        // Reference voltage
#define NUM_CHANNELS 4
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_fd = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int bus;
    int chip_select;
    int speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t config);
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int log_data(float voltages[NUM_CHANNELS]);
void signal_handler(int signal);
void cleanup();

// SPI Initialization function
int spi_init(spi_config_t config) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", config.bus, config.chip_select);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = config.speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buf[2] = 0x00;                           // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

// Function to log data to CSV file
int log_data(float voltages[NUM_CHANNELS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp,
            voltages[0], voltages[1], voltages[2], voltages[3]);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // SPI configuration
    spi_config_t spi_config = {
        .bus = SPI_BUS,
        .chip_select = SPI_CE,
        .speed = SPI_SPEED
    };

    // Initialize SPI
    if (spi_init(spi_config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("environmental_data.csv", "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Channel0,Channel1,Channel2,Channel3\n");
    }

    float voltages[NUM_CHANNELS];

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value == -1) {
                fprintf(stderr, "Error reading channel %d\n", i);
                voltages[i] = -1.0f; // Indicate error
            } else {
                voltages[i] = convert_to_voltage(adc_value);
            }
        }

        if (log_data(voltages) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

