#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on
int buffer_index = 0;

// Structure for the circular buffer
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} log_entry_t;

log_entry_t log_buffer[BUFFER_SIZE];

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void add_to_buffer(time_t timestamp, int moisture_level, int pump_state);
void print_buffer();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract moisture level from response
    int moisture_level = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return moisture_level;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump turned ON\n");
        } else {
            fprintf(stderr, "Error: Failed to turn pump ON\n");
        }
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Pump turned OFF\n");
        } else {
            fprintf(stderr, "Error: Failed to turn pump OFF\n");
        }
    }
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, int moisture_level, int pump_state) {
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n", time_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioWrite(PUMP_GPIO, 0); // Turn off pump
    spiClose(spi_handle);     // Close SPI
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read moisture level
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
        } else {
            printf("Moisture level: %d\n", moisture_level);

            // Control the pump
            control_pump(moisture_level);

            // Get current timestamp
            time_t current_time = time(NULL);

            // Add data to the circular buffer
            add_to_buffer(current_time, moisture_level, pump_state);

            // Print the buffer
            print_buffer();
        }

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function
    }

    return 0;
}

