#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3f        // Reference voltage
#define NUM_CHANNELS 3
#define LOG_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    int num_channels;
    int log_interval_ms;
    int max_retries;
} Config;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value, float vref);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, int channel, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("analog_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }
    fflush(log_file);

    return 0;
}

// Function to read data from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel number\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0f) * vref;
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to CSV file
int log_data(const char *timestamp, int channel, float voltage) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (!terminate) {
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            int adc_value = -1;
            int retries = 0;

            while (retries < MAX_RETRIES) {
                adc_value = read_mcp3008(channel);
                if (adc_value >= 0) {
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "Failed to read channel %d, retry %d\n", channel, retries + 1);
                    retries++;
                    gpioDelay(10); // Small delay before retrying
                }
            }

            if (adc_value >= 0) {
                float voltage = convert_to_voltage(adc_value, VREF);
                char* timestamp = get_iso8601_timestamp();
                if (log_data(timestamp, channel, voltage) != 0) {
                    fprintf(stderr, "Failed to log data for channel %d\n", channel);
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Failed to read channel %d after %d retries\n", channel, MAX_RETRIES);
            }
        }

        gpioDelay(LOG_INTERVAL_MS); // Wait for the specified interval
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

