#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define RELAY_GPIO 17
#define DOOR_SENSOR_GPIO 27
#define LOG_FILE "/var/log/door_events.log"
#define SAMPLE_INTERVAL_MS 200
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define RELAY_DURATION_S 3

// Global variables (minimize usage)
static volatile bool running = true;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(const char *bus);
int read_ads1115(int fd, int *raw_value);
float calibrate_distance(int raw_value);
float calculate_threshold(float baseline_distances[], int num_samples);
void control_relay(int gpio, int state);
int read_door_sensor(int gpio);
void log_event(const char *message);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from ADS1115
int read_ads1115(int fd, int *raw_value) {
    uint8_t config[3];
    uint8_t data[2];
    int16_t adc_value;

    // Configure ADS1115 for single-ended A0, 4.096V range, single conversion
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-ended A0, +/-4.096V, Single conversion)
    config[2] = 0x83; // LSB: 10000011 (Start single conversion)

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 128 SPS)
    usleep(150000); // 150ms

    // Read conversion result
    config[0] = 0x00; // Conversion register address
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    *raw_value = adc_value;

    return 0;
}

// Function to calibrate distance based on raw ADC value
float calibrate_distance(int raw_value) {
    // This is a placeholder.  A real implementation would use
    // a lookup table or a mathematical model based on the sensor's
    // datasheet and calibration data.
    // Example: Linear approximation (replace with actual calibration)
    float voltage = (float)raw_value / 32767.0 * 4.096; // Assuming +/-4.096V range
    float distance = 10.0 / voltage; // Example inverse relationship
    return distance;
}

// Function to calculate the distance threshold
float calculate_threshold(float baseline_distances[], int num_samples) {
    float threshold = 0.0;
    for (int i = 0; i < num_samples; i++) {
        threshold += baseline_distances[i];
    }
    return threshold / num_samples;
}

// Function to control the relay
void control_relay(int gpio, int state) {
    int fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
        perror("Error opening relay value file");
        return;
    }

    char buf[2];
    snprintf(buf, sizeof(buf), "%d", state);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Error writing to relay value file");
    }

    close(fd);
}

// Function to read the door sensor
int read_door_sensor(int gpio) {
    int fd = open("/sys/class/gpio/gpio27/value", O_RDONLY);
    if (fd < 0) {
        perror("Error opening door sensor value file");
        return -1;
    }

    char buf[2];
    if (read(fd, buf, 1) < 0) {
        perror("Error reading door sensor value file");
        close(fd);
        return -1;
    }

    close(fd);
    return (buf[0] == '0') ? 0 : 1; // Active low
}

// Function to log events
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s.%03d: %s\n", timestamp, (now % 1) * 1000, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = false;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    int raw_value;
    float distance;
    float baseline_distances[CALIBRATION_SAMPLES];
    float threshold;
    int door_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO for relay
    char gpio_export_path[] = "/sys/class/gpio/export";
    char gpio_direction_path[50];
    int fd_export, fd_direction;

    fd_export = open(gpio_export_path, O_WRONLY);
    if (fd_export < 0) {
        perror("Error opening GPIO export file");
        close(i2c_fd);
        return 1;
    }
    char buf[3];
    snprintf(buf, sizeof(buf), "%d", RELAY_GPIO);
    if (write(fd_export, buf, strlen(buf)) < 0) {
        perror("Error writing to GPIO export file");
        close(fd_export);
        close(i2c_fd);
        return 1;
    }
    close(fd_export);

    snprintf(gpio_direction_path, sizeof(gpio_direction_path), "/sys/class/gpio/gpio%d/direction", RELAY_GPIO);
    fd_direction = open(gpio_direction_path, O_WRONLY);
    if (fd_direction < 0) {
        perror("Error opening GPIO direction file");
        close(i2c_fd);
        return 1;
    }
    if (write(fd_direction, "out", 3) < 0) {
        perror("Error writing to GPIO direction file");
        close(fd_direction);
        close(i2c_fd);
        return 1;
    }
    close(fd_direction);

    // Initialize GPIO for door sensor
    char door_gpio_export_path[] = "/sys/class/gpio/export";
    char door_gpio_direction_path[50];
    int door_fd_export, door_fd_direction;

    door_fd_export = open(door_gpio_export_path, O_WRONLY);
    if (door_fd_export < 0) {
        perror("Error opening door GPIO export file");
        control_relay(RELAY_GPIO, 0); // Ensure relay is off on exit
        close(i2c_fd);
        return 1;
    }
    snprintf(buf, sizeof(buf), "%d", DOOR_SENSOR_GPIO);
    if (write(door_fd_export, buf, strlen(buf)) < 0) {
        perror("Error writing to door GPIO export file");
        close(door_fd_export);
        control_relay(RELAY_GPIO, 0); // Ensure relay is off on exit
        close(i2c_fd);
        return 1;
    }
    close(door_fd_export);

