#define SPI_CHANNEL 0
#define SPI_BAUD 1000000

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel, int cs_pin);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
} sensor_data_t;

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel, int cs_pin) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(cs_pin, 0); // Assert chip select
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(cs_pin, 1); // De-assert chip select

    // Extract ADC value from response
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Error writing to file.\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int sensor1_value, sensor2_value, sensor3_value;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins for chip select as output
    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("soil_moisture_log.csv", "a+");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open soil_moisture_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(fp);
    }
    fseek(fp, 0, SEEK_END); // Reset file pointer to the end

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1_value = read_mcp3008(0, CS0);
        sensor2_value = read_mcp3008(0, CS1);
        sensor3_value = read_mcp3008(0, CS2);

        // Log data to file
        if (log_data(fp, sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Close SPI interface and file
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

