#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define LOG_FILE "irrigation.log"

// Default values
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 3;
    int result;
    while (retries > 0) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed (channel %d), retrying...\n", channel);
            log_message("Error: SPI read failed, retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI read failed after multiple retries (channel %d)\n", channel);
    log_message("Error: SPI read failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[100];
    sprintf(message, "Pump %s", state ? "ON" : "OFF");
    log_message(message);
}

// Function to log messages to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
    control_pump(0); // Turn off pump
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    fclose(log_file); // Close log file
    exit(0);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
