// Define SPI pins
#define SPI_CE0 8
#define SPI_CLK 11
#define SPI_MOSI 10
#define SPI_MISO 9

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define log file path
#define LOG_FILE "/var/log/sound_events.log"

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL_MS 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float calculate_threshold(int *data, int size);
int detect_peak(int value, float threshold);
int log_event(int value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate dynamic threshold
float calculate_threshold(int *data, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    float average = sum / size;
    float standard_deviation = 0.0;
    for (int i = 0; i < size; i++) {
        standard_deviation += (data[i] - average) * (data[i] - average);
    }
    standard_deviation = sqrt(standard_deviation / size);
    return average + 2 * standard_deviation; // Threshold = average + 2 * standard deviation
}

// Detect peak
int detect_peak(int value, float threshold) {
    return (value > threshold) ? 1 : 0;
}

// Log event to file
int log_event(int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%d\n", timestamp, value);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    int data[100]; // Buffer for calculating dynamic threshold
    int data_index = 0;

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Store ADC value for threshold calculation
        data[data_index] = adc_value;
        data_index = (data_index + 1) % 100;

        // Calculate dynamic threshold
        float threshold = calculate_threshold(data, 100);

        // Detect peak
        if (detect_peak(adc_value, threshold)) {
            printf("Peak detected: %d\n", adc_value);

            // Log event
            if (log_event(adc_value) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Close SPI connection
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Sound level monitoring stopped.\n");

    return 0;
}

