#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define AIN0_REG 0x40

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int result;
    unsigned char dummy_read;
    unsigned char current_value;

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("ioctl (I2C_SLAVE)");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring PCF8591 AIN0 channel...\n");

    while (program_running) {
        // Dummy read to discard previous conversion
        result = write(i2c_fd, &AIN0_REG, 1);
        if (result != 1) {
            perror("write (dummy)");
            break;
        }
        result = read(i2c_fd, &dummy_read, 1);
        if (result != 1) {
            perror("read (dummy)");
            break;
        }

        // Read current ADC value
        result = write(i2c_fd, &AIN0_REG, 1);
        if (result != 1) {
            perror("write (current)");
            break;
        }
        result = read(i2c_fd, &current_value, 1);
        if (result != 1) {
            perror("read (current)");
            break;
        }

        printf("AIN0: %d\n", current_value);

        usleep(100000); // 100 ms
    }

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Program finished.\n");
    return 0;
}

