// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RAIN_SENSOR_CHANNEL 0 // MCP3008 Channel 0
#define VDD 3.3 // Volts
#define ADC_MAX_VALUE 1023
#define LOG_INTERVAL_SEC 1

// Rainfall Intensity Levels
#define NO_RAIN 0
#define LIGHT_DRIZZLE 1
#define MODERATE_RAIN 2
#define HEAVY_RAIN 3
#define EXTREME_RAIN 4

// Global variables
static int spi_handle = -1;
static volatile int running = 1;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float calculate_intensity(int adc_value);
void log_data(int adc_value, float intensity);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int rain_sensor_channel;
    float vdd;
    int adc_max_value;
    int log_interval_sec;
} Config;

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Calculate rainfall intensity level
float calculate_intensity(int adc_value) {
    float voltage = (float)adc_value / ADC_MAX_VALUE * VDD;

    if (voltage < 0.5) {
        return NO_RAIN;
    } else if (voltage < 1.5) {
        return LIGHT_DRIZZLE;
    } else if (voltage < 2.5) {
        return MODERATE_RAIN;
    } else if (voltage < 3.0) {
        return HEAVY_RAIN;
    } else {
        return EXTREME_RAIN;
    }
}

// Log data to stdout
void log_data(int adc_value, float intensity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - ADC: %d, Intensity: %.2f\n", timestamp, adc_value, intensity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read ADC value
        int adc_value = read_adc(RAIN_SENSOR_CHANNEL);
        if (adc_value >= 0) {
            // Calculate rainfall intensity
            float intensity = calculate_intensity(adc_value);

            // Log data
            log_data(adc_value, intensity);
        } else {
            fprintf(stderr, "Failed to read ADC value. Skipping.\n");
        }

        // Wait for the next sample
        sleep(LOG_INTERVAL_SEC);
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

