#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <mosquitto.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO_PIN 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_monitor_rpi4"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_TOPIC_PUMP_STATUS "pump_status"
#define PUBLISH_INTERVAL 60 // seconds

// Global variables
static int spi_fd = -1;
static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int spi_fd, int channel);
float calculate_moisture(int adc_value);
void control_pump(int gpio_pin, int state);
void publish_moisture(struct mosquitto *mosq, const char *topic, float moisture);
void subscribe_pump_control(struct mosquitto *mosq, const char *topic);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device %s: %s", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        syslog(LOG_ERR, "Failed to get SPI mode: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        syslog(LOG_ERR, "Failed to set SPI bits per word: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) == -1) {
        syslog(LOG_ERR, "Failed to get SPI bits per word: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        syslog(LOG_ERR, "Failed to set SPI max speed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) == -1) {
        syslog(LOG_ERR, "Failed to get SPI max speed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// MCP3008 read function
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        syslog(LOG_ERR, "SPI transfer failed in read_mcp3008");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Moisture calculation function
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate error
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

// Pump control function
void control_pump(int gpio_pin, int state) {
    digitalWrite(gpio_pin, state);
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
}

// Publish moisture function
void publish_moisture(struct mosquitto *mosq, const char *topic, float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture: %s", mosquitto_strerror(ret));
    }
}

// Subscribe to pump control topic
void subscribe_pump_control(struct mosquitto *mosq, const char *topic) {
    int ret = mosquitto_subscribe(mosq, NULL, topic, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to pump control: %s", mosquitto_strerror(ret));
    }
}

// Message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);
        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                control_pump(PUMP_GPIO_PIN, 1);
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                control_pump(PUMP_GPIO_PIN, 0);
            } else {
                syslog(LOG_WARNING, "Invalid pump control command: %s", (char *)message->payload);
            }
        }
    }
}

// Connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        subscribe_pump_control(mosq, MQTT_TOPIC_PUMP_CONTROL);
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_connack_string(result));
    }
}

// Disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize SPI");
        return 1;
    }

    // Initialize GPIO for pump control
    pinMode(PUMP_GPIO_PIN, OUTPUT);
    control_pump(PUMP_GPIO_PIN, 0); // Ensure pump is off on startup

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        close(spi_fd);
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        close(spi_fd);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to calculate moisture percentage");
            continue;
        }

        // Control pump based on moisture level and hysteresis
        static int pump_state = 0; // 0 = off, 1 = on
        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_pump(PUMP_GPIO_PIN, 1);
            pump_state = 1;
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_pump(PUMP_GPIO_PIN, 0);
            pump_state = 0;
        }

        // Publish moisture value
        publish_moisture(mosq, MQTT_TOPIC_SOIL_MOISTURE, moisture);

        // Sleep for the specified interval
        sleep(PUBLISH_INTERVAL);
    }

    // Cleanup
    control_pump(PUMP_GPIO_PIN, 0); // Turn off pump
    close(spi_fd);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();

    return 0;
}

