    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate error
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

// Pump control function
void control_pump(int gpio_pin, int state) {
    digitalWrite(gpio_pin, state);
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
}

// Publish moisture function
void publish_moisture(struct mosquitto *mosq, const char *topic, float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture: %s", mosquitto_strerror(ret));
    }
}

// Subscribe to pump control topic
void subscribe_pump_control(struct mosquitto *mosq, const char *topic) {
    int ret = mosquitto_subscribe(mosq, NULL, topic, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to pump control: %s", mosquitto_strerror(ret));
    }
}

// Message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);
        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                control_pump(PUMP_GPIO_PIN, 1);
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                control_pump(PUMP_GPIO_PIN, 0);
            } else {
                syslog(LOG_WARNING, "Invalid pump control command: %s", (char *)message->payload);
            }
        }
    }
}

// Connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        subscribe_pump_control(mosq, MQTT_TOPIC_PUMP_CONTROL);
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_connack_string(result));
    }
}

// Disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize SPI");
        return 1;
    }

    // Initialize GPIO for pump control
    pinMode(PUMP_GPIO_PIN, OUTPUT);
    control_pump(PUMP_GPIO_PIN, 0); // Ensure pump is off on startup

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        close(spi_fd);
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        close(spi_fd);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to calculate moisture percentage");
            continue;
        }

        // Control pump based on moisture level and hysteresis
        static int pump_state = 0; // 0 = off, 1 = on
        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_pump(PUMP_GPIO_PIN, 1);
            pump_state = 1;
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_pump(PUMP_GPIO_PIN, 0);
            pump_state = 0;
        }

        // Publish moisture value
        publish_moisture(mosq, MQTT_TOPIC_SOIL_MOISTURE, moisture);

        // Sleep for the specified interval
        sleep(PUBLISH_INTERVAL);
    }

    // Cleanup
    control_pump(PUMP_GPIO_PIN, 0); // Turn off pump
    close(spi_fd);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();

    return 0;
}

