#include <stdint.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI speed (Hz)
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channel to read
#define MCP3008_CHANNEL 0

// VDD and VREF (Volts)
#define VDD 3.3
#define VREF VDD

// Global variable for SPI file descriptor
int spi_fd = -1;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float calculate_voltage(int raw_value);
void signal_handler(int sig);

// Structure to hold SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Function to initialize the SPI interface
int spi_init(void) {
    spi_config_t config;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    config.mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    config.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    config.speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;
    transfer[0].cs_change = 0;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate voltage from raw ADC value
float calculate_voltage(int raw_value) {
    return ((float)raw_value / 1023.0) * VREF;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

int main(void) {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize SPI interface
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        // Read ADC value from MCP3008
        int raw_value = read_mcp3008(MCP3008_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 500ms.\n");
            usleep(500000); // Wait 500ms
            continue;
        }

        // Calculate voltage
        float voltage = calculate_voltage(raw_value);

        // Print raw value and voltage
        printf("Raw Value: %d, Voltage: %.2f V\n", raw_value, voltage);

        // Wait 500ms
        usleep(500000);
    }

    return 0;
}

