#define MOTOR2_GPIO 27

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define noise threshold
#define NOISE_THRESHOLD 500

// Define PWM frequency
#define PWM_FREQUENCY 100 // Hz

// Define PWM range
#define PWM_RANGE 1000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int gpio, int speed);
void log_vibration(int noise_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int gpio, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    gpioPWM(gpio, speed);
}

// Function to log vibration events
void log_vibration(int noise_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Vibration detected: Noise level = %d\n", timestamp, noise_level);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for vibration motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read noise level from MCP3008
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error: Failed to read noise level\n");
            continue; // Skip to the next iteration
        }

        // Calculate motor speeds based on noise level
        int motor1_speed = (noise_level > NOISE_THRESHOLD) ? (noise_level - NOISE_THRESHOLD) : 0;
        int motor2_speed = (noise_level > NOISE_THRESHOLD) ? (noise_level - NOISE_THRESHOLD) : 0;

        // Set motor speeds
        set_motor_speed(MOTOR1_GPIO, motor1_speed);
        set_motor_speed(MOTOR2_GPIO, motor2_speed);

        // Log vibration if noise level exceeds threshold
        if (noise_level > NOISE_THRESHOLD) {
            log_vibration(noise_level);
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms
    }

    // Graceful shutdown
    printf("Shutting down...\n");

    // Stop motors
    set_motor_speed(MOTOR1_GPIO, 0);
    set_motor_speed(MOTOR2_GPIO, 0);

    // Close SPI device
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

