#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables (to be cleaned up on exit)
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_adc_to_db(int adc_value);
int read_bh1750();
int log_data(float sound_level_db, int light_level_lux, int error_code);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB (example formula)
float convert_adc_to_db(int adc_value) {
    // This is a placeholder.  A real implementation would
    // require calibration and a more sophisticated formula.
    // The MAX9814 output is typically a voltage, so you'd
    // need to know the ADC's reference voltage to convert
    // the ADC value to a voltage, and then use the MAX9814's
    // datasheet to convert the voltage to dB.
    return (float)adc_value * 0.1; // Example conversion
}

// Function to read from BH1750 sensor
int read_bh1750() {
    // Send start measurement command (High Resolution Mode)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command to BH1750\n");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read data from BH1750\n");
        return -1;
    }

    // Combine bytes to get lux value
    int lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to log data to CSV file
int log_data(float sound_level_db, int light_level_lux, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, flags 0
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        float sound_level_db = 0.0;
        int light_level_lux = 0;
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            error_code = -1; // ADC read error
        } else {
            sound_level_db = convert_adc_to_db(adc_value);
        }

        int bh1750_result = read_bh1750();
        if (bh1750_result < 0) {
            fprintf(stderr, "Error: Failed to read BH1750 value\n");
            error_code = -2; // BH1750 read error
        } else {
            light_level_lux = bh1750_result;
        }

        if (log_data(sound_level_db, light_level_lux, error_code) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Sleep for 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();

    return 0;
}

