#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY 1000 // 1 second
#define DISTANCE_THRESHOLD 20.0 // 20 cm
#define LOG_FILE "door_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float distance_cm(int adc_value);
void control_relay(int state);
void log_event(float distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to distance in centimeters
float distance_cm(int adc_value) {
    // GP2Y0A21YK0F datasheet formula (approximate)
    // Distance (cm) = 29.12 / (ADC Value / 1023.0) - 1.11
    // This is a simplified approximation and may need calibration for your specific setup.
    if (adc_value == 0) return 100.0; // Avoid division by zero
    return 29.12 / ((float)adc_value / 1023.0) - 1.11;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    printf("Relay set to %d\n", state);
}

// Function to log events to a file
void log_event(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn off relay
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Door monitoring system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to distance
        float distance = distance_cm(adc_value);

        printf("ADC Value: %d, Distance: %.2f cm\n", adc_value, distance);

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            printf("Distance below threshold! Activating relay.\n");
            control_relay(1); // Activate relay
            log_event(distance); // Log the event
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (in microseconds)
            control_relay(0); // Deactivate relay
            printf("Relay deactivated.\n");
        }

        gpioDelay(100 * 1000); // Poll every 100 ms (in microseconds)
    }

    cleanup();
    return 0;
}

