#define VALVE_MIN_DUTY 0
#define VALVE_MAX_DUTY 100
#define NUM_SENSORS 3
#define NUM_READINGS 3
#define LOG_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int *readings, int num_readings);
int set_valve_position(float average_moisture);
void log_data(int *readings, float average_moisture, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate the average of an array of readings
float calculate_average(int *readings, int num_readings) {
    int sum = 0;
    int count = 0;
    for (int i = 0; i < num_readings; i++) {
        if (readings[i] != -1) { // Exclude invalid readings
            sum += readings[i];
            count++;
        }
    }
    if (count == 0) {
        return 0.0; // Return 0 if all readings are invalid
    }
    return (float)sum / count;
}

// Function to set the valve position based on the average moisture level
int set_valve_position(float average_moisture) {
    // Map moisture level (0-1023) to duty cycle (0-100)
    int duty_cycle = (int)((100.0 - (average_moisture / 1023.0) * 100.0) + 0.5); // Ensure integer value

    // Clamp duty cycle to the valid range
    if (duty_cycle < VALVE_MIN_DUTY) {
        duty_cycle = VALVE_MIN_DUTY;
    } else if (duty_cycle > VALVE_MAX_DUTY) {
        duty_cycle = VALVE_MAX_DUTY;
    }

    gpioPWM(VALVE_GPIO, duty_cycle);
    return duty_cycle;
}

