    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int readings[NUM_SENSORS];
    float average_moisture;
    int valve_position;

    time_t last_log_time = 0;

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            readings[i] = -1; // Initialize to invalid value
            for (int j = 0; j < NUM_READINGS; j++) {
                int raw_value = read_mcp3008(i);
                if (raw_value != -1) {
                    readings[i] = raw_value;
                    break; // Exit inner loop if read is successful
                } else {
                    fprintf(stderr, "Error: Failed to read sensor %d, attempt %d\n", i, j + 1);
                    gpioDelay(100); // Wait before retrying
                }
            }
        }

        average_moisture = calculate_average(readings, NUM_SENSORS);
        valve_position = set_valve_position(average_moisture);

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL) {
            log_data(readings, average_moisture, valve_position);
            last_log_time = current_time;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Graceful shutdown
    printf("Shutting down...\n");
    gpioPWM(VALVE_GPIO, 0); // Close the valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

