#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define RETRY_COUNT 5
#define MIN_DELAY_MS 10
#define MAX_DELAY_MS 100
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_data(float percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;
    int retries = 0;
    int delay_ms = MIN_DELAY_MS;

    // Construct the SPI command
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract the ADC value from the response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

            // Validate the ADC value
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
                fprintf(log_file, "Error: Invalid ADC value: %d\n", adc_value);
                fflush(log_file);
                return -1; // Indicate an error
            }
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d)\n", retries + 1);
            fprintf(log_file, "Error: SPI transfer failed (attempt %d)\n", retries + 1);
            fflush(log_file);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            if (delay_ms > MAX_DELAY_MS) {
                delay_ms = MAX_DELAY_MS;
            }
        }
    }

    fprintf(stderr, "Failed to read from MCP3008 after %d retries\n", RETRY_COUNT);
    fprintf(log_file, "Error: Failed to read from MCP3008 after %d retries\n", RETRY_COUNT);
    fflush(log_file);
    return -1; // Indicate a failure
}

// Function to convert the ADC value to a moisture percentage
float convert_to_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log the data to a file
void log_data(float percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to perform cleanup before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float percentage = convert_to_percentage(adc_value);
            log_data(percentage);
            printf("Soil Moisture: %.2f%%\n", percentage);
        } else {
            fprintf(stderr, "Failed to read soil moisture data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

