#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 20.0
#define MIN_VOLUME 0.0
#define MAX_VOLUME 1.0
#define CONFIG_FILE "theremin_config.txt"

// Global variables
static volatile int running = 1;
static int spi_fd;
static float last_distance = 10.0; // Default distance
static float last_volume = 0.5;    // Default volume

// Calibration parameters
static float distance_offset = 0.0;
static float distance_scale = 1.0;
static float ldr_offset = 0.0;
static float ldr_scale = 1.0;

// Function prototypes
void signal_handler(int signal);
int spi_init(int bus, int device, int speed);
int read_mcp3008(int channel);
float read_distance();
float read_ldr();
float map_distance_to_frequency(float distance);
float map_ldr_to_volume(float ldr_value);
void set_pwm_frequency(int pin, float frequency);
void set_pwm_duty_cycle(int pin, float volume);
void load_config();
void save_config();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize SPI interface
int spi_init(int bus, int device, int speed) {
    char spi_device[20];
    sprintf(spi_device, "/dev/spidev%d.%d", bus, device);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00;                  // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int timeout = 10000; // Timeout after 10ms
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: HC-SR04 timeout waiting for echo high\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 10000; // Timeout after 10ms
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: HC-SR04 timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    uint32_t pulse_duration = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_duration / 1000000.0) * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Read LDR value from MCP3008
float read_ldr() {
    int adc_value = read_mcp3008(0); // Assuming LDR is connected to channel 0
    if (adc_value < 0) {
        return -1.0; // Indicate error
    }

    // Apply calibration
    float ldr_value = (float)adc_value - ldr_offset;
    ldr_value *= ldr_scale;

    // Clamp value to 0-1 range
    if (ldr_value < 0.0) ldr_value = 0.0;
    if (ldr_value > 1.0) ldr_value = 1.0;

    return ldr_value;
}

// Map distance to frequency
float map_distance_to_frequency(float distance) {
    // Apply calibration
    float calibrated_distance = distance + distance_offset;
    calibrated_distance *= distance_scale;

    // Clamp distance to valid range
    if (calibrated_distance < MIN_DISTANCE) calibrated_distance = MIN_DISTANCE;
    if (calibrated_distance > MAX_DISTANCE) calibrated_distance = MAX_DISTANCE;

    // Map distance to frequency
    float frequency = MIN_FREQUENCY + (calibrated_distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Map LDR value to volume
float map_ldr_to_volume(float ldr_value) {
    // Map LDR value to volume
    float volume = ldr_value; // Linear mapping

    return volume;
}

// Set PWM frequency
void set_pwm_frequency(int pin, float frequency) {
    gpioSetPWMfrequency(pin, (int)frequency);
}

// Set PWM duty cycle
void set_pwm_duty_cycle(int pin, float volume) {
    int duty_cycle = (int)(volume * 1000000.0); // Assuming range 0-1000000
    gpioPWM(pin, duty_cycle);
}

// Load calibration parameters from file
void load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config file %s, using default values.\n", CONFIG_FILE);
        return;
    }

    if (fscanf(fp, "%f %f %f %f", &distance_offset, &distance_scale, &ldr_offset, &ldr_scale) != 4) {
        fprintf(stderr, "Warning: Could not read all values from config file %s, using default values.\n", CONFIG_FILE);
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration parameters loaded from %s\n", CONFIG_FILE);
}

// Save calibration parameters to file
void save_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config file %s for writing.\n", CONFIG_FILE);
        return;
    }

    fprintf(fp, "%f %f %f %f", distance_offset, distance_scale, ldr_offset, ldr_scale);
    fclose(fp);
    printf("Calibration parameters saved to %s\n", CONFIG_FILE);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init(SPI_BUS, SPI_DEVICE, SPI_SPEED) < 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Load calibration parameters
    load_config();

    // Set PWM frequency (initial value)
    set_pwm_frequency(PWM_PIN, 440.0); // Initial frequency

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Theremin instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        float distance = read_distance();
        float ldr_value = read_ldr();

        // Handle sensor read errors
        if (distance < 0.0) {
            distance = last_distance; // Use last valid distance
            fprintf(stderr, "Error: Invalid distance reading, using last valid value.\n");
        } else {
            last_distance = distance; // Update last valid distance
        }

        if (ldr_value < 0.0) {
            ldr_value = last_volume; // Use last valid volume
            fprintf(stderr, "Error: Invalid LDR reading, using last valid value.\n");
        } else {
            last_volume = ldr_value; // Update last valid volume
        }

        // Map sensor values to audio parameters
        float frequency = map_distance_to_frequency(distance);
        float volume = map_ldr_to_volume(ldr_value);

        // Set PWM frequency and duty cycle
        set_pwm_frequency(PWM_PIN, frequency);
        set_pwm_duty_cycle(PWM_PIN, volume);

        // Small delay
        gpioDelay(50); // 50ms delay
    }

    // Stop PWM and release resources
    gpioPWM(PWM_PIN, 0); // Stop PWM
    close(spi_fd);
    gpioTerminate();

    save_config();

    return 0;
}

