    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retry_count = 0;

        // Retry reading ADC value
        while (retry_count < MAX_RETRIES) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success
            } else {
                fprintf(stderr, "Retrying ADC read (attempt %d/%d)\n", retry_count + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
                retry_count++;
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        float aqi = calculate_aqi(adc_value);
        control_fan((int)aqi);
        log_data(aqi);

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

