        adc_values[reading_index] = adc_value;
        reading_index = (reading_index + 1) % SENSOR_ABSENT_READINGS;

        // Check for sensor absent condition
        if (is_sensor_absent(adc_values, SENSOR_ABSENT_READINGS)) {
            printf("Sensor absent condition detected!\n");
