#include <errno.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

#define MCP3008_CHANNEL0 0
#define MCP3008_CHANNEL1 1

// Define PWM parameters
#define PWM_RANGE 1024
#define PWM_CLOCK_DIVISOR 16 // Adjust for desired PWM frequency

// Define acceleration/deceleration parameters
#define ACCELERATION_TIME 1 // seconds
#define DECELERATION_TIME 1 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int map_adc_to_speed(int adc_value);
void set_motor_speed(int motor_number, int speed);
void set_motor_direction(int motor_number, int direction);
void accelerate_motor(int motor_number, int target_speed);
void decelerate_motor(int motor_number, int target_speed);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to map ADC value to motor speed
int map_adc_to_speed(int adc_value) {
    // Assuming ADC range is 0-1023 and speed range is 0-PWM_RANGE
    return (int)(((float)adc_value / 1023.0) * PWM_RANGE);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_number, int speed) {
    int gpio_pin;

    if (motor_number == 1) {
        gpio_pin = MOTOR1_ENABLE;
    } else if (motor_number == 2) {
        gpio_pin = MOTOR2_ENABLE;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor_number);
        return;
    }

    pwmWrite(gpio_pin, speed);
}

// Function to set motor direction
void set_motor_direction(int motor_number, int direction) {
    int gpio_pin;

    if (motor_number == 1) {
        gpio_pin = MOTOR1_DIRECTION;
    } else if (motor_number == 2) {
        gpio_pin = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor_number);
        return;
    }

    digitalWrite(gpio_pin, direction);
}

// Function to accelerate motor to target speed
void accelerate_motor(int motor_number, int target_speed) {
    int current_speed = 0;
    int increment = target_speed / ACCELERATION_TIME; // Speed increment per second
    int delay_ms = 10; // Delay in milliseconds

    for (int i = 0; i <= ACCELERATION_TIME * 1000 / delay_ms; ++i) {
        current_speed += increment;
        if (current_speed > target_speed) {
            current_speed = target_speed;
        }
        set_motor_speed(motor_number, current_speed);
        delay(delay_ms);
    }
}

// Function to decelerate motor to target speed
void decelerate_motor(int motor_number, int target_speed) {
    int current_speed = PWM_RANGE;
    int decrement = (PWM_RANGE - target_speed) / DECELERATION_TIME; // Speed decrement per second
    int delay_ms = 10; // Delay in milliseconds

    for (int i = 0; i <= DECELERATION_TIME * 1000 / delay_ms; ++i) {
        current_speed -= decrement;
        if (current_speed < target_speed) {
            current_speed = target_speed;
        }
        set_motor_speed(motor_number, current_speed);
        delay(delay_ms);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins for motor control
    pinMode(MOTOR1_ENABLE, PWM_OUTPUT);
    pinMode(MOTOR1_DIRECTION, OUTPUT);
    pinMode(MOTOR2_ENABLE, PWM_OUTPUT);
    pinMode(MOTOR2_DIRECTION, OUTPUT);

    // Set PWM range and clock divisor
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(1920000 / PWM_RANGE / PWM_CLOCK_DIVISOR); // Adjust clock for desired frequency

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int adc_value0 = read_mcp3008(MCP3008_CHANNEL0);
        int adc_value1 = read_mcp3008(MCP3008_CHANNEL1);

        if (adc_value0 == -1 || adc_value1 == -1) {
            fprintf(stderr, "Error reading ADC values. Continuing...\n");
            delay(5000); // Wait before retrying
            continue;
        }

        // Map ADC values to motor speeds
        int speed0 = map_adc_to_speed(adc_value0);
        int speed1 = map_adc_to_speed(adc_value1);

        // Accelerate motors
        accelerate_motor(1, speed0);
        accelerate_motor(2, speed1);

        // Hold constant speed for 2 seconds
        delay(2000);

        // Decelerate motors
        decelerate_motor(1, 0);
        decelerate_motor(2, 0);

        // Pause for 5 seconds
        delay(5000);

        // Reverse motor directions
        set_motor_direction(1, HIGH); // Motor 1 forward
        set_motor_direction(2, LOW);  // Motor 2 backward
        delay(100); // Short delay to ensure direction change takes effect

        // Accelerate motors in reverse
        accelerate_motor(1, speed0);
        accelerate_motor(2, speed1);

        // Hold constant speed for 2 seconds
        delay(2000);

        // Decelerate motors
        decelerate_motor(1, 0);
        decelerate_motor(2, 0);

        // Pause for 5 seconds
        delay(5000);
    }

    // Stop motors and clean up GPIO
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    printf("Program finished.\n");

    return 0;
}

