#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CS   8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define LED_PIN  17

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
float calibrate_baseline(int duration_ms);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int cs_pin;
    int mosi_pin;
    int miso_pin;
    int sclk_pin;
    int channel;
    int baud;
} spi_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_config_t spi_config = {
        .cs_pin = SPI_CS,
        .mosi_pin = SPI_MOSI,
        .miso_pin = SPI_MISO,
        .sclk_pin = SPI_SCLK,
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD
    };

    spi_handle = spiOpen(spi_config.channel, spi_config.baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(SPI_CS, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(SPI_CS, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate the baseline noise level
float calibrate_baseline(int duration_ms) {
    int sum = 0;
    int num_samples = duration_ms / 10; // Sample every 10 ms

    printf("Calibrating baseline for %d ms...\n", duration_ms);
    for (int i = 0; i < num_samples; i++) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        gpioDelay(10); // 10 ms delay
    }

    return (float)sum / num_samples;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Calibrate baseline noise level
    float baseline = calibrate_baseline(5000); // Calibrate for 5 seconds
    if (baseline < 0) {
        fprintf(stderr, "Calibration failed, exiting\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Baseline noise level: %.2f\n", baseline);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        // Compare to baseline and control LED
        if (adc_value > baseline) {
            control_led(1); // Turn LED on
            gpioDelay(10);   // Debounce delay
        } else {
            control_led(0); // Turn LED off
            gpioDelay(10);   // Debounce delay
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Cleanup
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

