#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>

// Define SPI device and chip select pin
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8 // GPIO8 (CE0)

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int spi_init(int spi_fd);
int read_adc(int spi_fd, int channel);
int log_data(FILE *log_file, long long timestamp_ns, int adc_value);
void signal_handler(int signal);

// Structure to hold SPI configuration
struct spi_config {
    int mode;
    int bits_per_word;
    int max_speed_hz;
};

// Initialize SPI device
int spi_init(int spi_fd) {
    struct spi_config config = {
        .mode = 0,
        .bits_per_word = 8,
        .max_speed_hz = 1000000 // 1 MHz
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("SPI_IOC_WR_MODE failed");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("SPI_IOC_WR_BITS_PER_WORD failed");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.max_speed_hz) == -1) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ failed");
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Transfer SPI data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("SPI_IOC_MESSAGE failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Log data to file
int log_data(FILE *log_file, long long timestamp_ns, int adc_value) {
    char buffer[128];
    snprintf(buffer, sizeof(buffer), "%lld|%d\n", timestamp_ns, adc_value);

    if (fputs(buffer, log_file) == EOF) {
        perror("fputs failed");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush failed");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    struct timespec sleep_time;
    struct timeval tv;
    long long timestamp_ns;
    int adc_value;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Initialize SPI
    if (spi_init(spi_fd) < 0) {
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read ADC value
        adc_value = read_adc(spi_fd, 0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Get timestamp
        gettimeofday(&tv, NULL);
        timestamp_ns = (long long)tv.tv_sec * 1000000000LL + tv.tv_usec * 1000LL;

        // Log data
        if (log_data(log_file, timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Sleep for 1 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 1000000; // 1 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);

    return 0;
}

