    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Gas leak detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (adc_value == -1 && retries < MAX_RETRIES) {
            adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value == -1) {
                fprintf(stderr, "Retrying ADC read (attempt %d/%d)...\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (adc_value != -1) {
            float voltage = adc_to_voltage(adc_value);
            float ppm = voltage_to_ppm(voltage);

            printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);
            log_data(voltage, ppm);
        } else {
            fprintf(stderr, "Error: Failed to read ADC after multiple retries.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

