#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 for MCP3008 Chip Select

// Define MCP3008 channel numbers
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

// Define ADXL335 sensitivity (3.3V reference)
#define SENSITIVITY 0.33 // 3.3V / 1024

// Define sampling rate (10 Hz)
#define SAMPLE_RATE 10

// Define Kalman filter parameters
#define Q 0.01 // Process noise covariance
#define R 0.1  // Measurement noise covariance

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float P;
} kalman_state_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_g(int adc_value);
accelerometer_data_t kalman_filter(kalman_state_t *state, float measurement);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to g-force units
float adc_to_g(int adc_value) {
    return (float)adc_value * SENSITIVITY;
}

// Kalman filter implementation
accelerometer_data_t kalman_filter(kalman_state_t *state, float measurement) {
    // Prediction step
    state->x = state->x; // No process model, just hold the previous estimate
    state->P = state->P + Q; // Increase uncertainty due to process noise

    // Update step
    float K = state->P / (state->P + R); // Kalman gain
    state->x = state->x + K * (measurement - state->x); // Update estimate
    state->P = (1 - K) * state->P; // Update uncertainty

    accelerometer_data_t filtered_data;
    filtered_data.x = state->x;
    return filtered_data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Kalman filter states
    kalman_state_t x_state = {0.0, 0.0};
    kalman_state_t y_state = {0.0, 0.0};
    kalman_state_t z_state = {0.0, 0.0};

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(X_CHANNEL);
        int y_adc = read_mcp3008(Y_CHANNEL);
        int z_adc = read_mcp3008(Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert ADC values to g-force units
        float x_g = adc_to_g(x_adc);
        float y_g = adc_to_g(y_adc);
        float z_g = adc_to_g(z_adc);

        // Apply Kalman filter
        accelerometer_data_t filtered_x = kalman_filter(&x_state, x_g);
        accelerometer_data_t filtered_y = kalman_filter(&y_state, y_g);
        accelerometer_data_t filtered_z = kalman_filter(&z_state, z_g);

        // Print filtered values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_x.x, filtered_y.y, filtered_z.z);

        // Delay for 10 Hz sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // microseconds
    }

    // Close SPI connection
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

