#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the voltage range
#define V_HIGH 3.3
#define V_LOW 0.0

// Define the magnetic field range
#define MIN_MAG_FIELD -100.0
#define MAX_MAG_FIELD 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the digital state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to convert the digital state to a voltage
float state_to_voltage(int state) {
    return (state == 1) ? V_HIGH : V_LOW;
}

// Function to convert the voltage to a magnetic field strength
float voltage_to_magnetic_field(float voltage) {
    // Assuming a linear relationship between voltage and magnetic field
    // This is a placeholder; replace with the actual calibration curve
    // for the DRV5055VA sensor.
    return voltage * 10.0; // Example: 1V = 10mT
}

// Function to log the magnetic field values to a file
int log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Ensure data is written to the file immediately
    fclose(fp);
    return 0;
}

// Function to check if the magnetic field value is within the valid range
int is_within_range(float magnetic_field) {
    return (magnetic_field >= MIN_MAG_FIELD && magnetic_field <= MAX_MAG_FIELD);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);
        int sensor3_state = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_state < 0 || sensor2_state < 0 || sensor3_state < 0) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Convert sensor states to voltages
        float sensor1_voltage = state_to_voltage(sensor1_state);
        float sensor2_voltage = state_to_voltage(sensor2_state);
        float sensor3_voltage = state_to_voltage(sensor3_state);

        // Convert voltages to magnetic field strengths
        float sensor1_mT = voltage_to_magnetic_field(sensor1_voltage);
        float sensor2_mT = voltage_to_magnetic_field(sensor2_voltage);
        float sensor3_mT = voltage_to_magnetic_field(sensor3_voltage);

        // Check if magnetic field values are within the valid range
        if (!is_within_range(sensor1_mT)) {
            fprintf(stderr, "Warning: Sensor 1 magnetic field value (%.2f mT) out of range.\n", sensor1_mT);
        }
        if (!is_within_range(sensor2_mT)) {
            fprintf(stderr, "Warning: Sensor 2 magnetic field value (%.2f mT) out of range.\n", sensor2_mT);
        }
        if (!is_within_range(sensor3_mT)) {
            fprintf(stderr, "Warning: Sensor 3 magnetic field value (%.2f mT) out of range.\n", sensor3_mT);
        }

        // Log the magnetic field values
        if (log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging magnetic field values.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

