#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channels to read
#define CHANNEL_0 0
#define CHANNEL_1 1
#define CHANNEL_2 2

// Global variables for SPI file descriptor and CSV file pointer
int spi_fd = -1;
FILE *csv_file = NULL;

// Function prototypes
int spi_init(const char *device);
int spi_read_channel(int channel);
int log_data_to_csv(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Function to initialize the SPI interface
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from a specific MCP3008 channel
int spi_read_channel(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform SPI transaction
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transaction");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data_to_csv(int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (csv_file == NULL) {
        csv_file = fopen("sensor_data.csv", "a");
        if (csv_file == NULL) {
            perror("Error opening CSV file");
            return -1;
        }
        // Write header if the file is newly created
        fseek(csv_file, 0, SEEK_END);
        long fsize = ftell(csv_file);
        if (fsize == 0) {
            fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
        }
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);
    fflush(csv_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        int channel0_value = spi_read_channel(CHANNEL_0);
        int channel1_value = spi_read_channel(CHANNEL_1);
        int channel2_value = spi_read_channel(CHANNEL_2);

        if (channel0_value < 0 || channel1_value < 0 || channel2_value < 0) {
            fprintf(stderr, "Error reading from SPI. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (log_data_to_csv(channel0_value, channel1_value, channel2_value) != 0) {
            fprintf(stderr, "Error logging data to CSV. Retrying...\n");
        }

        sleep(1); // Wait for 1 second
    }

    return 0;
}

