#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signum);
int mqtt_connect_and_subscribe(struct mosquitto **mosq);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
void set_led_state(int led_state);
void reconnect_with_backoff(struct mosquitto **mosq, int *reconnect_delay);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received signal %d, shutting down...\n", signum);
        running = 0;
    }
}

// Connect to MQTT broker and subscribe to topic
int mqtt_connect_and_subscribe(struct mosquitto **mosq) {
    int rc;

    mosquitto_lib_init();

    *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!*mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    mosquitto_connect_callback_set(*mosq, on_connect);
    mosquitto_disconnect_callback_set(*mosq, on_disconnect);
    mosquitto_message_callback_set(*mosq, on_message);

    rc = mosquitto_connect(*mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(*mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    rc = mosquitto_subscribe(*mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not subscribe to topic: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(*mosq);
        mosquitto_destroy(*mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    return 0;
}

// Callback function for successful MQTT connection
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Connected to MQTT broker.\n");
    } else {
        fprintf(stderr, "Error: MQTT connection failed: %s\n", mosquitto_strerror(result));
    }
}

// Callback function for MQTT disconnection
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    fprintf(stderr, "Disconnected from MQTT broker with code %d\n", rc);
}

// Callback function for incoming MQTT messages
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json_payload((const char *)message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            fprintf(stderr, "Error: Invalid JSON payload received.\n");
        }
    } else {
        fprintf(stderr, "Warning: Empty message received on topic %s\n", message->topic);
    }
}

// Parse JSON payload to extract led_state
int parse_json_payload(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        fprintf(stderr, "Error: JSON parse error: %s\n", error.text);
        return 1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        fprintf(stderr, "Error: 'led_state' key not found in JSON.\n");
        json_decref(root);
        return 1;
    }

    if (!json_is_boolean(led_state_json)) {
        fprintf(stderr, "Error: 'led_state' value is not a boolean.\n");
        json_decref(root);
        return 1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// Set the LED state using pigpio
void set_led_state(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
}

// Exponential backoff reconnection function
void reconnect_with_backoff(struct mosquitto **mosq, int *reconnect_delay) {
    int rc;
    int delay = *reconnect_delay;

    fprintf(stderr, "Attempting to reconnect in %d seconds...\n", delay);
    sleep(delay);

    rc = mosquitto_reconnect(*mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT reconnect failed: %s\n", mosquitto_strerror(rc));
        *reconnect_delay = (delay * 2 > MAX_RECONNECT_DELAY) ? MAX_RECONNECT_DELAY : delay * 2;
        reconnect_with_backoff(mosq, reconnect_delay);
    } else {
        *reconnect_delay = 1; // Reset delay on successful reconnect
    }
}

int main() {
    int reconnect_delay = 1;
    int rc;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Turn off LED initially
    set_led_state(0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT
    if (mqtt_connect_and_subscribe(&mosq) != 0) {
        fprintf(stderr, "Error: MQTT initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // Non-blocking loop with a timeout
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Error: MQTT loop error: %s\n", mosquitto_strerror(rc));
            reconnect_with_backoff(&mosq, &reconnect_delay);
        }
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

