#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to trigger the alarm LED
void trigger_alarm() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(1000);       // Wait for 1 second
    gpioWrite(LED_PIN, 0); // Turn LED off
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();

        if (sound_level == 0) { // Sound detected (LOW signal)
            printf("Sound detected! Triggering alarm.\n");
            trigger_alarm();
        } else if (sound_level == 1) {
            printf("Sound level: %d\n", sound_level);
        } else {
            fprintf(stderr, "Error reading sound sensor. Retrying...\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");

    return 0;
}

