#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define DEBOUNCE_DELAY_MS 50

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

// Function prototypes
void signal_handler(int signal);
int log_message(const char *message);
int read_temperature(float *temperature);
int read_humidity(float *humidity);
int read_vibration();
void shutdown_system();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Log message to file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Read temperature from DHT22 sensor
int read_temperature(float *temperature) {
    int data[5] = {0};
    int bit_count = 0;
    int i, j;

    // Send start signal
    gpioSetMode(4, PI_OUTPUT);
    gpioWrite(4, 0);
    gpioDelay(1);
    gpioWrite(4, 1);
    gpioDelay(30);

    gpioSetMode(4, PI_INPUT);

    // Read data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low
            int count = 0;
            while (gpioRead(4) == 0) {
                count++;
                gpioDelay(1);
                if (count > 100) return -1; // Timeout
            }

            // Wait for high
            count = 0;
            while (gpioRead(4) == 1) {
                count++;
                gpioDelay(1);
                if (count > 100) return -1; // Timeout
            }

            // Determine bit value
            if (count > 40) {
                data[i] |= (1 << (7 - j));
            }
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -1;
    }

    // Convert to temperature
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

// Read humidity from DHT22 sensor
int read_humidity(float *humidity) {
    int data[5] = {0};
    int bit_count = 0;
    int i, j;

    // Send start signal
    gpioSetMode(4, PI_OUTPUT);
    gpioWrite(4, 0);
    gpioDelay(1);
    gpioWrite(4, 1);
    gpioDelay(30);

    gpioSetMode(4, PI_INPUT);

    // Read data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low
            int count = 0;
            while (gpioRead(4) == 0) {
                count++;
                gpioDelay(1);
                if (count > 100) return -1; // Timeout
            }

            // Wait for high
            count = 0;
            while (gpioRead(4) == 1) {
                count++;
                gpioDelay(1);
                if (count > 100) return -1; // Timeout
            }

            // Determine bit value
            if (count > 40) {
                data[i] |= (1 << (7 - j));
            }
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -1;
    }

    // Convert to humidity
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;

    return 0;
}

// Read vibration sensor
int read_vibration() {
    return gpioRead(GPIO_PIN);
}

// Shutdown system
void shutdown_system() {
    printf("Shutting down system...\n");
    log_message("System shutdown initiated.");
    system("sudo shutdown -h now");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration and sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read vibration sensor
        int vibration_detected = read_vibration();

        if (vibration_detected == 0) {
            // Vibration detected
            printf("Vibration detected!\n");

            // Log vibration event
            log_message("Vibration detected!");

            // Read temperature and humidity
            float temperature, humidity;
            if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
                char log_message_buffer[256];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "Temperature: %.1f°C, Humidity: %.1f%%", temperature, humidity);
                log_message(log_message_buffer);
                printf("%s\n", log_message_buffer);
            } else {
                log_message("Failed to read temperature/humidity.");
                fprintf(stderr, "Failed to read temperature/humidity.\n");
            }

            // Shutdown system
            shutdown_system();
            break; // Exit the loop after shutdown
        }

        gpioDelay(10); // Check every 10ms
    }

    // Clean up
    gpioTerminate();
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Program terminated.\n");
    return 0;
}

