#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // LM35 connected to channel 0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void store_temperature(float temperature);
void log_temperature_data();
void signal_handler(int signal);

// Structure for SPI configuration (optional, but good practice)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Initialize SPI interface
int initialize_spi() {
    spi_config_t spi_config = {SPI_CHANNEL, SPI_SPEED};
    spi_handle = spiOpen(spi_config.channel, spi_config.speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    return (adc_value * 3.3 / 1024.0) * 100.0; // LM35: 10mV/°C
}

// Store temperature in circular buffer
void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Log temperature data to file
void log_temperature_data() {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    size_t elements_to_write = (buffer_index == 0) ? BUFFER_SIZE : BUFFER_SIZE - buffer_index;
    size_t bytes_to_write = elements_to_write * sizeof(float);

    if (fwrite(temperature_buffer, sizeof(float), elements_to_write, fp) != elements_to_write) {
        fprintf(stderr, "Error writing to log file.\n");
    }

    if (buffer_index != 0) {
        // Write the remaining elements from the beginning of the buffer
        size_t remaining_elements = BUFFER_SIZE - elements_to_write;
        size_t remaining_bytes = remaining_elements * sizeof(float);
        if (fwrite(temperature_buffer, sizeof(float), remaining_elements, fp) != remaining_elements) {
            fprintf(stderr, "Error writing to log file.\n");
        }
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading temperature, skipping...\n");
            sleep(5);
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Store temperature in circular buffer
        store_temperature(temperature);

        // Print temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Log temperature data to file
        log_temperature_data();

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Temperature monitoring stopped.\n");
    return 0;
}

