        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    return (adc_value * 3.3 / 1024.0) * 100.0; // LM35: 10mV/°C
}

// Store temperature in circular buffer
void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Log temperature data to file
void log_temperature_data() {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    size_t elements_to_write = (buffer_index == 0) ? BUFFER_SIZE : BUFFER_SIZE - buffer_index;
    size_t bytes_to_write = elements_to_write * sizeof(float);

    if (fwrite(temperature_buffer, sizeof(float), elements_to_write, fp) != elements_to_write) {
        fprintf(stderr, "Error writing to log file.\n");
    }

    if (buffer_index != 0) {
        // Write the remaining elements from the beginning of the buffer
        size_t remaining_elements = BUFFER_SIZE - elements_to_write;
        size_t remaining_bytes = remaining_elements * sizeof(float);
        if (fwrite(temperature_buffer, sizeof(float), remaining_elements, fp) != remaining_elements) {
            fprintf(stderr, "Error writing to log file.\n");
        }
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading temperature, skipping...\n");
            sleep(5);
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Store temperature in circular buffer
        store_temperature(temperature);

        // Print temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Log temperature data to file
        log_temperature_data();

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Temperature monitoring stopped.\n");
    return 0;
}

