#define MCP3008_CS 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "environmental_log.txt"

// Global variables
int i2c_handle;
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
int read_mcp3008(int spi_handle, int channel);
void log_data(FILE *log_file, int light_lux, int sound_adc);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read light level from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buffer[2];
    int lux = -1; // Default to -1 to indicate error

    if (i2cWriteByte(i2c_handle, config_cmd) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    if (i2cReadDevice(i2c_handle, buffer, 2) == 2) {
        lux = (buffer[0] << 8) | buffer[1];
    } else {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    return lux;
}

// Function to read sound level from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Function to log data to file
void log_data(FILE *log_file, int light_lux, int sound_adc) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light_lux, sound_adc);
    fflush(log_file); // Ensure data is written to disk immediately
}

