    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open SPI bus
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI bus: %d\n", spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set MCP3008 CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        spiClose(spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int light_lux = read_bh1750(i2c_handle);
        int sound_adc = read_mcp3008(spi_handle, 0);

        if (light_lux != -1 && sound_adc != -1) {
            log_data(log_file, light_lux, sound_adc);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

