#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000 // 500 kHz
#define SPI_CHIP_SELECT 0 // CE0
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x60
#define VREF 3.3 // Reference voltage for MCP3008
#define VCC 3.3 // Supply voltage for MCP4725
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 0.5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t channel, uint16_t *raw_value);
int i2c_init(const char *device, int address);
int i2c_write(int fd, uint16_t value);
float adc_to_temperature(uint16_t raw_value);
uint16_t temperature_to_dac(float temperature);
void log_data(FILE *fp, uint16_t raw_value, float temperature, uint16_t dac_value);
void signal_handler(int signum);

// SPI Initialization
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_value = 0;
    switch (mode) {
        case SPI_MODE_0: mode_value = 0; break;
        case SPI_MODE_1: mode_value = 1; break;
        case SPI_MODE_2: mode_value = 2; break;
        case SPI_MODE_3: mode_value = 3; break;
        default: fprintf(stderr, "Invalid SPI mode\n"); return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t channel, uint16_t *raw_value) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (4 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract raw value from response
    *raw_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return 0;
}

// I2C Initialization
int i2c_init(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C Write
int i2c_write(int fd, uint16_t value) {
    uint8_t buf[2];
    buf[0] = (value >> 4) & 0xFF; // MSB
    buf[1] = (value << 4) & 0xF0; // LSB

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// ADC to Temperature Conversion
float adc_to_temperature(uint16_t raw_value) {
    float voltage = (float)raw_value * VREF / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Temperature to DAC Conversion
uint16_t temperature_to_dac(float temperature) {
    float voltage = (temperature / 100.0) + 0.5;
    uint16_t dac_value = (uint16_t)(voltage * 1024.0 / VREF);
    return dac_value;
}

// Data Logging
void log_data(FILE *fp, uint16_t raw_value, float temperature, uint16_t dac_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %u, %.2f, %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_value, temperature, dac_value);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
