// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 3
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int channel;
    int value;
} sensor_data_t;

// Function prototypes
int read_mcp3008(int channel);
int log_data(sensor_data_t *sensor_data, int num_sensors);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log data to file
int log_data(sensor_data_t *sensor_data, int num_sensors) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_sensors; i++) {
        if (sensor_data[i].value >= 0 && sensor_data[i].value <= 1023) {
            fprintf(log_file, "%s,%d,%d\n", timestamp, sensor_data[i].channel, sensor_data[i].value);
        } else {
            fprintf(stderr, "Error: Invalid ADC value: %d for channel %d\n", sensor_data[i].value, sensor_data[i].channel);
        }
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Goodbye!\n");
}

int main() {
    if (initialize()) {
        return 1;
    }

    sensor_data_t sensor_data[NUM_SENSORS];

    while (!terminate) {
        // Read sensor data
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_data[i].channel = i;
            sensor_data[i].value = read_mcp3008(i);
            if (sensor_data[i].value < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }

        // Log data
        if (log_data(sensor_data, NUM_SENSORS) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    cleanup();
    return 0;
}

