// Define the GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
void activate_relay(int pin);
void deactivate_relay(int pin);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
        program_running = 0;

        // Deactivate all relays
        deactivate_relay(RELAY1_PIN);
        deactivate_relay(RELAY2_PIN);
        deactivate_relay(RELAY3_PIN);
        deactivate_relay(RELAY4_PIN);

        // Terminate the pigpio library
        gpioTerminate();

        exit(0);
    }
}

// Function to activate a relay
void activate_relay(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate relay on pin %d\n", pin);
    }
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate relay on pin %d\n", pin);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially deactivated
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate relay 1
        activate_relay(RELAY1_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY1_PIN);
        gpioDelay(1000); // Wait for 1 second

        // Activate relay 2
        activate_relay(RELAY2_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY2_PIN);
        gpioDelay(1000); // Wait for 1 second

        // Activate relay 3
        activate_relay(RELAY3_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY3_PIN);
        gpioDelay(1000); // Wait for 1 second

        // Activate relay 4
        activate_relay(RELAY4_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY4_PIN);
        gpioDelay(1000); // Wait for 1 second
    }

    // This point should not be reached unless program_running is manually set to 0
    gpioTerminate();
    return 0;
}

