#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 16
#define DEBOUNCE_DELAY 200 // milliseconds
#define THRESHOLD 500
#define LOG_FILE "sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_led(int state);
void log_event(int adc_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to log events to a file
void log_event(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Sound detected! ADC Value: %d\n", timestamp, adc_value);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    spiClose(spi_handle); // Close SPI interface
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        if (adc_value > THRESHOLD) {
            control_led(1); // Turn on LED
            log_event(adc_value); // Log the event
            gpioDelay(500); // Keep LED on for 500ms
            control_led(0); // Turn off LED
            gpioDelay(DEBOUNCE_DELAY); // Debounce delay
        }

        gpioDelay(10); // Sample every 10ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

