#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for motor control
#define IN1 17
#define IN2 18
#define ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor run time
#define MOTOR_RUN_TIME 3 // seconds

// Define PWM duty cycle
#define PWM_DUTY_CYCLE 150

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void log_rain_data(int rain_level);
void control_motor(int rain_level);
void signal_handler(int signal);

// Function to read rain sensor data from MCP3008
int read_rain_sensor() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int rain_level;

    // MCP3008 configuration: single-ended channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract rain level from the received data
    rain_level = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return rain_level;
}

// Function to log rain data to file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the motor based on rain level
void control_motor(int rain_level) {
    if (rain_level > RAIN_THRESHOLD) {
        // Close window (forward)
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioPWM(ENA, PWM_DUTY_CYCLE);
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Delay for 3 seconds (microseconds)
        gpioPWM(ENA, 0); // Stop motor
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
    } else {
        // Open window (reverse)
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioPWM(ENA, PWM_DUTY_CYCLE);
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Delay for 3 seconds (microseconds)
        gpioPWM(ENA, 0); // Stop motor
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop the motor
    gpioPWM(ENA, 0);
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    int rain_level;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        rain_level = read_rain_sensor();
        if (rain_level >= 0) {
            log_rain_data(rain_level);
            control_motor(rain_level);
        } else {
            fprintf(stderr, "Error: Failed to read rain sensor data\n");
        }

        gpioDelay(1000000); // Wait for 1 second (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

