#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define ADC_DATA_PIN 26
#define ADC_CLOCK_PIN 19
#define LED_PIN 16

// Define constants
#define ADC_RESOLUTION 1024 // 10-bit ADC
#define CLAP_THRESHOLD 500   // Adjust this value based on your environment
#define DEBOUNCE_INTERVAL 50 // Debounce interval in milliseconds
#define LED_ON_DURATION 500  // LED on duration in milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int state);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int adc_data_pin;
    int adc_clock_pin;
    int led_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ADC_DATA_PIN, PI_INPUT);
    gpioSetMode(ADC_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read analog value from MAX9814 using bit-banged ADC
int read_adc() {
    int adc_value = 0;

    for (int i = 0; i < ADC_RESOLUTION; i++) {
        gpioWrite(ADC_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock stability
        adc_value |= (gpioRead(ADC_DATA_PIN) << i);
        gpioWrite(ADC_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    return adc_value;
}

// Detect clap event
int detect_clap(int adc_value) {
    static int last_clap_time = 0;
    int current_time = gpioTick();

    if (adc_value > CLAP_THRESHOLD) {
        if (current_time - last_clap_time > DEBOUNCE_INTERVAL * 1000) { // Convert ms to us
            last_clap_time = current_time;
            return 1; // Clap detected
        }
    }
    return 0; // No clap detected
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Print timestamped message to console
void print_timestamped_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Clap detection program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_adc();

        if (detect_clap(adc_value)) {
            control_led(1); // Turn on LED
            print_timestamped_message("Clap detected!");
            gpioDelay(LED_ON_DURATION * 1000); // Delay for LED on duration (ms to us)
            control_led(0); // Turn off LED
        }

        gpioDelay(1000); // Delay between readings (ms to us)
    }

    // Cleanup
    control_led(0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

