#include <string.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

/* Reads the digital value from the specified GPIO pin. */
int read_distance_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

/* Logs the distance reading to the specified file with a timestamp. */
int log_distance(const char *filename, int distance) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing\n", filename);
        return -1; // Indicate an error
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d\n", timestamp, distance);
    fclose(fp);
    return 0;
}

/* Prints a message to the console indicating whether the feeder is activated or idle. */
void print_feeder_status(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance monitoring...\n");

    while (program_running) {
        int distance = read_distance_sensor(GPIO_PIN);
        if (distance >= 0) {
            if (log_distance(LOG_FILE, distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }
            print_feeder_status(distance);
        } else {
            fprintf(stderr, "Error reading distance sensor, retrying...\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

