        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Convert ADC value to magnetic field strength
        float magnetic_field = adc_to_magnetic_field(adc_value);

        // Log magnetic field reading
        log_magnetic_field(magnetic_field);

        // Control LED
        control_led(magnetic_field);

        // Wait 100 ms
        gpioDelay(100); // pigpio's delay function
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

