#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_POWER 17
#define ADC_CHANNEL 0
#define VREF 5.0       // Reference voltage for MCP3008
#define SENSITIVITY 0.1 // 100 mV/A = 0.1 V/A
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float convert_to_current(int adc_value);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int gpio_power;
    int adc_channel;
    float vref;
    float sensitivity;
    char *log_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    GPIO_POWER,
    ADC_CHANNEL,
    VREF,
    SENSITIVITY,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC. Retrying in 1 second.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        float current = convert_to_current(adc_value);
        if (log_current(current) != 0) {
            fprintf(stderr, "Error logging current. Check file permissions.\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for power enable
    gpioSetMode(config.gpio_power, PI_OUTPUT);
    gpioWrite(config.gpio_power, 1); // Enable the sensor

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", config.log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

