#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Debounce parameters
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000 // 2ms

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio_pin) {
    int samples[DEBOUNCE_SAMPLES];
    int high_count = 0;
    int low_count = 0;

    // Read the sensor multiple times
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        samples[i] = gpioRead(gpio_pin);
        gpioDelay(DEBOUNCE_DELAY_US);
    }

    // Determine the majority value
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        if (samples[i] == 1) {
            high_count++;
        } else {
            low_count++;
        }
    }

    // Return the majority value
    return (high_count > low_count) ? 1 : 0;
}

// Function to log the sensor states
void log_sensor_states(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);
}

// Function to check for simultaneous object detection
void check_simultaneous_detection(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] ALERT: Both sensors detect object\n", timestamp);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        // Log sensor states
        log_sensor_states(sensor1_state, sensor2_state);

        // Check for simultaneous detection
        check_simultaneous_detection(sensor1_state, sensor2_state);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

