#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define SNAPSHOT_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/motion_detector.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
}

int main() {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Motion detector started");

    while (program_running) {
        int motion_detected = gpioRead(GPIO_PIN);

        if (motion_detected) {
            time_t rawtime;
            struct tm *timeinfo;
            char filename[256];
            char command[512];
            int status;

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(filename, sizeof(filename), SNAPSHOT_DIR "%Y%m%d_%H%M%S.jpg", timeinfo);
            snprintf(command, sizeof(command), "libcamera-still -o %s", filename);

            syslog(LOG_INFO, "Motion detected, capturing image: %s", filename);

            pid_t pid = fork();

            if (pid == 0) {
                // Child process
                status = system(command);
                if (status == 0) {
                    syslog(LOG_INFO, "Image captured successfully: %s", filename);
                } else {
                    syslog(LOG_ERR, "Image capture failed with status: %d", status);
                }
                exit(status);
            } else if (pid < 0) {
                syslog(LOG_ERR, "Fork failed");
            } else {
                // Parent process
                int child_status;
                waitpid(pid, &child_status, 0);
                if (WIFEXITED(child_status)) {
                    if (WEXITSTATUS(child_status) != 0) {
                        syslog(LOG_ERR, "Child process exited with status: %d", WEXITSTATUS(child_status));
                    }
                } else {
                    syslog(LOG_ERR, "Child process terminated abnormally");
                }
            }

            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    gpioTerminate();
    syslog(LOG_INFO, "Motion detector stopped");
    closelog();

    return 0;
}

