#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

// Structure to hold camera parameters
struct camera_parameters {
    int width;
    int height;
    int pixel_format;
    int buffer_count;
    size_t buffer_size;
};

// Global variables
static int fd = -1; // Camera file descriptor
static void *buffer = NULL; // Mapped buffer
static size_t buffer_size = 0; // Size of the mapped buffer
static int running = 1; // Flag to control the main loop
static int frame_count = 0; // Counter for frame numbering
static char filename[64]; // Filename for image saving

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    running = 0;
}

// Function to initialize the camera
int initialize_camera(const char *device_path, struct camera_parameters *params) {
    fd = open(device_path, O_RDWR | O_NONBLOCK); // Open the camera device
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_path, strerror(errno));
        return -1;
    }

    // Configure camera parameters (OV5647 grayscale 8-bit)
    params->width = 640;
    params->height = 480;
    params->pixel_format = 1; // 1 = YUYV, 2 = YUV420, 3 = RGB565, 4 = RGBA8888, 5 = Grayscale 8-bit
    params->buffer_count = 1; // Single buffer

    // Calculate buffer size
    params->buffer_size = params->width * params->height * (params->pixel_format == 5 ? 1 : 2); // 1 byte per pixel for grayscale

    // Set camera parameters (example - adjust as needed for OV5647)
    int fd_stream = open("/dev/video0", O_RDWR | O_NONBLOCK); // Open stream device
    if (fd_stream < 0) {
        fprintf(stderr, "Error opening stream device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd_stream, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd_stream);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = params->width;
    fmt.fmt.pix.height = params->height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY; // Grayscale 8-bit
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd_stream, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd_stream);
        close(fd);
        return -1;
    }

    close(fd_stream);

    return 0;
}

// Function to map the camera buffer
int map_buffer(struct camera_parameters *params) {
    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0; // Only one buffer

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    buffer_size = buf.length;

    return 0;
}

// Function to unmap the camera buffer
int unmap_buffer() {
    if (munmap(buffer, buffer_size) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        return -1;
    }
    buffer = NULL;
    buffer_size = 0;
    return 0;
}

// Function to enqueue a buffer
int enqueue_buffer(int buffer_index) {
    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error enqueueing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int *buffer_index) {
    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) {
            // Timeout occurred, no frame available
            return -1; // Indicate EAGAIN
        } else {
            fprintf(stderr, "Error dequeueing buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    *buffer_index = buf.index;
    return 0;
}

// Function to save the frame as a PGM file
int save_frame(const void *data, size_t size) {
    snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_count + 1);
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    // Write PGM header
    fprintf(fp, "P5\n%d %d\n255\n", 640, 480); // Assuming 640x480 resolution

    // Write image data (grayscale)
    fwrite(data, 1, size, fp);

    fclose(fp);
    frame_count++;
    return 0;
}

// Function to cleanup resources
int cleanup() {
    if (fd != -1) {
        close(fd);
    }
    if (buffer != NULL) {
        unmap_buffer();
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device_path = "/dev/video0";
    if (argc > 1) {
        device_path = argv[1];
    }

    struct camera_parameters params;
    int buffer_index = 0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize camera
    if (initialize_camera(device_path, &params) < 0) {
        cleanup();
        return 1;
    }

    // Map the buffer
    if (map_buffer(&params) < 0) {
        cleanup();
        return 1;
    }

    // Enqueue the buffer
    if (enqueue_buffer(0) < 0) {
        cleanup();
        return 1;
    }

    printf("Capturing frames... Press Ctrl+C to stop.\n");

    // Main loop
    while (running) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r < 0) {
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            break;
        } else if (r == 0) {
            // Timeout occurred, no frame available
            continue;
        } else {
            // Frame is available
            if (dequeue_buffer(&buffer_index) < 0) {
                fprintf(stderr, "Error dequeueing buffer, exiting.\n");
                break;
            }

            // Save the frame
            if (save_frame(buffer, params.buffer_size) < 0) {
                fprintf(stderr, "Error saving frame, exiting.\n");
                break;
            }

            // Re-enqueue the buffer
            if (enqueue_buffer(buffer_index) < 0) {
                fprintf(stderr, "Error enqueueing buffer, exiting.\n");
                break;
            }
        }
    }

    // Cleanup resources
    cleanup();

    printf("Exiting.\n");
    return 0;
}

