#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define NUM_BUFFERS 4
#define MAX_PAYLOAD_SIZE 65000
#define FRAME_INDEX_SIZE 4
#define FRAGMENT_INDEX_SIZE 4
#define TOTAL_FRAGMENTS_SIZE 4
#define PAYLOAD_SIZE_SIZE 4
#define HEADER_SIZE (FRAME_INDEX_SIZE + FRAGMENT_INDEX_SIZE + TOTAL_FRAGMENTS_SIZE + PAYLOAD_SIZE_SIZE)

// Structure to hold buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
int                 fd                  = -1;
struct buffer        buffers[NUM_BUFFERS];
int                 n_buffers           = 0;
int                 sock                = -1;
struct sockaddr_in  dest_addr;
volatile sig_atomic_t keep_running = 1;

// Function prototypes
int init_v4l2(void);
int configure_buffers(void);
int capture_frame(void);
int fragment_frame(void *frame_data, size_t frame_size, int frame_index, int total_fragments);
int send_udp_packet(void *packet_data, size_t packet_size, struct sockaddr_in dest_addr);
void signal_handler(int sig);
void cleanup(void);

// Signal handler to catch SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    keep_running = 0;
}

// Initialize V4L2 device
int init_v4l2(void) {
    int ret;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    // Check if the device is a V4L2 device
    unsigned int caps;
    ret = ioctl(fd, VIDIOC_STREAMING, &caps);
    if (ret < 0) {
        fprintf(stderr, "Error checking V4L2 capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return 0;
}

// Configure buffers
int configure_buffers(void) {
    int ret;
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
        if (ret < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    n_buffers = NUM_BUFFERS;
    return 0;
}

// Capture a frame
int capture_frame(void) {
    int ret;
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_STREAMON, &req);
    if (ret < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret < 0) {
            fprintf(stderr, "Error dequeuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        // Process the frame (e.g., fragment and send)
        fragment_frame(buffers[buf.index].start, buffers[buf.index].length, i, n_buffers);

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    ret = ioctl(fd, VIDIOC_STREAMOFF, &req);
    if (ret < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Fragment a frame into UDP datagrams
int fragment_frame(void *frame_data, size_t frame_size, int frame_index, int total_fragments) {
    int num_fragments = (int)((double)frame_size / MAX_PAYLOAD_SIZE) + 1;
    if (num_fragments > total_fragments) {
        fprintf(stderr, "Too many fragments for frame %d, max allowed: %d, actual: %d\n", frame_index, total_fragments, num_fragments);
        return -1;
    }

    for (int i = 0; i < num_fragments; i++) {
        size_t payload_size = (i == num_fragments - 1) ? frame_size - i * MAX_PAYLOAD_SIZE : MAX_PAYLOAD_SIZE;
        size_t offset = i * MAX_PAYLOAD_SIZE;

        // Create header
        unsigned char header[HEADER_SIZE];
        memcpy(header, &frame_index, FRAME_INDEX_SIZE);
        memcpy(header + FRAME_INDEX_SIZE, &i, FRAGMENT_INDEX_SIZE);
        memcpy(header + FRAME_INDEX_SIZE + FRAGMENT_INDEX_SIZE, &num_fragments, TOTAL_FRAGMENTS_SIZE);
        memcpy(header + FRAME_INDEX_SIZE + FRAGMENT_INDEX_SIZE + TOTAL_FRAGMENTS_SIZE, &payload_size, PAYLOAD_SIZE_SIZE);

        // Create packet
        unsigned char packet[HEADER_SIZE + payload_size];
        memcpy(packet, header, HEADER_SIZE);
        memcpy(packet + HEADER_SIZE, frame_data + offset, payload_size);

        // Send packet
        if (send_udp_packet(packet, HEADER_SIZE + payload_size, dest_addr) != 0) {
            fprintf(stderr, "Error sending packet for fragment %d of frame %d\n", i, frame_index);
            return -1;
        }
    }

    return 0;
}

// Send a UDP packet
int send_udp_packet(void *packet_data, size_t packet_size, struct sockaddr_in dest_addr) {
    int ret;

