    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_STREAMON, &req);
    if (ret < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret < 0) {
            fprintf(stderr, "Error dequeuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        // Process the frame (e.g., fragment and send)
        fragment_frame(buffers[buf.index].start, buffers[buf.index].length, i, n_buffers);

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
