    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = IMAGE_HEIGHT; // Assuming height is also 192
    fmt.fmt.pix.pixelformat = pixel_format;
    fmt.fmt.pix.field = field;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting image format");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

// Function to map the buffers
int map_buffers(int fd, struct buffer *buffers, int num_buffers) {
    struct v4l2_buffer buf;
    for (int i = 0; i < num_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        return -1;
    }
    return 0;
}

// Function to dequeue a frame
int dequeue_frame(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("Error dequeuing frame");
        return -1;
    }
    return 0;
}

// Function to write the frame to a file
int write_frame_to_file(const void *data, size_t size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(data, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the V4L2 device
    fd = init_v4l2_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Set the image format
    if (set_image_format(fd, V4L2_PIX_FMT_MJPEG, IMAGE_WIDTH, V4L2_FIELD_NONE) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd, NUM_BUFFERS) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    buffers = (struct buffer *)malloc(NUM_BUFFERS * sizeof(struct buffer));
    if (buffers == NULL) {
        perror("Error allocating memory for buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    if (map_buffers(fd, buffers, NUM_BUFFERS) == -1) {
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        munmap(buffers[0].start, buffers[0].length);
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue a frame
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (dequeue_frame(fd, &buf) == -1) {
        munmap(buffers[0].start, buffers[0].length);
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify bytesused
    if (buf.bytesused <= 0) {
        fprintf(stderr, "Error: bytesused is 0 or negative\n");
        munmap(buffers[0].start, buffers[0].length);
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the frame to a file
    if (write_frame_to_file(buffers[buf.index].start, buf.bytesused, JPEG_FILE_NAME) == -1) {
        munmap(buffers[0].start, buffers[0].length);
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
    }

    // Unmap buffers
    for (int i = 0; i < NUM_BUFFERS; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
        }
    }

    // Free buffer array
    free(buffers);

    // Close the device file descriptor
    close(fd);

    printf("Image saved to %s\n", JPEG_FILE_NAME);
    return EXIT_SUCCESS;
}

