#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PAN_PIN 4
#define TILT_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define initial servo positions
#define INITIAL_PAN_POSITION 75
#define INITIAL_TILT_POSITION 75

// Define position limits
#define MIN_POSITION 25
#define MAX_POSITION 125

// Global variables for current servo positions
int pan_position = INITIAL_PAN_POSITION;
int tilt_position = INITIAL_TILT_POSITION;

// Function prototypes
void set_servo_position(int pin, int position);
int get_button_state(int pin);
void adjust_servo_position(int *position, int increment);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Function to set the servo position using PWM
void set_servo_position(int pin, int position) {
    if (position < MIN_POSITION || position > MAX_POSITION) {
        fprintf(stderr, "Error: Servo position out of range (%d). Clamping to %d-%d.\n", position, MIN_POSITION, MAX_POSITION);
        if (position < MIN_POSITION) position = MIN_POSITION;
        if (position > MAX_POSITION) position = MAX_POSITION;
    }

    int duty_cycle = 50 + (position * (PWM_RANGE - 50) / (MAX_POSITION - MIN_POSITION));
    gpioPWM(pin, duty_cycle);
}

// Function to get the button state
int get_button_state(int pin) {
    return gpioRead(pin);
}

// Function to adjust the servo position
void adjust_servo_position(int *position, int increment) {
    *position += increment;
    if (*position < MIN_POSITION) {
        *position = MIN_POSITION;
    } else if (*position > MAX_POSITION) {
        *position = MAX_POSITION;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs for servos
    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);

    // Set GPIO pins as inputs with pull-up resistors for buttons
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);

    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency for servos
    gpioSetPWMfrequency(PAN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_PIN, PWM_RANGE);

    // Set initial servo positions
    set_servo_position(PAN_PIN, pan_position);
    set_servo_position(TILT_PIN, tilt_position);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Check button states and adjust servo positions
        if (get_button_state(TILT_UP_PIN) == 0) {
            adjust_servo_position(&tilt_position, 5);
            set_servo_position(TILT_PIN, tilt_position);
            gpioDelay(200); // Debounce delay
        }
        if (get_button_state(TILT_DOWN_PIN) == 0) {
            adjust_servo_position(&tilt_position, -5);
            set_servo_position(TILT_PIN, tilt_position);
            gpioDelay(200); // Debounce delay
        }
        if (get_button_state(PAN_LEFT_PIN) == 0) {
            adjust_servo_position(&pan_position, -5);
            set_servo_position(PAN_PIN, pan_position);
            gpioDelay(200); // Debounce delay
        }
        if (get_button_state(PAN_RIGHT_PIN) == 0) {
            adjust_servo_position(&pan_position, 5);
            set_servo_position(PAN_PIN, pan_position);
            gpioDelay(200); // Debounce delay
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(50);
    }

    return 0;
}

