#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4

// Structure to hold camera information
typedef struct {
    int fd;
    struct v4l2_buffer *buffers;
    size_t buffer_size;
    size_t num_buffers;
    void **buffer_map;
} camera_t;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the camera
int init_camera(camera_t *camera) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }
    camera->fd = fd;

    // Check if the device is a V4L2 device
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    // Set image format
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Request buffers
    camera->num_buffers = NUM_BUFFERS;
    camera->buffers = calloc(camera->num_buffers, sizeof(struct v4l2_buffer));
    if (!camera->buffers) {
        fprintf(stderr, "Error allocating buffers\n");
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = camera->num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        free(camera->buffers);
        close(fd);
        return -1;
    }

    // Map buffers
    camera->buffer_map = calloc(camera->num_buffers, sizeof(void *));
    if (!camera->buffer_map) {
        fprintf(stderr, "Error allocating buffer map\n");
        free(camera->buffers);
        close(fd);
        return -1;
    }

    for (size_t i = 0; i < camera->num_buffers; i++) {
        camera->buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        camera->buffers[i].memory = V4L2_MEMORY_MMAP;
        camera->buffers[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &camera->buffers[i]) < 0) {
            fprintf(stderr, "Error querying buffer %zu: %s\n", i, strerror(errno));
            // Unmap and free previously mapped buffers
            for (size_t j = 0; j < i; j++) {
                munmap(camera->buffer_map[j], camera->buffers[j].length);
            }
            free(camera->buffer_map);
            free(camera->buffers);
            close(fd);
            return -1;
        }

        camera->buffer_map[i] = mmap(NULL, camera->buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, camera->buffers[i].m.offset);
        if (camera->buffer_map[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %zu: %s\n", i, strerror(errno));
            // Unmap and free previously mapped buffers
            for (size_t j = 0; j < i; j++) {
                munmap(camera->buffer_map[j], camera->buffers[j].length);
            }
            free(camera->buffer_map);
            free(camera->buffers);
            close(fd);
            return -1;
        }
        camera->buffer_size = camera->buffers[i].length;
    }

    return 0;
}

// Function to start streaming
int start_streaming(camera_t *camera) {
    for (size_t i = 0; i < camera->num_buffers; i++) {
        if (ioctl(camera->fd, VIDIOC_QBUF, &camera->buffers[i]) < 0) {
            fprintf(stderr, "Error queuing buffer %zu: %s\n", i, strerror(errno));
            // Dequeue and unmap previously queued buffers
            for (size_t j = 0; j < i; j++) {
                ioctl(camera->fd, VIDIOC_DQBUF, &camera->buffers[j]);
                munmap(camera->buffer_map[j], camera->buffers[j].length);
            }
            free(camera->buffer_map);
            free(camera->buffers);
            close(camera->fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        // Dequeue and unmap all buffers
        for (size_t i = 0; i < camera->num_buffers; i++) {
            ioctl(camera->fd, VIDIOC_DQBUF, &camera->buffers[i]);
            munmap(camera->buffer_map[i], camera->buffers[i].length);
        }
        free(camera->buffer_map);
        free(camera->buffers);
        close(camera->fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame using select()
int capture_frame(camera_t *camera, void **frame_data) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(camera->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(camera->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera->fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *frame_data = camera->buffer_map[buf.index];

    return 0;
}

// Function to stop streaming
int stop_streaming(camera_t *camera) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera->fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to unmap buffers
int unmap_buffers(camera_t *camera) {
    for (size_t i = 0; i < camera->num_buffers; i++) {
        if (munmap(camera->buffer_map[i], camera->buffers[i].length) < 0) {
            fprintf(stderr, "Error unmapping buffer %zu: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to free buffers
int free_buffers(camera_t *camera) {
    free(camera->buffers);
    free(camera->buffer_map);
    return 0;
}

// Function to close the file descriptor
int close_device(camera_t *camera) {
    close(camera->fd);
    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(const void *yuyv_data, unsigned char *rgb_data, int width, int height) {
    const unsigned char *src = (const unsigned char *)yuyv_data;
    unsigned char *dest = rgb_data;
    int i, j;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            // Y0 U Y1 V
            unsigned char y0 = src[0];
            unsigned char u = src[1];
            unsigned char y1 = src[2];
            unsigned char v = src[3];

            // Convert YUV to RGB
            int r0 = (int)(1.164 * y0 + 2.018 * v);
            int g0 = (int)(1.164 * y0 - 0.813 * v - 0.391 * u);
            int b0 = (int)(1.164 * y0 + 1.596 * u);

            int r1 = (int)(1.164 * y1 + 2.018 * v);
            int g1 = (int)(1.164 * y1 - 0.813 * v - 0.391 * u);
            int b1 = (int)(1.164 * y1 + 1.596 * u);

