            dest[0] = r1;
            dest[1] = g1;
            dest[2] = b1;
            dest += 3;

            src += 4;
        }
    }
}

// Function to apply a simple blur filter
void blur_filter(unsigned char *rgb_data, int width, int height) {
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        fprintf(stderr, "Error allocating temporary buffer for blur filter\n");
        return;
    }

    for (int y = 1; y < height - 1; y++) {
        for (int x = 1; x < width - 1; x++) {
            int index = y * width * 3 + x * 3;
            int sum_r = 0, sum_g = 0, sum_b = 0;

            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    sum_r += rgb_data[(y + dy) * width * 3 + (x + dx) * 3];
                    sum_g += rgb_data[(y + dy) * width * 3 + (x + dx) * 3 + 1];
                    sum_b += rgb_data[(y + dy) * width * 3 + (x + dx) * 3 + 2];
                }
            }

            temp[index] = sum_r / 9;
            temp[index + 1] = sum_g / 9;
            temp[index + 2] = sum_b / 9;
        }
    }

    // Copy the blurred image back to the original buffer
    memcpy(rgb_data, temp, width * height * 3);

    free(temp);
}

// Function to encode the image as JPEG
int encode_jpeg(const unsigned char *rgb_data, int width, int height, int quality, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening output file %s: %s\n", filename, strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3; // RGB

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb_data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

