#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

// Function to check if a file exists
int file_exists(const char *filename) {
    struct stat buffer;
    return (stat(filename, &buffer) == 0);
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_device_caps(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) == -1) {
        fprintf(stderr, "Error querying device capabilities: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, struct v4l2_fmtdesc *fmt, struct v4l2_frmsizeenum *frmsize) {
    memset(frmsize, 0, sizeof(struct v4l2_frmsizeenum));
    frmsize->index = 0;
    frmsize->pixel_format = fmt->pixelformat;

    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, frmsize) == 0) {
        if (frmsize->type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  Resolution: %dx%d\n", frmsize->discrete.width, frmsize->discrete.height);
        }
        frmsize->index++;
    }
    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, struct v4l2_frmsizeenum *frmsize, struct v4l2_frmivalenum *frmival) {
