#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_PIN 4
#define TILT_PIN 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Global variables for pulse widths
int pan_pulse_width = CENTER_PULSE_WIDTH;
int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_servo_pulse_width(int pin, int pulse_width);
int read_button(int pin);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PAN_PIN, 0); // Stop PWM on pan servo
    gpioPWM(TILT_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Initialize GPIO pins and PWM
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON, PI_INPUT);
    gpioSetMode(DOWN_BUTTON, PI_INPUT);
    gpioSetMode(LEFT_BUTTON, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Set servo pulse width
void set_servo_pulse_width(int pin, int pulse_width) {
    gpioPWM(pin, pulse_width);
}

// Read button state
int read_button(int pin) {
    return !gpioRead(pin); // Active low
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d\n", PAN_PIN, TILT_PIN);
    printf("Center Position: %d us\n", CENTER_PULSE_WIDTH);

    // Main loop
    while (1) {
        // Read button states
        int up_pressed = read_button(UP_BUTTON);
        int down_pressed = read_button(DOWN_BUTTON);
        int left_pressed = read_button(LEFT_BUTTON);
        int right_pressed = read_button(RIGHT_BUTTON);

        // Adjust pan servo
        if (left_pressed) {
            pan_pulse_width = (pan_pulse_width > MIN_PULSE_WIDTH) ? pan_pulse_width - 10 : MIN_PULSE_WIDTH;
        } else if (right_pressed) {
            pan_pulse_width = (pan_pulse_width < MAX_PULSE_WIDTH) ? pan_pulse_width + 10 : MAX_PULSE_WIDTH;
        }

        // Adjust tilt servo
        if (up_pressed) {
            tilt_pulse_width = (tilt_pulse_width > MIN_PULSE_WIDTH) ? tilt_pulse_width - 10 : MIN_PULSE_WIDTH;
        } else if (down_pressed) {
            tilt_pulse_width = (tilt_pulse_width < MAX_PULSE_WIDTH) ? tilt_pulse_width + 10 : MAX_PULSE_WIDTH;
        }

        // Set servo pulse widths
        set_servo_pulse_width(PAN_PIN, pan_pulse_width);
        set_servo_pulse_width(TILT_PIN, tilt_pulse_width);

        // Delay
        gpioDelay(50); // 50 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

