} ProgramState;

ProgramState state = {1, "", 0, 0};

// Function prototypes
int init_gpio();
int read_pir_sensor();
int capture_image(char *filename);
char *format_json(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp);
int post_data(const char *json_payload, const char *filename);
void signal_handler(int signal);
void cleanup();

// Initialize GPIO
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(PIR_PIN, INPUT);
    pullUpDnControl(PIR_PIN, PUD_DOWN);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return digitalRead(PIR_PIN);
}

// Capture image using raspistill
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -q %d", filename, JPEG_QUALITY);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Format data into JSON string
char *format_json(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    char *json_string = malloc(512); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error allocating memory for JSON string\n");
        return NULL;
    }

    snprintf(json_string, 512, "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}", filename, timestamp, motion_status, gpio_pin);
    return json_string;
}

// Write callback function for libcurl
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    return real_size;
}

// Post data to HTTP endpoint
int post_data(const char *json_payload, const char *filename) {
    CURL *curl;
    CURLcode res;
    char url[256];

    snprintf(url, sizeof(url), "http://%s:%d/upload", state.ip_address, state.port);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        // Set the filename for the image data
        curl_easy_setopt(curl, CURLOPT_HTTPPOST, NULL); // Remove default HTTP POST

        struct curl_httppost *formpost = NULL;
        struct curl_httppost *lastptr = NULL;

        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image_file", CURLFORM_FILE, filename, CURLFORM_END);

        curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        // Clean up
        curl_formfree(formpost);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signal);
    state.running = 0;
}

// Cleanup resources
void cleanup() {
    // No specific cleanup needed for wiringPi or libcurl in this example
    // but you might want to add code here to release resources if needed
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP address> <port number>\n", argv[0]);
        return 1;
    }

    strncpy(state.ip_address, argv[1], sizeof(state.ip_address) - 1);
    state.ip_address[sizeof(state.ip_address) - 1] = '\0'; // Ensure null termination
    state.port = atoi(argv[2]);

    if (init_gpio() == -1) {
        return 1;
    }

    // Create motion_captures directory if it doesn't exist
    struct stat st = {0};
    if (stat(MOTION_CAPTURE_DIR, &st) == -1) {
        if (mkdir(MOTION_CAPTURE_DIR, 0777) == -1) {
            fprintf(stderr, "Error creating directory: %s\n", strerror(errno));
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (state.running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            time_t current_time = time(NULL);
            if (difftime(current_time, state.last_motion_time) >= DEBOUNCE_TIME) {
                char filename[64];
                snprintf(filename, sizeof(filename), "%s/motion_%s", MOTION_CAPTURE_DIR, __TIME__);

                if (capture_image(filename) == 0) {
                    char timestamp[32];
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);
                    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02dT%02d:%02d:%02d.%06ldZ",
                             ts.tv_sec / 3600 % 24, ts.tv_sec / 3600 / 24 % 12 + 12 * (ts.tv_sec / 3600 / 24 > 12), ts.tv_sec / 3600 / 24 % 12 > 12 ? 0 : 1,
                             ts.tv_sec % 3600 / 60, ts.tv_sec % 60, ts.tv_nsec / 1000000, ts.tv_nsec % 1000000);

                    char *json_payload = format_json(filename, timestamp, 1, PIR_PIN);
                    if (json_payload != NULL) {
                        printf("Motion detected! Capturing image and posting data.\n");
                        if (post_data(json_payload, filename) == 0) {
                            printf("Data posted successfully.\n");
                        } else {
                            fprintf(stderr, "Failed to post data.\n");
                        }
                        free(json_payload);
                    }
                }
                state.last_motion_time = current_time;
            }
        }
        delay(POLLING_INTERVAL);
    }

    cleanup();
    return 0;
}

