#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate a timestamped filename
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[100];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), IMAGE_DIR "/%Y%m%d_%H%M%S_%3N.jpg", timeinfo);
    return strdup(filename); // Allocate memory for the filename
}

// Function to capture an image using raspistill
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -w 640 -h 480 -q 85 -t 2000 --nopreview", filename);
    int status = system(command);
    return status;
}

// Function to log messages to a file
void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written immediately
}

// Function to handle motion detection
void handle_motion() {
    char *filename = generate_filename();
    if (filename == NULL) {
        log_message("Error generating filename.");
        return;
    }

    int status = capture_image(filename);
    if (status == 0) {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Image captured: %s", filename);
        log_message(log_message_buffer);
    } else {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Image capture failed with status: %d", status);
        log_message(log_message_buffer);
    }

    free(filename); // Free the allocated memory
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with falling edge detection
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Optional: pull-down resistor
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable default alert function

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_state = 1; // Initialize to no motion
    unsigned int last_tick = 0;

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state == 0 && last_state == 1) { // Falling edge detected
            unsigned int now = gpioTick();
            if (now - last_tick > DEBOUNCE_TIME_MS * 1000) { // Debounce
                handle_motion();
                last_tick = now;
            }
        }

        last_state = current_state;
        gpioDelay(10); // Check every 10ms
    }

    // Cleanup
    gpioTerminate();
    fclose(log_file);
    printf("Exiting.\n");
    return 0;
}

