#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FILENAME "cropped.yuv"

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;
int fd = -1;
void *buffer = NULL;
size_t buffer_size = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to initialize the V4L2 device
int init_v4l2_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to configure the V4L2 device
int configure_v4l2_device(int fd, int width, int height, enum v4l2_pix_format format, enum v4l2_field field) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = format;
    fmt.fmt.pix.field = field;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, int count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    return 0;
}

// Function to map a buffer
int map_buffer(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0; // Use the first buffer

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        return -1;
    }

    *buffer_size = buf.length;
    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }

    return 0;
}

// Function to unmap a buffer
int unmap_buffer(int fd, void *buffer) {
    if (munmap(buffer, buffer_size) == -1) {
        perror("Error unmapping buffer");
        return -1;
    }
    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(int fd, void *buffer, size_t buffer_size) {
    fd_set fds;
    struct timeval tv;
    struct v4l2_buffer buf;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // 2-second timeout
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error in select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to verify the frame
int verify_frame(void *buffer, size_t buffer_size, int width, int height, enum v4l2_pix_format format) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_G_FMT, &fmt) == -1) {
        perror("Error getting format");
        return -1;
    }

    if (fmt.fmt.pix.width != width || fmt.fmt.pix.height != height || fmt.fmt.pix.pixelformat != format) {
        fprintf(stderr, "Frame format mismatch: width=%d, height=%d, format=0x%x (expected width=%d, height=%d, format=0x%x)\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height, fmt.fmt.pix.pixelformat, width, height, format);
        return -1;
    }

    return 0;
}

// Function to crop the frame
void crop_frame(void *buffer, int width, int height, int crop_width, int crop_height, int x_offset, int y_offset, uint8_t *cropped_buffer) {
    int i, j;
    uint8_t *src = (uint8_t *)buffer;

    for (i = 0; i < crop_height; i++) {
        for (j = 0; j < crop_width; j++) {
            cropped_buffer[(i * crop_width + j) * 2] = src[(y_offset + i) * width * 2 + (x_offset + j) * 2];
            cropped_buffer[(i * crop_width + j) * 2 + 1] = src[(y_offset + i) * width * 2 + (x_offset + j) * 2 + 1];
        }
    }
}

// Function to write the cropped frame to a file
int write_to_file(const char *filename, const uint8_t *cropped_buffer, int cropped_width, int cropped_height) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_buffer, 1, cropped_width * cropped_height * 2, fp);
    if (bytes_written != cropped_width * cropped_height * 2) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the V4L2 device
    fd = init_v4l2_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Configure the V4L2 device
    if (configure_v4l2_device(fd, WIDTH, HEIGHT, V4L2_PIX_FMT_YUYV, V4L2_FIELD_NONE) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd, 1) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    if (map_buffer(fd, &buffer, &buffer_size) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        unmap_buffer(fd, buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the cropped frame
    uint8_t *cropped_buffer = (uint8_t *)malloc(WIDTH * HEIGHT * 2);
    if (cropped_buffer == NULL) {
        perror("Error allocating memory for cropped buffer");
        stop_streaming(fd);
        unmap_buffer(fd, buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        // Capture a frame
        if (capture_frame(fd, buffer, buffer_size) == -1) {
            fprintf(stderr, "Error capturing frame, retrying...\n");
            continue; // Retry capturing the frame
        }

        // Verify the frame
        if (verify_frame(buffer, buffer_size, WIDTH, HEIGHT, V4L2_PIX_FMT_YUYV) == -1) {
            fprintf(stderr, "Frame verification failed, retrying...\n");
            continue; // Retry capturing the frame
        }

        // Crop the frame
        crop_frame(buffer, WIDTH, HEIGHT, 200, 150, 0, 0, cropped_buffer);

        // Write the cropped frame to a file
        if (write_to_file(FILENAME, cropped_buffer, 200, 150) == -1) {
            fprintf(stderr, "Error writing to file, retrying...\n");
            continue; // Retry capturing the frame
        }

        printf("Frame captured and written to %s\n", FILENAME);
    }

    // Clean up
    printf("Cleaning up...\n");
    stop_streaming(fd);
    unmap_buffer(fd, buffer);
    free(cropped_buffer);
    close(fd);

    return EXIT_SUCCESS;
}

