#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define PWM range (adjust as needed for your servo)
#define PWM_RANGE 2000

// Define neutral angle (90 degrees)
#define NEUTRAL_ANGLE 90

// Define PWM pulse width for neutral angle (adjust as needed for your servo)
#define NEUTRAL_PWM 1500

// Global variables for current angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int initialize_gpio();
void set_servo_angle(int gpio, int angle);
void handle_input(int input);
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the pigpio library and set up GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Set initial servo angles to neutral
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);

    return 0; // Indicate success
}

// Function to set the servo angle using PWM
void set_servo_angle(int gpio, int angle) {
    // Validate angle
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return;
    }

    // Calculate PWM pulse width (adjust the formula as needed for your servo)
    int pulse_width = NEUTRAL_PWM + (angle - NEUTRAL_ANGLE) * (PWM_RANGE / 180.0);

    // Set PWM duty cycle
    gpioPWM(gpio, pulse_width);
}

// Function to handle user input
void handle_input(int input) {
    switch (input) {
        case 'a': // Left arrow key
            pan_angle -= 5;
            if (pan_angle < 0) pan_angle = 0;
            set_servo_angle(PAN_GPIO, pan_angle);
            break;
        case 'd': // Right arrow key
            pan_angle += 5;
            if (pan_angle > 180) pan_angle = 180;
            set_servo_angle(PAN_GPIO, pan_angle);
            break;
        case 'w': // Up arrow key
            tilt_angle += 5;
            if (tilt_angle > 180) tilt_angle = 180;
            set_servo_angle(TILT_GPIO, tilt_angle);
            break;
        case 's': // Down arrow key
            tilt_angle -= 5;
            if (tilt_angle < 0) tilt_angle = 0;
            set_servo_angle(TILT_GPIO, tilt_angle);
            break;
        case 'q': // Quit
            printf("Exiting program\n");
            cleanup_gpio();
            exit(0);
            break;
        default:
            break;
    }
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    // Set servos to neutral position
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);

    // Terminate pigpio library
    gpioTerminate();
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Servo control program started. Press 'a', 'd', 'w', 's' to control pan and tilt. Press 'q' to quit.\n");

    // Main loop
    while (1) {
        int input = getchar();
        handle_input(input);
        gpioDelay(100); // Delay for 100ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

