// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_raw;
    float temp_celsius;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_raw / 1000.0;
    return temp_celsius;
