// Function to read CPU usage from file
float read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float cpu_usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        return -1.0; // Indicate error
    }

    // Read initial CPU stats
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fclose(fp);
        return -1.0; // Indicate error
    }

    sleep(1);

    // Read CPU stats again
    rewind(fp);
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);

    // Calculate CPU usage
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle - prev_idle;

    if (delta_total == 0) {
        cpu_usage = 0.0;
    } else {
        cpu_usage = 100.0 * (delta_total - delta_idle) / delta_total;
    }

    return cpu_usage;
}

// Function to initialize the OLED display
void oled_init() {
    oled_write_command(0xAE); // Display off
    oled_write_command(0xD5); // Set display clock divide ratio/oscillator frequency
    oled_write_command(0x80); // Default value
    oled_write_command(0xA8); // Set multiplex ratio
    oled_write_command(0x3F); // 63 COM lines
    oled_write_command(0xD3); // Set display offset
    oled_write_command(0x00); // No offset
    oled_write_command(0x40); // Set start line address
    oled_write_command(0x8D); // Charge pump setting
    oled_write_command(0x14); // Enable charge pump
    oled_write_command(0x20); // Set memory addressing mode
    oled_write_command(0x00); // Horizontal addressing mode
    oled_write_command(0xA1); // Set segment re-map
    oled_write_command(0xC8); // Set COM output scan direction
    oled_write_command(0xDA); // Set COM pins hardware configuration
    oled_write_command(0x12); // Alternative COM pin configuration
    oled_write_command(0x81); // Set contrast control
    oled_write_command(0xCF); // Set contrast to 207
    oled_write_command(0xD9); // Set pre-charge period
    oled_write_command(0xF1); // Set pre-charge period
    oled_write_command(0xDB); // Set VCOMH deselect level
    oled_write_command(0x40); // Set VCOMH deselect level
    oled_write_command(0xA4); // Entire display ON/OFF
    oled_write_command(0xA6); // Set normal display
    oled_write_command(0xAF); // Display on
}

// Function to clear the OLED display
void oled_clear() {
    for (int i = 0; i < OLED_WIDTH * OLED_HEIGHT / 8; i++) {
        oled_write_data(0x00);
    }
}

// Function to write a command to the OLED display
void oled_write_command(unsigned char command) {
    unsigned char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing command to I2C: %s\n", strerror(errno));
    }
}

// Function to write data to the OLED display
void oled_write_data(unsigned char data) {
    unsigned char buf[2];
    buf[0] = 0x40; // Control byte: data
    buf[1] = data;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing data to I2C: %s\n", strerror(errno));
    }
}

// Function to display text on the OLED display
void oled_display_text(int x, int y, const char *text) {
    int i, j;
    for (i = 0; text[i] != '\0'; i++) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 10; // Map A-Z to 10-35
        } else if (c >= '0' && c <= '9') {
            c = c - '0' + 36; // Map 0-9 to 36-45
        } else if (c == ' ') {
            c = 0; // Map space to 0
        } else {
            continue; // Skip other characters
        }

        for (j = 0; j < 5; j++) {
            unsigned char pixel_data = font[c][j];
            for (int k = 0; k < 8; k++) {
                if ((pixel_data >> k) & 0x01) {
                    oled_set_pixel(x + j, y + i, 1); // Set pixel to 1 (white)
                } else {
                    oled_set_pixel(x + j, y + i, 0); // Set pixel to 0 (black)
                }
            }
        }
    }
}

// Function to display an error message on the OLED display
void oled_display_error(const char *error_message) {
    oled_clear();
    oled_display_text(0, 0, error_message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    oled_clear();
    close(i2c_fd);
    exit(0);
}

// Function to set a pixel on the OLED display
void oled_set_pixel(int x, int y, int color) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) {
        return; // Out of bounds
    }

    int page = y / 8;
    int bit = y % 8;
    int index = x + (page * OLED_WIDTH);

    oled_write_command(0xB0 + page); // Set page address
    oled_write_command(0x00 + (x & 0x0F)); // Set lower column address
    oled_write_command(0x10 + ((x >> 4) & 0x0F)); // Set higher column address

    if (color) {
        oled_write_data(0x01); // Set bit to 1
    } else {
        oled_write_data(0x00); // Set bit to 0
    }
}

int main() {
    float cpu_temp, cpu_usage;
    char temp_str[20], usage_str[20];
    char error_message[100];

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = wiringPiI2CSetup(I2C_BUS);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize OLED display
    oled_init();
    oled_clear();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    while (1) {
        // Read CPU temperature and usage
        cpu_temp = read_cpu_temp();
        cpu_usage = read_cpu_usage();

        // Format the data into strings
        if (cpu_temp >= 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", cpu_temp);
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: Error");
        }

        if (cpu_usage >= 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", cpu_usage);
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: Error");
        }

        // Display the data on the OLED
        oled_clear();
        oled_display_text(0, 0, temp_str);
        oled_display_text(0, 16, usage_str);

        // Check for errors and display error message
        if (cpu_temp < 0 || cpu_usage < 0) {
            snprintf(error_message, sizeof(error_message), "Error reading data");
            oled_display_error(error_message);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

