    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing data to I2C: %s\n", strerror(errno));
    }
}

// Function to display text on the OLED display
void oled_display_text(int x, int y, const char *text) {
    int i, j;
    for (i = 0; text[i] != '\0'; i++) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = c - 'A' + 10; // Map A-Z to 10-35
        } else if (c >= '0' && c <= '9') {
            c = c - '0' + 36; // Map 0-9 to 36-45
        } else if (c == ' ') {
            c = 0; // Map space to 0
        } else {
            continue; // Skip other characters
        }

        for (j = 0; j < 5; j++) {
            unsigned char pixel_data = font[c][j];
            for (int k = 0; k < 8; k++) {
                if ((pixel_data >> k) & 0x01) {
                    oled_set_pixel(x + j, y + i, 1); // Set pixel to 1 (white)
                } else {
                    oled_set_pixel(x + j, y + i, 0); // Set pixel to 0 (black)
                }
            }
        }
    }
}

// Function to display an error message on the OLED display
void oled_display_error(const char *error_message) {
    oled_clear();
    oled_display_text(0, 0, error_message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    oled_clear();
    close(i2c_fd);
    exit(0);
}

// Function to set a pixel on the OLED display
void oled_set_pixel(int x, int y, int color) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) {
        return; // Out of bounds
    }

    int page = y / 8;
    int bit = y % 8;
    int index = x + (page * OLED_WIDTH);

    oled_write_command(0xB0 + page); // Set page address
    oled_write_command(0x00 + (x & 0x0F)); // Set lower column address
    oled_write_command(0x10 + ((x >> 4) & 0x0F)); // Set higher column address

    if (color) {
        oled_write_data(0x01); // Set bit to 1
    } else {
        oled_write_data(0x00); // Set bit to 0
    }
}

int main() {
    float cpu_temp, cpu_usage;
    char temp_str[20], usage_str[20];
    char error_message[100];

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = wiringPiI2CSetup(I2C_BUS);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize OLED display
    oled_init();
    oled_clear();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    while (1) {
        // Read CPU temperature and usage
        cpu_temp = read_cpu_temp();
        cpu_usage = read_cpu_usage();

        // Format the data into strings
        if (cpu_temp >= 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", cpu_temp);
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: Error");
        }

        if (cpu_usage >= 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", cpu_usage);
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: Error");
        }

        // Display the data on the OLED
        oled_clear();
        oled_display_text(0, 0, temp_str);
        oled_display_text(0, 16, usage_str);

        // Check for errors and display error message
        if (cpu_temp < 0 || cpu_usage < 0) {
            snprintf(error_message, sizeof(error_message), "Error reading data");
            oled_display_error(error_message);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

