#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int lcd_fd;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulses);
void log_data(double flow_rate, double total_volume);
void lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void lcd_string(const char *s);
void signal_handler(int signal);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Function to calculate flow rate
double calculate_flow_rate(int pulses)
{
    return (double)pulses / PULSES_PER_LITER * 60.0; // Liters per minute
}

// Function to log data to the console
void log_data(double flow_rate, double total_volume)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Flow Rate: %.2f LPM, Total Volume: %.2f Liters\n", timestamp, flow_rate, total_volume);
}

// LCD initialization function
void lcd_init()
{
    lcd_fd = wiringPiI2CSetup(I2C_ADDR);
    if (lcd_fd == -1)
    {
        fprintf(stderr, "Error initializing I2C communication.\n");
        exit(1);
    }

    // Initialize LCD in 4-bit mode
    delay(50); // Wait for more than 4.1ms after VCC rises to 2.7V
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    lcd_send_command(0x06); // Increment cursor, no shift
    lcd_clear();
}

// Function to clear the LCD
void lcd_clear()
{
    lcd_send_command(0x01); // Clear display
    delay(2);              // Delay for clear display command
}

// Function to send a command to the LCD
void lcd_send_command(unsigned char command)
{
    unsigned char upper = command & 0xF0;
    unsigned char lower = (command << 4) & 0xF0;

    wiringPiI2CWriteReg8(lcd_fd, 0x00, upper | 0x04); // En = 1
    wiringPiI2CWriteReg8(lcd_fd, 0x00, upper & 0x0F); // En = 0
    delay(1);

    wiringPiI2CWriteReg8(lcd_fd, 0x00, lower | 0x04); // En = 1
    wiringPiI2CWriteReg8(lcd_fd, 0x00, lower & 0x0F); // En = 0
    delay(1);
}

// Function to send data to the LCD
void lcd_send_data(unsigned char data)
{
    unsigned char upper = data & 0xF0;
    unsigned char lower = (data << 4) & 0xF0;

    wiringPiI2CWriteReg8(lcd_fd, 0x00, upper | 0x05); // En = 1, RS = 1
    wiringPiI2CWriteReg8(lcd_fd, 0x00, upper & 0x0F); // En = 0
    delay(1);

    wiringPiI2CWriteReg8(lcd_fd, 0x00, lower | 0x05); // En = 1, RS = 1
    wiringPiI2CWriteReg8(lcd_fd, 0x00, lower & 0x0F); // En = 0
    delay(1);
}

// Function to print a string to the LCD
void lcd_string(const char *s)
{
    while (*s)
    {
        lcd_send_data(*s++);
    }
}

// Function to print to a specific row and column
void lcd_print(int row, int col, const char *text)
{
    int address;
    if (row == 0)
    {
        address = 0x80 + col;
    }
    else
    {
        address = 0xC0 + col;
    }
    lcd_send_command(address);
    lcd_string(text);
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt on rising edge
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback);

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);
    time_t last_lcd_update = time(NULL);

    // Main loop
    while (1)
    {
        time_t current_time = time(NULL);

        // Calculate flow rate
        int current_pulses = pulse_count;
        double flow_rate = calculate_flow_rate(current_pulses);

        // Accumulate total volume
        total_volume += (double)current_pulses / PULSES_PER_LITER;

        // Log data every second
        if (difftime(current_time, last_log_time) >= 1.0)
        {
            log_data(flow_rate, total_volume);
            last_log_time = current_time;
        }

        // Update LCD every ten seconds
        if (difftime(current_time, last_lcd_update) >= 10.0)
        {
            lcd_clear();
            char flow_str[32];
            char volume_str[32];

            snprintf(flow_str, sizeof(flow_str), "Flow: %.2f LPM", flow_rate);
            snprintf(volume_str, sizeof(volume_str), "Vol: %.2f Lit", total_volume);

            lcd_print(0, 0, flow_str);
            lcd_print(1, 0, volume_str);
            last_lcd_update = current_time;
        }

        pulse_count = 0; // Reset pulse count
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

