#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>

// Constants
#define ANEMOMETER_PIN 17 // BCM GPIO17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_ADDRESS 0x27 // PCF8574 I2C address
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define WIND_SPEED_SCALE 1.2 // Example scaling factor
#define WIND_SPEED_OFFSET 0.5 // Example offset
#define WIND_DIRECTION_RESOLUTION 16 // Number of directions
#define ADC_CHANNEL 0 // MCP3008 channel for wind vane
#define ADC_MIN 0
#define ADC_MAX 1023
#define ADC_MIN_VALUE 0
#define ADC_MAX_VALUE 1023
#define ADC_MIN_READINGS 5
#define ADC_MAX_READINGS 5
#define ADC_STABILITY_THRESHOLD 10

// Global variables
volatile int pulse_count = 0;
volatile bool running = true;
int spi_fd;
int i2c_fd;

// Function prototypes
void anemometer_interrupt_handler(void);
float calculate_wind_speed(int pulse_count);
int read_wind_direction(int spi_fd);
void lcd_init(int i2c_fd);
void lcd_clear(int i2c_fd);
void lcd_set_cursor(int i2c_fd, int row, int col);
void lcd_print(int i2c_fd, const char *text);
void display_data(int i2c_fd, float wind_speed, int wind_direction);
void signal_handler(int signal);
int read_adc(int spi_fd, int channel);
bool is_adc_stable(int spi_fd, int channel);

// Anemometer interrupt handler
void anemometer_interrupt_handler(void) {
    pulse_count++;
}

// Calculate wind speed from pulse count
float calculate_wind_speed(int pulse_count) {
    return (float)pulse_count * WIND_SPEED_SCALE + WIND_SPEED_OFFSET;
}

// Read wind direction from MCP3008 ADC
int read_wind_direction(int spi_fd) {
    int adc_value = read_adc(spi_fd, ADC_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1; // Indicate error
    }

    // Map ADC value to wind direction (0-15)
    int direction = (int)((float)adc_value / ADC_MAX * WIND_DIRECTION_RESOLUTION);
    if (direction >= WIND_DIRECTION_RESOLUTION) {
        direction = WIND_DIRECTION_RESOLUTION - 1;
    }
    if (direction < 0) {
        direction = 0;
    }

    return direction;
}

// Initialize LCD
void lcd_init(int i2c_fd) {
    // Initialization sequence (refer to PCF8574 datasheet)
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x03); // Function set: 8-bit interface
    delay(5);
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x03); // Function set: 8-bit interface
    delay(1);
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x03); // Function set: 8-bit interface
    delay(1);
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x02); // Function set: 4-bit interface
    delay(1);
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x28); // Function set: 4-bit, 2 lines, 5x8 font
    delay(1);
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x0C); // Display control: Display on, cursor off, blink off
    delay(1);
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x01); // Clear display
    delay(2);
}

// Clear LCD display
void lcd_clear(int i2c_fd) {
    wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x01); // Clear display command
    delay(2); // Wait for clear command to complete
}

// Set LCD cursor position
void lcd_set_cursor(int i2c_fd, int row, int col) {
    int address;
    if (row == 0) {
        address = 0x80 + col;
    } else {
        address = 0xC0 + col;
    }
    wiringPiI2CWriteReg8(i2c_fd, 0x00, address);
}

// Print text to LCD
void lcd_print(int i2c_fd, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        wiringPiI2CWriteReg8(i2c_fd, 0x00, text[i]);
    }
}

// Display wind speed and direction on LCD
void display_data(int i2c_fd, float wind_speed, int wind_direction) {
    char speed_str[17];
    char direction_str[17];

    snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
    snprintf(direction_str, sizeof(direction_str), "Dir: %d", wind_direction);

    lcd_clear(i2c_fd);
    lcd_set_cursor(i2c_fd, 0, 0);
    lcd_print(i2c_fd, speed_str);
    lcd_set_cursor(i2c_fd, 1, 0);
    lcd_print(i2c_fd, direction_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Read ADC value from MCP3008
int read_adc(int spi_fd, int channel) {
    unsigned char buffer[3];
    int adc_value = -1;
    int retries = 3;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    while (retries > 0) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == 0) {
            adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed, retrying...\n");
            retries--;
            delay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries\n");
    return -1; // Indicate error
}

// Check if ADC readings are stable
bool is_adc_stable(int spi_fd, int channel) {
    int readings[ADC_MIN_READINGS + ADC_MAX_READINGS];
    int min_count = 0;
    int max_count = 0;
    int current_value;
    int i;

    // Read ADC multiple times
    for (i = 0; i < ADC_MIN_READINGS + ADC_MAX_READINGS; i++) {
        current_value = read_adc(spi_fd, channel);
        if (current_value < 0) {
            fprintf(stderr, "Error reading ADC during stability check\n");
            return false; // Assume unstable if read fails
        }
        readings[i] = current_value;
        delay(10); // Small delay between readings
    }

    // Find the most frequent value (mode)
    for (i = 0; i < ADC_MIN_READINGS + ADC_MAX_READINGS; i++) {
        int count = 0;
        for (int j = 0; j < ADC_MIN_READINGS + ADC_MAX_READINGS; j++) {
            if (readings[j] == readings[i]) {
                count++;
            }
        }
        if (count > max_count) {
            max_count = count;
        }
        if (count > min_count) {
            min_count = count;
        }
    }

    // Check if the most frequent value occurs frequently enough
    if (max_count >= ADC_STABILITY_THRESHOLD) {
        return true;
    } else {
        return false;
    }
}

int main(void) {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
