    i2c_fd = wiringPiI2CSetup(I2C_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LCD
    lcd_init(i2c_fd);

    // Set anemometer pin as input with pull-up resistor
    pinMode(ANEMOMETER_PIN, INPUT);
    pullUpDnControl(ANEMOMETER_PIN, PUD_UP);

    // Set up interrupt on rising edge
    if (wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, anemometer_interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_adc_check = time(NULL);

    // Main loop
    while (running) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for sample window
        delay(SAMPLE_WINDOW_MS);

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(pulse_count);

        // Read wind direction
        int wind_direction = read_wind_direction(spi_fd);

        // Display data on LCD
        display_data(i2c_fd, wind_speed, wind_direction);

        // Check ADC stability periodically
        if (time(NULL) - last_adc_check >= 5) {
            if (!is_adc_stable(spi_fd, ADC_CHANNEL)) {
                fprintf(stderr, "Wind vane sensor unstable, check connections!\n");
            }
            last_adc_check = time(NULL);
        }

        // Small delay to avoid busy-waiting
        delay(10);
    }

    // Cleanup
    printf("Cleaning up...\n");
    wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, NULL); // Disable interrupt
    lcd_clear(i2c_fd);
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

