#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define I2C_ADDR 0x27
#define PULSES_PER_LITER 450.0
#define LOG_FILE "flow_log.txt"
#define FLOW_RATE_THRESHOLD 0.5 // L/min
#define LOG_INTERVAL 60 // seconds

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
float calculate_flow_rate(int pulses);
void display_flow_rate(float flow_rate);
void log_flow_rate(float flow_rate);
void signal_handler(int signal);
int initialize_i2c();
void cleanup();

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Calculate flow rate in L/min
float calculate_flow_rate(int pulses)
{
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// Display flow rate on LCD1602
void display_flow_rate(float flow_rate)
{
    char buffer[20];
    int result;

    // Clear the LCD
    result = wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x08); // Function set: 8-bit interface
    if (result < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", result);
        return;
    }
    result = wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x00); // Display control: Display on, cursor off, blink off
    if (result < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", result);
        return;
    }
    result = wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x06); // Entry mode set: Increment cursor, no shift
    if (result < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", result);
        return;
    }
    result = wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x01); // Clear display
    if (result < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", result);
        return;
    }
    result = wiringPiI2CWriteReg8(i2c_fd, 0x00, 0x80); // Set DDRAM address to 0
    if (result < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", result);
        return;
    }

    snprintf(buffer, sizeof(buffer), "Flow Rate:");
    for (int i = 0; i < 16; i++)
    {
        result = wiringPiI2CWriteReg8(i2c_fd, 0x40, buffer[i]);
        if (result < 0) {
            fprintf(stderr, "Error writing to LCD: %d\n", result);
            return;
        }
    }

    result = wiringPiI2CWriteReg8(i2c_fd, 0x00, 0xC0); // Set DDRAM address to 0x40
    if (result < 0) {
        fprintf(stderr, "Error writing to LCD: %d\n", result);
        return;
    }

    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    for (int i = 0; i < 16; i++)
    {
        result = wiringPiI2CWriteReg8(i2c_fd, 0x40, buffer[i]);
        if (result < 0) {
            fprintf(stderr, "Error writing to LCD: %d\n", result);
            return;
        }
    }
}

// Log flow rate to file
void log_flow_rate(float flow_rate)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f L/min\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize I2C communication
int initialize_i2c()
{
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1)
    {
        fprintf(stderr, "Error initializing I2C communication.\n");
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup()
{
    printf("Cleaning up resources...\n");
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    if (i2c_fd != -1)
    {
        // No specific I2C cleanup function in wiringPi, but good practice to reset the file descriptor
    }
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt on rising edge
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int no_pulse_count = 0;
    time_t last_pulse_time = time(NULL);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running)
    {
        // Reset pulse count
        pulse_count = 0;
        no_pulse_count = 0;
        last_pulse_time = time(NULL);

        // Wait for 1 second
        time_sleep(1.0);

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate
        display_flow_rate(flow_rate);

        // Log flow rate
        log_flow_rate(flow_rate);

        // Check for sensor-absent condition
        time_t current_time = time(NULL);
        if (difftime(current_time, last_pulse_time) > 10) // No pulse for 10 seconds
        {
            no_pulse_count++;
            if (no_pulse_count >= 5) // Log error after 5 consecutive 10-second intervals
            {
                fprintf(stderr, "Sensor absent or malfunction detected!\n");
                fprintf(log_file, "Sensor absent or malfunction detected!\n");
                fflush(log_file);
                no_pulse_count = 0; // Reset the counter
            }
        }
        else
        {
            no_pulse_count = 0; // Reset the counter if pulse is detected
        }

        // Check for low flow rate and log
        if (flow_rate < FLOW_RATE_THRESHOLD)
        {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Low flow rate detected: %.2f L/min\n", timestamp, flow_rate);
            fflush(log_file);
        }

        // Log flow rate every LOG_INTERVAL seconds
        static time_t last_log_time = 0;
        if (time(NULL) - last_log_time >= LOG_INTERVAL) {
            log_flow_rate(flow_rate);
            last_log_time = time(NULL);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

