    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int no_pulse_count = 0;
    time_t last_pulse_time = time(NULL);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running)
    {
        // Reset pulse count
        pulse_count = 0;
        no_pulse_count = 0;
        last_pulse_time = time(NULL);

        // Wait for 1 second
        time_sleep(1.0);

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate
        display_flow_rate(flow_rate);

        // Log flow rate
        log_flow_rate(flow_rate);

        // Check for sensor-absent condition
        time_t current_time = time(NULL);
        if (difftime(current_time, last_pulse_time) > 10) // No pulse for 10 seconds
        {
            no_pulse_count++;
            if (no_pulse_count >= 5) // Log error after 5 consecutive 10-second intervals
            {
                fprintf(stderr, "Sensor absent or malfunction detected!\n");
                fprintf(log_file, "Sensor absent or malfunction detected!\n");
                fflush(log_file);
                no_pulse_count = 0; // Reset the counter
            }
        }
        else
        {
            no_pulse_count = 0; // Reset the counter if pulse is detected
        }

        // Check for low flow rate and log
        if (flow_rate < FLOW_RATE_THRESHOLD)
        {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Low flow rate detected: %.2f L/min\n", timestamp, flow_rate);
            fflush(log_file);
        }

        // Log flow rate every LOG_INTERVAL seconds
        static time_t last_log_time = 0;
        if (time(NULL) - last_log_time >= LOG_INTERVAL) {
            log_flow_rate(flow_rate);
            last_log_time = time(NULL);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

