// Define GPIO pins for rows and columns
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int num_rows = 8;
const int num_cols = 8;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as output
    for (int i = 0; i < num_rows; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set row pin %d as output\n", row_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(row_pins[i], 1); // Initialize to HIGH (common anode)
    }

    // Set column pins as output
    for (int i = 0; i < num_cols; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set column pin %d as output\n", col_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(col_pins[i], 1); // Initialize to HIGH (LED off)
    }

    return 0;
}

// Function to clear the LED matrix
void clear_matrix()
{
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 1); // HIGH
    }
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1); // HIGH
    }
}

// Function to set a specific LED to ON or OFF
void set_led(int row, int col, int state)
{
    if (row < 0 || row >= num_rows || col < 0 || col >= num_cols) {
        fprintf(stderr, "Invalid row or column index\n");
        return;
    }

    gpioWrite(row_pins[row], state); // Set row HIGH or LOW
    gpioWrite(col_pins[col], !state); // Set column LOW or HIGH (common anode)
}

// Function to render the left-to-right wave animation
void render_left_to_right_wave(int frame)
{
    for (int i = 0; i < num_rows; i++) {
        int col = (i + frame) % num_cols;
        set_led(i, col, 0); // Turn on LED
    }
    clear_matrix(); // Clear the rest of the matrix
}

// Function to render the right-to-left wave animation
void render_right_to_left_wave(int frame)
{
    for (int i = 0; i < num_rows; i++) {
        int col = num_cols - 1 - (i + frame) % num_cols;
        set_led(i, col, 0); // Turn on LED
    }
    clear_matrix(); // Clear the rest of the matrix
}

// Function to perform the scanning multiplexing
void scan_matrix()
{
    for (int row = 0; row < num_rows; row++) {
        gpioWrite(row_pins[row], 0); // Set row LOW
        gpioDelay(800); // Delay for 800 us
        clear_matrix(); // Clear the matrix
        gpioWrite(row_pins[row], 1); // Set row HIGH
    }
}

int main()
{
    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int frame = 0;

    // Main loop
    while (!terminate) {
        // Render left-to-right wave
        render_left_to_right_wave(frame);
        scan_matrix();

        // Render right-to-left wave
        render_right_to_left_wave(frame);
        scan_matrix();

        frame = (frame + 1) % num_cols; // Increment frame, wrap around
        gpioDelay(1000); // Delay for 1 ms
    }

    // Cleanup and terminate
    clear_matrix(); // Clear the matrix before exiting
    gpioTerminate(); // Terminate pigpio
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

