#include <string.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(100);        // Wait 100ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Function to log the timestamp to a file
void log_timestamp(const char *timestamp) {
    FILE *fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening proximity.log for writing\n");
        return;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
}

// Function to get the current timestamp in ISO 8601 UTC format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_sensor_value = 1; // Assume initially no object is detected (HIGH)

    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0 && last_sensor_value == 1) {
            // Falling edge detected (HIGH to LOW)
            char timestamp[21];
            get_timestamp(timestamp);
            printf("Object detected at %s\n", timestamp);
            log_timestamp(timestamp);
            blink_led();
        }

        last_sensor_value = sensor_value;
        gpioDelay(100); // Wait 100ms
    }

    // Cleanup GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");

    return 0;
}

