// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int si1145_read_register(int reg);
int si1145_write_register(int reg, int value);
int si1145_read_proximity();
int si1145_read_ambient_light();
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    int part_id;

    // Check the PART_ID register
    part_id = si1145_read_register(SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register.\n");
        return -1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Si1145 sensor found with PART_ID: 0x%02X\n", part_id);

    // Initialize the sensor (example initialization sequence)
    if (si1145_write_register(0x18, 0x0F) < 0) return -1; // PS1_ADCMUX
    if (si1145_write_register(0x17, 0x20) < 0) return -1; // PS1_ADC_GAIN
    if (si1145_write_register(0x03, 0x00) < 0) return -1; // MEAS_RATE
    if (si1145_write_register(0x02, 0x01) < 0) return -1; // HW_KEY
    if (si1145_write_register(0x01, 0x01) < 0) return -1; // Enable

    return 0;
}

// Read a single byte from the Si1145 sensor
int si1145_read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a single byte to the Si1145 sensor
int si1145_write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Read the proximity value from the sensor
int si1145_read_proximity() {
    int low = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    int high = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0 + 1);

    if (low < 0 || high < 0) {
        fprintf(stderr, "Error reading proximity data.\n");
        return -1;
    }

    return (high << 8) | low;
}

// Read the ambient light value from the sensor
int si1145_read_ambient_light() {
    int low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    int high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0 + 1);

    if (low < 0 || high < 0) {
        fprintf(stderr, "Error reading ambient light data.\n");
        return -1;
    }

    return (high << 8) | low;
}

// Log the data to a file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = si1145_read_proximity();
        int ambient_light = si1145_read_ambient_light();

        if (proximity >= 0 && ambient_light >= 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

