#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Configuration values
#define APDS9960_PROX_EN 0x01
#define APDS9960_ALS_EN 0x02
#define APDS9960_POWER_ON 0x01
#define APDS9960_ALS_AUTO 0x00
#define APDS9960_GAIN_1X 0x00
#define APDS9960_AGAIN_100MS 0x00
#define APDS9960_PTIME_100MS 0x00
#define APDS9960_WTIME_100MS 0x00
#define APDS9960_PPULSE_10US 0x00
#define APDS9960_CONTROL_DEFAULT 0x00
#define APDS9960_CONFIG1_DEFAULT 0x00

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_apds9960();
int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *proximity);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the APDS9960 sensor
int initialize_apds9960() {
    int status;

    // Enable proximity and ALS
    status = i2cWriteByteData(i2c_handle, APDS9960_ENABLE, APDS9960_PROX_EN | APDS9960_ALS_EN);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960_ENABLE register: %d\n", status);
        return -1;
    }

    // Set ALS integration time
    status = i2cWriteByteData(i2c_handle, APDS9960_ATIME, APDS9960_AGAIN_100MS);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960_ATIME register: %d\n", status);
        return -1;
    }

    // Set proximity time
    status = i2cWriteByteData(i2c_handle, APDS9960_PTIME, APDS9960_PTIME_100MS);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960_PTIME register: %d\n", status);
        return -1;
    }

    // Set wait time
    status = i2cWriteByteData(i2c_handle, APDS9960_WTIME, APDS9960_WTIME_100MS);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960_WTIME register: %d\n", status);
        return -1;
    }

    // Set proximity pulse length
    status = i2cWriteByteData(i2c_handle, APDS9960_PPULSE, APDS9960_PPULSE_10US);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960_PPULSE register: %d\n", status);
        return -1;
    }

    // Set control register (default)
    status = i2cWriteByteData(i2c_handle, APDS9960_CONTROL, APDS9960_CONTROL_DEFAULT);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960_CONTROL register: %d\n", status);
        return -1;
    }

    // Set config1 register (default)
    status = i2cWriteByteData(i2c_handle, APDS9960_CONFIG1, APDS9960_CONFIG1_DEFAULT);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960_CONFIG1 register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read data from the APDS9960 sensor
int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *proximity) {
    int status;
    uint8_t buffer[8];

    // Read color data (L, G, R, B)
    status = i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL, (char *)buffer, 8);
    if (status < 0) {
        fprintf(stderr, "Error reading color data: %d\n", status);
        return -1;
    }

    *red = (uint16_t)buffer[1] << 8 | buffer[0];
    *green = (uint16_t)buffer[3] << 8 | buffer[2];
    *blue = (uint16_t)buffer[5] << 8 | buffer[4];

    // Read proximity data
    status = i2cReadI2CBlockData(i2c_handle, APDS9960_PDATA, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", status);
        return -1;
    }

    *proximity = (uint16_t)buffer[1] << 8 | buffer[0];

    return 0;
}

// Function to log data to a CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

