    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (initialize_apds9960() != 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_apds9960_data(&red, &green, &blue, &proximity);
        if (status == 0) {
            // Check proximity threshold
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            // Attempt to re-initialize the sensor
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit if re-initialization fails
            } else {
                if (initialize_apds9960() != 0) {
                    fprintf(stderr, "APDS9960 re-initialization failed\n");
                    terminate = 1; // Exit if re-initialization fails
                }
            }
        }

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup
    printf("Closing I2C bus...\n");
    i2cClose(i2c_handle);
    printf("Closing log file...\n");
    fclose(log_file);
    printf("Terminating pigpio...\n");
    gpioTerminate();

    return 0;
}

