#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses (Example - refer to datasheet for complete list)
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L0X_REG_SYSRANGE_START 0x0040
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0083
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0084
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// GPIO pin for trigger input
#define TRIGGER_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor();
int configure_sensor();
int read_distance();
int log_distance(int distance);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the VL53L0X sensor
int verify_sensor() {
    char model_id;
    int result = i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading model ID: %d\n", result);
        return -1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02x\n", model_id);
        return -1;
    }

    return 0;
}

// Function to configure the VL53L0X sensor
int configure_sensor() {
    // Example configuration (refer to datasheet for optimal settings)
    char data[2];

    // Example: Set timing budget (adjust as needed)
    data[0] = 0x00; // Register address
    data[1] = 0x00; // Value
    int result = i2cWriteI2CBlockData(i2c_handle, 0x001E, data + 1, 1); // Example register
    if (result != 1) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

    // Example: Set inter-measurement period (adjust as needed)
    data[0] = 0x00; // Register address
    data[1] = 0x0A; // Value
    result = i2cWriteI2CBlockData(i2c_handle, 0x001F, data + 1, 1); // Example register
    if (result != 1) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance() {
    char data[1];
    int distance = -1; // Initialize to error value
    int timeout_count = 0;

    // Start a single measurement
    data[0] = 0x01; // Value to write to start bit
    if (i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_SYSRANGE_START, data, 1) != 1) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for the measurement to complete (polling RESULT_INTERRUPT_STATUS)
    while (timeout_count < 10) {
        data[0] = 0x00; // Dummy data for reading
        if (i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, data, 1) != 1) {
            fprintf(stderr, "Error writing to sensor for interrupt status\n");
            return -1;
        }

        if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, data, 1) != 1) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }

        if (data[0] & 0x04) { // Check bit 2 for new result
            break;
        }

        gpioDelay(10000); // 10ms delay
        timeout_count++;
    }

    if (timeout_count >= 10) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    data[0] = 0x00; // Dummy data for reading
    if (i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 1) != 1) {
        fprintf(stderr, "Error writing to sensor for distance\n");
        return -1;
    }

    char distance_data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    distance = (distance_data[0] << 8) | distance_data[1];

    return distance;
}

// Function to log the distance to a file
int log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Wait for falling edge on trigger pin
        if (gpioRead(TRIGGER_PIN) == 0) {
            gpioDelay(100000); // Debounce delay (100ms)
            if (gpioRead(TRIGGER_PIN) == 0) {
                // Read distance
                int distance = read_distance();
                if (distance >= 0) {
                    // Log distance
                    if (log_distance(distance) != 0) {
                        fprintf(stderr, "Error logging distance\n");
                    }
                } else {
                    fprintf(stderr, "Error reading distance\n");
                }
            }
        }
        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

