        return -1;
    }

    // Example: Set inter-measurement period (adjust as needed)
    data[0] = 0x00; // Register address
    data[1] = 0x0A; // Value
    result = i2cWriteI2CBlockData(i2c_handle, 0x001F, data + 1, 1); // Example register
    if (result != 1) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

