// Function to read the distance from the VL53L0X sensor
int read_distance() {
    char data[1];
    int distance = -1; // Initialize to error value
    int timeout_count = 0;

    // Start a single measurement
    data[0] = 0x01; // Value to write to start bit
    if (i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_SYSRANGE_START, data, 1) != 1) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for the measurement to complete (polling RESULT_INTERRUPT_STATUS)
    while (timeout_count < 10) {
        data[0] = 0x00; // Dummy data for reading
        if (i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, data, 1) != 1) {
            fprintf(stderr, "Error writing to sensor for interrupt status\n");
            return -1;
        }

        if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, data, 1) != 1) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }

        if (data[0] & 0x04) { // Check bit 2 for new result
            break;
        }

        gpioDelay(10000); // 10ms delay
        timeout_count++;
    }

    if (timeout_count >= 10) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    data[0] = 0x00; // Dummy data for reading
    if (i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 1) != 1) {
        fprintf(stderr, "Error writing to sensor for distance\n");
        return -1;
    }

    char distance_data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    distance = (distance_data[0] << 8) | distance_data[1];

    return distance;
}

