#define I2C_ADDRESS 0x50
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_DELAY_MS 10
#define SAMPLING_PERIOD_MS 100
#define NUM_SAMPLES 10
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint8_t header;
    uint16_t distance;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int verify_header(uint8_t header);
uint16_t extract_distance(const uint8_t *data);
float calculate_average_distance(uint16_t *distances, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

