int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char write_data[4] = {0x01, 0x02, 0x03, 0x04}; // Example command
    char read_data[15];

    if (i2cWriteDevice(i2c_handle, write_data, 4) != 4) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(SAMPLE_DELAY_MS); // Delay before reading

    if (i2cReadDevice(i2c_handle, read_data, 15) != 15) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
