#include <string.h>
#include <errno.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0083
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0084
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l0x();
int read_distance();
void print_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L0X sensor
int init_vl53l0x() {
    int model_id;

    // Read model ID register
    model_id = i2cReadWordData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    // Check if model ID matches expected value (0xEEAA)
    if (model_id != 0xEEAA) {
        fprintf(stderr, "Error: Incorrect model ID (0x%X). Expected 0xEEAA.\n", model_id);
        return -1;
    }

    printf("VL53L0X sensor initialized successfully.\n");
    return 0;
}

// Read distance from VL53L0X sensor
int read_distance() {
    int distance;
    int status;

    // Read RESULT_INTERRUPT_STATUS register
    status = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading RESULT_INTERRUPT_STATUS: %s\n", strerror(errno));
        return -1;
    }

    // Check if a new measurement is available (bit 0 is set)
    if ((status & 0x01) == 0) {
        return -1; // No new measurement available
    }

    // Read RESULT_RANGE_STATUS register
    status = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading RESULT_RANGE_STATUS: %s\n", strerror(errno));
        return -1;
    }

    // Read distance from RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 register
    distance = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

// Print distance with timestamp
void print_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %d mm\n", timestamp, distance);
}

int main() {
    int distance;
    int init_attempts = 0;
    const int max_init_attempts = 3;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize VL53L0X sensor with retry mechanism
    while (init_attempts < max_init_attempts) {
        if (init_vl53l0x() == 0) {
            break; // Initialization successful
        } else {
            fprintf(stderr, "VL53L0X initialization failed. Attempt %d/%d\n", init_attempts + 1, max_init_attempts);
            init_attempts++;
            gpioDelay(1000); // Wait before retrying
        }
    }

    if (init_attempts == max_init_attempts) {
        fprintf(stderr, "VL53L0X initialization failed after %d attempts. Exiting.\n", max_init_attempts);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance >= 0) {
            print_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance. Continuing...\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

