#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 380.0    // Maximum measurable distance in cm
#define TIMEOUT_US 200000      // Timeout in microseconds (200ms)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;

    return pulse_duration;
}

// Function to calculate the distance in centimeters
double calculateDistance(long pulse_duration) {
    if (pulse_duration <= 0 || pulse_duration > MAX_DISTANCE * 2 * 10000) { // Check for invalid pulse durations
        fprintf(stderr, "Error: Invalid pulse duration: %ld\n", pulse_duration);
        return -1.0; // Indicate an error
    }

    double distance = (pulse_duration / 1000000.0) * SPEED_OF_SOUND / 2.0;
    return distance;
}

// Function to log the distance with a timestamp
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = measurePulse();

        if (pulse_duration > 0) {
            double distance = calculateDistance(pulse_duration);
            if (distance > 0) {
                logDistance(distance);
            }
        } else {
            fprintf(stderr, "Error: Failed to measure pulse duration\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

