#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define MAGIC_WORD_LENGTH 8
#define RANGE_PROFILE_LENGTH 128
#define NUM_DISTANCE_BINS 64
#define INTRUSION_THRESHOLD 1.0 // meters
#define GPIO_PIN 17
#define ALERT_DURATION 2 // seconds
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_uart(const char *device, speed_t baud_rate);
int read_uart_data(int fd, unsigned char *buffer, size_t buffer_size);
int validate_magic_word(const unsigned char *buffer, size_t buffer_size);
int decode_range_profile(const unsigned char *buffer, float *distance_bins);
int detect_intrusion(const float *distance_bins, float threshold);
int log_intrusion(float distance);
int activate_alert(int gpio_pin, int duration_seconds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart_data(int fd, unsigned char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    } else if (bytes_read == 0) {
        //fprintf(stderr, "No data received from UART\n"); //Commented out to reduce verbosity
        return 0; // No data received
    }
    return (int)bytes_read;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, size_t buffer_size) {
    if (buffer_size < MAGIC_WORD_LENGTH) {
        fprintf(stderr, "Buffer too small to contain magic word\n");
        return 0;
    }

    // Define the expected magic word (example: 0x0201040306050807)
    unsigned char expected_magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

    for (size_t i = 0; i < MAGIC_WORD_LENGTH; ++i) {
        if (buffer[i] != expected_magic_word[i]) {
            return 0; // Magic word mismatch
        }
    }

    return 1; // Magic word valid
}

// Decode range profile
int decode_range_profile(const unsigned char *buffer, float *distance_bins) {
    if (buffer == NULL || distance_bins == NULL) {
        fprintf(stderr, "Error: Null pointer passed to decode_range_profile\n");
        return -1;
    }

    // Assuming range profile data starts immediately after the magic word
    for (int i = 0; i < NUM_DISTANCE_BINS; ++i) {
        // Extract 16-bit little-endian data
        int16_t raw_distance = (buffer[MAGIC_WORD_LENGTH + i * 2] << 8) | buffer[MAGIC_WORD_LENGTH + i * 2 + 1];

        // Convert raw data to distance in meters (example scaling factor)
        distance_bins[i] = (float)raw_distance / 100.0; // Example scaling
    }

    return 0;
}

// Detect intrusion
int detect_intrusion(const float *distance_bins, float threshold) {
    for (int i = 0; i < NUM_DISTANCE_BINS; ++i) {
        if (distance_bins[i] <= threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Log intrusion
int log_intrusion(float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Activate alert
int activate_alert(int gpio_pin, int duration_seconds) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_seconds * 1000000); // Delay for 2 seconds (microseconds)
    gpioWrite(gpio_pin, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

