#define LOG_FILE "distance_log.txt"
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
int log_distance(float distance);
int set_gpio_alert(int alert);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg1;
    uint8_t config_reg2;
} sensor_config_t;

// Initialize the sensor configuration
sensor_config_t init_sensor_config() {
    sensor_config_t config = {0x00, 0x00}; // Example configuration
    return config;
}

// Function to write a register value to the I2C device
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a register value from the I2C device
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    uint8_t data[2];
    int result;
    int retries = I2C_RETRY_COUNT;

    // Trigger measurement (replace with actual register and value)
    if (write_register(i2c_handle, 0x00, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    gpioDelay(1); // Small delay after trigger

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, data, 2);
        if (result == 2) {
            // Convert raw data to distance (replace with actual conversion formula)
            *distance = (float)((data[0] << 8) | data[1]) / 10.0; // Example conversion
            return 0;
        } else {
            fprintf(stderr, "Error reading distance data: %d, retries remaining: %d\n", result, retries);
            retries--;
            gpioDelay(I2C_RETRY_DELAY_MS);
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries\n");
    return -1;
}

// Log distance to file
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Set GPIO alert
int set_gpio_alert(int alert) {
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, alert);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor configuration
    sensor_config_t config = init_sensor_config();

    // Write initial configuration to the sensor
    if (write_register(i2c_handle, 0x01, config.config_reg1) != 0) {
        fprintf(stderr, "Error writing config register 1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, 0x02, config.config_reg2) != 0) {
        fprintf(stderr, "Error writing config register 2\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                set_gpio_alert(1); // Assert alert
            } else {
                set_gpio_alert(0); // Deassert alert
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    set_gpio_alert(0); // Ensure GPIO is low on exit
    gpioTerminate();

    return 0;
}

