#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x40
#define LED_GPIO 18
#define MAX_DISTANCE 2000 // mm
#define MIN_DISTANCE 200  // mm
#define MIN_FREQUENCY 100 // Hz
#define MAX_FREQUENCY 1000 // Hz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
void set_led_frequency(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buf[2];
    int result;

    // Retry I2C write
    for (int i = 0; i < 3; ++i) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result == 0) break; // Success
        gpioDelay(10); // Wait 10ms before retrying
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement (adjust as needed)

    // Retry I2C read
    for (int i = 0; i < 3; ++i) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break; // Success
        gpioDelay(10); // Wait 10ms before retrying
    }
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1]; // Combine the two bytes into a 16-bit distance
    return 0;
}

// Set LED blink frequency based on distance
void set_led_frequency(int distance) {
    // Clamp distance to defined range
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    // Map distance to frequency range
    float frequency = MIN_FREQUENCY + (float)(distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    // Calculate period in microseconds
    int period_us = 1000000 / frequency; // period_us = 1 / frequency

    // Set LED on
    gpioWrite(LED_GPIO, 1);
    gpioDelay(period_us / 2); // Half period

    // Set LED off
    gpioWrite(LED_GPIO, 0);
    gpioDelay(period_us / 2); // Half period
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    struct timespec ts;

    printf("Starting distance measurement...\n");

    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log distance and timestamp
                printf("%ld.%09ld, %d\n", ts.tv_sec, ts.tv_nsec, distance);
            } else {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            }

            // Set LED frequency
            set_led_frequency(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

