#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x00
#define DATA_REG 0x01
#define SAMPLE_INTERVAL_MS 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx75030_address;
    char *log_file_name;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_distance(int handle);
int log_data(FILE *fp, time_t timestamp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read distance from MLX75030
int read_distance(int handle) {
    int distance = -1;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Trigger measurement
        if (i2cWriteByteData(handle, MEASURE_CMD, 0) < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", i2cWriteByteData(handle, MEASURE_CMD, 0));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        // Read distance data
        int data = i2cReadWordData(handle, DATA_REG);
        if (data >= 0) {
            distance = (data & 0xFF); // Extract the distance value
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "Error reading from I2C device: %d\n", data);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read distance after multiple retries.\n");
        return -1; // Indicate failure
    }

    return distance;
}

// Log data to file
int log_data(FILE *fp, time_t timestamp, int distance) {
    if (fprintf(fp, "%ld,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

