    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, MLX75030_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get current timestamp
        time_t now = time(NULL);

        // Read distance
