#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x00
#define DATA_REG 0x01
#define SAMPLE_INTERVAL_MS 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
