    int i2c_bus;
    int mlx75030_address;
    char *log_file_name;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_distance(int handle);
int log_data(FILE *fp, time_t timestamp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read distance from MLX75030
int read_distance(int handle) {
    int distance = -1;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Trigger measurement
        if (i2cWriteByteData(handle, MEASURE_CMD, 0) < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", i2cWriteByteData(handle, MEASURE_CMD, 0));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

