        // Read distance data
        int data = i2cReadWordData(handle, DATA_REG);
        if (data >= 0) {
            distance = (data & 0xFF); // Extract the distance value
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "Error reading from I2C device: %d\n", data);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read distance after multiple retries.\n");
        return -1; // Indicate failure
    }

    return distance;
}

