int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log an event to the file
void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", buf, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_state = 1; // Initialize to no obstacle (HIGH)
    int sensor2_state = 1;
    int sensor1_debounce_count = 0;
    int sensor2_debounce_count = 0;

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR1_GPIO);

        if (sensor1_value != sensor1_state) {
            sensor1_debounce_count++;
            if (sensor1_debounce_count >= DEBOUNCE_TIME / 10) {
                if (sensor1_value == 0 && sensor1_state == 1) {
                    log_event(1, "DETECTED");
                } else if (sensor1_value == 1 && sensor1_state == 0) {
                    log_event(1, "CLEARED");
                }
                sensor1_state = sensor1_value;
                sensor1_debounce_count = 0; // Reset debounce counter
            }
        } else {
            sensor1_debounce_count = 0; // Reset debounce counter if no change
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor2_value != sensor2_state) {
            sensor2_debounce_count++;
            if (sensor2_debounce_count >= DEBOUNCE_TIME / 10) {
                if (sensor2_value == 0 && sensor2_state == 1) {
                    log_event(2, "DETECTED");
                } else if (sensor2_value == 1 && sensor2_state == 0) {
                    log_event(2, "CLEARED");
                }
                sensor2_state = sensor2_value;
                sensor2_debounce_count = 0; // Reset debounce counter
            }
        } else {
            sensor2_debounce_count = 0; // Reset debounce counter if no change
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

