#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_read(int fd, unsigned char reg, unsigned char *data, int len);
int read_distance(int fd);
int log_data(FILE *fp, int distance);
void signal_handler(int sig);

// I2C write-read helper function
int i2c_write_read(int fd, unsigned char reg, unsigned char *data, int len) {
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance(int fd) {
    unsigned char status;
    unsigned char distance_data[2];
    int distance;
    struct timespec timeout;
    int retries = 3;

    while (retries > 0) {
        timeout.tv_sec = 0;
        timeout.tv_nsec = TIMEOUT_MS * 1000000; // 50ms timeout

        if (nanosleep(&timeout, NULL) == -1) {
            perror("nanosleep");
            return -1;
        }

        if (i2c_write_read(fd, MEAS_STATUS_REG, &status, 1) != 0) {
            fprintf(stderr, "Error reading MEAS_STATUS register, retrying...\n");
            retries--;
            continue;
        }

        // Check if the measurement is ready (example: status == 0x00 means ready)
        if (status == 0x00) {
            if (i2c_write_read(fd, DISTANCE_REG, distance_data, 2) != 0) {
                fprintf(stderr, "Error reading distance data, retrying...\n");
                retries--;
                continue;
            }

            distance = (distance_data[0] << 8) | distance_data[1];
            return distance;
        } else {
            fprintf(stderr, "Measurement not ready yet (status = 0x%02X), retrying...\n", status);
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1;
}

// Function to log data to a CSV file
int log_data(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    int distance;
    struct timespec sleep_time;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // 500ms

    while (!terminate) {
        distance = read_distance(i2c_fd);
        if (distance >= 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

