#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Register addresses (Example - adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L5CX_REG_SYSRANGE_START 0x0010
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Zone data registers (Example - adjust based on datasheet)
#define VL53L5CX_REG_ZONE_DISTANCES_START 0x0100 // Example start address

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold sensor configuration
typedef struct {
    uint8_t model_id;
    uint8_t revision_id;
} sensor_config_t;

// Function prototypes
int i2c_write_byte(int fd, uint16_t reg, uint8_t data);
int i2c_read_byte(int fd, uint16_t reg, uint8_t *data);
int i2c_write_bytes(int fd, uint16_t reg, uint8_t *data, int len);
int i2c_read_bytes(int fd, uint16_t reg, uint8_t *data, int len);
int vl53l5cx_init(int fd);
int vl53l5cx_read_zone_distances(int fd, uint16_t *distances);
void log_zone_distances(uint16_t *distances);
void signal_handler(int sig);

// I2C write byte function
int i2c_write_byte(int fd, uint16_t reg, uint8_t data) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = data;

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read byte function
int i2c_read_byte(int fd, uint16_t reg, uint8_t *data) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address

    if (write(fd, buf, 2) != 2) {
        perror("I2C write (address) failed");
        return -1;
    }

    if (read(fd, data, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

// I2C write bytes function
int i2c_write_bytes(int fd, uint16_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    memcpy(buf + 2, data, len);

    if (write(fd, buf, len + 2) != len + 2) {
        perror("I2C write (multiple bytes) failed");
        return -1;
    }
    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint16_t reg, uint8_t *data, int len) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address

    if (write(fd, buf, 2) != 2) {
        perror("I2C write (address) failed");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("I2C read (multiple bytes) failed");
        return -1;
    }

    return 0;
}

