#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance measurement (example)
#define DISTANCE_REG 0x00

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle) {
    int distance = -1; // Initialize to an error value
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (distance >= 0) {
            return distance;
        } else {
            fprintf(stderr, "Error reading distance: %d. Retrying...\n", distance);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Return error value
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance
        int distance = read_distance(i2c_handle);

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Log data to console
        if (distance >= 0) {
            printf("Timestamp: %ld ms, Distance: %d mm\n", timestamp_ms, distance);
        } else {
            fprintf(stderr, "Timestamp: %ld ms, Error reading distance\n", timestamp_ms);
        }

        // Delay for 100 ms
        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

