#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define READ_DELAY_MS 500

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    char data[2];

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", data[0]);
        return -1;
    }

    // Example: Set continuous ranging mode (adjust register address)
    data[0] = 0x002d; // Example register, adjust based on datasheet
    data[1] = 0x04;   // Example value, adjust based on datasheet
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char cmd[1];
    char data[2];
    int distance = -1; // Default to error value

    // Start a single measurement
    cmd[0] = VL53L1X_REG_SYSRANGE_START;
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10000); // 10ms

    // Read the distance
    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

// Control the buzzer based on distance
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(READ_DELAY_MS * 1000); // Delay for 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();

    return 0;
}

