    long width = 0;
    long start = gpioTick();

    while (gpioRead(pin) != level) {
        if (gpioTick() - start > timeout * 1000) {
            return -1; // Timeout
        }
    }

    long pulse_start = gpioTick();

    while (gpioRead(pin) == level) {
        if (gpioTick() - pulse_start > timeout * 1000) {
            return -1; // Timeout
        }
    }

    long pulse_end = gpioTick();
    width = pulse_end - pulse_start;

    return width;
}

