#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/msg.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_KEY 1234
#define MESSAGE_QUEUE_MAX_SIZE 1024
#define MAX_RETRIES 3

// Message queue structure
struct msgbuf {
    long mtype;
    int distance;
};

// Global variables
int i2c_handle;
int message_queue_id;
bool running = true;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
int log_distance(int distance);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    char init_data[] = {0x00, 0x01}; // Example: Set bit 0 of register 0x00 to 1
    int result = i2cWriteI2CBlockData(i2c_handle, 0x00, init_data, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to VL53L1X: %d\n", result);
        return -1;
    }

    // Check sensor ID (example)
    char model_id;
    result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading VL53L1X model ID: %d\n", result);
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "VL53L1X not found or incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X sensor
int read_distance() {
    char cmd[] = {0x00}; // Command to trigger a single measurement
    int result = i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, cmd, 1);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to be ready (polling, can be improved with interrupts)
    int ready = 0;
    int retries = 0;
    while (!ready && retries < 100) {
        char ready_bit;
        result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &ready_bit, 1);
        if (result < 0) {
            fprintf(stderr, "Error reading ready bit: %d\n", result);
            return -1;
        }
        if (ready_bit & 0x01) {
            ready = 1;
        } else {
            gpioDelay(1); // Small delay
            retries++;
        }
    }

    if (!ready) {
        fprintf(stderr, "Timeout waiting for measurement ready\n");
        return -1;
    }

    char distance_data[2];
    result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];
    return distance;
}

// Function to log distance to message queue
int log_distance(int distance) {
    struct msgbuf message;
    message.mtype = 1; // Message type (positive for normal messages)
    message.distance = distance;

    if (msgsnd(message_queue_id, &message, sizeof(message.distance), 0) == -1) {
        fprintf(stderr, "Error sending message: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO HIGH
}

// Function to deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer(); // Ensure buzzer is off initially

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create message queue
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, 0666 | IPC_CREAT);
    if (message_queue_id == -1) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
            } else {
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(50); // 50 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    msgctl(message_queue_id, IPC_RMID, NULL);

    return 0;
}

