#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define BUZZER_ON_TIME_MS 100  // Buzzer on time in milliseconds

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, unsigned int tick);
float calculateDistance(unsigned int pulse_width);
void controlBuzzer(float distance);
void signalHandler(int signal);

// Signal handler for clean shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echoCallback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo has been received
    } else if (level == 0) {
        end_tick = tick;
    }
}

// Function to calculate distance in centimeters
float calculateDistance(unsigned int pulse_width) {
    float time_taken = (float)pulse_width / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

// Function to control the buzzer
void controlBuzzer(float distance) {
    if (distance < 30.0) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
        gpioDelay(BUZZER_ON_TIME_MS); // Keep buzzer on for BUZZER_ON_TIME_MS ms
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

