#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define VL53L1X_ADDR 0x29
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INT_PIN 24
#define SERVO_PIN 18

// Define constants
#define DISTANCE_THRESHOLD_OPEN 50  // cm
#define DISTANCE_THRESHOLD_CLOSE 60 // cm
#define SERVO_OPEN_PULSE_WIDTH 2000 // us
#define SERVO_CLOSE_PULSE_WIDTH 1000 // us
#define SERVO_FREQUENCY 50          // Hz
#define SERVO_PERIOD (1000000 / SERVO_FREQUENCY) // us

// Global variables
static volatile int gate_state = 0; // 0: closed, 1: open
static volatile int running = 1;
static FILE *log_file = NULL;
static int i2c_fd;

// Function prototypes
int vl53l1x_init(int fd);
int vl53l1x_read_distance(int fd);
void servo_set_pulse_width(int pin, int pulse_width);
void log_event(int gate_state, int distance);
void signal_handler(int signal);

// VL53L1X Initialization function
int vl53l1x_init(int fd) {
    // Check sensor ID (0xEEAA)
    int sensor_id = wiringPiI2CReadReg8(fd, 0x010F); // Register to read sensor ID
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if (sensor_id != 0xEE) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Example initialization sequence (replace with actual sequence from datasheet)
    if (wiringPiI2CWriteReg8(fd, 0x002D, 0x04) < 0) {
        fprintf(stderr, "Error writing to register 0x002D: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x002E, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x002E: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, 0x002F, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x002F: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L1X Distance Reading function
int vl53l1x_read_distance(int fd) {
    // Start a single measurement
    if (wiringPiI2CWriteReg8(fd, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x0000: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (polling)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        int status = wiringPiI2CReadReg8(fd, 0x0014); // Status register
        if (status < 0) {
            fprintf(stderr, "Error reading status register: %s\n", strerror(errno));
            return -1;
        }
        if (status & 0x01) {
            break; // Measurement ready
        }
        delay(1); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read distance (2 bytes)
    int distance = wiringPiI2CReadReg16(fd, 0x001E); // Distance register
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

// Servo Control function
void servo_set_pulse_width(int pin, int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return;
    }

    // Calculate duty cycle (0-1000)
    int duty_cycle = (pulse_width - 500) * 1000 / (2000 - 500);

    // Set PWM duty cycle
    pwmWrite(pin, duty_cycle);
}

// Logging function
void log_event(int gate_state, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Gate: %s, Distance: %d cm\n", timestamp,
            gate_state == 1 ? "OPEN" : "CLOSED", distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Close the gate
    servo_set_pulse_width(SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH);
    gate_state = 0;
    log_event(gate_state, -1); // Log closing event

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources (not strictly necessary with wiringPi, but good practice)
    pwmWrite(SERVO_PIN, 0); // Stop PWM

    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(VL53L1X_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_fd) == -1) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        return 1;
    }

    // Configure servo pin for PWM
    pinMode(SERVO_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(SERVO_PERIOD);
    pwmSetClock(192); // Adjust clock for desired frequency

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int distance;
    while (running) {
        distance = vl53l1x_read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        if (distance < DISTANCE_THRESHOLD_OPEN && gate_state == 0) {
            // Open the gate
            servo_set_pulse_width(SERVO_PIN, SERVO_OPEN_PULSE_WIDTH);
            gate_state = 1;
            log_event(gate_state, distance);
        } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_state == 1) {
            // Close the gate
            servo_set_pulse_width(SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH);
            gate_state = 0;
            log_event(gate_state, distance);
        }

        delay(50); // Delay between readings
    }

    return 0;
}

