#include <errno.h>

// Define constants
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_SOFT_RESET 0x0010
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
static int i2c_fd;
static FILE *log_file;
