// Function prototypes
int vl53l1x_init(int fd);
int vl53l1x_read_distance(int fd);
void control_gate(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// Helper function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int fd, uint16_t reg, uint8_t value) {
    int result, retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        result = wiringPiI2CWriteReg8(fd, reg, value);
        if (result == 0) return 0; // Success
        fprintf(stderr, "I2C write error (reg 0x%04X, value 0x%02X): %s\n", reg, value, strerror(errno));
        log_event("I2C write error");
        delay(I2C_RETRY_DELAY_MS);
        retries++;
    }
    return -1; // Failure after retries
}

// Helper function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int fd, uint16_t reg, uint8_t *value) {
    int result, retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        result = wiringPiI2CReadReg8(fd, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%04X): %s\n", reg, strerror(errno));
        log_event("I2C read error");
        delay(I2C_RETRY_DELAY_MS);
        retries++;
    }
    return -1; // Failure after retries
}

// Helper function to write a 16-bit word to a VL53L1X register
int vl53l1x_write_word(int fd, uint16_t reg, uint16_t value) {
    int result, retries = 0;
    uint8_t msb = (value >> 8) & 0xFF;
    uint8_t lsb = value & 0xFF;

    while (retries < I2C_RETRY_COUNT) {
        result = wiringPiI2CWriteReg8(fd, reg, msb);
        if (result != 0) {
            fprintf(stderr, "I2C write error (reg 0x%04X, msb 0x%02X): %s\n", reg, msb, strerror(errno));
            log_event("I2C write error");
            delay(I2C_RETRY_DELAY_MS);
            retries++;
