#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300

// Define VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_SOFT_RESET 0x0016
#define VL53L1X_REG_START_MEASUREMENT 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void motor_forward(void);
void motor_backward(void);
void motor_stop(void);
void trigger_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Start measurement
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_MEASUREMENT, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X start measurement failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    int distance = -1;
    int retries = 0;
    int delay_ms = 10;

    while (retries < 5) {
        // Check data ready bit
        int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error: VL53L1X read status failed: %s\n", strerror(errno));
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries++;
            continue;
        }

        if (status & 0x01) { // Data ready
            // Read distance
            distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
            if (distance < 0) {
                fprintf(stderr, "Error: VL53L1X read distance failed: %s\n", strerror(errno));
                gpioDelay(delay_ms);
                delay_ms *= 2; // Exponential backoff
                retries++;
                continue;
            }
            return distance;
        } else {
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Error: VL53L1X read distance failed after multiple retries.\n");
    return -1;
}

// Motor control functions
void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Forward\n");
}

void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: Backward\n");
}

void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Stop\n");
}

// Interrupt service routine
void trigger_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        int distance1 = vl53l1x_read_distance(i2c_handle_1);
        int distance2 = vl53l1x_read_distance(i2c_handle_2);

        if (distance1 >= 0 && distance2 >= 0) {
            int avg_distance = (distance1 + distance2) / 2;
            printf("Distance: %d mm (Sensor 1: %d, Sensor 2: %d)\n", avg_distance, distance1, distance2);

            if (avg_distance < DISTANCE_THRESHOLD_FORWARD) {
                motor_forward();
            } else if (avg_distance > DISTANCE_THRESHOLD_BACKWARD) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance from one or more sensors.\n");
            motor_stop(); // Stop motor on sensor failure
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);

    // Open I2C bus
    i2c_handle_1 = i2cOpen(1, VL53L1X_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error: I2C open failed for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(1, VL53L1X_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error: I2C open failed for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensors
    if (vl53l1x_init(i2c_handle_1) < 0) {
        fprintf(stderr, "Error: VL53L1X sensor 1 initialisation failed.\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle_2) < 0) {
        fprintf(stderr, "Error: VL53L1X sensor 2 initialisation failed.\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function.\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    motor_stop();
    gpioTerminate();

    return 0;
}

