#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define ELE0_REG 0x00
#define ELE11_REG 0x0C
#define LED_GPIO_0 17
#define LED_GPIO_1 18
#define LED_GPIO_2 27
#define LED_GPIO_3 22

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
void set_led_pattern(uint16_t touch_status);
void log_event(uint16_t touch_status);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioSetMode(LED_GPIO_0, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_GPIO_1, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_GPIO_2, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_GPIO_3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes.\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MPR121 sensor
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error resetting MPR121.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure MPR121 (example configuration - adjust as needed)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x05) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x2F, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x30, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x31, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x32, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x33, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x34, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x35, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x36, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x37, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x38, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x39, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x3A, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x3B, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x3C, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x3D, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x3E, 0x01) < 0) return -1; // Set Electrode Configuration
    if (i2cWriteByteData(i2c_handle, 0x3F, 0x01) < 0) return -1; // Set Electrode Configuration

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0F) < 0) return -1; // Enable all electrodes

    // Set touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30) < 0) return -1; // Touch threshold
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10) < 0) return -1; // Release threshold
    }

    // Start the sensor
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) return -1; // Enable sensor

    return 0;
}

// Read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ELE0_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status.\n");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Set LED pattern based on touch status
void set_led_pattern(uint16_t touch_status) {
    gpioWrite(LED_GPIO_0, (touch_status & 0x0001) ? 1 : 0);
    gpioWrite(LED_GPIO_1, (touch_status & 0x0002) ? 1 : 0);
    gpioWrite(LED_GPIO_2, (touch_status & 0x0004) ? 1 : 0);
    gpioWrite(LED_GPIO_3, (touch_status & 0x0008) ? 1 : 0);
}

// Log proximity event to file
void log_event(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity detected on electrodes: ", timestamp);
    for (int i = 0; i < 12; i++) {
        if (touch_status & (1 << i)) {
            fprintf(log_file, "ELE%d ", i);
        }
    }
    fprintf(log_file, "\n");
    fflush(log_file);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO_0, 0);
    gpioWrite(LED_GPIO_1, 0);
    gpioWrite(LED_GPIO_2, 0);
    gpioWrite(LED_GPIO_3, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (init_gpio() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C communication
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (init_mpr121() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t last_touch_status = 0;

    // Main loop
    while (!terminate) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status != last_touch_status) {
                set_led_pattern(touch_status);
                log_event(touch_status);
                last_touch_status = touch_status;
            }
        } else {
            fprintf(stderr, "Error reading touch status, attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            if (init_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1;
            }
        }
        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

