    if (mpr121_write_register(0x2C, 0x05)) return -1; // Set ESI
    if (mpr121_write_register(0x2D, 0x05)) return -1; // Set FFI

    // Debounce configuration
    if (mpr121_write_register(0x22, 0x0A)) return -1; // Set debounce

