#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5); // Keep trigger low for 5us

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // Keep trigger high for 10us
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout: No echo received
    }

    start_tick = gpioTick();

    // Wait for echo to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout: Echo never falls
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            fprintf(stderr, "Error: No echo received or timeout occurred.\n");
            fprintf(log_file, "Error: No echo received or timeout occurred.\n");
            fflush(log_file);
        } else {
            float distance = calculate_distance(pulse_width);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
                fprintf(log_file, "Error: Distance out of range (%.2f cm).\n", distance);
                fflush(log_file);
            } else {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

