#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 200 // 20 cm in mm
#define POLLING_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int init_vl53l1x() {
    // Implement VL53L1X initialization sequence here
    // This is a placeholder; refer to the VL53L1X datasheet for the correct initialization sequence.
    // Example: Writing specific registers to configure the sensor.
    // For simplicity, we'll just return success for now.
    // In a real application, this function would contain the initialization code.
    return 0; // Success
}

// Function to read distance from VL53L1X sensor
int read_distance() {
    uint8_t data[2];
    int distance;

    // Read 2 bytes from register 0x0089 (example register address)
    if (i2cReadI2CBlockData(i2c_handle, 0x0089, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading distance data from VL53L1X\n");
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit integer
    distance = (data[0] << 8) | data[1];

    return distance;
}

// Function to control the gate actuator
void control_gate(int distance) {
    static int gate_open = 0; // Track gate state

    if (distance < DISTANCE_THRESHOLD && !gate_open) {
        gpioWrite(GATE_GPIO, 1); // Open the gate
        gate_open = 1;
        log_data(distance, 1);
    } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
        gpioWrite(GATE_GPIO, 0); // Close the gate
        gate_open = 0;
        log_data(distance, 0);
    }
}

// Function to log data to file
void log_data(int distance, int gate_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Distance: %d mm, Gate: %s\n", timestamp, distance, gate_state ? "Open" : "Closed");
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initialize gate to closed state

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            control_gate(distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping gate control\n");
        }

        gpioDelay(POLLING_INTERVAL_MS); // Wait 100ms
    }

