#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define SERVO_CENTER_ANGLE 90.0 // degrees
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define NUM_SAMPLES 5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold the moving average filter state
typedef struct {
    float buffer[NUM_SAMPLES];
    int index;
    float sum;
} MovingAverageFilter;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);
void cleanup();
void init_moving_average(MovingAverageFilter *filter);
float update_moving_average(MovingAverageFilter *filter, float new_value);

// Global variables for interrupt callback
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int new_pulse = 0;

// Initialize moving average filter
void init_moving_average(MovingAverageFilter *filter) {
    for (int i = 0; i < NUM_SAMPLES; i++) {
        filter->buffer[i] = 0.0;
    }
    filter->index = 0;
    filter->sum = 0.0;
}

// Update moving average filter with a new value
float update_moving_average(MovingAverageFilter *filter, float new_value) {
    // Subtract the oldest value
    filter->sum -= filter->buffer[filter->index];
    // Add the new value
    filter->buffer[filter->index] = new_value;
    filter->sum += new_value;
    // Increment the index, wrapping around if necessary
    filter->index = (filter->index + 1) % NUM_SAMPLES;
    // Calculate the average
    return filter->sum / NUM_SAMPLES;
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        new_pulse = 1;
    } else if (level == 0) {
        end_tick = tick;
        new_pulse = 1;
    }
}

// Function to calculate distance from pulse width
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) return -1.0; // No echo

    float distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Invalid distance
    }

    return distance;
}

// Function to set the servo angle
void set_servo_angle(float angle) {
    if (angle < 0.0 || angle > 180.0) {
        angle = SERVO_CENTER_ANGLE; // Default to center if out of range
    }

    // Map angle (0-180) to pulse width (SERVO_MIN_PULSE_WIDTH - SERVO_MAX_PULSE_WIDTH)
    int pulse_width = (int)((angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to a CSV file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, 0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range and frequency for servo (adjust as needed)
    gpioSetPWMrange(SERVO_PIN, 1000000); // Range of 0-1000000
    gpioSetPWMfrequency(SERVO_PIN, 50);   // 50 Hz

    // Initialize log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Angle (degrees)\n");
    }

    // Initialize moving average filter
    MovingAverageFilter distance_filter;
    init_moving_average(&distance_filter);

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Distance measurement and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for a short period to allow the echo to be received
        gpioDelay(1000); // 1ms delay

        // Check if a new pulse has been received
        if (new_pulse) {
            // Calculate pulse width
            uint32_t pulse_width = end_tick - start_tick;
            if (end_tick < start_tick) {
                // Handle wrap-around
                pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
            }

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Update moving average filter
            distance = update_moving_average(&distance_filter, distance);

            // Set servo angle based on distance
            float angle = 90.0; // Default angle
            if (distance > 0) {
                angle = 90.0 + (distance - 2.0) * (180.0 - 90.0) / (400.0 - 2.0); // Map distance to angle range
                if (angle < 0) angle = 0;
                if (angle > 180) angle = 180;
            }

            set_servo_angle(angle);

            // Log data
            log_data(distance, angle);

            // Reset new_pulse flag
            new_pulse = 0;
        } else {
            // No echo received, log -1.0 and set servo to center
            log_data(-1.0, SERVO_CENTER_ANGLE);
            set_servo_angle(SERVO_CENTER_ANGLE);
        }

        // Delay to control loop rate
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

