#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define DISTANCE_THRESHOLD 200 // mm

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int vl53l1x_init();
int read_distance();
void update_led(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Example initialization sequence (refer to VL53L1X datasheet)
    // This is a simplified example and may need adjustments based on the datasheet
    char data[2];
    int status;

    // Check sensor ID (Example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    char model_id;
    status = i2cReadDevice(i2c_handle, &model_id, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", model_id);
        return -1;
    }

    // Set default configuration (Example - adjust based on datasheet)
    data[0] = 0x02d8; // Example register address
    data[1] = 0x01;   // Example value
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    // Enable signal-rate checking (Example - adjust based on datasheet)
    data[0] = 0x0050; // Example register address
    data[1] = 0x01;   // Example value
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    // Configure cross-talk compensation (Example - adjust based on datasheet)
    data[0] = 0x0052; // Example register address
    data[1] = 0x02;   // Example value
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    // Start ranging (Example - adjust based on datasheet)
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01; // Start ranging
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X sensor
int read_distance() {
    char data[1];
    char distance_data[2];
    int status;

    // Read range status (Example - adjust based on datasheet)
    data[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    char range_status;
    status = i2cReadDevice(i2c_handle, &range_status, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    // Read distance (Example - adjust based on datasheet)
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, distance_data, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];

    return distance;
}

// Function to update the LED based on distance
void update_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn on LED
    } else {
        gpioWrite(GPIO_LED, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
