// Constants
#define I2C_BUS 1
#define SI1102_ADDR_DEFAULT 0x60
#define SI1102_ADDR_ALT 0x5E
#define PROXIMITY_THRESHOLD_DEFAULT 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int i2c_address = SI1102_ADDR_DEFAULT;
int proximity_threshold = PROXIMITY_THRESHOLD_DEFAULT;
volatile int interrupt_flag = 0;

// Function prototypes
int initialize_i2c(int bus, int address);
int configure_si1102(int handle);
int set_interrupt_gpio(int pin);
int read_proximity_value(int handle);
void log_data(int proximity_value, int status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Function to initialize I2C
int initialize_i2c(int bus, int address) {
    i2c_handle = i2cOpen(bus, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the Si1102 sensor
int configure_si1102(int handle) {
    // Example configuration (adjust based on datasheet)
    if (i2cWriteByteData(handle, 0x01, 0x00) < 0) return -1; // Reset
    gpioDelay(10); // Wait for reset
    if (i2cWriteByteData(handle, 0x02, 0x01) < 0) return -1; // Enable
    if (i2cWriteByteData(handle, 0x03, 0x00) < 0) return -1; // Set proximity interrupt pin
    if (i2cWriteByteData(handle, 0x04, 0x01) < 0) return -1; // Enable interrupt
    if (i2cWriteByteData(handle, 0x05, 0x00) < 0) return -1; // Set interrupt threshold

    return 0;
}

// Function to set the GPIO pin for the interrupt
int set_interrupt_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetISRFuncEx(pin, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function\n");
        return -1;
    }
    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity_value(int handle) {
    int proximity_value = i2cReadWordData(handle, 0x06); // Example register
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity value\n");
        return -1;
    }
    return proximity_value;
}

// Function to log the data to a file
void log_data(int proximity_value, int status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d, %s\n", timestamp, proximity_value, (status == 0) ? "SAFE" : "ALERT");
    fclose(fp);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    interrupt_flag = 1;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                proximity_threshold = strtol(optarg, NULL, 10);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(I2C_BUS, i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure Si1102 sensor
    if (configure_si1102(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set interrupt GPIO
    if (set_interrupt_gpio(GPIO_PIN) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            int proximity_value = read_proximity_value(i2c_handle);
            if (proximity_value >= 0) {
                int status = (proximity_value <= proximity_threshold) ? 0 : 1;
                log_data(proximity_value, status);
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

