#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 200000      // Timeout in microseconds (200ms)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;
double current_frequency = 0.0; // Store the current frequency

// Function prototypes
void trigger_pulse();
double measure_distance();
double map_distance_to_frequency(double distance);
void set_frequency(double frequency);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 0; // Reset echo received flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1; // Set echo received flag
    }
}

// Function to generate a 10us trigger pulse
void trigger_pulse()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
double measure_distance()
{
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    trigger_pulse();

    uint32_t start_time = gpioTick();

    while (!echo_received) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for echo.\n");
            return -1.0; // Indicate timeout error
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    uint32_t end_time = gpioTick();

    if (echo_start_tick == 0 || echo_end_tick == 0) {
        fprintf(stderr, "Error: Invalid echo pulse.\n");
        return -1.0; // Indicate invalid pulse
    }

    double pulse_duration = (double)(echo_end_tick - echo_start_tick);
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2

    return distance;
}

// Function to map distance to frequency on a logarithmic scale
double map_distance_to_frequency(double distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance out of range (%f cm). Using previous frequency.\n", distance);
        return current_frequency; // Return the previous frequency
    }

    double log_distance = log10(distance);
    double log_min_distance = log10(MIN_DISTANCE);
    double log_max_distance = log10(MAX_DISTANCE);

    double frequency = MIN_FREQUENCY * pow((MAX_FREQUENCY / MIN_FREQUENCY), (log_distance - log_min_distance) / (log_max_distance - log_min_distance));

    return frequency;
}

// Function to set the PWM frequency
void set_frequency(double frequency)
{
    if (frequency > 0) {
        int range = 1000; // PWM range (adjust as needed)
        int dutycycle = range / 2; // 50% duty cycle
        gpioSetPWMfrequency(PWM_PIN, (int)frequency);
        gpioPWM(PWM_PIN, dutycycle);
        current_frequency = frequency; // Update the current frequency
    } else {
        gpioPWM(PWM_PIN, 0); // Stop the PWM
        current_frequency = 0.0; // Update the current frequency
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range and frequency (initial value)
    gpioSetPWMrange(PWM_PIN, 1000);
    gpioSetPWMfrequency(PWM_PIN, 440); // Initial frequency (A4 note)
    gpioPWM(PWM_PIN, 500); // 50% duty cycle

    // Set up interrupt on echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = map_distance_to_frequency(distance);
            set_frequency(frequency);
        } else {
            // Handle error (e.g., timeout or invalid pulse)
            set_frequency(current_frequency); // Maintain previous frequency
        }

        gpioDelay(50); // Delay for 50ms
    }

    return 0;
}

