    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range and frequency (initial value)
    gpioSetPWMrange(PWM_PIN, 1000);
    gpioSetPWMfrequency(PWM_PIN, 440); // Initial frequency (A4 note)
    gpioPWM(PWM_PIN, 500); // 50% duty cycle

