#define TIMEOUT_US 50000       // 50ms timeout

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_tick, end_tick, diff;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return diff;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to validate the distance reading
void validateDistance(float distance) {
    if (distance < 2.0 || distance > 400.0) {
        printf("Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0) {
            printf("Too close!\n");
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = measurePulse();
        float distance = calculateDistance(pulse_duration);

        if (distance >= 0) {
            validateDistance(distance);
        } else {
            printf("Timeout or error measuring pulse\n");
        }

        gpioDelay(500); // 500ms delay
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

