// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)
#define LOG_FILE "distance_log.csv"
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data (example)
typedef struct {
    int distance;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_distance(sensor_data_t *data);
int log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(sensor_data_t *data) {
    char tx_buffer[2] = {0x00, 0x00}; // Example: Send two bytes to trigger reading
    char rx_buffer[2];

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        data->distance = -1; // Indicate error
        data->status = -1;
        return -1;
    }

    // Example: Assuming the distance is in the first byte (adjust as needed)
    data->distance = rx_buffer[0]; // Placeholder: Replace with actual conversion
    data->status = 0; // Success

    return 0;
}

// Log data to CSV file
int log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_distance(&sensor_data) == 0) {
            if (sensor_data.distance >= MIN_DISTANCE && sensor_data.distance <= MAX_DISTANCE) {
                if (log_data(sensor_data.distance) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Sensor absent or out of range: %d\n", sensor_data.distance);
            }
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

