#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses (Example - refer to datasheet for correct values)
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_DATA_LOW 0x10
#define SI1120_REG_ALS_DATA_HIGH 0x11
#define SI1120_REG_PS_DATA_LOW 0x12
#define SI1120_REG_PS_DATA_HIGH 0x13
#define SI1120_REG_RESET 0x07

// Expected Part ID (Example - refer to datasheet for correct value)
#define SI1120_PART_ID 0x41

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1120();
int read_si1120_data(uint16_t *als, uint16_t *prox);
int log_data(uint16_t als, uint16_t prox);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1120 sensor
int init_si1120() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, 0x01); // Reset command
        if (result == 0) {
            gpioDelay(10); // Wait for reset to complete
            break;
        } else {
            fprintf(stderr, "Error resetting Si1120, retrying... (%d retries left)\n", retries);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    // Verify Part ID
    int part_id;
    retries = 3;
    while (retries > 0) {
        part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (part_id >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading Part ID, retrying... (%d retries left)\n", retries);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Part ID after multiple retries.\n");
        return -1;
    }

    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }

    printf("Si1120 initialized successfully.\n");
    return 0;
}

// Read ALS and proximity data from the Si1120 sensor
int read_si1120_data(uint16_t *als, uint16_t *prox) {
    int retries = 3;
    int result;
    uint8_t als_low, als_high, prox_low, prox_high;

    // Read ALS data
    while (retries > 0) {
        als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_DATA_LOW);
        if (als_low >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading ALS_LOW, retrying... (%d retries left)\n", retries);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS_LOW after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_DATA_HIGH);
        if (als_high >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading ALS_HIGH, retrying... (%d retries left)\n", retries);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS_HIGH after multiple retries.\n");
        return -1;
    }

    // Read proximity data
    retries = 3;
    while (retries > 0) {
        prox_low = i2cReadByteData(i2c_handle, SI1120_REG_PS_DATA_LOW);
        if (prox_low >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading PS_LOW, retrying... (%d retries left)\n", retries);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read PS_LOW after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        prox_high = i2cReadByteData(i2c_handle, SI1120_REG_PS_DATA_HIGH);
        if (prox_high >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading PS_HIGH, retrying... (%d retries left)\n", retries);
            gpioDelay(10);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read PS_HIGH after multiple retries.\n");
        return -1;
    }

    // Combine the bytes into 16-bit little-endian values
    *als = (uint16_t)((als_high << 8) | als_low);
    *prox = (uint16_t)((prox_high << 8) | prox_low);

    return 0;
}

// Log the data to a file
int log_data(uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, prox);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1120 sensor
    if (init_si1120() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t als, prox;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1120_data(&als, &prox) == 0) {
            // Log the data
            if (log_data(als, prox) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

