// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int verify_sensor(int fd);
int configure_sensor(int fd);
int read_sensor_data(int fd, float *lux, uint16_t *proximity);
char* get_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(const char *timestamp, float lux, uint16_t proximity);
void signal_handler(int sig);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device.\n");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    return 0;
}

// Sensor verification function
int verify_sensor(int fd) {
    int part_id = i2c_read_reg(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading part ID.\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }
    printf("Sensor verified. Part ID: 0x%02X\n", part_id);
    return 0;
}

// Sensor configuration function
int configure_sensor(int fd) {
    // Configure measurement rate (example: 100ms)
    if (i2c_write_reg(fd, MEAS_RATE_REG, 0x0A) < 0) {
