    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%03ld", ts.tv_nsec / 1000000);
    return timestamp_str;
