    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s,%.2f,%u\n", timestamp, lux, proximity);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus.\n");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address.\n");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        close(i2c_fd);
        return 1;
    }

