#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_PS1_DATA0 0x0A
#define REG_PS1_DATA1 0x0B
#define REG_COMMAND 0x30
#define REG_HW_KEY 0x07

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int si1145_read_proximity();
void log_data(int proximity_value);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    int retries = 3;
    int status;

    // Reset the device
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET);
        if (status == 0) {
            gpioDelay(10); // Wait for reset to complete
            break;
        } else {
            log_error("Failed to reset Si1145, retrying...");
            retries--;
            gpioDelay(100); // Wait before retrying
        }
    }
    if (retries == 0) {
        log_error("Failed to reset Si1145 after multiple retries.");
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) != 0) {
        log_error("Failed to write HW_KEY.");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) != 0) {
        log_error("Failed to force ALS measurement.");
        return -1;
    }

    return 0;
}

// Read proximity data from the Si1145 sensor
int si1145_read_proximity() {
    int retries = 3;
    int status;
    uint8_t data0, data1;

    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE);
        if (status != 0) {
            log_error("Failed to force ALS measurement for proximity read, retrying...");
            retries--;
            gpioDelay(100);
            continue;
        }

        gpioDelay(10); // Wait for measurement

        data0 = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
        if (data0 < 0) {
            log_error("Failed to read PS1_DATA0, retrying...");
            retries--;
            gpioDelay(100);
            continue;
        }

        data1 = i2cReadByteData(i2c_handle, REG_PS1_DATA1);
        if (data1 < 0) {
            log_error("Failed to read PS1_DATA1, retrying...");
            retries--;
            gpioDelay(100);
            continue;
        }

        return (data1 << 8) | data0;
    }

    log_error("Failed to read proximity data after multiple retries.");
    return -1;
}

// Log the proximity data to a file
void log_data(int proximity_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, proximity_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Log errors to a file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
    perror(message); // Also print to stderr
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity_value = si1145_read_proximity();
        if (proximity_value >= 0) {
            log_data(proximity_value);
        } else {
            log_error("Failed to read proximity data.");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

