    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0) {
        if (echo_received) {
            echo_end_tick = tick;
            int pulse_width = echo_end_tick - echo_start_tick;
            double distance = calculate_distance(pulse_width);
            print_distance(distance);
            control_buzzer(distance);
            echo_received = 0; // Reset flag
        }
    }
}

// Function to calculate distance from pulse width
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to control the buzzer based on distance
void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

// Function to print the distance to stdout
void print_distance(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

