#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 18
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000000 // microseconds
#define DISTANCE_THRESHOLD_OPEN 250 // mm
#define DISTANCE_THRESHOLD_CLOSE 200 // mm
#define HYSTERESIS_BAND 50 // mm
#define PWM_DUTY_CYCLE_OPEN 1000 // us
#define PWM_DUTY_CYCLE_CLOSE 2000 // us
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance(uint16_t *distance);
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x0050

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) { // Start continuous ranging
        fprintf(stderr, "Error writing to VL53L1X_REG_RANGING_MODE\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x0A) < 0) { // Set intermeasurement period
        fprintf(stderr, "Error writing to VL53L1X_REG_INTERMEASUREMENT_PERIOD\n");
        return -1;
    }

    // Verify model ID (example)
    uint8_t model_id;
    if (i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID) < 0) {
        fprintf(stderr, "Error reading VL53L1X_REG_IDENTIFICATION_MODEL_ID\n");
        return -1;
    }
    model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X sensor
int read_distance(uint16_t *distance) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x0089, buffer, 2) != 2) { // Read distance register
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }
    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(GATE_GPIO, pulse_width); // Set PWM duty cycle
}

// Function to log events
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for PWM
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(GATE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(GATE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint16_t distance;
    int pulse_width = 1500; // Initial pulse width (center)
    int gate_state = 0; // 0 = closed, 1 = open

    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Control servo based on distance
            if (distance > DISTANCE_THRESHOLD_OPEN + HYSTERESIS_BAND && gate_state == 0) {
                pulse_width = PWM_DUTY_CYCLE_OPEN;
                set_servo_pulse_width(pulse_width);
                log_event("Gate opened");
                gate_state = 1;
            } else if (distance < DISTANCE_THRESHOLD_CLOSE - HYSTERESIS_BAND && gate_state == 1) {
                pulse_width = PWM_DUTY_CYCLE_CLOSE;
                set_servo_pulse_width(pulse_width);
                log_event("Gate closed");
                gate_state = 0;
            } else {
                // Smooth transition between pulse widths
                if (distance > DISTANCE_THRESHOLD_OPEN) {
                    pulse_width = PWM_DUTY_CYCLE_OPEN;
                } else if (distance < DISTANCE_THRESHOLD_CLOSE) {
                    pulse_width = PWM_DUTY_CYCLE_CLOSE;
                } else {
                    // Linearly interpolate between the two pulse widths
                    pulse_width = PWM_DUTY_CYCLE_OPEN + (int)(((float)(distance - DISTANCE_THRESHOLD_CLOSE) / (DISTANCE_THRESHOLD_OPEN - DISTANCE_THRESHOLD_CLOSE)) * (PWM_DUTY_CYCLE_CLOSE - PWM_DUTY_CYCLE_OPEN));
                }
                set_servo_pulse_width(pulse_width);
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(GATE_GPIO, 0); // Stop PWM
    fclose(log_file);
    gpioTerminate();

    return 0;
}

