    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(GATE_GPIO, pulse_width); // Set PWM duty cycle
}

// Function to log events
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for PWM
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(GATE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(GATE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint16_t distance;
    int pulse_width = 1500; // Initial pulse width (center)
    int gate_state = 0; // 0 = closed, 1 = open

    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Control servo based on distance
            if (distance > DISTANCE_THRESHOLD_OPEN + HYSTERESIS_BAND && gate_state == 0) {
                pulse_width = PWM_DUTY_CYCLE_OPEN;
                set_servo_pulse_width(pulse_width);
                log_event("Gate opened");
                gate_state = 1;
            } else if (distance < DISTANCE_THRESHOLD_CLOSE - HYSTERESIS_BAND && gate_state == 1) {
                pulse_width = PWM_DUTY_CYCLE_CLOSE;
                set_servo_pulse_width(pulse_width);
                log_event("Gate closed");
                gate_state = 0;
            } else {
                // Smooth transition between pulse widths
                if (distance > DISTANCE_THRESHOLD_OPEN) {
                    pulse_width = PWM_DUTY_CYCLE_OPEN;
                } else if (distance < DISTANCE_THRESHOLD_CLOSE) {
                    pulse_width = PWM_DUTY_CYCLE_CLOSE;
                } else {
                    // Linearly interpolate between the two pulse widths
                    pulse_width = PWM_DUTY_CYCLE_OPEN + (int)(((float)(distance - DISTANCE_THRESHOLD_CLOSE) / (DISTANCE_THRESHOLD_OPEN - DISTANCE_THRESHOLD_CLOSE)) * (PWM_DUTY_CYCLE_CLOSE - PWM_DUTY_CYCLE_OPEN));
                }
                set_servo_pulse_width(pulse_width);
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(GATE_GPIO, 0); // Stop PWM
    fclose(log_file);
    gpioTerminate();

    return 0;
}

