#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum pulse width for servo (0 degrees)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width for servo (180 degrees)
#define SERVO_MIN_ANGLE 0.0
#define SERVO_MAX_ANGLE 180.0
#define SERVO_MIN_DISTANCE 2.0
#define SERVO_MAX_DISTANCE 200.0

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout occurred
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout occurred
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map the distance to a servo angle
float mapDistanceToAngle(float distance) {
    if (distance < SERVO_MIN_DISTANCE) {
        return SERVO_MIN_ANGLE;
    } else if (distance > SERVO_MAX_DISTANCE) {
        return SERVO_MAX_ANGLE;
    } else {
        // Linear interpolation
        float angle = (distance - SERVO_MIN_DISTANCE) / (SERVO_MAX_DISTANCE - SERVO_MIN_DISTANCE) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE);
        return angle;
    }
}

// Function to set the servo angle using the pigpio API
int setServoAngle(float angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180 degrees)\n");
        return -1; // Indicate an error
    }

    // Calculate the pulse width based on the angle
    float pulse_width = SERVO_MIN_PULSE_WIDTH + (angle / SERVO_MAX_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);

    // Set the servo pulse width
    gpioServo(SERVO_PIN, (int)pulse_width);

    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Measure the distance
        float distance = measureDistance();

        // Map the distance to a servo angle
        float angle = mapDistanceToAngle(distance);

        // Set the servo angle
        if (distance != -1.0) {
            if (setServoAngle(angle) != 0) {
                fprintf(stderr, "Error setting servo angle\n");
            }
        } else {
            fprintf(stderr, "Timeout occurred, skipping servo update\n");
        }

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Pause for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Stop the servo
    setServoAngle(SERVO_MIN_ANGLE);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

