#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x30
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUMID_HOLD 0xE5
#define SLEEP_MS 2000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature and humidity from the sensor
int read_sensor(float *temperature, float *humidity) {
    int result;
    uint8_t buf[2];
    uint16_t raw_temp, raw_humidity;

    // Measure temperature
    result = i2cWriteByteData(i2c_handle, CONFIG_REG, MEASURE_TEMP_HOLD);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for conversion

    result = i2cReadI2CBlockData(i2c_handle, MEASURE_TEMP_HOLD, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature from I2C: %d\n", result);
        return -1;
    }
    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Measure humidity
    result = i2cWriteByteData(i2c_handle, CONFIG_REG, MEASURE_HUMID_HOLD);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for conversion

    result = i2cReadI2CBlockData(i2c_handle, MEASURE_HUMID_HOLD, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity from I2C: %d\n", result);
        return -1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Log temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    float temperature, humidity;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    printf("Si7005 sensor reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_sensor(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            if (init_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit loop if re-initialization fails
            }
        }
        gpioDelay(SLEEP_MS); // Sleep for 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

