#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// Global variables for graceful shutdown
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial
#define CRC8_POLY 0x31

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} sht40_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sht40_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
void log_data(const sht40_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // I2C bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40 sensor
int read_sht40(sht40_data_t *data) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t raw_data[6];
    int result;

    result = i2cWriteByte(i2c_handle, cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait at least 10 ms

    result = i2cReadDevice(i2c_handle, (char *)raw_data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC validation
    uint8_t temp_crc = calculate_crc(raw_data, 2);
    uint8_t hum_crc = calculate_crc(raw_data + 3, 2);

    if (temp_crc != raw_data[2] || hum_crc != raw_data[5]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (raw_data[0] << 8) | raw_data[1];
    uint16_t raw_humidity = (raw_data[3] << 8) | raw_data[4];

    data->temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    data->humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log temperature and humidity data to the console
void log_data(const sht40_data_t *data) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data->temperature, data->humidity);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    sht40_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        result = read_sht40(&sensor_data);
        if (result == 0) {
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit loop if re-initialization fails
            }
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

