#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A

// Define the registers for ambient and object temperature
#define TA_REG 0x06
#define TO_REG 0x07

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_temperature(int handle, uint16_t reg, float *temperature);
float convert_to_celsius(uint16_t raw_temp);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the sensor
int read_temperature(int handle, uint16_t reg, float *temperature) {
    int raw_temp = i2cReadWordData(handle, reg);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature from register 0x%02X: %d\n", reg, raw_temp);
        return -1;
    }
    *temperature = convert_to_celsius(raw_temp);
    return 0;
}

// Function to convert raw temperature data to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Function to log the temperature data to a file
int log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("temperature_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float ambient_temp, object_temp;

        // Read ambient temperature
        if (read_temperature(i2c_handle, TA_REG, &ambient_temp) != 0) {
            fprintf(stderr, "Error reading ambient temperature, retrying in 5 seconds...\n");
            time_sleep(5.0);
            continue;
        }

        // Read object temperature
        if (read_temperature(i2c_handle, TO_REG, &object_temp) != 0) {
            fprintf(stderr, "Error reading object temperature, retrying in 5 seconds...\n");
            time_sleep(5.0);
            continue;
        }

        // Log the temperature data
        if (log_temperature(ambient_temp, object_temp) != 0) {
            fprintf(stderr, "Error logging temperature data!\n");
        }

        // Wait for 5 seconds
        time_sleep(5.0);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

