    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Open error log file
    error_file = fopen(config.error_log_name, "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
