    buf[0] = (MEASURE_HIGH_REP >> 8) & 0xFF;
    buf[1] = MEASURE_HIGH_REP & 0xFF;

    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return 1;
