#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define DATA_FRAME_SIZE 9
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
sensor_data_t convert_data(uint8_t data[]);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the SDP810 sensor
int init_sensor() {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_FRAME_SIZE);
    if (result != DATA_FRAME_SIZE) {
        fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t calculated_crc = crc8(data, nbrOfBytes);
    if (calculated_crc != checksum) {
        fprintf(stderr, "CRC check failed! Calculated: 0x%02X, Received: 0x%02X\n", calculated_crc, checksum);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(uint8_t data[]) {
    sensor_data_t sensor_data;

    // Pressure
    int16_t raw_pressure = (data[0] << 8) | data[1];
    uint8_t pressure_crc = data[2];
    if (validate_crc(data, 2, pressure_crc) != 0) {
        sensor_data.pressure = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure; // Placeholder conversion
    }

    // Temperature
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint8_t temperature_crc = data[5];
    if (validate_crc(data + 3, 2, temperature_crc) != 0) {
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature; // Placeholder conversion
    }

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is new and write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[DATA_FRAME_SIZE];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Convert data
            sensor_data = convert_data(data);

            // Log data
            if (sensor_data.pressure != -999.0 && sensor_data.temperature != -999.0) {
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Error converting sensor data, skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

