#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REP 0xFD
#define LOG_FILE "sht40_log.txt"
#define RETRY_DELAY_MS 100
#define SLEEP_DURATION_S 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    uint8_t cmd = MEASURE_HIGH_REP;
    uint8_t raw_data[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_fd, &cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait 10ms

        if (i2cReadDevice(i2c_fd, raw_data, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        // CRC validation
        if (calculate_crc(raw_data, 2) != raw_data[2] ||
            calculate_crc(raw_data + 3, 2) != raw_data[5]) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

