            } else {
                retries++;
                gpioDelay(10 * (1 << (retries - 1))); // Exponential backoff
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
