#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void log_data(sensor_data_t data);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[2];
    int retries = 0;
    int result;

    // Read temperature
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            uint16_t raw_temp = (buf[0] << 8) | buf[1];
            data->temperature = convert_temperature(raw_temp);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to convert raw humidity data to percentage relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to print data to the console
void print_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sensor_data(&sensor_data);
        if (result == 0) {
            // Log data
            log_data(sensor_data);

            // Print data to console
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

