            fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            uint16_t raw_temp = (buf[0] << 8) | buf[1];
            data->temperature = convert_temperature(raw_temp);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to convert raw humidity data to percentage relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to print data to the console
void print_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sensor_data(&sensor_data);
        if (result == 0) {
            // Log data
            log_data(sensor_data);

            // Print data to console
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

