    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open data file
    fp = fopen(FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s\n", FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(fp);

    // Main loop
    uint8_t data[DATA_LENGTH];
    sensor_data_t sensor_data;

    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement (45ms)
        gpioDelay(45);

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process sensor data
        sensor_data = process_sensor_data(data);

        // Log data
        if (sensor_data.pressure != -999.0 && sensor_data.temperature != -999.0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error: Invalid sensor data, skipping logging.\n");
        }

        // Sleep for 100ms
        gpioDelay(SLEEP_MS);
    }

    // Cleanup
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

