// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
FILE *log_fp = NULL;
FILE *error_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int validate_crc(uint8_t data[], uint8_t crc);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        return -1;
    }
    return 0;
}

// Read temperature from STS30 sensor
int read_temperature(float *temperature) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[3];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command.");
        return -1;
    }

    gpioDelay(15000); // Wait 15 ms for conversion

    result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        log_error("Failed to read temperature data.");
        return -1;
    }

    if (!validate_crc(data, data[2])) {
        log_error("CRC validation failed.");
        return -1;
    }

    uint16_t raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t polynomial = 0x31; // CRC-8 polynomial
    uint8_t crc_calculated = 0xFF;
    uint8_t bit;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            bit = crc_calculated & 0x80;
            crc_calculated <<= 1;
            if (bit) {
                crc_calculated ^= polynomial;
            }
        }
    }

    return (crc_calculated == crc);
}

// Log temperature data to file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_fp, "%s, %.2f\n", timestamp, temperature);
    fflush(log_fp); // Ensure data is written to disk immediately

    return 0;
}

// Log errors to file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(error_fp, "%s, %s\n", timestamp, message);
    fflush(error_fp); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (error_fp != NULL) {
        fclose(error_fp);
    }
    gpioTerminate();
}

int main() {
    float temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    error_fp = fopen(ERROR_LOG, "a");
    if (error_fp == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        fclose(log_fp);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        result = read_temperature(&temperature);
        if (result == 0) {
            log_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            log_error("Failed to read temperature.");
        }

        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

