FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t buffer[6];

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(log_file, "%s", "Error: Failed to write measurement command.\n");
        fflush(log_file);
        return -1;
