    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            if (validate_crc(sensor_data, 6)) {
                converted_data = convert_data(sensor_data);
                log_data(converted_data);
            } else {
                fprintf(stderr, "CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

