#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define CIRCULAR_BUFFER_SIZE 60
#define RETRY_COUNT 3

// Data structure for circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
} Reading;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
Reading circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(float *temperature);
void control_fan(float temperature);
void add_reading(time_t timestamp, float temperature);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from Si7021 sensor
int read_temperature(float *temperature) {
    char cmd[1] = {0xE3}; // Command to measure temperature
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 10ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Convert raw data to temperature (Celsius)
        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Temperature: %.2f °C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Temperature: %.2f °C)\n", temperature);
    }
}

// Function to add a reading to the circular buffer
void add_reading(time_t timestamp, float temperature) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Readings ---\n");
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % CIRCULAR_BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C\n", time_str, circular_buffer[index].temperature);
    }
    printf("--- End of Readings ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    time_t current_time;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            current_time = time(NULL);
            add_reading(current_time, temperature);
            printf("Temperature: %.2f °C\n", temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
