#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// SCD40 data structure
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} scd40_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_scd40();
int read_scd40_data(scd40_data_t *data);
int verify_crc(uint8_t data[], uint8_t crc);
void log_data(scd40_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the SCD40 sensor
int init_scd40() {
    int result;

    // Send start periodic measurement command
    result = i2cWriteByteData(i2c_handle, CMD_START_PERIODIC_MEASUREMENT >> 8, CMD_START_PERIODIC_MEASUREMENT & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error sending start periodic measurement command: %d\n", result);
        return -1;
    }

    // Wait for at least one second
    gpioDelay(1000000); // 1 second

    return 0;
}

// Read data from the SCD40 sensor
int read_scd40_data(scd40_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Read 9 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data from sensor: %d\n", result);
        return -1;
    }

    // Verify CRC for each 2-byte word
    if (verify_crc(buffer, buffer[2]) != 0 ||
        verify_crc(buffer + 3, buffer[5]) != 0 ||
        verify_crc(buffer + 6, buffer[8]) != 0) {
        fprintf(stderr, "CRC verification failed\n");
        return -1;
    }

    // Extract raw data
    data->co2 = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[3] << 8) | buffer[4];
    data->humidity = (buffer[6] << 8) | buffer[7];

    return 0;
}

// Verify CRC checksum
int verify_crc(uint8_t data[], uint8_t crc) {
    uint8_t polynomial = 0x31; // CRC-8 polynomial
    uint8_t crc_calculated = 0xFF;
    uint8_t bit;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated != crc) ? -1 : 0;
}

// Log data to file
void log_data(scd40_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, (float)data.temperature / 2048.0, (float)data.humidity / 1024.0);
    fflush(log_file);
}

int main() {
    scd40_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Check data ready flag (bit 0 of the first byte)
        uint8_t data_ready = i2cReadByteData(i2c_handle, 0);
        if (data_ready < 0) {
            fprintf(stderr, "Error reading data ready flag: %d\n", data_ready);
            break;
        }

        if (data_ready & 0x01) {
            // Read sensor data
            if (read_scd40_data(&sensor_data) == 0) {
                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Stop periodic measurement
    result = i2cWriteByteData(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT >> 8, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error sending stop periodic measurement command: %d\n", result);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

