#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_REINIT 0x3646

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    time_t timestamp;
} sensor_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
sensor_data_t data_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_scd40();
int read_scd40(uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
int validate_crc(uint16_t data, uint8_t crc);
void store_data(uint16_t co2, uint16_t temperature, uint16_t humidity);
void print_data(uint16_t co2, uint16_t temperature, uint16_t humidity);
void control_led(uint16_t co2);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t co2, temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd40(&co2, &temperature, &humidity) == 0) {
            // Validate CRC
            if (validate_crc(co2, (uint8_t)(co2 >> 8)) &&
                validate_crc(temperature, (uint8_t)(temperature >> 8)) &&
                validate_crc(humidity, (uint8_t)(humidity >> 8))) {

                // Store data in circular buffer
                store_data(co2, temperature, humidity);

                // Print data to stdout
                print_data(co2, temperature, humidity);

                // Control LED based on CO2 level
                control_led(co2);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        time_sleep(5.0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize SCD40 sensor
int init_scd40() {
    uint8_t buf[2];
    int result;

    // Send start periodic measurement command
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start periodic measurement command: %d\n", result);
        return 1;
    }

    time_sleep(0.1); // Wait for sensor to initialize

    return 0;
}

// Read CO2, temperature, and humidity from SCD40
int read_scd40(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t buf[2];
    uint8_t data[9];
    int result;

    // Send read measurement command
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return 1;
    }

    time_sleep(0.01); // Small delay before reading

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return 1;
    }

    // Extract CO2, temperature, and humidity values
    *co2 = (data[0] << 8) | data[1];
    *temperature = (data[3] << 8) | data[4];
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    uint8_t calculated_crc = crc8(data_bytes, 2);
    return (calculated_crc == crc);
}

// Store data in circular buffer
void store_data(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    data_buffer[buffer_index].co2 = co2;
    data_buffer[buffer_index].temperature = temperature;
    data_buffer[buffer_index].humidity = humidity;
    data_buffer[buffer_index].timestamp = time(NULL);

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print data to stdout
void print_data(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    printf("CO2: %d ppm, Temperature: %d \u00b0C, Humidity: %d %%\n", co2, temperature, humidity);
}

// Control LED based on CO2 level
void control_led(uint16_t co2) {
    if (co2 > 1000) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;

    // Stop periodic measurement
    uint8_t buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, (char *)buf, 2);

    // Reinitialize the sensor
    buf[0] = (CMD_REINIT >> 8) & 0xFF;
    buf[1] = CMD_REINIT & 0xFF;
    i2cWriteDevice(i2c_handle, (char *)buf, 2);

    time_sleep(0.1);

    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

