#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define MAX_READINGS 3
#define TEMP_MIN -40.0
#define TEMP_MAX 150.0
#define TIMEOUT_US 50000 // 50ms timeout

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read temperature from TMP05 sensor
float read_temperature() {
    int start_time, end_time, high_time, low_time;
    float temperature;
    int valid_readings = 0;
    float temp_sum = 0.0;

    while (valid_readings < MAX_READINGS) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for rising edge.\n");
                return -1000.0; // Indicate error
            }
        }
        start_time = gpioTick();

        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for falling edge.\n");
                return -1000.0; // Indicate error
            }
        }
        end_time = gpioTick();

        high_time = end_time - start_time;
        start_time = gpioTick();

        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for rising edge.\n");
                return -1000.0; // Indicate error
            }
        }
        end_time = gpioTick();

        low_time = end_time - start_time;

        if (low_time == 0) {
            fprintf(stderr, "Error: Low time is zero, cannot calculate temperature.\n");
            return -1000.0; // Indicate error
        }

        temperature = (float)high_time / (float)low_time * 165.0 - 40.0;

        if (temperature >= TEMP_MIN && temperature <= TEMP_MAX) {
            temp_sum += temperature;
            valid_readings++;
        } else {
            fprintf(stderr, "Error: Temperature reading out of range: %.2f\n", temperature);
        }
    }

    if (valid_readings == MAX_READINGS) {
        return temp_sum / MAX_READINGS;
    } else {
        return -1000.0; // Indicate error
    }
}

// Function to log temperature data to file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    int pigpio_init_result;

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

