#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, int len);
SensorData convert_data(const uint8_t *data);
SensorData apply_offset(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = crc8(data, len - 1);
    if (crc_calculated != data[len - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
SensorData convert_data(const uint8_t *data) {
    SensorData sensor_data;
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Apply sinusoidal offset
SensorData apply_offset(SensorData data) {
    time_t now = time(NULL);
    double t = (double)now / 3600.0; // Time in hours
    double temp_offset = 2.0 * sin(2 * M_PI * t);
    double humidity_offset = 5.0 * cos(2 * M_PI * t);

    data.temperature += temp_offset;
    data.humidity += humidity_offset;

    // Clamp humidity to 0-100%
    if (data.humidity < 0.0) data.humidity = 0.0;
    if (data.humidity > 100.0) data.humidity = 100.0;

    return data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s,%.2f,%.2f\n", buf, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[6];
    SensorData sensor_data;
    int retry;

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(data) == 0) {
                if (validate_crc(data, 2) == 0 && validate_crc(data + 3, 2) == 0) {
                    sensor_data = convert_data(data);
                    sensor_data = apply_offset(sensor_data);
                    if (log_data(sensor_data) != 0) {
                        fprintf(stderr, "Failed to log data\n");
                    }
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "CRC validation failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
            }
            retry++;
            gpioDelay(RETRY_DELAY_MS);
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Max retries reached, logging NaN values\n");
            time_t now = time(NULL);
            struct tm *tstruct = gmtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
            fprintf(log_file, "%s,NaN,NaN\n", buf);
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000); // Sample every 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

