        }

        gpioDelay(45); // Wait for conversion

        // Read data from the sensor
        if (read_data(i2c_handle, buffer, DATA_LENGTH) != 0) {
            fprintf(stderr, "Error reading data. Retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
