#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06 // Single shot, high repeatability, clock stretching disabled
#define SAMPLE_INTERVAL_MS 5000
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the SHT35 sensor
int read_sensor_data(uint8_t *data) {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait 15ms for measurement

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate the CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

