#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define CONVERSION_TIME_MS 50
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int write_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(uint8_t data[], size_t len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], size_t len) {
    uint8_t calculated_crc = calculate_crc(data, len - 1);
    if (calculated_crc != data[len - 1]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Pressure conversion
    int16_t pressure_raw = (data[0] << 8) | data[1];
    sensor_data.pressure = (float)pressure_raw / 240.0; // Scale factor from datasheet

    // Temperature conversion
    int16_t temperature_raw = (data[3] << 8) | data[4];
    sensor_data.temperature = (float)temperature_raw / 200.0; // Scale factor from datasheet

    return sensor_data;
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    size_t elements_written = fwrite(&data, sizeof(sensor_data_t), 1, fp);
    if (elements_written != 1) {
        fprintf(stderr, "Failed to write data to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open file for logging
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write continuous measurement command
    if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t data[9];
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure
        if (validate_crc(data, 2) != 0) {
            fprintf(stderr, "Pressure CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for temperature
        if (validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "Temperature CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data
        if (log_data(fp, sensor_data) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

