    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);

    return 0;
}

