        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[9];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, data) == 0) {
            // Validate CRC for pressure data
            if (validate_crc(data, 3) == 0) {
                // Process data
                sensor_data_t sensor_data = process_data(data);

                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "Pressure CRC validation failed!\n");
            }

            // Validate CRC for temperature data
            if (validate_crc(data + 3, 3) == 0) {
