                sensor_data_t sensor_data = process_data(data + 3);

                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "Temperature CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

