#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define GPIO_FAN 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure_raw;
    float pressure_pa;
    float flow_rate;
} sensor_data_t;

// Function prototypes
int initialize();
int read_sensor(sensor_data_t *data);
float convert_to_pressure(int16_t raw_pressure);
float convert_to_flow_rate(float pressure_pa);
int control_fan(float flow_rate);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(GPIO_FAN, 0); // Turn off the fan
    i2cClose(i2c_handle); // Close the I2C handle
    if (log_file != NULL) {
        fflush(log_file); // Flush the log file
        fclose(log_file);  // Close the log file
    }
    gpioTerminate(); // Terminate the pigpio library
}

// Initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(GPIO_FAN, PI_OUTPUT); // Set GPIO18 as output
    gpioSetPWMfrequency(GPIO_FAN, PWM_FREQUENCY); // Set PWM frequency
    gpioSetPWMrange(GPIO_FAN, PWM_RANGE); // Set PWM range

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read raw pressure data from the sensor
int read_sensor(sensor_data_t *data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    data->pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Convert raw pressure data to Pascals
float convert_to_pressure(int16_t raw_pressure) {
    // Assuming a linear relationship between raw value and pressure
    // You'll need to calibrate this based on your sensor's datasheet
    // Example:  raw_pressure = 0 corresponds to 0 Pa, raw_pressure = 65535 corresponds to 100 Pa
    float pressure_pa = (float)raw_pressure / 65535.0 * 100.0; // Example conversion
    return pressure_pa;
}

// Convert pressure to flow rate (SLPM)
float convert_to_flow_rate(float pressure_pa) {
    // Assuming a linear relationship between pressure and flow rate
    // You'll need to calibrate this based on your sensor's datasheet
    // Example:  pressure_pa = 0 Pa corresponds to 0 SLPM, pressure_pa = 100 Pa corresponds to 100 SLPM
    float flow_rate = pressure_pa * 1.0; // Example conversion
    return flow_rate;
}

// Control the fan speed based on the flow rate
int control_fan(float flow_rate) {
    // Map the flow rate to a PWM duty cycle (0-1000)
    // You'll need to adjust these values based on your fan's characteristics
    int duty_cycle = (int)(flow_rate * (PWM_RANGE / 100.0)); // Example mapping

    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    gpioPWM(GPIO_FAN, duty_cycle);
    return 0;
}

// Log the data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, data.pressure_pa);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor(&sensor_data) == 0) {
            sensor_data.pressure_pa = convert_to_pressure(sensor_data.pressure_raw);
            sensor_data.flow_rate = convert_to_flow_rate(sensor_data.pressure_pa);

            control_fan(sensor_data.flow_rate);
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    cleanup();
    return 0;
}

