#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_scd30();
int read_scd30_data(float *co2, float *temperature, float *humidity);
int write_log_entry(float co2, float temperature, float humidity);
void ventilation_control(float co2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Set measurement interval to 5 seconds
    char buf[6];
    buf[0] = (SCD30_CMD_SET_MEASUREMENT_INTERVAL >> 8) & 0xFF;
    buf[1] = SCD30_CMD_SET_MEASUREMENT_INTERVAL & 0xFF;
    buf[2] = 0x05; // 5 seconds
    buf[3] = 0x00;
    buf[4] = 0x00;
    buf[5] = 0x00;

    if (i2cWriteDevice(i2c_handle, buf, 6) != 0) {
        fprintf(log_file, "%s,I2C Write Error: Setting measurement interval\n", __TIME__);
        fflush(log_file);
        return -1;
    }

    // Start periodic measurement
    buf[0] = (SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(log_file, "%s,I2C Write Error: Starting periodic measurement\n", __TIME__);
        fflush(log_file);
        return -1;
    }

    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30_data(float *co2, float *temperature, float *humidity) {
    char buf[2];
    char data[18];
    int retries = 3;

    buf[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buf, 2) == 0) {
            break;
        } else {
            fprintf(log_file, "%s,I2C Write Error: Reading measurement command\n", __TIME__);
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            retries--;
        }
    }

    if (retries == 0) {
        return -1;
    }

    gpioDelay(100); // Wait for data to be ready

    retries = 3;
    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, data, 18) == 18) {
            break;
        } else {
            fprintf(log_file, "%s,I2C Read Error: Reading measurement data\n", __TIME__);
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            retries--;
        }
    }

    if (retries == 0) {
        return -1;
    }

    // CRC check
    uint8_t crc[2];
    crc[0] = data[0];
    crc[1] = data[1];

    if (crc8(data, 2) != crc[0]) {
        fprintf(log_file, "%s,CRC Error: CO2\n", __TIME__);
        fflush(log_file);
        return -1;
    }

    crc[0] = data[2];
    crc[1] = data[3];
    if (crc8(data + 2, 2) != crc[0]) {
        fprintf(log_file, "%s,CRC Error: Temperature\n", __TIME__);
        fflush(log_file);
        return -1;
    }

    crc[0] = data[4];
    crc[1] = data[5];
    if (crc8(data + 4, 2) != crc[0]) {
        fprintf(log_file, "%s,CRC Error: Humidity\n", __TIME__);
        fflush(log_file);
        return -1;
    }

    // Convert data to float values
    *co2 = (float)((uint16_t)data[0] << 8 | (uint16_t)data[1]);
    *temperature = (float)((int16_t)data[2] << 8 | (int16_t)data[3]) / 200.0;
    *humidity = (float)((uint16_t)data[4] << 8 | (uint16_t)data[5]) / 100.0;

    return 0;
}

// Function to write data to the log file
int write_log_entry(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Function to control ventilation based on CO2 level
void ventilation_control(float co2) {
    if (co2 < 800.0) {
        printf("Ventilation: OFF\n");
    } else if (co2 < 1200.0) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd30_data(&sensor_data.co2, &sensor_data.temperature, &sensor_data.humidity) == 0) {
            // Write data to log file
            write_log_entry(sensor_data.co2, sensor_data.temperature, sensor_data.humidity);

            // Control ventilation
            ventilation_control(sensor_data.co2);
        } else {
            fprintf(log_file, "%s,Error reading sensor data\n", __TIME__);
            fflush(log_file);
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Stop periodic measurement
    char buf[2];
    buf[0] = (SCD30_CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, buf, 2);

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

