#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// I2C bus
#define I2C_BUS 1

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read temperature and humidity from HDC1000
int read_hdc1000(int i2c_handle, float *temperature, float *humidity) {
    char buf[4];
    int result;

    // Trigger temperature and humidity measurement
    result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Write 0x00 to register 0x00
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 4 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temperature_raw = (buf[0] << 8) | buf[1];
    uint16_t humidity_raw = (buf[2] << 8) | buf[3];

    *temperature = ((float)temperature_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humidity_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
