#define PRESSURE_REG 0x00

// Global variable for the I2C handle
int i2c_handle;

// Function prototypes
int initialize_i2c();
int read_pressure(float *pressure);
void log_pressure(float pressure);
void signal_handler(int signal);

// Structure to hold program state
struct ProgramState {
    int running;
};

struct ProgramState state = {1}; // Initialize running to 1

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    state.running = 0; // Set running to 0 to exit the main loop
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, MLX90833_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the pressure value from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int result;

    // Write the register address to be read
    result = i2cWriteByteData(i2c_handle, PRESSURE_REG, 0); // Send register address
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    // Read two bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert the raw pressure value to Pascals (adjust scaling as needed)
    *pressure = (float)raw_pressure * 0.1; // Example scaling factor

    return 0;
}

// Function to log the pressure value with a timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Pressure: %.2f Pa\n", timestamp, pressure);
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() < 0) {
        return 1;
    }

    float pressure;

    // Main loop to read and log pressure values
    while (state.running) {
        // Read the pressure value
        if (read_pressure(&pressure) == 0) {
            // Log the pressure value
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

