#define PRESSURE_REG 0x00 // Example register address, adjust as needed
#define LOG_FILE "pressure_log.csv"
#define SAFE_PRESSURE_MIN 200.0
#define SAFE_PRESSURE_MAX 250.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data (example)
typedef struct {
    float pressure_kPa;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
float read_pressure();
void log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read pressure from the sensor
float read_pressure() {
    char buf[2]; // Assuming 2 bytes for pressure data
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to reopen I2C bus: %s\n", strerror(errno));
            return -1.0; // Indicate error
        }
        return -1.0; // Indicate error
    }

    // Convert the raw data to pressure (kPa) - Example conversion
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    float pressure_kPa = (float)raw_pressure / 10.0; // Example scaling

    return pressure_kPa;
}

// Function to log pressure data to a file
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }

        // Check if the file is empty, if so, write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
        fseek(log_file, 0, SEEK_END); // Reset file pointer to end for appending
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
}

// Function to check if the pressure is within the safe range
void check_pressure_range(float pressure) {
    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "WARNING: Pressure reading %.2f kPa is outside the safe range (%.2f - %.2f kPa)!\n",
                pressure, SAFE_PRESSURE_MIN, SAFE_PRESSURE_MAX);
    }
}

// Cleanup function to close I2C and file handles
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float pressure = read_pressure();
        if (pressure >= 0) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

