#define LOG_FILE "pressure_log.txt"
#define MAX_PULSE_WIDTH 813 // Maximum valid pulse width in microseconds
#define MIN_PULSE_WIDTH 36  // Minimum valid pulse width in microseconds
#define TIMEOUT_US 1000000  // Timeout in microseconds (1 second)

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data1;
    unsigned int data2;
    unsigned int data3;
    unsigned int checksum;
} SENTData;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sent_data(SENTData *data);
int validate_pulse_width(unsigned int pulse_width);
int calculate_checksum(unsigned int data1, unsigned int data2, unsigned int data3);
int log_pressure_data(const SENTData *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to read SENT data from the sensor
int read_sent_data(SENTData *data) {
    int i;
    unsigned int pulse_widths[6]; // 6 pulses: sync, status, data1, data2, data3, checksum
    unsigned int start_tick, end_tick;
    unsigned int pulse_width;

    // Read synchronization pulse
    gpioTime(0, &start_tick, NULL);
    while (gpioRead(GPIO_PIN) == 0) {
        gpioTime(0, &end_tick, NULL);
        pulse_width = end_tick - start_tick;
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for synchronization pulse.\n");
            return -1; // Timeout
        }
    }
    gpioTime(0, &end_tick, NULL);
    pulse_width = end_tick - start_tick;
    if (!validate_pulse_width(pulse_width)) {
        fprintf(stderr, "Error: Invalid synchronization pulse width: %u\n", pulse_width);
        return -1; // Invalid pulse width
    }
    pulse_widths[0] = pulse_width;

    // Read status nibble
    gpioTime(0, &start_tick, NULL);
    while (gpioRead(GPIO_PIN) == 1) {
        gpioTime(0, &end_tick, NULL);
        pulse_width = end_tick - start_tick;
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for status nibble.\n");
            return -1; // Timeout
        }
    }
    gpioTime(0, &end_tick, NULL);
    pulse_width = end_tick - start_tick;
    if (!validate_pulse_width(pulse_width)) {
        fprintf(stderr, "Error: Invalid status nibble pulse width: %u\n", pulse_width);
        return -1; // Invalid pulse width
    }
    pulse_widths[1] = pulse_width;

    // Read data nibbles
    for (i = 0; i < 3; i++) {
        gpioTime(0, &start_tick, NULL);
        while (gpioRead(GPIO_PIN) == 0) {
            gpioTime(0, &end_tick, NULL);
            pulse_width = end_tick - start_tick;
            if (pulse_width > TIMEOUT_US) {
                fprintf(stderr, "Error: Timeout waiting for data nibble %d.\n", i + 1);
                return -1; // Timeout
            }
        }
        gpioTime(0, &end_tick, NULL);
        pulse_width = end_tick - start_tick;
        if (!validate_pulse_width(pulse_width)) {
            fprintf(stderr, "Error: Invalid data nibble %d pulse width: %u\n", i + 1, pulse_width);
            return -1; // Invalid pulse width
        }
        pulse_widths[i + 2] = pulse_width;
    }

    // Read checksum nibble
    gpioTime(0, &start_tick, NULL);
    while (gpioRead(GPIO_PIN) == 1) {
        gpioTime(0, &end_tick, NULL);
        pulse_width = end_tick - start_tick;
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for checksum nibble.\n");
            return -1; // Timeout
        }
    }
    gpioTime(0, &end_tick, NULL);
    pulse_width = end_tick - start_tick;
    if (!validate_pulse_width(pulse_width)) {
        fprintf(stderr, "Error: Invalid checksum nibble pulse width: %u\n", pulse_width);
        return -1; // Invalid pulse width
    }
    pulse_widths[5] = pulse_width;

    // Convert pulse widths to nibbles
    data->status = (pulse_widths[1] > 60) ? 1 : 0; // Example: status bit 1 if pulse > 60us
    data->data1 = (pulse_widths[2] > 60) ? 1 : 0;
    data->data2 = (pulse_widths[3] > 60) ? 1 : 0;
    data->data3 = (pulse_widths[4] > 60) ? 1 : 0;
    data->checksum = (pulse_widths[5] > 60) ? 1 : 0;

    return 0; // Success
}

// Function to validate pulse width
int validate_pulse_width(unsigned int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        return 0; // Invalid pulse width
    }
    return 1; // Valid pulse width
}

// Function to calculate checksum
int calculate_checksum(unsigned int data1, unsigned int data2, unsigned int data3) {
    return (data1 + data2 + data3) & 0x0F; // Simple checksum calculation
}

