int log_pressure_data(const SENTData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    float pressure;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Example: Convert data to pressure (replace with actual conversion)
    pressure = (float)data->data1 * 10.0; // Example: Pressure in Pascals

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Error
    }
}

int main() {
    SENTData sent_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting pressure sensor monitoring...\n");

    // Main loop
    while (running) {
        result = read_sent_data(&sent_data);
        if (result == 0) {
            // Checksum validation
            unsigned int calculated_checksum = calculate_checksum(sent_data.data1, sent_data.data2, sent_data.data3);
            if (calculated_checksum != sent_data.checksum) {
                fprintf(stderr, "Error: Checksum mismatch! Calculated: %u, Received: %u\n", calculated_checksum, sent_data.checksum);
            } else {
                // Log pressure data
                if (log_pressure_data(&sent_data) != 0) {
                    fprintf(stderr, "Error: Failed to log pressure data.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read SENT data.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

