#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Precision)
#define MEASURE_CMD 0xFD

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t crc);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SHT40 sensor
int read_sensor_data(uint8_t *data) {
    if (i2cWriteByte(i2c_handle, MEASURE_CMD) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion (at least 8.5ms)

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    sensor_data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(const sensor_data_t *sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, sensor_data->temperature, sensor_data->humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC for temperature
            if (!validate_crc(sensor_data, 2, sensor_data[2])) {
                fprintf(stderr, "Temperature CRC validation failed\n");
            } else {
                // Validate CRC for humidity
                if (!validate_crc(sensor_data + 3, 2, sensor_data[5])) {
                    fprintf(stderr, "Humidity CRC validation failed\n");
                } else {
                    // Convert data
                    if (convert_data(sensor_data, &converted_data) == 0) {
                        // Log data
                        if (log_data(&converted_data) != 0) {
                            fprintf(stderr, "Failed to log data\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to convert data\n");
                    }
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

