#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temperature);
int write_buffer_to_file(const CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius (see TMP117 datasheet)
    temperature = (float)raw_temp * 0.0078125;
    return temperature;
}

// Add temperature to circular buffer
void add_to_buffer(CircularBuffer *cb, float temperature) {
    cb->buffer[cb->head] = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Write circular buffer to file
int write_buffer_to_file(const CircularBuffer *cb) {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return -1;
    }

    size_t elements_to_write = (cb->count < BUFFER_SIZE) ? cb->count : BUFFER_SIZE;
    size_t bytes_written = fwrite(cb->buffer, sizeof(float), elements_to_write, fp);

    if (bytes_written != elements_to_write) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer cb = {{0.0}, 0, 0};

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            add_to_buffer(&cb, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        }

        // Write buffer to file every SAMPLE_INTERVAL seconds
        if (time(NULL) % SAMPLE_INTERVAL == 0) {
            if (write_buffer_to_file(&cb) != 0) {
                fprintf(stderr, "Error writing buffer to file\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Temperature monitoring stopped.\n");
    return 0;
}

