// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// Measurement command (Normal Mode, Clock Stretching disabled)
#define MEASURE_CMD 0x7866

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_shtc3(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t data[], int nbrOfBytes);
int validate_crc(const uint8_t data[], int nbrOfBytes, uint8_t crc);
int convert_data(const uint8_t data[], sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t data[], int nbrOfBytes, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, nbrOfBytes);
    return (calculated_crc == crc);
}

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SHTC3 sensor
int read_shtc3(sensor_data_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[6];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(12400); // Wait for conversion (12.4 ms)

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    if (!validate_crc(buffer, 2, buffer[2]) || !validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    if (convert_data(buffer, data) != 0) {
        fprintf(stderr, "Data conversion failed\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
int convert_data(const uint8_t data[], sensor_data_t *data) {
    int temp_raw = (data[0] << 8) | data[1];
    int hum_raw = (data[3] << 8) | data[4];

    data->temperature = 175.0 * temp_raw / 65535.0 - 45.0;
    data->humidity = 100.0 * hum_raw / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(const sensor_data_t *data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

