#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define SI7202_REG_SPEED 0x00 // Example register address for speed
#define SI7202_REG_TEMP 0x01  // Example register address for temperature
#define SPEED_SCALE_FACTOR 0.1 // Example scaling factor
#define TEMP_SCALE_FACTOR 0.01 // Example scaling factor
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float speed;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
float convert_speed(uint16_t raw_speed);
float convert_temperature(uint16_t raw_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int create_log_file();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from Si7202
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint16_t raw_speed, raw_temperature;

    // Read raw speed data
    raw_speed = i2cReadWordData(i2c_handle, SI7202_REG_SPEED);
    if (raw_speed < 0) {
        fprintf(stderr, "Error reading speed data: %d\n", raw_speed);
        data.speed = NAN;
    } else {
        data.speed = convert_speed(raw_speed);
    }

    // Read raw temperature data
    raw_temperature = i2cReadWordData(i2c_handle, SI7202_REG_TEMP);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temperature);
        data.temperature = NAN;
    } else {
        data.temperature = convert_temperature(raw_temperature);
    }

    return data;
}

// Convert raw speed data to RPM
float convert_speed(uint16_t raw_speed) {
    return (float)raw_speed * SPEED_SCALE_FACTOR;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature * TEMP_SCALE_FACTOR;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.speed, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Create log file and write header
int create_log_file() {
    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Speed(RPM),Temperature(C)\n");
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create log file
    if (create_log_file() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data logging... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

