#define FLOW_SENSOR_ID_EXPECTED 0x41
#define FLOW_SENSOR_ID_RETRY_COUNT 3
#define FLOW_SENSOR_ID_RETRY_DELAY_MS 100
#define FLOW_SENSOR_ID_RETRY_DELAY_MAX_MS 1000
#define FLOW_SENSOR_ID_RETRY_BACKOFF_FACTOR 2
#define FLOW_SENSOR_ID_RETRY_BACKOFF_MIN 1
#define FLOW_SENSOR_ID_RETRY_BACKOFF_MAX 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t flow;
    uint16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int verify_sensor_id();
int read_sensor_data(sensor_data_t *data);
float convert_flow_to_slpm(uint16_t raw_flow);
float convert_temperature_to_celsius(uint16_t raw_temperature);
void log_data(float flow_slpm, float temperature_celsius);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id() {
    char buf[1];
    int result = i2cReadDevice(i2c_handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }

    if (buf[0] != FLOW_SENSOR_ID_EXPECTED) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", buf[0], FLOW_SENSOR_ID_EXPECTED);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract flow and temperature values
    data->flow = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    data->temperature = ((uint16_t)buf[2] << 8) | (uint16_t)buf[3];

    return 0;
}

// Convert raw flow value to SLPM
float convert_flow_to_slpm(uint16_t raw_flow) {
    // Assuming a linear relationship between raw value and SLPM
    // You'll need to calibrate this based on your sensor's datasheet
    // Example: 0 raw = 0 SLPM, 16383 raw = 25 SLPM
    float slpm = (float)raw_flow / 16383.0 * 25.0;
    return slpm;
}

// Convert raw temperature value to Celsius
float convert_temperature_to_celsius(uint16_t raw_temperature) {
    // Assuming a linear relationship between raw value and Celsius
    // You'll need to calibrate this based on your sensor's datasheet
    // Example: 0 raw = -40°C, 4095 raw = 125°C
    float celsius = (float)raw_temperature / 4095.0 * 165.0 - 40.0;
    return celsius;
}

// Log data to file
void log_data(float flow_slpm, float temperature_celsius) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, flow_slpm, temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert data
            float flow_slpm = convert_flow_to_slpm(sensor_data.flow);
            float temperature_celsius = convert_temperature_to_celsius(sensor_data.temperature);

            // Log data
            log_data(flow_slpm, temperature_celsius);
        } else {
            // Log error
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, I2C read error\n", timestamp);
            fflush(log_file);

            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            if (verify_sensor_id() != 0) {
                fprintf(stderr, "Failed to verify sensor ID after re-initialization\n");
                terminate = 1; // Exit loop if sensor ID verification fails
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

