#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define READ_INTERVAL 2000 // milliseconds
#define MAX_RETRIES 3

// Structure to hold sensor data
typedef struct {
    int humidity_integer;
    int humidity_decimal;
    int temperature_integer;
    int temperature_decimal;
} SensorData;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_dht11_data(SensorData *data);
int validate_checksum(unsigned char *data);
int log_data(SensorData data);
int log_error(const char *message, int status_code);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 1); // Set high initially
    return 0;
}

// Read data from DHT11 sensor
int read_dht11_data(SensorData *data) {
    int retries = 0;
    unsigned char raw_data[5] = {0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT11_GPIO, PI_OUTPUT);
        gpioWrite(DHT11_GPIO, 0);
        gpioDelay(18000); // 18 ms
        gpioWrite(DHT11_GPIO, 1);
        gpioDelay(20); // 20 us
        gpioSetMode(DHT11_GPIO, PI_INPUT);

        // Wait for response (low for 80us, high for 80us)
        int timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                log_error("DHT11: No response (high)", 1);
                retries++;
                goto retry;
            }
        }

        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                log_error("DHT11: No response (low)", 2);
                retries++;
                goto retry;
            }
        }

        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                log_error("DHT11: No response (high after low)", 3);
                retries++;
                goto retry;
            }
        }

        // Read 40 bits of data
        for (int i = 0; i < 40; i++) {
            timeout = 0;
            while (gpioRead(DHT11_GPIO) == 0) {
                gpioDelay(1); // Wait 1 us
                timeout++;
                if (timeout > 100) {
                    log_error("DHT11: Timeout waiting for low", 4);
                    retries++;
                    goto retry;
                }
            }

            long start = gpioTick();
            timeout = 0;
            while (gpioRead(DHT11_GPIO) == 1) {
                gpioDelay(1); // Wait 1 us
                timeout++;
                if (timeout > 100) {
                    log_error("DHT11: Timeout waiting for high", 5);
                    retries++;
                    goto retry;
                }
            }
            long end = gpioTick();
            long duration = end - start;

            if (duration > 40) {
                raw_data[i / 8] |= (1 << (7 - (i % 8)));
            }
        }

        // Check checksum
        if (validate_checksum(raw_data)) {
            data->humidity_integer = raw_data[0];
            data->humidity_decimal = raw_data[1];
            data->temperature_integer = raw_data[2];
            data->temperature_decimal = raw_data[3];
            return 0; // Success
        } else {
            log_error("DHT11: Checksum failure", 6);
            retries++;
            goto retry;
        }

        retry:
        gpioDelay(1000); // Wait before retrying
    }

    log_error("DHT11: Max retries reached", 7);
    return -1; // Failure
}

// Validate checksum
int validate_checksum(unsigned char *data) {
    return (data[0] + data[1] + data[2] + data[3]) == data[4];
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Humidity: %d.%d%%, Temperature: %d.%d°C\n",
            timestamp, data.humidity_integer, data.humidity_decimal,
            data.temperature_integer, data.temperature_decimal);
    fflush(log_file);
    return 0;
}

// Log errors to file
int log_error(const char *message, int status_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Error: %s, Status: %d\n", timestamp, message, status_code);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    SensorData sensor_data;

    while (!terminate) {
        if (read_dht11_data(&sensor_data) == 0) {
            log_data(sensor_data);
        }
        gpioDelay(READ_INTERVAL * 1000); // Delay for READ_INTERVAL ms
    }

    cleanup();
    return 0;
}

