#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor I2C addresses
#define SENSOR1_ADDR 0x38
#define SENSOR2_ADDR 0x39

// Define ADPD105 register addresses (example, adjust based on datasheet)
#define ADPD105_REG_CONTROL 0x00
#define ADPD105_REG_DATA_RED 0x01
#define ADPD105_REG_DATA_GREEN 0x02
#define ADPD105_REG_DATA_BLUE 0x03

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue);
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
float average_cct(float cct1, float cct2);
int log_cct(float average_cct);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the ADPD105 sensor
int initialize_sensor(int i2c_handle) {
    // Example initialization sequence (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, ADPD105_REG_CONTROL, 0x03) < 0) { // Enable sensor
        fprintf(stderr, "Error writing to sensor control register\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    if (i2cWriteByteData(i2c_handle, ADPD105_REG_CONTROL, 0x00) < 0) { // Disable sensor
        fprintf(stderr, "Error writing to sensor control register\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    if (i2cWriteByteData(i2c_handle, ADPD105_REG_CONTROL, 0x01) < 0) { // Set gain
        fprintf(stderr, "Error writing to sensor control register\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ADPD105_REG_DATA_RED, buf, 6) != 6) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *red = (buf[0] << 8) | buf[1];
    *green = (buf[2] << 8) | buf[3];
    *blue = (buf[4] << 8) | buf[5];

    return 0;
}

// Function to calculate CCT (simplified example)
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    // This is a placeholder.  A real implementation would use a more sophisticated algorithm.
    // For example, you could use the McCamy approximation or a lookup table.
    // This example just returns a dummy value.
    return 6500.0 + (red - blue) * 0.1; // Dummy calculation
}

// Function to average CCT values
float average_cct(float cct1, float cct2) {
    return (cct1 + cct2) / 2.0;
}

// Function to log CCT to a file
int log_cct(float average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus for both sensors
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0); // Bus 1, address 0x38, no flags
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 2\n");
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize both sensors
    if (initialize_sensor(i2c_handle1) < 0) {
        fprintf(stderr, "Error initializing sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle2) < 0) {
        fprintf(stderr, "Error initializing sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1, cct2, average_cct;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) == 0) {
            cct1 = calculate_cct(red1, green1, blue1);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) == 0) {
            cct2 = calculate_cct(red2, green2, blue2);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Calculate average CCT
        if (cct1 >= 0 && cct2 >= 0) {
            average_cct = average_cct(cct1, cct2);

            // Log CCT
            if (log_cct(average_cct) != 0) {
                fprintf(stderr, "Error logging CCT\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid CCT value(s)\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

