        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data.pressure, &sensor_data.temperature) == 0) {
            // Log the data
            log_data(log_file, sensor_data.pressure, sensor_data.temperature);
        } else {
            // Log the error
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s,ERROR: Failed to read sensor data\n", timestamp);
            fflush(log_file);
        }

        // Wait for 2 seconds
        gpioDelay(2000); // pigpio's delay function
    }

    return 0;
}

