#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define AVG_TEMP_HIGH 28.0
#define AVG_TEMP_LOW 26.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temp);
float calculate_average(CircularBuffer *cb);
void control_fan(float avg_temp);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a temperature reading to the circular buffer
void add_to_buffer(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average temperature from the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read the temperature from the LM75B sensor
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, 0);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate an error
    }

    // The LM75B returns a 11-bit temperature value, left-aligned.
    // Shift right by 5 bits to get the correct value.
    raw_temp = raw_temp >> 5;

    // Convert to Celsius (0.125°C per LSB)
    float temperature = raw_temp * 0.125;
    return temperature;
}

// Control the cooling fan based on the average temperature
void control_fan(float avg_temp) {
    static int fan_on = 0; // Track fan state

    if (avg_temp > AVG_TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) != 0) {
            fprintf(stderr, "Error setting fan ON\n");
        }
        fan_on = 1;
        printf("Fan ON\n");
    } else if (avg_temp < AVG_TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) != 0) {
            fprintf(stderr, "Error setting fan OFF\n");
        }
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            add_to_buffer(&temp_buffer, temperature);
            float avg_temp = calculate_average(&temp_buffer);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, avg_temp);
            control_fan(avg_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        time_sleep(1.0); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

