#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <wiringPi.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x43
#define TEMP_REG 0x00
#define GPIO_PIN 17
#define HIGH_TEMP 28.0
#define LOW_TEMP 27.0
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
float convert_temperature(int16_t raw_temp);
int gpio_write(int pin, int value);
void signal_handler(int sig);

// I2C read function with retry mechanism
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (fd < 0) {
            fprintf(stderr, "Error: I2C file descriptor is invalid.\n");
            return -1;
        }

        if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
            fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error: Could not write register address: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        unsigned char buffer[2];
        if (read(fd, buffer, 2) != 2) {
            fprintf(stderr, "Error: Could not read temperature data: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        result = (buffer[0] << 8) | buffer[1];
        return result;
    }

    fprintf(stderr, "Error: Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Temperature conversion function
float convert_temperature(int16_t raw_temp) {
    // STTS2004 returns temperature in 2's complement format, LSB is 0.0625 degrees C
    return (float)raw_temp * 0.0625;
}

// GPIO write function
int gpio_write(int pin, int value) {
    digitalWrite(pin, value);
    return 0; // Success
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin to output mode
    pinMode(GPIO_PIN, OUTPUT);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    int led_state = LOW; // Initialize LED state

    while (!terminate) {
        // Read temperature from sensor
        int16_t raw_temp = i2c_read_reg(i2c_fd, TEMP_REG);
        if (raw_temp == -1) {
            fprintf(stderr, "Error: Failed to read temperature.\n");
            continue; // Skip to the next iteration
        }

        // Convert temperature to Celsius
        temperature = convert_temperature(raw_temp);

        // Log temperature to stdout
        printf("Temperature: %.2f °C\n", temperature);

        // Control LED with hysteresis
        if (temperature > HIGH_TEMP && led_state == LOW) {
            gpio_write(GPIO_PIN, HIGH);
            led_state = HIGH;
        } else if (temperature < LOW_TEMP && led_state == HIGH) {
            gpio_write(GPIO_PIN, LOW);
            led_state = LOW;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpio_write(GPIO_PIN, LOW); // Turn off LED
    close(i2c_fd); // Close I2C file descriptor

    return 0;
}

