#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C address of the SDP800-500Pa sensor
#define SDP800_I2C_ADDR 0x25

// Define the command to trigger a measurement (continuous mode)
#define MEASURE_CMD 0x362F

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len);
sensor_data_t process_sensor_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SDP800_I2C_ADDR, 0); // Bus 1, address 0x25, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP800-500Pa sensor
int read_sensor_data(uint8_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(45000); // Wait 45 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            bit = crc & 0x80;
            if (bit) {
                crc = (crc << 1) ^ 0x31; // Polynomial 0x31
            } else {
                crc = (crc << 1);
            }
        }
    }

    return (crc == data[len - 1]);
}

// Process sensor data and convert to physical units
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;

    // Differential pressure
    int16_t raw_pressure = (data[0] << 8) | data[1];
    sensor_data.differential_pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet

    // Temperature
    int16_t raw_temperature = (data[3] << 8) | data[4];
    sensor_data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

