#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_RH_CMD 0xE5
#define MEASURE_TEMP_CMD 0xE3
#define READ_TEMP_CMD 0xE0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int check_sensor_presence();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Check sensor presence by reading the firmware revision
int check_sensor_presence() {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, 0xE0); // Read Firmware Revision
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for the sensor to prepare the data

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    if (buf[0] != 0x90 || buf[1] != 0x3F) {
        fprintf(stderr, "Error: Invalid firmware revision. Expected 0x903F, got 0x%02X%02X\n", buf[0], buf[1]);
        return -1;
    }

    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    int result;
    uint16_t raw_humidity, raw_temperature;

    // Measure Relative Humidity
    result = i2cWriteByte(i2c_handle, MEASURE_RH_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing RH command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait 20ms

    // Read Humidity
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];

    // Measure Temperature
    result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait 20ms

    // Read Temperature
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    raw_temperature = (buf[0] << 8) | buf[1];

    // Convert raw data to temperature and humidity
    data->humidity = ((125.0 * raw_humidity) / 65536.0) - 6.0;
    data->temperature = ((175.72 * raw_temperature) / 65536.0) - 46.85;

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);
    printf("%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);

    return 0;
}

int main() {
    sensor_data_t sensor_data;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (check_sensor_presence() != 0) {
        fprintf(stderr, "Sensor not found! Exiting.\n");
        fprintf(log_file, "%s,Sensor not found!\n", __TIME__);
        fflush(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(&sensor_data) == 0) {
                log_data(sensor_data);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS);
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "I2C read failed after %d retries. Skipping.\n", MAX_RETRIES);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

