    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the HDC1080 sensor
int configure_sensor() {
    // Configure for temperature and humidity measurement, 14-bit resolution, 15 minute conversion time
    char config_data[2] = {0x00, 0x00}; // Reset and configure registers
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for configuration to take effect
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[2] << 8) | buf[3];

    data->temperature = convert_temperature(raw_temp);
    data->humidity = convert_humidity(raw_humidity);

    return 0;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return ((float)raw_temp / 65536.0) * 165.0 - 40.0;
}

// Convert raw humidity data to percentage
float convert_humidity(uint16_t raw_humidity) {
    return ((float)raw_humidity / 65536.0) * 100.0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping log entry.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

