#define MEASURE_HIGH_REP 0x2C06
#define LOG_FILE "temperature_log.txt"

int i2c_fd;
FILE *log_file;

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40
int read_temperature(float *temperature) {
    uint8_t cmd[2] = {MEASURE_HIGH_REP >> 8, MEASURE_HIGH_REP & 0xFF};
    uint8_t data[3];

    if (i2cWriteDevice(i2c_fd, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion

    if (i2cReadDevice(i2c_fd, (char *)data, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // CRC check
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC check failed.\n");
        return -1;
    }

    // Convert data to temperature
    int16_t raw_temp = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * raw_temp) / 65535.0;

    return 0;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

