    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

