}

// Function to read data from the SCD40 sensor
int read_scd40_data(SCD40Data *data) {
    char buf[6];
    int result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // CRC check
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[2] << 8) | buf[3];
    data->humidity = (buf[4] << 8) | buf[5];

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    char buf[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to initialize the circular buffer
int init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    if (pthread_mutex_init(&cb->mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return -1;
    }
    return 0;
}

// Function to add data to the circular buffer
void add_to_circular_buffer(CircularBuffer *cb, SCD40Data data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % 100;
    if (cb->count == 100) {
        cb->tail = (cb->tail + 1) % 100;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

// Function to get data from the circular buffer
int get_from_circular_buffer(CircularBuffer *cb, SCD40Data *data) {
    pthread_mutex_lock(&cb->mutex);
    if (cb->count == 0) {
        pthread_mutex_unlock(&cb->mutex);
        return -1; // Buffer is empty
    }
    *data = cb->data[cb->tail];
    cb->tail = (cb->tail + 1) % 100;
    cb->count--;
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

