        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        sensor_data_t sensor_data;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(45);

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure data
        if (validate_crc(data, 2, data[2]) != 0) {
            fprintf(stderr, "Pressure CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for temperature data
        if (validate_crc(data + 3, 2, data[5]) != 0) {
            fprintf(stderr, "Temperature CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for scale factor data
        if (validate_crc(data + 6, 2, data[8]) != 0) {
            fprintf(stderr, "Scale factor CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        if (convert_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Error converting data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

