// Constants
#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x69
#define GPIO_PIN 17
#define PRESSURE_THRESHOLD 95000.0 // Pa
#define BLINK_FREQUENCY_NORMAL 1.0 // Hz
#define BLINK_FREQUENCY_WARNING 5.0 // Hz
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
int running = 1;

// Function prototypes
int i2c_read_sensor(int fd, uint8_t *data);
int verify_crc(const uint8_t *data);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
void control_led(int gpio_pin, float pressure);
void signal_handler(int signal);

// I2C read sensor function
int i2c_read_sensor(int fd, uint8_t *data) {
    int retries = I2C_RETRY_COUNT;
    int bytes_read;

    while (retries > 0) {
        bytes_read = read(fd, data, 6);
        if (bytes_read == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// CRC verification function
int verify_crc(const uint8_t *data) {
    uint8_t crc_pressure = data[2];
    uint8_t crc_temperature = data[4];
    uint16_t pressure_data = (data[0] << 8) | data[1];
    uint16_t temperature_data = (data[3] << 8) | data[5];

