        usleep(100000); // 100 ms
        gpioWrite(gpio_pin, 0);
        usleep(100000); // 100 ms
    } else {
        // Normal mode: 1 Hz
        gpioWrite(gpio_pin, 1);
        usleep(500000); // 500 ms
        gpioWrite(gpio_pin, 0);
        usleep(500000); // 500 ms
    }
