                uint16_t raw_temperature = (sensor_data[3] << 8) | sensor_data[5];

                // Convert data
                pressure = convert_pressure(raw_pressure);
                temperature = convert_temperature(raw_temperature);

                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

                // Control LED
                control_led(GPIO_PIN, pressure);
            } else {
                fprintf(stderr, "CRC verification failed, skipping LED control.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping LED control.\n");
        }

        usleep(1000000); // 1 second delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

