            // Verify CRC
            if (verify_crc(sensor_data) == 0) {
                // Extract raw data
                uint16_t raw_pressure = (sensor_data[0] << 8) | sensor_data[1];
                uint16_t raw_temperature = (sensor_data[3] << 8) | sensor_data[5];

                // Convert data
                pressure = convert_pressure(raw_pressure);
                temperature = convert_temperature(raw_temperature);

                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

