// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_TEMP_THRESHOLD 35.0
#define OBJECT_TEMP_THRESHOLD 30.0
#define AMBIENT_TEMP_HYSTERESIS 33.0
#define OBJECT_TEMP_HYSTERESIS 28.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(int reg, float *temperature);
int log_temperature(float ambient_temp, float object_temp);
void control_fan(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
int read_temperature(int reg, float *temperature) {
    int raw_data;
    int retries = 3;

    while (retries > 0) {
        raw_data = i2cReadWordData(i2c_handle, reg);
        if (raw_data >= 0) {
            // Convert raw data to Celsius (see MLX90614 datasheet)
            *temperature = (float)raw_data * 0.02 - 273.15;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading temperature from register 0x%02X: %d\n", reg, raw_data);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read temperature from register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Log temperature data to file
int log_temperature(float ambient_temp, float object_temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f °C, Object: %.2f °C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
    return 0;
}

