void control_fan(float ambient_temp, float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > OBJECT_TEMP_THRESHOLD && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (object_temp < OBJECT_TEMP_HYSTERESIS && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Signal handler for graceful shutdown
