        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float ambient_temp, object_temp;

        // Read temperatures
        if (read_temperature(AMBIENT_TEMP_REG, &ambient_temp) == 0 &&
            read_temperature(OBJECT_TEMP_REG, &object_temp) == 0) {

            // Log temperatures
            if (log_temperature(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Error logging temperature data.\n");
            }

            // Control fan
            control_fan(ambient_temp, object_temp);

            printf("Ambient: %.2f °C, Object: %.2f °C\n", ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature data.\n");
        }

        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

