#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define PORT 8080
#define BUFFER_SIZE 1024

int i2c_handle;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sensor_data_t *data);
void process_data(unsigned char *raw_data, sensor_data_t *data);
char* create_html(sensor_data_t data);
int start_http_server(char* html_content);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    unsigned char raw_data[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait for measurement (at least 10ms)

        result = i2cReadDevice(i2c_handle, (char *)raw_data, 6);
        if (result == 6) {
            process_data(raw_data, data);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read SHT40 after multiple retries.\n");
    return -1; // Failure after retries
}

// Process raw data and convert to temperature and humidity
void process_data(unsigned char *raw_data, sensor_data_t *data) {
    unsigned int temperature_ticks = (raw_data[0] << 8) | raw_data[1];
    unsigned int humidity_ticks = (raw_data[3] << 8) | raw_data[4];

    data->temperature = -45.0 + 175.0 * (float)temperature_ticks / 65535.0;
    data->humidity = 100.0 * (float)humidity_ticks / 65535.0;

    // Clamp humidity to 0-100%
    if (data->humidity < 0.0) data->humidity = 0.0;
    if (data->humidity > 100.0) data->humidity = 100.0;
}

// Create HTML content with sensor data
char* create_html(sensor_data_t data) {
    char* html_content = (char*)malloc(BUFFER_SIZE);
    if (html_content == NULL) {
        fprintf(stderr, "Error allocating memory for HTML content.\n");
        return NULL;
    }

    snprintf(html_content, BUFFER_SIZE, 
             "HTTP/1.1 200 OK\r\n" \
             "Content-Type: text/html\r\n" \
             "\r\n" \
             "<!DOCTYPE html><html><head><title>SHT40 Sensor Data</title></head><body>" \
             "<h1>SHT40 Sensor Data</h1>" \
             "<p>Temperature: %.2f °C</p>" \
             "<p>Humidity: %.2f %%</p>" \
             "</body></html>",
             data.temperature, data.humidity);

    return html_content;
}

// Start HTTP server
int start_http_server(char* html_content) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        return -1;
    }

    printf("HTTP server listening on port %d\n", PORT);

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            continue; // Continue listening for new connections
        }

        send(new_socket, html_content, strlen(html_content), 0);
        close(new_socket);
    }

    return 0;
}

int main() {
    sensor_data_t sensor_data;
    char* html_content;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_sht40(&sensor_data) == 0) {
            html_content = create_html(sensor_data);
            if (html_content != NULL) {
                if (start_http_server(html_content) != 0) {
                    fprintf(stderr, "HTTP server failed to start.\n");
                }
                free(html_content);
            } else {
                fprintf(stderr, "Failed to create HTML content.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup (should not reach here in normal operation due to signal handling)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

