#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02
#define MEASUREMENT_CONFIG_REG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_hdc2010(sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC2010
int read_hdc2010(sensor_data_t *data) {
    uint8_t buf[4];
    int retries = 3;
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG_REG, 0x00); // Configure for temperature and humidity measurement
    if (result < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG_REG: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (polling MEASUREMENT_CONFIG_REG)
    int timeout_count = 0;
    while (1) {
        result = i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG_REG);
        if (result < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG_REG: %d\n", result);
            return -1;
        }
        if ((result & 0x01) == 0) {
            break; // Measurement complete
        }
        gpioDelay(10); // Wait 10ms
        timeout_count++;
        if (timeout_count > 50) {
            fprintf(stderr, "Timeout waiting for measurement.\n");
            return -1;
        }
    }

    // Read temperature and humidity data
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, (char *)buf, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature/humidity data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temperature_raw = (buf[0] << 8) | buf[1];
    uint16_t humidity_raw = (buf[2] << 8) | buf[3];

    data->temperature = ((float)temperature_raw / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)humidity_raw / 65536.0) * 100.0;

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_hdc2010(&sensor_data) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

