#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SDP800-500Pa I2C address
#define SDP800_ADDR 0x25

// Measurement command (continuous measurement without averaging)
#define MEASURE_CMD 0x362F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++)
    {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
        {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

// Function to read data from the SDP800-500Pa sensor
int read_sdp800(int i2c_handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2)
    {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement to complete (45ms)
    gpioDelay(45000); // 45ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6)
    {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Extract raw pressure and temperature values
    *pressure = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (int16_t)((data[3] << 8) | data[4]);

    // CRC validation
    if (crc8(data, 2) != data[2])
    {
        fprintf(stderr, "Pressure CRC check failed.\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5])
    {
        fprintf(stderr, "Temperature CRC check failed.\n");
        return -1;
    }

    return 0;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SDP800_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    int16_t pressure, temperature;

    // Main loop
    while (!terminate)
    {
        // Read data from the sensor
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0)
        {
            // Log the raw pressure and temperature values
            printf("Pressure: %d Pa, Temperature: %d\n", pressure, temperature);
        }
        else
        {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

