#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0 // CE0
#define GPIO_RELAY 17
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_TEMP 1000 // Maximum expected temperature (Celsius)
#define MIN_TEMP -273 // Minimum expected temperature (Celsius)

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static FILE *profile_file;

// Structure to hold the target temperature profile
typedef struct {
    double time;
    double temperature;
} ProfilePoint;

static ProfilePoint *profile = NULL;
static int profile_size = 0;

// Function Prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_relay_duty_cycle(double duty_cycle);
void log_temperature(double temperature);
void load_profile();
void signal_handler(int signal);

// Function to read temperature from MAX6675
double read_temperature() {
    char buf[4];
    int result;

    result = spiRead(spi_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        log_temperature(-999.0); // Log error value
        return -999.0; // Indicate error
    }

    // Check for fault bits
    if (buf[1] & 0x07) {
        fprintf(stderr, "MAX6675 Fault: %02X\n", buf[1]);
        log_temperature(-999.0); // Log error value
        return -999.0; // Indicate error
    }

    // Extract temperature data
    int raw_temp = ((buf[0] << 8) | buf[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Function to set the relay duty cycle
void set_relay_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int pwm_value = (int)(duty_cycle * 1000000.0); // pigpio PWM range is 0-1000000
    gpioPWM(GPIO_RELAY, pwm_value);
}

// Function to log temperature to file
void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written immediately
}

// Function to load the temperature profile from file
void load_profile() {
    profile_size = 0;
    char line[256];
    while (fgets(line, sizeof(line), profile_file)) {
        ProfilePoint point;
        if (sscanf(line, "%lf,%lf", &point.time, &point.temperature) == 2) {
            profile_size++;
            if (profile == NULL) {
                profile = (ProfilePoint *)malloc(profile_size * sizeof(ProfilePoint));
            } else {
                profile = (ProfilePoint *)realloc(profile, profile_size * sizeof(ProfilePoint));
            }
            if (profile == NULL) {
                fprintf(stderr, "Error allocating memory for profile\n");
                running = 0; // Stop the program if memory allocation fails
                break;
            }
            profile[profile_size - 1] = point;
        }
    }
    rewind(profile_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // SPI speed 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_RELAY, PWM_FREQUENCY);
