#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define PWM_GPIO 18
#define RELAY_GPIO 17
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // 0-1000

// Global variables (minimize usage)
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold PID gains
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDGains;

// Function prototypes
double read_temperature();
int validate_crc(unsigned char *data, int len);
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, PIDGains gains);
void set_pwm_duty_cycle(int duty_cycle);
void set_relay_state(int state);
void log_data(double average_temperature, double setpoint, double pid_output, int duty_cycle);
void signal_handler(int signal);

// Function to read temperature from DS18B20 sensor
double read_temperature() {
    char filepath[100];
    FILE *fp;
    char line[256];
    double temperature = -1000.0; // Initialize to an invalid value

    // Find the sensor ID
    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/28-");
    char sensor_id[10];
    snprintf(filepath, sizeof(filepath), "%s%02x%02x%02x%02x%02x%02x%02x%02x", filepath, 0x28, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);

    if (access(filepath, F_OK) == -1) {
        snprintf(filepath, sizeof(filepath), "%s%02x%02x%02x%02x%02x%02x%02x%02x", filepath, 0x28, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
        if (access(filepath, F_OK) == -1) {
            snprintf(filepath, sizeof(filepath), "%s%02x%02x%02x%02x%02x%02x%02x%02x", filepath, 0x28, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
            if (access(filepath, F_OK) == -1) {
                snprintf(filepath, sizeof(filepath), "%s%02x%02x%02x%02x%02x%02x%02x%02x", filepath, 0x28, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00);
                if (access(filepath, F_OK) == -1) {
                    fprintf(stderr, "Error: DS18B20 sensor not found. Check wiring and permissions.\n");
                    return -1000.0;
                }
            }
        }
    }

    snprintf(filepath, sizeof(filepath), "%s/w1_slave", filepath);

    fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1000.0;
    }

    // Read two lines from the file
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading line 1 from %s: %s\n", filepath, strerror(errno));
        fclose(fp);
        return -1000.0;
    }
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading line 2 from %s: %s\n", filepath, strerror(errno));
        fclose(fp);
        return -1000.0;
    }

    fclose(fp);

    // Check for CRC error
    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "CRC check failed\n");
        return -1000.0;
    }

    // Extract temperature
    char *temp_str = strstr(line, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found\n");
        return -1000.0;
    }

    long temp_reading = strtol(temp_str + 2, NULL, 10);
    temperature = (double)temp_reading / 1000.0;

    return temperature;
}

// Function to validate CRC checksum
int validate_crc(unsigned char *data, int len) {
    unsigned char crc = 0;
    unsigned char polynomial = 0x31; // 0x988000 is the polynomial

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == data[len - 1]);
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, PIDGains gains) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = gains.Kp * error + gains.Ki * (*integral) + gains.Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to set relay state
void set_relay_state(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log data to file
void log_data(double average_temperature, double setpoint, double pid_output, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, average_temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = 0.0; // Assuming Kd is not provided, set to 0

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Initialize relay to OFF
    set_relay_state(0);

    // Initialize PWM to 0
    set_pwm_duty_cycle(0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double integral = 0.0;
    double previous_error = 0.0;
    PIDGains gains = {Kp, Ki, Kd};

    while (running) {
        double temperature = read_temperature();

        if (temperature > -999.0) {
            double pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error, gains);

            // Map PID output to PWM duty cycle (0-1000)
            int duty_cycle = (int)pid_output;

            // Limit duty cycle to 0-1000
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

            set_pwm_duty_cycle(duty_cycle);

            // Control relay based on duty cycle (example: turn on relay if duty cycle is above a threshold)
            if (duty_cycle > 500) {
                set_relay_state(1); // Turn on relay
            } else {
                set_relay_state(0); // Turn off relay
            }

            log_data(temperature, setpoint, pid_output, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping PID calculation.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    set_relay_state(0);
    set_pwm_duty_cycle(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

