    double integral = 0.0;
    double previous_error = 0.0;
    PIDGains gains = {Kp, Ki, Kd};

    while (running) {
        double temperature = read_temperature();

        if (temperature > -999.0) {
            double pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error, gains);

            // Map PID output to PWM duty cycle (0-1000)
            int duty_cycle = (int)pid_output;

            // Limit duty cycle to 0-1000
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

            set_pwm_duty_cycle(duty_cycle);

            // Control relay based on duty cycle (example: turn on relay if duty cycle is above a threshold)
            if (duty_cycle > 500) {
                set_relay_state(1); // Turn on relay
            } else {
                set_relay_state(0); // Turn off relay
            }

            log_data(temperature, setpoint, pid_output, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping PID calculation.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    set_relay_state(0);
    set_pwm_duty_cycle(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

