// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3
#define POLLING_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_aht20(float *humidity);
void control_dehumidifier(float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    unsigned char buf[6];
    int result;
    int retries = 0;

    // Trigger measurement
    unsigned char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    result = i2cWriteDevice(i2c_handle, (char *)trigger_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

    while (retries < MAX_RETRIES) {
        // Read 6 bytes of data
        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result == 6) {
            // Check status byte (first byte)
            if ((buf[0] & 0x80) == 0 && (buf[0] & 0x40) == 0) {
                // Calculate humidity
                uint32_t raw_humidity = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
                *humidity = ((float)raw_humidity / 0x100000) * 100;
                return 0; // Success
            } else {
                fprintf(stderr, "Error: Sensor busy or calibration failed. Retry %d\n", retries + 1);
            }
        } else {
            fprintf(stderr, "Error reading data: %d. Retry %d\n", result, retries + 1);
        }

        gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retry
        retries++;
    }

    fprintf(stderr, "Error: Failed to read humidity after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to control the dehumidifier relay
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Activate dehumidifier
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Deactivate dehumidifier
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

// Function to log humidity reading with timestamp
void log_humidity(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    float humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set dehumidifier GPIO as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        result = read_aht20(&humidity);
        if (result == 0) {
            log_humidity(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Error reading humidity.\n");
        }

        sleep(POLLING_INTERVAL_S);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off on exit
    gpioTerminate();

    return 0;
}

