#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define READ_INTERVAL 60 // seconds

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int socket_fd = -1;

// Function prototypes
int init_i2c(const char *bus);
int read_htu21d(int fd, float *humidity);
int post_humidity(const char *url, float humidity);
void signal_handler(int signum);

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02x: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    syslog(LOG_INFO, "I2C bus %s initialized successfully.", bus);
    return fd;
}

// Function to read humidity from the HTU21D sensor
int read_htu21d(int fd, float *humidity) {
    unsigned char cmd = 0xE5; // Trigger humidity measurement
    unsigned char data[3];
    int result;

    result = write(fd, &cmd, 1);
    if (result != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }

    usleep(50000); // Wait for measurement (at least 50ms)

    result = read(fd, data, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1;
    }

    // CRC check (simplified, assuming data is valid)
    unsigned short raw_humidity = (data[0] << 8) | data[1];

    // Convert raw humidity to percentage
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    syslog(LOG_INFO, "Humidity: %.2f%%", *humidity);
    return 0;
}

// Function to post humidity data to the API endpoint
int post_humidity(const char *url, float humidity) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Default HTTP port
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char json_data[100];
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    char post_data[256];
    snprintf(post_data, sizeof(post_data), "POST %s HTTP/1.1\r\n" \
                             "Host: api.example.com\r\n" \
                             "Content-Type: application/json\r\n" \
                             "Content-Length: %zu\r\n" \
                             "\r\n" \
                             "%s", API_ENDPOINT, strlen(json_data), json_data);

    ssize_t bytes_sent = send(sock, post_data, strlen(post_data), 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
        close(sock);
        return -1;
    }

    close(sock);
    syslog(LOG_INFO, "Humidity data posted to %s", url);
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    syslog(LOG_INFO, "Signal %d received, shutting down...", signum);
}

int main() {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting.");
        closelog();
        return 1;
    }

    float humidity;

    while (program_running) {
        if (read_htu21d(i2c_fd, &humidity) == 0) {
            if (post_humidity(API_ENDPOINT, humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    closelog();

    return 0;
}

