    while (verify_chip_id() != 0 && retries < 3) {
        fprintf(stderr, "Chip ID verification failed. Retrying... (%d/%d)\n", retries + 1, 3);
        i2cClose(i2c_handle);
        gpioDelay(1000); // Wait 1 second before retrying
        if (init_i2c() != 0) {
            fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
            cleanup();
            return 1;
        }
        retries++;
    }

    if (retries == 3) {
        fprintf(stderr, "Chip ID verification failed after multiple retries. Exiting.\n");
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Calibration data read failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set sensor mode and oversampling
    char config_data[2];
    config_data[0] = BMP280_REG_CTRL_MEAS;
    config_data[1] = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL;
    int result = i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, config_data + 1, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing control register: %d\n", result);
        cleanup();
        return 1;
    }

    config_data[0] = BMP280_REG_CONFIG;
    config_data[1] = (0x02 << 5) | (0x00 << 2); // t_sb = 0.5ms, filter = off
    result = i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CONFIG, config_data + 1, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing config register: %d\n", result);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;

        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            double temperature = compensate_temperature(raw_temperature);
            double pressure = compensate_pressure(raw_pressure, temperature);

            printf("Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", temperature, pressure);
            log_pressure(pressure);
        } else {
