// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_I2C_RETRIES 3
#define BACKOFF_MS 10
#define LOG_FILE_NAME_MAX_LEN 20

// Global variables
static volatile int running = 1;
static int i2c_handle_tmp117 = -1;
static int i2c_handle_aht20 = -1;
static char log_file_name[LOG_FILE_NAME_MAX_LEN] = "sensor_log.csv";

// Function prototypes
int init_i2c(int bus, int addr);
int read_tmp117(int i2c_handle, float *temperature);
int read_aht20(int i2c_handle, float *humidity);
int read_pir(int gpio);
int log_data(const char *filename, float temperature, float humidity, int motion);
void signal_handler(int signal);
void create_daily_log_file();

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read temperature from TMP117
int read_tmp117(int i2c_handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_I2C_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (float)raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_MS * (1 << retries)); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_I2C_RETRIES);
    return -1; // Failure
}

// Function to read humidity from AHT20
int read_aht20(int i2c_handle, float *humidity) {
    char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_I2C_RETRIES) {
        // Trigger measurement (Datasheet specifies this)
        char trigger_cmd[3] = {0xAC, 0x33, 0x00};
        result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
        if (result != 3) {
            fprintf(stderr, "Error triggering AHT20 measurement (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_MS * (1 << retries));
            continue;
        }
        gpioDelay(80); // Wait for measurement (Datasheet specifies 75ms)

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            // Check status bit (bit 7 of byte 0)
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20 busy.\n");
                retries++;
                gpioDelay(BACKOFF_MS * (1 << retries));
                continue;
            }

            // Calculate humidity
            int humidity_raw = ((buf[1] << 12) | (buf[2] << 4) | (buf[3] >> 4));
            *humidity = ((float)humidity_raw / 0x100000) * 100;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading AHT20 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_MS * (1 << retries));
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries.\n", MAX_I2C_RETRIES);
    return -1; // Failure
