#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int direction, int duration_seconds);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, stopping motor and cleaning up...");
    control_motor(0, 0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1; // Indicate failure
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Control the motor
int control_motor(int direction, int duration_seconds) {
    if (duration_seconds > 0) {
        if (direction == 1) { // Forward
            gpioWrite(MOTOR_ENA_PIN, 1);
            gpioWrite(MOTOR_IN1_PIN, 1);
            gpioWrite(MOTOR_IN2_PIN, 0);
            log_message("Motor started (forward)");
        } else if (direction == -1) { // Backward
            gpioWrite(MOTOR_ENA_PIN, 1);
            gpioWrite(MOTOR_IN1_PIN, 0);
            gpioWrite(MOTOR_IN2_PIN, 1);
            log_message("Motor started (backward)");
        } else {
            log_message("Invalid motor direction");
            return 1;
        }

        gpioDelay(duration_seconds * 1000000); // Delay in microseconds
    } else {
        gpioWrite(MOTOR_ENA_PIN, 0); // Stop the motor
        log_message("Motor stopped");
    }
    return 0;
}

// Log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_message("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = (read_rain_sensor() == 0); // Active low

        if (rain_detected) {
            log_message("Rain detected!");
            control_motor(1, 5); // Close window (forward)
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

