#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
float calculate_cpu_load();
void map_load_to_color(float load, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", signal);
        program_running = 0;
        set_led_color(0, 0, 0); // Turn off LED
        gpioTerminate();       // Terminate pigpio
        exit(0);
    }
}

// Function to calculate CPU load
float calculate_cpu_load() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float load;

    // Read CPU statistics from /proc/stat
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }

    // Read the first line (CPU statistics)
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error reading CPU stats from /proc/stat\n");
        return -1.0; // Indicate error
    }
    fclose(fp);

    // Wait for 500ms
    gpioDelay(500000); // 500ms in microseconds

    // Read CPU statistics again
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }

    // Read the first line (CPU statistics)
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error reading CPU stats from /proc/stat\n");
        return -1.0; // Indicate error
    }
    fclose(fp);

    // Calculate the differences
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long diff_total = total - prev_total;
    unsigned long long diff_idle = idle - prev_idle;

    // Calculate CPU load
    load = (float)(diff_total - diff_idle) / diff_total * 100.0;

    return load;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float load, int *red, int *green, int *blue) {
    if (load < 0.0) {
        *red = 0;
        *green = 0;
        *blue = 0;
        return;
    }

    if (load <= 50.0) {
        // Green to Yellow
        *red = (int)(load / 50.0 * 255.0);
        *green = 255 - (int)(load / 50.0 * 255.0);
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = 255 - (int)((load - 50.0) / 50.0 * 255.0);
        *blue = 0;
    }
}

// Function to set the LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the value
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Calculate CPU load
        float load = calculate_cpu_load();
        if (load < 0.0) {
            fprintf(stderr, "Error calculating CPU load, exiting.\n");
            break;
        }

        // Map load to color
        int red, green, blue;
        map_load_to_color(load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Print CPU load and color values (optional)
        printf("CPU Load: %.2f%%, RGB: (%d, %d, %d)\n", load, red, green, blue);

        // Wait for 500ms
        gpioDelay(500000); // 500ms in microseconds
    }

    // Clean up and exit
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    return 0;
}

