int send_udp_packet(const char *json_string) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return 1;
    }

    // Initialize UDP socket
    if (init_udp_socket() != 0) {
        fprintf(stderr, "UDP socket initialisation failed\n");
        cleanup();
        return 1;
    }

    printf("Starting data acquisition and transmission...\n");

    while (!terminate) {
        int32_t raw_temperature, raw_pressure;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            double temperature = compensate_temperature(raw_temperature);
            double pressure = compensate_pressure(raw_pressure, temperature);

            // Format data into JSON
            char *json_string = format_json(temperature, pressure);
            if (json_string != NULL) {
                // Send UDP packet
                if (send_udp_packet(json_string) != 0) {
                    fprintf(stderr, "Failed to send UDP packet\n");
                }

                // Free allocated memory
                free(json_string);
            } else {
                fprintf(stderr, "Failed to format JSON\n");
            }
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Exiting.\n");
    return 0;
}

