#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Structure to store temperature, duty cycle, and timestamp
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} DataPoint;

// Circular buffer
DataPoint buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_handle;

// Function prototypes
float read_temperature();
int calculate_duty_cycle(float temperature);
void update_pwm(int duty_cycle);
void store_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x07) {
        fprintf(stderr, "MAX31855 Fault: %02X\n", data[3]);
        return -1000.0; // Indicate error
    }

    // Extract temperature data (bits 3-18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 3;

    // Convert to Celsius
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < 25.0) {
        return 0;
    } else if (temperature < 40.0) {
        return (int)((temperature - 25.0) / (40.0 - 25.0) * 50.0);
    } else if (temperature < 60.0) {
        return (int)((temperature - 40.0) / (60.0 - 40.0) * 150.0 + 50.0);
    } else {
        return 200;
    }
}

// Function to update PWM duty cycle
void update_pwm(int duty_cycle) {
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to store data in the circular buffer
void store_data(float temperature, int duty_cycle) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, buffer[index].temperature, buffer[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM GPIO
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            int duty_cycle = calculate_duty_cycle(temperature);
            update_pwm(duty_cycle);
            store_data(temperature, duty_cycle);
            printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping PWM update.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    update_pwm(0); // Stop the fan
    spiClose(spi_handle);
    print_buffer();
    gpioTerminate();

    return 0;
}

