    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char control_value = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &control_value, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure from BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char control_value = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &control_value, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(26000); // Wait 25.5ms (OSS=3)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }

    *raw_pressure = ((unsigned long)buf[0] << 16 | (unsigned long)buf[1] << 8 | (unsigned long)buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) / 4;

    unsigned long x1_pressure = ((unsigned long)ac3 * b6) / pow(2, 13);
    unsigned long x2_pressure = ((unsigned long)b1 * ((b6 * b6) / pow(2, 12))) / pow(2, 16);
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) / 4);
    unsigned long b4 = ((unsigned long)ac4 * (x3_pressure + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);

    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to calculate altitude in meters
double calculate_altitude(double pressure) {
    double altitude = 44330 * (1 - pow(pressure / 101325, 0.1903));
    return altitude;
}

// Function to log data to file
void log_data(double temperature, double pressure, double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, pressure, altitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    logging_active = !logging_active;
    printf("Interrupt received on GPIO %d. Logging %s\n", gpio, logging_active ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode and pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw_temp, raw_pressure;
        double temperature, pressure, altitude;

        if (logging_active) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate temperature, pressure, and altitude
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, raw_temp);
                altitude = calculate_altitude(pressure);

                // Log data
                log_data(temperature, pressure, altitude);

                printf("Temperature: %.2f C, Pressure: %.2f Pa, Altitude: %.2f m\n", temperature, pressure, altitude);
            } else {
                fprintf(stderr, "Error reading sensor data. Retrying in 1 second.\n");
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

