#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// RTD Constants (PT100)
#define R0 100.0
#define A 3.9083e-3
#define B -5.775e-7
#define C -4.183e-12

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_spi();
int read_max31865(uint16_t *raw_data);
int check_fault_status(uint16_t raw_data);
double calculate_temperature(uint16_t raw_data);
int log_temperature(double temperature);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_pin;
    char *log_file;
    int sample_interval;
} Config;

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate chip select initially
    return 0;
}

// Read data from MAX31865
int read_max31865(uint16_t *raw_data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Read RTD MSB and LSB registers (0x01 and 0x02)
    tx_buffer[0] = MAX31865_RTD_MSB_REG | 0x80; // Read command
    tx_buffer[1] = 0x00; // Dummy byte for MSB
    tx_buffer[2] = 0x00; // Dummy byte for LSB

    gpioWrite(CS_PIN, 0); // Activate chip select
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deactivate chip select

    if (result != 3) {
        fprintf(stderr, "SPI read/write error: %d\n", result);
        return -1;
    }

    *raw_data = ((uint16_t)rx_buffer[1] << 8) | (uint16_t)rx_buffer[2];
    return 0;
}

// Check fault status
int check_fault_status(uint16_t raw_data) {
    uint16_t fault_data;

    // Read Fault Register (0x07)
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = MAX31865_FAULT_REG | 0x80; // Read command
    tx_buffer[1] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Activate chip select
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    gpioWrite(CS_PIN, 1); // Deactivate chip select

    if (result != 2) {
        fprintf(stderr, "SPI fault read error: %d\n", result);
        return -1;
    }

    fault_data = (uint16_t)rx_buffer[1];

    if (fault_data & 0x01) {
        fprintf(stderr, "Sensor absent\n");
        return -1;
    }

    if (fault_data & 0x02) {
        fprintf(stderr, "RTD fault\n");
        return -1;
    }

    return 0;
}

// Calculate temperature using Callendar-Van Dusen equation
double calculate_temperature(uint16_t raw_data) {
    double rtd_resistance = (double)raw_data * 430.0 / 32768.0; // Convert to resistance (assuming 430 Ohm reference resistor)
    double temperature;

    if (rtd_resistance < 30) {
        fprintf(stderr, "Invalid RTD resistance: %.2f\n", rtd_resistance);
        return -273.15; // Return absolute zero as error value
    }

    double ratio = rtd_resistance / R0;

    if (ratio > 1.0) {
        temperature = (rtd_resistance - R0) / (A * rtd_resistance);
    } else {
        temperature = (rtd_resistance - R0) / (B * rtd_resistance * rtd_resistance);
    }

    return temperature;
}

// Log temperature to file
int log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        double temperature;

        // Read data from MAX31865
        if (read_max31865(&raw_data) == 0) {
            // Check fault status
            if (check_fault_status(raw_data) == 0) {
                // Calculate temperature
                temperature = calculate_temperature(raw_data);

                // Log temperature
                if (temperature > -273.0) {
                    log_temperature(temperature);
                    printf("Temperature: %.2f °C\n", temperature);
                } else {
                    fprintf(stderr, "Error: Invalid temperature reading\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading MAX31865\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for sample interval
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

