#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

static struct bme280_calib_data calib;

// Function prototypes
int bme280_init();
int bme280_read_calibration_data(struct bme280_calib_data *calib);
int bme280_read_data(float *temperature, float *humidity, float *pressure);
int bme280_write_register(uint8_t reg, uint8_t value);
int bme280_read_register(uint8_t reg, uint8_t *value);
int bme280_read_registers(uint8_t reg, uint8_t *buffer, int len);
void log_data(float temperature, float humidity, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to write a single byte to a BME280 register
int bme280_write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a single byte from a BME280 register
int bme280_read_register(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to read multiple bytes from a BME280 register
int bme280_read_registers(uint8_t reg, uint8_t *buffer, int len) {
    int result = i2cReadI2CBlockData(i2c_handle, reg, (char *)buffer, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the BME280 sensor
int bme280_init() {
    // Check the chip ID
    uint8_t chip_id;
    if (bme280_read_register(BME280_REG_CHIPID, &chip_id) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (bme280_read_calibration_data(&calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    if (bme280_write_register(BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error setting humidity oversampling\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (bme280_write_register(BME280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error setting temperature and pressure oversampling\n");
        return -1;
    }

    // Set inactive duration to 0.5ms
    if (bme280_write_register(BME280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error setting inactive duration\n");
        return -1;
    }

