#include <pthread.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SLEEP_SECONDS 1

// Global variables (protected by mutex)
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
double running_average = 0.0;
int i2c_handle;
pthread_mutex_t buffer_mutex;
volatile sig_atomic_t terminate = 0;

// Function prototypes
double read_temperature();
void update_buffer(double temperature);
double calculate_average();
void control_led(double temperature);
void *led_thread(void *arg);
void signal_handler(int signal);

// Function to read temperature from LM75 sensor
double read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    double temperature = raw_temp * 0.125;

    return temperature;
}

// Function to update the circular buffer
void update_buffer(double temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
double calculate_average() {
    pthread_mutex_lock(&buffer_mutex);
    double sum = 0.0;
    if (buffer_count > 0) {
        for (int i = 0; i < buffer_count; i++) {
            sum += temperature_buffer[i];
        }
        running_average = sum / buffer_count;
    } else {
        running_average = 0.0;
    }
    pthread_mutex_unlock(&buffer_mutex);
    return running_average;
}

// Function to control the LED based on temperature
void control_led(double temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Thread function to control the LED
void *led_thread(void *arg) {
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            control_led(temperature);
        }
        sleep(SLEEP_SECONDS);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    pthread_t led_thread_id;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initially turn LED off

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create LED control thread
    result = pthread_create(&led_thread_id, NULL, led_thread, NULL);
    if (result) {
        fprintf(stderr, "Error creating LED thread: %d\n", result);
        pthread_mutex_destroy(&buffer_mutex);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature > -999.0) {
            update_buffer(temperature);
            double average = calculate_average();
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average);
        } else {
            fprintf(stderr, "Error reading temperature, skipping buffer update.\n");
        }
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    pthread_join(led_thread_id, NULL);
    pthread_mutex_destroy(&buffer_mutex);
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn LED off before exiting
    gpioTerminate();

    return 0;
}

