#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, int raw_temp);
void log_breach(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    char buf[22];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char control_value = 0x2E; // Temperature measurement command
    int result;

    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &control_value, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature: %d\n", result);
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char control_value = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    int result;

    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &control_value, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure command: %d\n", result);
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait 2.5ms, 7.5ms, 12.5ms, or 17.5ms

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", result);
        return -1;
    }

    *raw_pressure = ((unsigned long)buf[0] << 16 | (unsigned long)buf[1] << 8 | (unsigned long)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1, x2;
    long b5;

    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;

    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temp) {
    long x1, x2, x3, b3, b6, p;
    unsigned long b4, b7;

    long ut = raw_temp;
    long up = raw_pressure;

    long x1_t, x2_t, b5_t;

    x1_t = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    x2_t = ((long)mc << 11) / (x1_t + md);
    b5_t = x1_t + x2_t;

    b6 = b5_t - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    double pressure = p / 100.0; // Convert to hPa
    return pressure;
}

// Function to log a breach to the breach_log.txt file
void log_breach(double temperature, double pressure) {
    FILE *fp = fopen("breach_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening breach_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", s, temperature, pressure);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_temp, raw_pressure;
        double temperature, pressure;
        int retry_count = 0;

        // Read raw temperature and pressure with retries
        while (retry_count < 3) {
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read error, retrying (%d/3)...\n", retry_count + 1);
                retry_count++;
                gpioDelay(100000); // Wait 100ms before retrying
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read sensor data after multiple retries. Skipping.\n");
            gpioDelay(1000000); // Wait 1 second before next attempt
            continue;
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        // Check for breaches
        if (temperature > 30.0 || pressure < 950.0) {
            log_breach(temperature, pressure);
            printf("Breach detected: Temperature = %.2f C, Pressure = %.2f hPa\n", temperature, pressure);
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("BMP180 sensor monitoring stopped.\n");
    return 0;
}

