    return (msb << 8) + lsb;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure() {
    wiringPiI2CWriteReg8(bmp180_fd, BMP180_REG_CONTROL, 0x34 + (OSS << 6));
    delay(2 + (3 << OSS)); // Wait for conversion

    int msb = wiringPiI2CReadReg8(bmp180_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(bmp180_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(bmp180_fd, BMP180_REG_XLSB);

