void add_reading(float temperature, float pressure) {
    readings[buffer_index].timestamp = time(NULL);
    readings[buffer_index].temperature = temperature;
    readings[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

