void control_fan(float temperature) {
    if (temperature > 30.0) {
        digitalWrite(FAN_PIN, HIGH); // Turn fan on
    } else {
        digitalWrite(FAN_PIN, LOW);  // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature = read_raw_temperature();
    int raw_pressure = read_raw_pressure();

    if (raw_temperature != -1 && raw_pressure != -1) {
        float temperature = calculate_temperature(raw_temperature);
        float pressure = calculate_pressure(raw_pressure, temperature);

        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        add_reading(temperature, pressure);
        control_fan(temperature);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
    digitalWrite(FAN_PIN, LOW); // Turn fan off
    close(bmp180_fd);
    exit(0);
}

