    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() == -1) {
        return 1;
    }

    // Set GPIO pin for fan as output
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW); // Initially turn the fan off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    if (wiringPiISR(0, INT_TIMER_500, timer_callback) < 0) {
        fprintf(stderr, "Unable to setup timer callback.\n");
        return 1;
    }

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        delay(1000); // Sleep for 1 second
    }

    return 0;
}

