// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    ac1 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC1); if (ac1 == -1) return -1;
    ac2 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC2); if (ac2 == -1) return -1;
    ac3 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC3); if (ac3 == -1) return -1;
    ac4 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC4); if (ac4 == -1) return -1;
    ac5 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC5); if (ac5 == -1) return -1;
