    *raw_pressure = ((int)msb << 16 | (int)lsb << 8 | (int)xlsb) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate the compensated temperature in degrees Celsius
double calculate_temperature(int raw_temperature) {
    long x1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
