        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to log the data to a file
void log_data(double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Interrupt handler function
void interrupt_handler(void) {
    unsigned long current_time = millis();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_time = current_time;
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() == -1) {
        fprintf(stderr, "Error reading calibration data.\n");
        return 1;
    }

    // Set up interrupt on GPIO27
    wiringPiISR(LOGGING_PIN, INT_EDGE_FALLING, &interrupt_handler);
    pinMode(LOGGING_PIN, INPUT);
    pullUpDnControl(LOGGING_PIN, PUD_UP); // Enable pull-up resistor

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("BMP180 data logger started. Press Ctrl+C to exit.\n");

    while (1) {
        if (logging_enabled) {
            int raw_temperature, raw_pressure;
            double temperature, pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == -1 || read_raw_pressure(&raw_pressure) == -1) {
                fprintf(stderr, "Error reading sensor data. Re-initializing I2C.\n");
                close(i2c_fd);
                if (init_i2c() == -1) {
                    fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                    break;
                }
                if (read_calibration_data() == -1) {
                    fprintf(stderr, "Error reading calibration data after re-initialization.\n");
                    break;
                }
                delay(1000); // Wait before retrying
                continue;
            }

            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temperature);
            pressure = calculate_pressure(raw_pressure, temperature);

            // Log the data
            log_data(pressure);
        }

        delay(2000); // Wait 2 seconds
    }

    return 0;
}

