#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define KP 1.0
#define KI 0.1
#define SAMPLE_INTERVAL 1 // seconds
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold PI controller state
typedef struct {
    double integral;
} PIControllerState;

PIControllerState pi_state = {0.0};

// Function prototypes
int spi_read_max31855(int spi_handle, uint32_t *data);
double extract_temperature(uint32_t raw_data);
double calculate_duty_cycle(double current_temperature, double target_temperature, PIControllerState *pi_state);
void set_heater_duty_cycle(int gpio_pin, double duty_cycle);
void log_data(FILE *log_file, double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// SPI read function
int spi_read_max31855(int spi_handle, uint32_t *data) {
    char tx_buf[4] = {0, 0, 0, 0}; // Dummy data for reading
    char rx_buf[4];

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1;
    }

    *data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];
    return 0;
}

// Temperature extraction function
double extract_temperature(uint32_t raw_data) {
    if (raw_data & 0x00000007) {
        fprintf(stderr, "MAX31855 Fault: %08X\n", raw_data);
        return -273.15; // Return absolute zero on error
    }

    double temperature = ((double)((raw_data >> 18) & 0x3FFF)) * 0.25;
    if (raw_data & 0x80000000) {
        temperature -= 16384.0 * 0.25;
    }

    return temperature;
}

// PI controller function
double calculate_duty_cycle(double current_temperature, double target_temperature, PIControllerState *pi_state) {
    double error = target_temperature - current_temperature;
    pi_state->integral += error * SAMPLE_INTERVAL;

    // Anti-windup
    double max_integral = (MAX_DUTY_CYCLE / 100.0) * (KP / KI); // Calculate max integral based on max duty cycle
    if (pi_state->integral > max_integral) {
        pi_state->integral = max_integral;
    } else if (pi_state->integral < -max_integral) {
        pi_state->integral = -max_integral;
    }

    double output = KP * error + KI * pi_state->integral;

    // Clamp the output
    if (output < 0.0) {
        output = 0.0;
    } else if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    }

    return output;
}

// Heater control function
void set_heater_duty_cycle(int gpio_pin, double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // pigpio PWM range is 0-255
    gpioPWM(gpio_pin, pwm_value);
}

// Logging function
void log_data(FILE *log_file, double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    set_heater_duty_cycle(HEATER_GPIO, 0.0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    uint32_t raw_data;
    double temperature;
    double duty_cycle;

    while (!terminate) {
        if (spi_read_max31855(spi_handle, &raw_data) == 0) {
            temperature = extract_temperature(raw_data);

            if (temperature > -273.0) {
                duty_cycle = calculate_duty_cycle(temperature, TARGET_TEMPERATURE, &pi_state);
                set_heater_duty_cycle(HEATER_GPIO, duty_cycle);
                log_data(log_file, temperature, duty_cycle);
            } else {
                fprintf(stderr, "Invalid temperature reading, setting duty cycle to 0\n");
                set_heater_duty_cycle(HEATER_GPIO, 0.0);
                log_data(log_file, temperature, 0.0);
            }
        } else {
            fprintf(stderr, "SPI read failed, setting duty cycle to 0\n");
            set_heater_duty_cycle(HEATER_GPIO, 0.0);
            log_data(log_file, -273.15, 0.0); // Log error temperature
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

