// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Define PWM range
#define PWM_RANGE 255

// Define temperature thresholds
#define TEMP_LOW   40000
#define TEMP_MED   59999
#define TEMP_HIGH  60000

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_temperature();
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    set_led_color(255, 255, 255); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    temperature = atoi(buffer);
    return temperature;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    int result;

    result = gpioPWM(RED_PIN, PWM_RANGE - red);
    if (result != 0) {
        fprintf(stderr, "Error setting red PWM: %d\n", result);
    }

    result = gpioPWM(GREEN_PIN, PWM_RANGE - green);
    if (result != 0) {
        fprintf(stderr, "Error setting green PWM: %d\n", result);
    }

    result = gpioPWM(BLUE_PIN, PWM_RANGE - blue);
    if (result != 0) {
        fprintf(stderr, "Error setting blue PWM: %d\n", result);
    }
}

int main() {
    int temperature;
    int red, green, blue;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Set PWM frequency (optional, but recommended)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        temperature = read_temperature();

        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, skipping update\n");
            sleep(0.5);
            continue;
        }

        // Determine LED color based on temperature
        if (temperature < TEMP_LOW) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temperature < TEMP_MED) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temperature, PWM_RANGE - red, PWM_RANGE - green, PWM_RANGE - blue);

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_led_color(255, 255, 255); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    return 0;
}

