#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 1

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read data from DHT22 sensor
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1000); // 1 ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 30 us

    // Switch to input mode and read data
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the sensor to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22 not responding (timeout waiting for low signal)\n");
        return -1; // Sensor not responding
    }

    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22 not responding (timeout waiting for high signal)\n");
        return -1; // Sensor not responding
    }

    timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22 not responding (timeout waiting for low signal)\n");
        return -1; // Sensor not responding
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0 && timeout < 100) {
            gpioDelay(1); // Wait 1 us
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22 timeout waiting for high signal (bit %d)\n", i);
            return -1; // Timeout
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1 && timeout < 100) {
            gpioDelay(1); // Wait 1 us
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22 timeout waiting for low signal (bit %d)\n", i);
            return -1; // Timeout
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        fprintf(stderr, "DHT22 checksum mismatch\n");
        return -2; // Checksum mismatch
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Failed to allocate memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to post data to the server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        // Set content type header
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "Failed to initialize libcurl\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    float temperature, humidity;
    int retries = 0;
    int result;
    char *json_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (!terminate) {
        retries = 0;
        result = -1; // Initialize result to an error state

        while (retries < MAX_RETRIES && result != 0) {
            result = read_dht22(DHT22_GPIO, &temperature, &humidity);
            if (result == 0) {
                json_data = format_json(temperature, humidity);
                if (json_data != NULL) {
                    if (post_data(json_data) == 0) {
                        printf("Data posted successfully: %s\n", json_data);
                    } else {
                        fprintf(stderr, "Failed to post data (attempt %d)\n", retries + 1);
                    }
                    free(json_data);
                } else {
                    fprintf(stderr, "Failed to format JSON data (attempt %d)\n", retries + 1);
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 data (attempt %d): %d\n", retries + 1, result);
            }

            if (result != 0) {
                retries++;
                sleep(RETRY_DELAY_SEC);
            }
        }

        if (result != 0) {
            fprintf(stderr, "Failed to post data after %d retries\n", MAX_RETRIES);
        }

        sleep(60); // Wait 60 seconds
    }

    // Clean up
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

