#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS3 0xF4 // OSS = 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 4

// Debounce time (microseconds)
#define DEBOUNCE_TIME 200000

// Global variables
static int i2c_fd;
static volatile bool logging_enabled = false;
static volatile unsigned long last_interrupt_time = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, double temperature);
void log_pressure(double pressure);
void interrupt_handler();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    ac1 = wiringPiI2CReadReg16(i2c_fd, 0xAA); if (ac1 == -1) return -1;
    ac2 = wiringPiI2CReadReg16(i2c_fd, 0xAC); if (ac2 == -1) return -1;
    ac3 = wiringPiI2CReadReg16(i2c_fd, 0xAE); if (ac3 == -1) return -1;
    ac4 = wiringPiI2CReadReg16(i2c_fd, 0xB0); if (ac4 == -1) return -1;
    ac5 = wiringPiI2CReadReg16(i2c_fd, 0xB2); if (ac5 == -1) return -1;
    ac6 = wiringPiI2CReadReg16(i2c_fd, 0xB4); if (ac6 == -1) return -1;
    b1 = wiringPiI2CReadReg16(i2c_fd, 0xB6); if (b1 == -1) return -1;
    b2 = wiringPiI2CReadReg16(i2c_fd, 0xB8); if (b2 == -1) return -1;
    mb = wiringPiI2CReadReg16(i2c_fd, 0xBA); if (mb == -1) return -1;
    mc = wiringPiI2CReadReg16(i2c_fd, 0xBC); if (mc == -1) return -1;
    md = wiringPiI2CReadReg16(i2c_fd, 0xBE); if (md == -1) return -1;

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temp) {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP);
    delay(5); // Wait 4.5ms
    *raw_temp = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_MSB); if (*raw_temp == -1) return -1;
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int *raw_pressure) {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS3);
    delay(26); // Wait 26ms for OSS = 3

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB); if (msb == -1) return -1;
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB); if (lsb == -1) return -1;
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB); if (xlsb == -1) return -1;

    *raw_pressure = (msb << 16 | lsb << 8 | xlsb) >> (8 - 3); // OSS = 3
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, double temperature) {
    long b6 = (long)temperature * 10 - 4000;
    long x1 = ((long)b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    long x2 = ((long)ac2 * b6) / pow(2, 11);
    long x3 = x1 + x2;
    long b3 = (((((long)ac1) * 4 + x3) << 3) + 2) / 4;
    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> 3);

    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to log pressure to a file
void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler() {
    unsigned long current_time = micros();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        if (logging_enabled) {
            log_file = fopen("pressure_log.txt", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
                logging_enabled = false; // Disable logging if file can't be opened
            }
            printf("Logging enabled.\n");
        } else {
            printf("Logging disabled.\n");
            if (log_file != NULL) {
                fclose(log_file);
                log_file = NULL;
            }
        }
        last_interrupt_time = current_time;
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() == -1) {
        fprintf(stderr, "Error reading calibration data.\n");
        return 1;
    }

    // Set up interrupt pin
    pinMode(INTERRUPT_PIN, INPUT);
    pullUpDnControl(INTERRUPT_PIN, PUD_UP); // Enable internal pull-up resistor
    if (wiringPiISR(INTERRUPT_PIN, INT_EDGE_FALLING, &interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 data logger started. Press the button connected to GPIO %d to toggle logging.\n", INTERRUPT_PIN);

    while (program_running) {
        if (logging_enabled && log_file != NULL) {
            int raw_temp, raw_pressure;
            double temperature, pressure;

            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, temperature);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        }
        delay(2000); // Wait 2 seconds
    }

    return 0;
}

