#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define CURRENT_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char temp_str[10];
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fgets(temp_str, sizeof(temp_str), fp) == NULL) {
        perror("Failed to read temperature from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temp_milli_celsius = atoi(temp_str);
    return temp_milli_celsius;
}

// Function to read the maximum fan state from file
int read_max_state() {
    FILE *fp;
    char max_state_str[10];

    fp = fopen(MAX_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open max_state file");
        return -1;
    }

    if (fgets(max_state_str, sizeof(max_state_str), fp) == NULL) {
        perror("Failed to read max_state from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return atoi(max_state_str);
}

// Function to read the current fan state from file
int read_current_state() {
    FILE *fp;
    char current_state_str[10];

    fp = fopen(CURRENT_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open current_state file");
        return -1;
    }

    if (fgets(current_state_str, sizeof(current_state_str), fp) == NULL) {
        perror("Failed to read current_state from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return atoi(current_state_str);
}

// Function to set the fan state
int set_fan_state(int state) {
    FILE *fp;
    char state_str[10];

    fp = fopen(CURRENT_STATE_FILE, "w");
    if (fp == NULL) {
        perror("Failed to open current_state file for writing");
        return -1;
    }

    snprintf(state_str, sizeof(state_str), "%d", state);
    if (fputs(state_str, fp) == EOF) {
        perror("Failed to write state to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Function to determine the fan state based on temperature
int determine_fan_state(int temperature, int max_state) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else if (temperature <= (max_state * 10000)) {
        return max_state;
    } else {
        return max_state;
    }
}

int main() {
    int cpu_temp, max_state, current_state, desired_state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read CPU temperature
        cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            fprintf(stderr, "Error reading CPU temperature, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Read maximum fan state
        max_state = read_max_state();
        if (max_state == -1) {
            fprintf(stderr, "Error reading max fan state, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Determine desired fan state
        desired_state = determine_fan_state(cpu_temp, max_state);

        // Read current fan state
        current_state = read_current_state();
        if (current_state == -1) {
            fprintf(stderr, "Error reading current fan state, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Set fan state if it has changed
        if (desired_state != current_state) {
            if (set_fan_state(desired_state) == 0) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Fan state changed to %d", desired_state);
                log_event(log_message);
                printf("%s\n", log_message);
            } else {
                fprintf(stderr, "Error setting fan state.\n");
            }
        }

        sleep(5);
    }

    // Graceful shutdown
    printf("Shutting down...\n");
    log_event("Program shutting down.");
    set_fan_state(0);
    log_event("Fan turned off during shutdown.");
    printf("Fan turned off.\n");

    return 0;
}

