#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

// Define PID gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Define target temperature
#define TARGET_TEMPERATURE 50.0

// Define failsafe temperature limits
#define MAX_SAFE_TEMPERATURE 100.0
#define MIN_SAFE_TEMPERATURE 0.0

// Define log file name
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void handle_error(const char *message);
void signal_handler(int signal);

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int i2c_handle;
    double temperature = 0.0;

    i2c_handle = i2cOpen(SPI_CHANNEL, 0, 0); // Open I2C device
    if (i2c_handle < 0) {
        handle_error("Failed to open I2C device");
        return -1000.0; // Indicate error
    }

    if (i2cReadDevice(i2c_handle, (char *)buffer, 4) != 4) {
        handle_error("Failed to read from I2C device");
        i2cClose(i2c_handle);
        return -1000.0; // Indicate error
    }

    i2cClose(i2c_handle);

    // Check for fault bits
    if (buffer[3] & 0x04) {
        handle_error("Thermocouple open circuit");
        return -1000.0; // Indicate error
    }
    if (buffer[3] & 0x02) {
        handle_error("Thermocouple short to GND");
        return -1000.0; // Indicate error
    }
    if (buffer[3] & 0x01) {
        handle_error("Thermocouple short to VCC");
        return -1000.0; // Indicate error
    }

    // Extract temperature data
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    pid_state.integral += error;
    double derivative = error - pid_state.previous_error;
    double output = Kp * error + Ki * pid_state.integral + Kd * derivative;
    pid_state.previous_error = error;
    return output;
