#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define I2C bus and addresses
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define the number of retries
#define MAX_RETRIES 3

// Define the log file name
#define LOG_FILE "flow_log.txt"

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int i2c_handle, int sensor_address, float *flow_rate);
int validate_checksum(uint8_t data1, uint8_t data2, uint8_t crc);
int log_data(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, int sensor_address, float *flow_rate) {
    char buf[3];
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 3);
        if (result == 3) {
            // Checksum validation
            if (validate_checksum(buf[0], buf[1], buf[2])) {
                // Convert raw data to flow rate (example conversion, adjust as needed)
                *flow_rate = (float)((buf[0] << 8) | buf[1]) / 100.0; // Example scaling
                return 0; // Success
            } else {
                fprintf(stderr, "Checksum validation failed for sensor 0x%02X\n", sensor_address);
                return -1; // Checksum failure
            }
        } else {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor 0x%02X after %d retries\n", sensor_address, MAX_RETRIES);
    return -1; // Failure after retries
}

// Function to validate the CRC-8 checksum
int validate_checksum(uint8_t data1, uint8_t data2, uint8_t crc) {
    uint8_t polynomial = 0x31; // CRC-8 polynomial
    uint8_t crc_calculated = 0xFF;
    uint8_t data[2] = {data1, data2};

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Function to log the data to a file
int log_data(float flow1, float flow2) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);

    return 0;
}

int main() {
    float flow1, flow2;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus for sensor 1
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C bus for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus for sensor 2
    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C bus for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read data from sensor 1
        result = read_sensor(i2c_handle1, SENSOR1_ADDR, &flow1);
        if (result == 0) {
            // Read data from sensor 2
            result = read_sensor(i2c_handle2, SENSOR2_ADDR, &flow2);
            if (result == 0) {
                // Log the data
                if (log_data(flow1, flow2) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor 2\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor 1\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Close I2C handles and terminate pigpio library
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

