// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold the current quadrature state
typedef struct {
    int a_state;
    int b_state;
} QuadratureState;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();
int read_encoder_state(QuadratureState *state);
float calculate_angular_position(QuadratureState *current_state, QuadratureState *previous_state);
void log_position(float position);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);

    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to initialize the log file
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Function to cleanup resources before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to read the current state of the encoder channels
int read_encoder_state(QuadratureState *state) {
    state->a_state = gpioRead(ENCODER_A_PIN);
    state->b_state = gpioRead(ENCODER_B_PIN);
    return 0;
}

// Function to calculate the angular position based on the quadrature state
float calculate_angular_position(QuadratureState *current_state, QuadratureState *previous_state) {
    static float position = 0.0;
    int a_diff = current_state->a_state - previous_state->a_state;
    int b_diff = current_state->b_state - previous_state->b_state;

    if (a_diff != 0 && b_diff != 0) {
        if (a_diff == 1 && b_diff == 1) {
            position += 90.0;
        } else if (a_diff == -1 && b_diff == -1) {
            position -= 90.0;
        } else if (a_diff == 1 && b_diff == -1) {
            position += 270.0;
        } else if (a_diff == -1 && b_diff == 1) {
            position -= 270.0;
        }
    } else if (a_diff != 0) {
        if (a_diff == 1) {
            position += 180.0;
        } else {
            position -= 180.0;
        }
    } else if (b_diff != 0) {
        if (b_diff == 1) {
            position += 180.0;
        } else {
            position -= 180.0;
        }
    }

    // Normalize the position to be within 0.0 to 360.0
    if (position >= 360.0) {
        position -= 360.0;
    } else if (position < 0.0) {
        position += 360.0;
    }

    return position;
}

// Function to log the timestamped angular position to the file
void log_position(float position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, position);
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    QuadratureState current_state, previous_state;
    previous_state.a_state = gpioRead(ENCODER_A_PIN);
    previous_state.b_state = gpioRead(ENCODER_B_PIN);

    // Main loop
    while (running) {
        if (read_encoder_state(&current_state) == 0) {
            float position = calculate_angular_position(&current_state, &previous_state);
            log_position(position);
            previous_state = current_state;
        }
        gpioDelay(10); // Small delay to avoid excessive CPU usage
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

