#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x38
#define RED_REG 0x00
#define IR_REG 0x02
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *red, uint16_t *ir);
void log_data(uint16_t red, uint16_t ir);
void control_led(uint16_t ir);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ADPD144RI
int read_sensor_data(uint16_t *red, uint16_t *ir) {
    char buf[4];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *red = (uint16_t)((buf[1] << 8) | buf[0]);
    *ir = (uint16_t)((buf[3] << 8) | buf[2]);

    return 0;
}

// Log data to CSV file
void log_data(uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED based on IR value
void control_led(uint16_t ir) {
    if (ir > IR_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, ir;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&red, &ir) == 0) {
            log_data(red, ir);
            control_led(ir);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

