#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASUREMENT_INTERVAL_MS 1000
#define CSV_FILENAME "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 Polynomial
#define CRC8_POLYNOMIAL 0x31

// Function prototypes
int initialize_i2c();
int read_flow_rate(uint16_t *raw_flow);
float convert_to_ul_min(uint16_t raw_flow);
int validate_crc(uint8_t data[], uint8_t crc);
int log_data(float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads the flow rate from the sensor
int read_flow_rate(uint16_t *raw_flow) {
    char buf[3];
    int result = i2cReadDevice(i2c_handle, buf, 3);

    if (result != 3) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    *raw_flow = (buf[0] << 8) | buf[1];
    return 0;
}

// Converts the raw flow rate to microliters per minute
float convert_to_ul_min(uint16_t raw_flow) {
    // Conversion factor from datasheet (example, adjust as needed)
    return (float)raw_flow * 0.01; // Example: 0.01 uL/min per raw unit
}

// Validates the CRC-8 checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

// Logs the flow rate data to a CSV file
int log_data(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(stdout, "Starting flow rate monitoring...\n");

    uint16_t raw_flow;
    float flow_rate;

    while (!terminate) {
        if (read_flow_rate(&raw_flow) == 0) {
            if (validate_crc((uint8_t[]){(raw_flow >> 8) & 0xFF, raw_flow & 0xFF}, (uint8_t)raw_flow & 0xFF)) {
                flow_rate = convert_to_ul_min(raw_flow);
                log_data(flow_rate);
                printf("Flow Rate: %.2f uL/min\n", flow_rate);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Program terminated.\n");
    return 0;
}

