#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x71
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float tvoc;
    float eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
float calculate_iaq(sensor_data_t data);
int log_data(sensor_data_t data, float iaq);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data = {0.0, 0.0};
    char buf[4];
    int bytes_read;

    // Read TVOC (2 bytes)
    bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        data.tvoc = -1.0; // Indicate error
        data.eco2 = -1.0;
        return data;
    }

    // Convert TVOC (assuming 16-bit integer)
    int tvoc_raw = (buf[0] << 8) | buf[1];
    data.tvoc = (float)tvoc_raw; // Placeholder conversion, adjust based on datasheet

    // Convert eCO2 (assuming 16-bit integer)
    int eco2_raw = (buf[2] << 8) | buf[3];
    data.eco2 = (float)eco2_raw; // Placeholder conversion, adjust based on datasheet

    return data;
}

// Function to calculate IAQ index
float calculate_iaq(sensor_data_t data) {
    // Simple linear combination of TVOC and eCO2
    return (data.tvoc + data.eco2) / 2.0;
}

// Function to log data to CSV file
int log_data(sensor_data_t data, float iaq) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.tvoc, data.eco2, iaq);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data();
        if (sensor_data.tvoc >= 0.0 && sensor_data.eco2 >= 0.0) {
            float iaq = calculate_iaq(sensor_data);
            log_data(sensor_data, iaq);
            printf("TVOC: %.2f ppb, eCO2: %.2f ppm, IAQ: %.2f\n", sensor_data.tvoc, sensor_data.eco2, iaq);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

