#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define TOUCH_DURATION_SEC 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result;
    int gpio_mode_result;
    int gpio_read_result;
    struct timespec touch_start, touch_end;
    double touch_duration;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    gpio_mode_result = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_mode_result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", GPIO_PIN, gpio_mode_result);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring GPIO %d for touch events...\n", GPIO_PIN);

    while (program_running) {
        // Read the GPIO pin
        gpio_read_result = gpioRead(GPIO_PIN);
        if (gpio_read_result < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, gpio_read_result);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Check if the sensor is touched (HIGH)
        if (gpio_read_result == 1) {
            // Record the start time of the touch
            if (clock_gettime(CLOCK_MONOTONIC, &touch_start) == -1) {
                perror("clock_gettime");
                gpioTerminate();
                return EXIT_FAILURE;
            }

            // Wait for the touch to end (LOW)
            while (program_running && gpioRead(GPIO_PIN) == 1) {
                gpioDelay(10000); // 10ms delay
            }

            // Record the end time of the touch
            if (clock_gettime(CLOCK_MONOTONIC, &touch_end) == -1) {
                perror("clock_gettime");
                gpioTerminate();
                return EXIT_FAILURE;
            }

            // Calculate the touch duration
            touch_duration = (touch_end.tv_sec - touch_start.tv_sec) + (touch_end.tv_nsec - touch_start.tv_nsec) / 1000000000.0;

            // Check if the touch duration exceeds the threshold
            if (touch_duration > TOUCH_DURATION_SEC) {
                printf("Intrusion Alert! Touch duration: %.2f seconds\n", touch_duration);
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

