#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHANNEL 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE
#define PERIOD_SIZE 1024

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle;
static FILE *audio_file;

void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

int initialize_alsa() {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(&pcm_handle, I2S_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_CHANNEL, PI_OUTPUT);
    gpioWrite(GPIO_CHANNEL, 0); // Select left channel
    return 0;
}

int initialize_file() {
    audio_file = fopen("audio_capture.pcm", "wb");
    if (audio_file == NULL) {
        fprintf(stderr, "Error opening audio file for writing\n");
        return -1;
    }
    return 0;
}

int capture_audio() {
    int err;
    snd_pcm_sframes_t frames;
    char *buffer = (char *)malloc(PERIOD_SIZE * 2); // 2 bytes per sample (16-bit)

    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for audio buffer\n");
        return -1;
    }

    while (keep_running) {
        frames = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (frames < 0) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(frames));
            free(buffer);
            return -1;
        } else if (frames != PERIOD_SIZE) {
            fprintf(stderr, "Short read, read %d frames, expected %d\n", frames, PERIOD_SIZE);
        }

        if (fwrite(buffer, 1, frames * 2, audio_file) != frames * 2) {
            fprintf(stderr, "Error writing to audio file\n");
            free(buffer);
            return -1;
        }
    }

    free(buffer);
    return 0;
}

int cleanup() {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (audio_file) {
        fclose(audio_file);
    }
    gpioWrite(GPIO_CHANNEL, 0); // Reset GPIO
    gpioTerminate();
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_alsa() != 0) {
        return 1;
    }

    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (initialize_file() != 0) {
        cleanup();
        return 1;
    }

    if (capture_audio() != 0) {
        cleanup();
        return 1;
    }

    cleanup();
    printf("Audio capture complete.\n");
    return 0;
}

