        return -1;
    }

    while (keep_running) {
        frames = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (frames < 0) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(frames));
            free(buffer);
            return -1;
        } else if (frames != PERIOD_SIZE) {
            fprintf(stderr, "Short read, read %d frames, expected %d\n", frames, PERIOD_SIZE);
        }

        if (fwrite(buffer, 1, frames * 2, audio_file) != frames * 2) {
            fprintf(stderr, "Error writing to audio file\n");
            free(buffer);
            return -1;
        }
    }

    free(buffer);
    return 0;
}

int cleanup() {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (audio_file) {
        fclose(audio_file);
    }
    gpioWrite(GPIO_CHANNEL, 0); // Reset GPIO
    gpioTerminate();
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_alsa() != 0) {
        return 1;
    }

    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (initialize_file() != 0) {
        cleanup();
        return 1;
    }

    if (capture_audio() != 0) {
        cleanup();
        return 1;
    }

    cleanup();
    printf("Audio capture complete.\n");
    return 0;
}

