        if (sensor_value == 0) {
            flame_detected = 1;
        } else {
            flame_detected = 0;
        }

        if (flame_detected != last_flame_state) {
            control_fan(flame_detected);
            last_flame_state = flame_detected;
        }

        gpioDelay(50000); // Check every 50ms
    }

    cleanup();
    return 0;
}

