#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_FREQUENCY 1000000 // 1 MHz
#define FRAME_SIZE 32768
#define MAGIC_NUMBER 4144
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24
#define LOG_FILE "radar_data.bin"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold radar configuration
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t num_chirps;
    uint16_t num_samples;
} radar_config_t;

// Function prototypes
int initialize_spi();
int initialize_gpio();
int initialize_logging();
void trigger_frame();
int read_frame(uint8_t *frame_data);
void log_frame(uint8_t *frame_data);
void handle_data_ready();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_FREQUENCY, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_TRIGGER);
        return -1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_DATA_READY);
        return -1;
    }
    gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_DOWN); // Pull-down resistor
    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Write header to log file
    radar_config_t config = {7700000000, 7900000000, 64, 256};
    uint8_t header[sizeof(radar_config_t) + 8];
    memcpy(header, &MAGIC_NUMBER, sizeof(MAGIC_NUMBER));
    memcpy(header + sizeof(MAGIC_NUMBER), &config, sizeof(radar_config_t));
    time_t now = time(NULL);
    memcpy(header + sizeof(radar_config_t), &now, 8);

    if (fwrite(header, 1, sizeof(header), log_file) != sizeof(header)) {
        fprintf(stderr, "Error writing header to log file\n");
        fclose(log_file);
        return -1;
    }

    return 0;
}

// Trigger a frame by setting GPIO high for 100us
void trigger_frame() {
    gpioWrite(GPIO_TRIGGER, 1);
    gpioDelay(100); // 100 microseconds
    gpioWrite(GPIO_TRIGGER, 0);
}

// Read a frame from the AWR1642
int read_frame(uint8_t *frame_data) {
    if (spiRead(spi_handle, (char *)frame_data, FRAME_SIZE) != FRAME_SIZE) {
        fprintf(stderr, "Error reading frame from SPI\n");
        return -1;
    }
    return 0;
}

// Log a frame to the binary file
void log_frame(uint8_t *frame_data) {
    time_t now = time(NULL);
    fwrite(&now, 8, 1, log_file);
    fwrite(&((uint32_t){1}), 4, 1, log_file); // Frame number (dummy)
    fwrite(frame_data, 1, FRAME_SIZE, log_file);
}

// Handle data ready interrupt
void handle_data_ready() {
    uint8_t frame_data[FRAME_SIZE];
    if (read_frame(frame_data) == 0) {
        log_frame(frame_data);
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI, GPIO, and logging
    if (initialize_spi() != 0 || initialize_gpio() != 0 || initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    // Main loop
    while (program_running) {
        trigger_frame();
        gpioDelay(100000); // 100ms delay (100000 microseconds)

        // Check for data ready interrupt
        if (gpioRead(GPIO_DATA_READY) == 1) {
            handle_data_ready();
            gpioDelay(1000); // Debounce delay
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

