#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONTINUOUS_MODE 0xCC00 // Continuous conversion mode, auto range
#define SLEEP_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_lux(float *lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    uint16_t config_value;
    uint8_t config_reg;
} sensor_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    uint8_t buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = (CONTINUOUS_MODE >> 8) & 0xFF; // MSB
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to config register (MSB): %d\n", i2c_handle);
        return -1;
    }

    buf[0] = CONFIG_REG + 1;
    buf[1] = CONTINUOUS_MODE & 0xFF; // LSB
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to config register (LSB): %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the lux value from the OPT3001 sensor
int read_lux(float *lux) {
    uint8_t buf[2];
    uint16_t raw_result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        buf[0] = RESULT_REG;
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to result register: %d\n", i2c_handle);
            retries++;
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
            fprintf(stderr, "Error reading result register: %d\n", i2c_handle);
            retries++;
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        raw_result = (buf[0] << 8) | buf[1];

        // Extract exponent and result
        int exponent = (raw_result >> 12) & 0x0F;
        uint16_t result = raw_result & 0x0FFF;

        // Calculate lux value
        *lux = 0.01 * pow(2, exponent) * result;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read lux value after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log the lux value to a file
int log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    float lux;

    // Main loop
    while (!terminate) {
        if (read_lux(&lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }
        gpioDelay(SLEEP_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

