#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 17
volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int gpio_status;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Flame detection program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the GPIO pin value
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO pin: %d\n", gpio_status);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the flame detection status
            if (gpio_status == 0) {
                printf("%s Flame Detected: YES\n", timestamp);
            } else {
                printf("%s Flame Detected: NO\n", timestamp);
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup and exit
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

