#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 channels
const int TTP226_PINS[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int NUM_CHANNELS = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the state of a single TTP226 channel
int read_channel(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to read all TTP226 channels and return the data as a string
char* read_all_channels() {
    char *data = (char*)malloc(NUM_CHANNELS + 1); // Allocate memory for the data string
    if (data == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for channel data.\n");
        return NULL;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int channel_value = read_channel(TTP226_PINS[i]);
        if (channel_value < 0) {
            // Handle error reading a channel (e.g., set to 0 or exit)
            data[i] = '0'; // Set to 0 to avoid further issues
        } else {
            data[i] = (channel_value == 0) ? '0' : '1'; // Convert to '0' or '1'
        }
    }
    data[NUM_CHANNELS] = '\0'; // Null-terminate the string
    return data;
}

// Function to log the sensor data with a timestamp
void log_data(const char *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: %s\n", timestamp, data);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(TTP226_PINS[i], PI_INPUT);
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the sensor data
        char *data = read_all_channels();
        if (data != NULL) {
            // Log the data
            log_data(data);

            // Free the allocated memory
            free(data);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100); // pigpio's delay function
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

