#include <pigpio.h>
#include <unistd.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor data
int read_sensor_data() {
    int data = 0;
    for (int i = 0; i < num_sensors; i++) {
        data |= (gpioRead(sensor_pins[i]) << i);
    }
    return data;
}

// Function to print the sensor data
void print_sensor_data(int data) {
    printf("[%d] ", data);
    for (int i = 0; i < num_sensors; i++) {
        printf("CH%d=%d ", i + 1, (data >> i) & 1);
    }
    printf("\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs with pull-down resistors
