#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define the GPIO pins for the TTP226 sensor channels
const int sensor_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor data
int read_sensor_data(int *channel_states) {
    for (int i = 0; i < num_channels; i++) {
        int pin = sensor_pins[i];
        int state = gpioRead(pin);
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO pin %d: %d\n", pin, state);
            return -1; // Indicate an error
        }
        channel_states[i] = state;
    }
    return 0; // Indicate success
}

// Function to format the data into a CSV string
int format_data(int *channel_states, char *timestamp, char *csv_string) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    int offset = 0;
    for (int i = 0; i < num_channels; i++) {
        offset += snprintf(csv_string + offset, 2, "%d", channel_states[i]);
        if (i < num_channels - 1) {
            offset += snprintf(csv_string + offset, 2, ",");
        }
    }

    return 0;
}

// Function to print the CSV string to the console
void print_data(const char *csv_string) {
    printf("%s\n", csv_string);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        int pin = sensor_pins[i];
        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_DOWN); // Enable pull-down resistor
    }

    // Install the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int channel_states[num_channels];
        char timestamp[21];
        char csv_string[100]; // Adjust size as needed

        // Read the sensor data
        if (read_sensor_data(channel_states) != 0) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break;
        }

        // Format the data into a CSV string
        if (format_data(channel_states, timestamp, csv_string) != 0) {
            fprintf(stderr, "Error formatting data, exiting...\n");
            break;
        }

        // Print the CSV string to the console
        print_data(csv_string);

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

