#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    int current_state, previous_state;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    previous_state = gpioRead(TILT_SENSOR_GPIO);
    if (previous_state < 0) {
        fprintf(stderr, "Failed to read initial state from GPIO%d\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    while (program_running) {
        current_state = gpioRead(TILT_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read state from GPIO%d\n", TILT_SENSOR_GPIO);
            gpioTerminate();
            return 1;
        }

        if (current_state != previous_state) {
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            previous_state = current_state;
        }

        gpioDelay(100); // 100ms delay
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

