#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_LOG_FILE "flow_log.txt"
#define START_COMMAND 0x3608
#define MEASUREMENT_COMMAND 0x0000
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INITIAL 0xFF
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 600.0
#define MIN_FLOW_RATE_ALARM 0.5

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_flow_rate(int i2c_handle, float *flow_rate);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t crc);
void log_data(FILE *fp, float flow_rate1, float flow_rate2, float average_flow_rate);
void control_alarm(int gpio_pin, float average_flow_rate);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read flow rate from the sensor
int read_flow_rate(int i2c_handle, float *flow_rate) {
    uint8_t command[2] = {(START_COMMAND >> 8) & 0xFF, START_COMMAND & 0xFF};
    if (i2cWriteDevice(i2c_handle, command, 2) != 2) {
        fprintf(stderr, "Error sending start command\n");
        return -1;
    }
    gpioDelay(100); // Wait 100ms

    uint8_t read_command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    if (i2cWriteDevice(i2c_handle, read_command, 2) != 2) {
        fprintf(stderr, "Error sending measurement command\n");
        return -1;
    }

    uint8_t buffer[3];
    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        fprintf(stderr, "Error reading data from sensor\n");
        return -1;
    }

    uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
    uint8_t crc = buffer[2];

    if (!validate_crc(buffer, 2, crc)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw flow to ml/min (adjust scaling as needed)
    *flow_rate = (float)raw_flow / 100.0; // Example scaling

    // Validate flow rate
    if (*flow_rate < MIN_FLOW_RATE || *flow_rate > MAX_FLOW_RATE) {
        fprintf(stderr, "Invalid flow rate: %.2f ml/min\n", *flow_rate);
        return -1;
    }

    return 0;
}

// Function to calculate CRC
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Function to log data to file
void log_data(FILE *fp, float flow_rate1, float flow_rate2, float average_flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate1, flow_rate2, average_flow_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to control the alarm
void control_alarm(int gpio_pin, float average_flow_rate) {
    if (average_flow_rate < MIN_FLOW_RATE_ALARM) {
        gpioWrite(gpio_pin, 1); // Set GPIO high
    } else {
        gpioWrite(gpio_pin, 0); // Set GPIO low
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially set alarm low

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2, average_flow_rate;

    // Main loop
    while (!terminate) {
        int read_status1 = read_flow_rate(i2c_handle1, &flow_rate1);
        int read_status2 = read_flow_rate(i2c_handle2, &flow_rate2);

        float valid_flow_rate1 = (read_status1 == 0) ? flow_rate1 : 0.0;
        float valid_flow_rate2 = (read_status2 == 0) ? flow_rate2 : 0.0;

        average_flow_rate = (valid_flow_rate1 + valid_flow_rate2) / 2.0;

        log_data(log_file, flow_rate1, flow_rate2, average_flow_rate);
        control_alarm(ALARM_GPIO, average_flow_rate);

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off on exit
    gpioTerminate();
    fclose(log_file);

    return 0;
}

