    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially set alarm low

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2, average_flow_rate;

    // Main loop
    while (!terminate) {
        int read_status1 = read_flow_rate(i2c_handle1, &flow_rate1);
        int read_status2 = read_flow_rate(i2c_handle2, &flow_rate2);

        float valid_flow_rate1 = (read_status1 == 0) ? flow_rate1 : 0.0;
        float valid_flow_rate2 = (read_status2 == 0) ? flow_rate2 : 0.0;

