        log_data(log_file, flow_rate1, flow_rate2, average_flow_rate);
        control_alarm(ALARM_GPIO, average_flow_rate);

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off on exit
    gpioTerminate();
    fclose(log_file);

    return 0;
}

