#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold sensor data and timestamp
typedef struct {
    int sensor_value;
    time_t timestamp;
} SensorData;

// Circular buffer
SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int sensor_value);
void dump_buffer();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Add to circular buffer
        add_to_buffer(sensor_value);

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            printf("Obstacle detected at: %s\n", buf);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Dump the circular buffer before exiting
    dump_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value from GPIO4
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add sensor data to the circular buffer
void add_to_buffer(int sensor_value) {
    circular_buffer[buffer_index].sensor_value = sensor_value;
    circular_buffer[buffer_index].timestamp = time(NULL);

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the contents of the circular buffer to stdout
void dump_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        time_t timestamp = circular_buffer[index].timestamp;
        struct tm *tstruct = localtime(&timestamp);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
        printf("[%s] Sensor Value: %d\n", buf, circular_buffer[index].sensor_value);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler function to catch SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

