#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor and I2C parameters
#define I2C_BUS 1
#define D7S_ADDR 0x4C
#define D7S_REG_X_LSB 0x28
#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_MODE 0x00
#define D7S_MODE_CONT_CONT 0x03
#define D7S_MODE_CONT_CONT_CONT 0x07

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
int write_sensor_data_to_csv(const sensor_data_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the D7S sensor
int init_sensor() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, D7S_REG_MODE, D7S_MODE_CONT_CONT_CONT) >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to sensor mode register: %d\n", i2c_handle);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    return -1; // Failure after multiple retries
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_LSB, buf, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Write sensor data to CSV file
int write_sensor_data_to_csv(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("fan_health.csv", "a+");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    sensor_data_t sensor_data;
    int active = 0;
    int timeout_count = 0;
    const int timeout_limit = 10; // 10 * 100ms = 1 second

    // Wait for sensor to become active
    while (!active && timeout_count < timeout_limit) {
        if (read_sensor_data(&sensor_data) == 0) {
            active = 1;
        } else {
            fprintf(stderr, "Sensor not active yet, retrying...\n");
            gpioDelay(10000); // Wait 10ms
            timeout_count++;
        }
    }

    if (!active) {
        fprintf(stderr, "Sensor did not become active within the timeout period\n");
        fclose(csv_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (write_sensor_data_to_csv(&sensor_data) != 0) {
                fprintf(stderr, "Error writing data to CSV\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data in main loop\n");
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Cleanup
    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

