#define STALL_DURATION_SEC 2
#define LOG_FILE "stall_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
int is_stall_detected(int sensor1_value, int sensor2_value);
void log_stall_event(void);
void signal_handler(int signal);

