#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// Register addresses
#define REG_X_AXIS_MSB 0x00
#define REG_X_AXIS_LSB 0x01
#define REG_Y_AXIS_MSB 0x02
#define REG_Y_AXIS_LSB 0x03
#define REG_Z_AXIS_MSB 0x04
#define REG_Z_AXIS_LSB 0x05
#define REG_CONFIG 0x09

// Configuration values
#define CONFIG_CONT_CONV 0x01 // Continuous conversion mode
#define CONFIG_50MT_RANGE 0x00 // +/- 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the TMAG5170-Q1 sensor
int initialize_sensor() {
    // Configure the sensor for continuous conversion mode and 50 mT range
    uint8_t config_data[2];
    config_data[0] = REG_CONFIG;
    config_data[1] = (CONFIG_CONT_CONV << 7) | (CONFIG_50MT_RANGE << 5); // Example config value

    int result = i2cWriteDevice(i2c_handle, (char *)config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];

    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from sensor: %d\n", result);
        data.x = 0; // Set to 0 to indicate error
        data.y = 0;
        data.z = 0;
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

