#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_count_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
void *rpm_calculation_thread(void *arg);
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();

// Structure to pass data to the thread
typedef struct {
    int gpio_pin;
} thread_data_t;

// Callback function for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pthread_mutex_lock(&pulse_count_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_count_mutex);
    }
}

// Thread function for RPM calculation and logging
void *rpm_calculation_thread(void *arg) {
    thread_data_t *data = (thread_data_t *)arg;
    int gpio_pin = data->gpio_pin;
    int pulses;
    double rpm;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        pthread_mutex_lock(&pulse_count_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_count_mutex);

        rpm = (double)pulses / SAMPLE_INTERVAL_SEC * 60.0;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (log_file != NULL) {
            fprintf(log_file, "%s %.2f\n", timestamp, rpm);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }

        printf("%s %.2f\n", timestamp, rpm);
    }

    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return 1;
    }
    return 0;
