#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the debounce time in microseconds
#define DEBOUNCE_TIME 5000

// Define the quadrature state machine states
typedef enum {
    STATE_00,
    STATE_01,
    STATE_10,
    STATE_11
} QuadratureState;

// Global variables
static QuadratureState current_state = STATE_00;
static QuadratureState previous_state = STATE_00;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void log_rotation_event(const char *direction);
void signal_handler(int signal);

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick < DEBOUNCE_TIME) {
        return; // Debounce
    }
    last_tick = current_tick;

    if (level == 1) {
        pthread_mutex_lock(&mutex);
        current_state = (current_state == STATE_00) ? STATE_01 : STATE_11;
        pthread_mutex_unlock(&mutex);
    } else {
        pthread_mutex_lock(&mutex);
        current_state = (current_state == STATE_00) ? STATE_10 : STATE_00;
        pthread_mutex_unlock(&mutex);
    }

    if (current_state != previous_state) {
        pthread_mutex_lock(&mutex);
        const char *direction = (current_state == STATE_01 && previous_state == STATE_00) ? "Clockwise" :
                               (current_state == STATE_10 && previous_state == STATE_00) ? "Counter-Clockwise" :
                               (current_state == STATE_11 && previous_state == STATE_01) ? "Clockwise" :
                               (current_state == STATE_00 && previous_state == STATE_11) ? "Counter-Clockwise" :
                               (current_state == STATE_00 && previous_state == STATE_10) ? "Clockwise" :
                               (current_state == STATE_11 && previous_state == STATE_00) ? "Counter-Clockwise" :
                               (current_state == STATE_10 && previous_state == STATE_01) ? "Clockwise" : "Unknown";
        pthread_mutex_unlock(&mutex);

        if (strcmp(direction, "Unknown") != 0) {
            log_rotation_event(direction);
        }

        pthread_mutex_lock(&mutex);
        previous_state = current_state;
        pthread_mutex_unlock(&mutex);
    }
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick < DEBOUNCE_TIME) {
        return; // Debounce
    }
    last_tick = current_tick;

    if (level == 1) {
        pthread_mutex_lock(&mutex);
        current_state = (current_state == STATE_00) ? STATE_10 : STATE_11;
        pthread_mutex_unlock(&mutex);
    } else {
        pthread_mutex_lock(&mutex);
        current_state = (current_state == STATE_00) ? STATE_01 : STATE_00;
        pthread_mutex_unlock(&mutex);
    }

    if (current_state != previous_state) {
        pthread_mutex_lock(&mutex);
        const char *direction = (current_state == STATE_10 && previous_state == STATE_00) ? "Clockwise" :
                               (current_state == STATE_01 && previous_state == STATE_00) ? "Counter-Clockwise" :
                               (current_state == STATE_11 && previous_state == STATE_10) ? "Clockwise" :
                               (current_state == STATE_00 && previous_state == STATE_11) ? "Counter-Clockwise" :
                               (current_state == STATE_00 && previous_state == STATE_01) ? "Clockwise" :
                               (current_state == STATE_11 && previous_state == STATE_00) ? "Counter-Clockwise" :
                               (current_state == STATE_10 && previous_state == STATE_01) ? "Clockwise" : "Unknown";
        pthread_mutex_unlock(&mutex);

        if (strcmp(direction, "Unknown") != 0) {
            log_rotation_event(direction);
        }

        pthread_mutex_lock(&mutex);
        previous_state = current_state;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to log rotation events to a file
void log_rotation_event(const char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    long milliseconds = (long)(timeinfo->tm_sec * 1000.0 + timeinfo->tm_usec / 1000.0);

    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s.%03ld %s\n", timestamp, milliseconds, direction);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_unlock(&mutex);

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Open the log file
    pthread_mutex_lock(&mutex);
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        pthread_mutex_unlock(&mutex);
        return 1;
    }
    pthread_mutex_unlock(&mutex);

    // Set up interrupt handlers for both sensors
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, EITHER_EDGE, 0, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for Sensor A\n");
        pthread_mutex_lock(&mutex);
        fclose(log_file);
        pthread_mutex_unlock(&mutex);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(SENSOR_B_GPIO, EITHER_EDGE, 0, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for Sensor B\n");
        pthread_mutex_lock(&mutex);
        fclose(log_file);
        pthread_mutex_unlock(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    // Main loop (sleep to avoid busy-waiting)
    while (running) {
        gpioDelay(100); // Sleep for 100ms
    }

    return 0;
}

