#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
    cleanup_gpio();
    exit(0);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    syslog(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    syslog(LOG_INFO, "GPIO terminated");
}

int main() {
    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialisation failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Program started");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            control_led(1); // Turn on LED
            syslog(LOG_INFO, "Touch detected, LED ON");
        } else {
            control_led(0); // Turn off LED
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return 0;
}

