#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Define log buffer size
#define LOG_BUFFER_SIZE 100

// Define log entry structure
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} log_entry_t;

// Define log buffer structure
typedef struct {
    log_entry_t entries[LOG_BUFFER_SIZE];
    int head;
    int tail;
    int overflow_count;
} log_buffer_t;

// Global variables
static volatile int running = 1;
static log_buffer_t log_buffer;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int state);
void print_log_buffer();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Shutting down...\n", signal);
    running = 0;

    // Turn off LEDs
    control_led(LED1_PIN, 0);
    control_led(LED2_PIN, 0);

    // Print log buffer
    print_log_buffer();

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set sensor pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set LED pins as outputs
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Log event to circular buffer
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);

    log_buffer.entries[log_buffer.head].sensor_pin = sensor_pin;
    log_buffer.entries[log_buffer.head].timestamp = now;
    log_buffer.entries[log_buffer.head].state = state;

    log_buffer.head = (log_buffer.head + 1) % LOG_BUFFER_SIZE;

    if (log_buffer.head == log_buffer.tail) {
        log_buffer.overflow_count++;
    }
}

// Print log buffer contents
void print_log_buffer() {
    printf("Log Buffer Contents:\n");
    printf("Sensor Pin | Timestamp | State\n");
    printf("-----------|-----------|------\n");

    int i = log_buffer.tail;
    while (i != log_buffer.head) {
        printf("%d | %ld | %d\n", log_buffer.entries[i].sensor_pin, log_buffer.entries[i].timestamp, log_buffer.entries[i].state);
        i = (i + 1) % LOG_BUFFER_SIZE;
    }

    printf("Overflow Count: %d\n", log_buffer.overflow_count);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize log buffer
    log_buffer.head = 0;
    log_buffer.tail = 0;
    log_buffer.overflow_count = 0;

    int last_sensor1_state = 0;
    int last_sensor2_state = 0;

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        // Debounce and log events
        if (sensor1_state != last_sensor1_state) {
            log_event(SENSOR1_PIN, sensor1_state);
            control_led(LED1_PIN, sensor1_state);
            last_sensor1_state = sensor1_state;
        }

        if (sensor2_state != last_sensor2_state) {
            log_event(SENSOR2_PIN, sensor2_state);
            control_led(LED2_PIN, sensor2_state);
            last_sensor2_state = sensor2_state;
        }

        // Delay for debouncing
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }

    return 0;
}

