#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the rain sensor state
int read_rain_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log rain events to a file
void log_rain_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = 1; // Initialize to no rain (HIGH)

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_state = read_rain_sensor();

        if (current_state != previous_state) {
            if (current_state == 0) {
                log_rain_event("Rain Detected");
                printf("Rain Detected\n");
            } else {
                log_rain_event("No Rain");
                printf("No Rain\n");
            }
            previous_state = current_state;
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Rain sensor monitoring stopped.\n");
    return 0;
}

