#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Define the log file name
#define LOG_FILE "shaft_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void log_sensor_data(SensorStates states);
float calculate_rpm(int pulse_count, float time_interval);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpioInitialise());
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Function to initialize the log file
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log sensor data to the CSV file
void log_sensor_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to calculate RPM
float calculate_rpm(int pulse_count, float time_interval) {
    return (float)pulse_count / time_interval * 60.0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    int last_sensor1_state = gpioRead(SENSOR1_GPIO);
    int last_sensor2_state = gpioRead(SENSOR2_GPIO);
    int pulse_count = 0;
    time_t start_time, current_time;
    time(&start_time);

    printf("Monitoring shaft RPM... Press Ctrl+C to exit.\n");

    while (running) {
        int current_sensor1_state = gpioRead(SENSOR1_GPIO);
        int current_sensor2_state = gpioRead(SENSOR2_GPIO);

        if (current_sensor1_state != last_sensor1_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            if (gpioRead(SENSOR1_GPIO) == current_sensor1_state) {
                last_sensor1_state = current_sensor1_state;
                pulse_count++;
            }
        }

        if (current_sensor2_state != last_sensor2_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            if (gpioRead(SENSOR2_GPIO) == current_sensor2_state) {
                last_sensor2_state = current_sensor2_state;
                pulse_count++;
            }
        }

        time(&current_time);
        float time_interval = difftime(current_time, start_time);

        if (time_interval >= 1.0) {
            float rpm = calculate_rpm(pulse_count, time_interval);
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
            time(&start_time);
        }

        gpioDelay(1000); // Check every 1 ms
    }

    cleanup();
    return 0;
}

