            if (gpioRead(SENSOR1_GPIO) == current_sensor1_state) {
                last_sensor1_state = current_sensor1_state;
                pulse_count++;
            }
        }

        if (current_sensor2_state != last_sensor2_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            if (gpioRead(SENSOR2_GPIO) == current_sensor2_state) {
                last_sensor2_state = current_sensor2_state;
                pulse_count++;
            }
        }

        time(&current_time);
        float time_interval = difftime(current_time, start_time);

        if (time_interval >= 1.0) {
            float rpm = calculate_rpm(pulse_count, time_interval);
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
            time(&start_time);
        }

        gpioDelay(1000); // Check every 1 ms
    }

    cleanup();
    return 0;
}

