#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 2

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_event(const char *event_type, int sensor_id, int state);
int activate_alarm();
int deactivate_alarm();
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, PI_LOW);

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log event to file
int log_event(const char *event_type, int sensor_id, int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s - State: %d\n", timestamp, sensor_id, event_type, state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
    free(timestamp);
    return 0;
}

// Activate alarm
int activate_alarm() {
    gpioWrite(ALARM_PIN, PI_HIGH);
    return 0;
}

// Deactivate alarm
int deactivate_alarm() {
    gpioWrite(ALARM_PIN, PI_LOW);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    int sensor1_state = 0;
    int sensor2_state = 0;
    int alarm_active = 0;
    time_t alarm_start_time = 0;

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        int new_sensor1_state = read_sensor(SENSOR_1_PIN);
        int new_sensor2_state = read_sensor(SENSOR_2_PIN);

        // Log tilt start events
        if (new_sensor1_state == 1 && sensor1_state == 0) {
            log_event("Tilt Start", 1, new_sensor1_state);
        }
        if (new_sensor2_state == 1 && sensor2_state == 0) {
            log_event("Tilt Start", 2, new_sensor2_state);
        }

        // Log tilt end events
        if (new_sensor1_state == 0 && sensor1_state == 1) {
            log_event("Tilt End", 1, new_sensor1_state);
        }
        if (new_sensor2_state == 0 && sensor2_state == 1) {
            log_event("Tilt End", 2, new_sensor2_state);
        }

        // Check for alarm condition
        if (new_sensor1_state == 1 || new_sensor2_state == 1) {
            if (!alarm_active) {
                activate_alarm();
                alarm_active = 1;
                if (new_sensor1_state == 1) {
                    alarm_start_time = time(NULL);
                } else {
                    alarm_start_time = time(NULL);
                }
            }
        } else {
            if (alarm_active) {
                deactivate_alarm();
                alarm_active = 0;
            }
        }

        // Check alarm duration
        if (alarm_active) {
            time_t current_time = time(NULL);
            if (difftime(current_time, alarm_start_time) >= ALARM_DURATION) {
                deactivate_alarm();
                alarm_active = 0;
            }
        }

        // Update sensor states
        sensor1_state = new_sensor1_state;
        sensor2_state = new_sensor2_state;

        gpioDelay(100); // Poll every 100 ms
    }

    // Clean up
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    printf("Bridge integrity monitoring stopped.\n");
    return 0;
}

