#define CTRL2_REG 0x01
#define X_AXIS_REG 0x02
#define Y_AXIS_REG 0x04
#define Z_AXIS_REG 0x06
#define LED_PIN 17
#define THRESHOLD 500
#define NUM_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(int *x, int *y, int *z);
double calculate_magnitude(int x, int y, int z);
bool check_threshold(double magnitude);
void log_event(int x, int y, int z, double magnitude);
void activate_led();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the sensor
int init_sensor() {
    int retries = 0;
    while (retries < NUM_RETRIES) {
        // Check sensor presence (read CTRL1 register)
        int ctrl1_value = wiringPiI2CReadReg8(i2c_fd, CTRL1_REG);
        if (ctrl1_value != -1) {
            // Sensor present, clear power-down bit
            if (wiringPiI2CWriteReg8(i2c_fd, CTRL1_REG, 0x00) == 0) {
                printf("Sensor initialized successfully.\n");
                return 0;
            } else {
                fprintf(stderr, "Error writing to CTRL1 register (attempt %d): %s\n", retries + 1, strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading CTRL1 register (attempt %d): %s\n", retries + 1, strerror(errno));
        }
        retries++;
        delay(RETRY_DELAY_MS);
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", NUM_RETRIES);
    return -1;
}

// Function to read sensor data
int read_sensor_data(int *x, int *y, int *z) {
    int retries = 0;
    while (retries < NUM_RETRIES) {
        *x = wiringPiI2CReadReg8(i2c_fd, X_AXIS_REG);
        *y = wiringPiI2CReadReg8(i2c_fd, Y_AXIS_REG);
        *z = wiringPiI2CReadReg8(i2c_fd, Z_AXIS_REG);

        if (*x != -1 && *y != -1 && *z != -1) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %s\n", retries + 1, strerror(errno));
        }
        retries++;
        delay(RETRY_DELAY_MS);
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", NUM_RETRIES);
    return -1; // Failure
}

// Function to calculate the Euclidean magnitude
double calculate_magnitude(int x, int y, int z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to check if the magnitude exceeds the threshold
bool check_threshold(double magnitude) {
    return magnitude > THRESHOLD;
}

// Function to log the event
void log_event(int x, int y, int z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
}

// Function to activate the LED
void activate_led() {
    digitalWrite(LED_PIN, HIGH);
    delay(1000);
    digitalWrite(LED_PIN, LOW);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() == -1) {
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int x, y, z;
    double magnitude;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check threshold
            if (check_threshold(magnitude)) {
                // Log event
                log_event(x, y, z, magnitude);

                // Activate LED
                activate_led();
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        delay(100); // Poll every 100ms
    }

    // Cleanup
    fclose(log_file);
    return 0;
}

