#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for sensors and LED
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs or output
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        // Check if any sensor detects an obstacle
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
            // Turn LED ON
            control_led(LED_PIN, 1);
        } else {
            // Turn LED OFF
            control_led(LED_PIN, 0);
        }

        // Delay for 50 milliseconds
        gpioDelay(50);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

