#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the flame sensors
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Structure to hold GPIO line information
struct gpio_line_info {
    struct gpiod_line *line;
    int pin;
    int id;
};

// Global array to store GPIO line information
struct gpio_line_info sensor_lines[5];

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int debounce(struct gpiod_line *line);
int log_event(int sensor_id, int pin);
void signal_handler(int sig);
int setup_gpio(int pin, int id);

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    syslog(LOG_USER, "Signal received, exiting...");
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_USER, "Error reading sensor value: %m");
        return -1;
    }
    return value;
}

// Function to perform debouncing
int debounce(struct gpiod_line *line) {
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds

    int value = read_sensor(line);
    if (value < 0) {
        return -1; // Propagate the error
    }

    nanosleep(&delay, NULL);

    value = read_sensor(line);
    if (value < 0) {
        return -1; // Propagate the error
    }

    return value;
}

// Function to log the event
int log_event(int sensor_id, int pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_USER, "Error opening log file: %m");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    int flock_result = flock(fileno(fp), LOCK_EX);
    if (flock_result == -1) {
        syslog(LOG_USER, "Error acquiring file lock: %m");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);
    fflush(fp);

    int unlock_result = flock(fileno(fp), LOCK_UN);
    if (unlock_result == -1) {
        syslog(LOG_USER, "Error releasing file lock: %m");
    }

    fclose(fp);
    return 0;
}

// Function to setup GPIO line
int setup_gpio(int pin, int id) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_USER, "Error opening GPIO chip: %m");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_USER, "Error getting GPIO line: %m");
        gpiod_chip_close(chip);
        return -1;
    }

    int request_flags = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    int request_result = gpiod_line_request(line, "flame_monitor", request_flags);
    if (request_result < 0) {
        syslog(LOG_USER, "Error requesting GPIO line: %m");
        gpiod_chip_close(chip);
        return -1;
    }

    sensor_lines[id].line = line;
    sensor_lines[id].pin = pin;
    sensor_lines[id].id = id;

    return 0;
}

int main() {
    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    if (setup_gpio(GPIO_2, 0) < 0) return 1;
    if (setup_gpio(GPIO_3, 1) < 0) return 1;
    if (setup_gpio(GPIO_4, 2) < 0) return 1;
    if (setup_gpio(GPIO_17, 3) < 0) return 1;
    if (setup_gpio(GPIO_27, 4) < 0) return 1;

    syslog(LOG_USER, "Flame monitor started");

    // Main loop
    while (program_running) {
        for (int i = 0; i < 5; i++) {
            int sensor_value = read_sensor(sensor_lines[i].line);
            if (sensor_value < 0) {
                syslog(LOG_USER, "Error reading sensor %d, continuing...", i);
                continue;
            }

            if (sensor_value == 0) {
                int debounced_value = debounce(sensor_lines[i].line);
                if (debounced_value < 0) {
                    syslog(LOG_USER, "Error debouncing sensor %d, continuing...", i);
                    continue;
                }

                if (debounced_value == 0) {
                    if (log_event(sensor_lines[i].id, sensor_lines[i].pin) == 0) {
                        syslog(LOG_USER, "Flame detected on sensor %d (GPIO %d)", sensor_lines[i].id, sensor_lines[i].pin);
                    } else {
                        syslog(LOG_USER, "Error logging event for sensor %d", i);
                    }
                }
            }
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup
    syslog(LOG_USER, "Flame monitor exiting");

    for (int i = 0; i < 5; i++) {
        if (sensor_lines[i].line) {
            gpiod_line_release(sensor_lines[i].line);
        }
    }

    closelog();
    return 0;
}

