#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define the GPIO pins connected to the TTP226 outputs
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to store the previous sensor states
int previous_states[8] = {0};

// Function to handle the SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Terminate the pigpio library
    exit(0); // Exit the program
}

// Function to read the sensor states
int read_sensor_states(int *states) {
    for (int i = 0; i < num_sensors; i++) {
        int pin = sensor_pins[i];
        int state = gpioRead(pin);
        if (state < 0) {
            fprintf(stderr, "Error reading pin %d: %d\n", pin, state);
            return -1; // Indicate an error
        }
        states[i] = state;
    }
    return 0; // Indicate success
}

// Function to log sensor events
void log_sensor_event(int sensor_index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 1) {
        printf("%s Sensor %d (GPIO %d): Touch Detected\n", timestamp, sensor_index, pin);
    } else {
        printf("%s Sensor %d (GPIO %d): Released\n", timestamp, sensor_index, pin);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_sensors; i++) {
        int pin = sensor_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error setting pin %d as input\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int current_states[8];

        // Read the sensor states
        if (read_sensor_states(current_states) != 0) {
            fprintf(stderr, "Error reading sensor states, exiting...\n");
            gpioTerminate();
            return 1;
        }

        // Compare the current states with the previous states
        for (int i = 0; i < num_sensors; i++) {
            if (current_states[i] != previous_states[i]) {
                int pin = sensor_pins[i];
                log_sensor_event(i, pin, current_states[i]);
                previous_states[i] = current_states[i]; // Update previous state
            }
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // The program should never reach here, but include cleanup for completeness
    gpioTerminate();
    return 0;
}

