#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"

// VEML7700 Registers
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
float read_lux();
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configuration: Integration time = 100ms, Gain = 1/8, Continuous mode
    uint16_t config_value = 0x0000; // Default configuration
    config_value |= (0x00 << 11); // IT = 100ms
    config_value |= (0x03 << 6);  // Gain = 1/8
    config_value |= (0x03 << 1);  // Continuous mode

    char buf[3];
    buf[0] = VEML7700_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to VEML7700 config register\n");
        return -1;
    }

    return 0;
}

// Read lux value from VEML7700 sensor
float read_lux() {
    char buf[1];
    char data[2];

    buf[0] = VEML7700_ALS_DATA;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to VEML7700 data register\n");
        return -1.0;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from VEML7700 data register\n");
        return -1.0;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];

    // Conversion formula (adjust based on gain and integration time)
    float lux = (float)raw_value * 0.0576; // Example conversion, adjust as needed

    return lux;
}

// Map lux value to brightness level (0-100)
int map_lux_to_brightness(float lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set LED brightness using PWM
void set_led_brightness(int brightness) {
    int duty_cycle = (int)((brightness / 100.0) * 255.0);
    gpioPWM(GPIO_LED, duty_cycle);
}

// Log data to file
void log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux < 0) {
            log_data(-1.0, -1, -1); // Log error
        } else {
            int brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
            log_data(lux, brightness, 0); // Log data
        }

        sleep(1);
    }

    // Cleanup
    set_led_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

