#include <time.h>
#include <string.h>

// Define GPIO pins for the touch sensor channels
#define CHANNEL_1 2
#define CHANNEL_2 3
#define CHANNEL_3 4
#define CHANNEL_4 5
#define CHANNEL_5 6
#define CHANNEL_6 7
#define CHANNEL_7 8
#define CHANNEL_8 9

// Define GPIO pin for the alert LED
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_channel(int channel);
int log_touch_event(int channel);
void control_led(int on);
void signal_handler(int signal);

// Structure to hold the last touch time for each channel
struct {
    long long last_touch_time;
} channel_states[8] = {{0}};

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure touch sensor channels as inputs with pull-down resistors
    gpioSetMode(CHANNEL_1, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_1, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_2, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_2, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_3, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_3, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_4, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_4, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_5, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_5, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_6, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_6, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_7, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_7, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_8, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_8, PI_PUD_DOWN);

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the state of a touch sensor channel
int read_touch_channel(int channel) {
    return gpioRead(channel);
}

// Function to log a touch event to a file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }

    if (fprintf(log_file, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to control the alert LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off the LED
    gpioTerminate(); // Release pigpio resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int any_touched = 0;

        // Read touch sensor channels
        if (read_touch_channel(CHANNEL_1)) {
            any_touched = 1;
            long long now = time(NULL);
            if (now - channel_states[0].last_touch_time > DEBOUNCE_TIME) {
                if (log_touch_event(1) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 1.\n");
                }
                channel_states[0].last_touch_time = now;
            }
        }
