                if (log_touch_event(2) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 2.\n");
                }
                channel_states[1].last_touch_time = now;
            }
        }
        if (read_touch_channel(CHANNEL_3)) {
            any_touched = 1;
            long long now = time(NULL);
            if (now - channel_states[2].last_touch_time > DEBOUNCE_TIME) {
                if (log_touch_event(3) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 3.\n");
                }
                channel_states[2].last_touch_time = now;
            }
        }
        if (read_touch_channel(CHANNEL_4)) {
            any_touched = 1;
            long long now = time(NULL);
            if (now - channel_states[3].last_touch_time > DEBOUNCE_TIME) {
                if (log_touch_event(4) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 4.\n");
                }
                channel_states[3].last_touch_time = now;
            }
        }
        if (read_touch_channel(CHANNEL_5)) {
            any_touched = 1;
            long long now = time(NULL);
            if (now - channel_states[4].last_touch_time > DEBOUNCE_TIME) {
                if (log_touch_event(5) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 5.\n");
                }
                channel_states[4].last_touch_time = now;
            }
        }
        if (read_touch_channel(CHANNEL_6)) {
            any_touched = 1;
            long long now = time(NULL);
            if (now - channel_states[5].last_touch_time > DEBOUNCE_TIME) {
                if (log_touch_event(6) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 6.\n");
                }
                channel_states[5].last_touch_time = now;
            }
        }
        if (read_touch_channel(CHANNEL_7)) {
            any_touched = 1;
            long long now = time(NULL);
            if (now - channel_states[6].last_touch_time > DEBOUNCE_TIME) {
                if (log_touch_event(7) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 7.\n");
                }
                channel_states[6].last_touch_time = now;
            }
        }
        if (read_touch_channel(CHANNEL_8)) {
            any_touched = 1;
            long long now = time(NULL);
            if (now - channel_states[7].last_touch_time > DEBOUNCE_TIME) {
                if (log_touch_event(8) != 0) {
                    fprintf(stderr, "Error logging touch event for channel 8.\n");
                }
                channel_states[7].last_touch_time = now;
            }
        }

        // Control the LED based on the touch sensor state
        if (any_touched) {
            control_led(1); // Turn on the LED
        } else {
            control_led(0); // Turn off the LED
        }

        gpioDelay(50); // Poll every 50 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
