#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONTINUOUS_MODE 0xCC00 // Continuous mode, 100ms conversion time
#define LUX_SCALE 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(float *lux);
char *format_data(float lux);
int write_to_file(const char *data);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int opt3001_address;
    int continuous_mode;
    float lux_scale;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_value = (CONTINUOUS_MODE >> 8) | ((CONTINUOUS_MODE & 0xFF) << 8); // Byte swap
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }

    gpioDelay(100); // Wait 100ms
    return 0;
}

// Read sensor data and convert to lux
int read_sensor_data(float *lux) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Byte swap the result
    uint16_t raw_result = (buf[1] << 8) | buf[0];

    // Extract exponent and result from the raw data
    int exponent = (raw_result >> 12) & 0x0F;
    int result_value = raw_result & 0x0FFF;

    // Calculate lux value
    *lux = (float)result_value * (float)(1 << exponent) * LUX_SCALE;

    return 0;
}

// Format data into a string
char *format_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char data_string[50]; // Static to avoid stack allocation issues

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(data_string, sizeof(data_string), "%s, %.2f", timestamp, lux);

    return data_string;
}

// Write data to file
int write_to_file(const char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", data) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stdout, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float lux;
    char *data_string;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&lux) == 0) {
            // Format data
            data_string = format_data(lux);

            // Write to file
            if (write_to_file(data_string) != 0) {
                fprintf(stderr, "Error writing to file, but continuing...\n");
            }

            // Print to stdout
            printf("%s\n", data_string);
        } else {
            fprintf(stderr, "Error reading sensor data, but continuing...\n");
        }

        sleep(1); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

