#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to get the current timestamp in the specified format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the event to the file
void log_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // Assume initially not touched
    int current_state;

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            current_state = gpioRead(GPIO_PIN); // Re-read after debounce

            if (current_state != last_state) {
                last_state = current_state;

                if (current_state == 1) {
                    log_event("Touch Detected");
                    fprintf(stderr, "Touch Detected\n");
                } else {
                    log_event("Touch Released");
                    fprintf(stderr, "Touch Released\n");
                }
            }
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup before exiting
    fprintf(stderr, "Cleaning up...\n");
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF); // Remove pull-up/down

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

