        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // Assume initially not touched
    int current_state;

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            current_state = gpioRead(GPIO_PIN); // Re-read after debounce

            if (current_state != last_state) {
                last_state = current_state;

                if (current_state == 1) {
                    log_event("Touch Detected");
                    fprintf(stderr, "Touch Detected\n");
                } else {
                    log_event("Touch Released");
                    fprintf(stderr, "Touch Released\n");
                }
            }
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup before exiting
    fprintf(stderr, "Cleaning up...\n");
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF); // Remove pull-up/down

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

