        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write the header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    uint8_t sensor_data[3];
    sensor_data_t sensor_values;

    printf("Monitoring coolant flow rate... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            uint8_t calculated_crc = calculate_crc(sensor_data, 2);
            if (calculated_crc == sensor_data[2]) {
                // Convert raw data to flow rate
                sensor_values.raw_flow = (sensor_data[0] << 8) | sensor_data[1];
                sensor_values.flow_rate = convert_to_flow_rate(sensor_values.raw_flow);

                // Validate flow rate
                if (sensor_values.flow_rate >= MIN_FLOW_RATE && sensor_values.flow_rate <= MAX_FLOW_RATE) {
                    strcpy(sensor_values.status, "OK");
                } else {
                    strcpy(sensor_values.status, "INVALID");
                }

                // Log the data
                log_data(sensor_values);
            } else {
                fprintf(stderr, "CRC check failed!\n");
                strcpy(sensor_values.status, "ERROR");
                log_data(sensor_values);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
            strcpy(sensor_values.status, "ERROR");
            log_data(sensor_values);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

