#include <stdbool.h>
#include <wiringPi.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int pin);
char* get_iso8601_timestamp();
void log_data(const char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Function to read the sensor value from a given GPIO pin
int read_sensor(int pin) {
    int value = digitalRead(pin);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading %d on pin %d\n", value, pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to log the sensor data to a CSV file
void log_data(const char *timestamp, int left, int middle, int right) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Release GPIO pins
    pinMode(LEFT_SENSOR_PIN, INPUT); // Set to input to avoid spurious output
    pinMode(MIDDLE_SENSOR_PIN, INPUT);
    pinMode(RIGHT_SENSOR_PIN, INPUT);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Unable to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs
    pinMode(LEFT_SENSOR_PIN, INPUT);
    pinMode(MIDDLE_SENSOR_PIN, INPUT);
    pinMode(RIGHT_SENSOR_PIN, INPUT);

    // Open the log file in append mode
    log_file = fopen("path_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Unable to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    fflush(log_file);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error: Failed to get timestamp.\n");
            continue; // Skip logging this iteration
        }

        // Log the data
        log_data(timestamp, left_value, middle_value, right_value);

        // Free the timestamp memory
        free(timestamp);

        // Wait for 50 milliseconds
        delay(50);
    }

    return 0;
}

