    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        // Check for errors during sensor read
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
            gpioTerminate();
            return 1;
        }

        // Check for falling edge (active-low)
        if (sensor_value == 0) {
            log_flame_event();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100); // 100 milliseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

