// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off initially

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Activate buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    return 0;
}

// Log alert to file
int log_alert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup resources before exiting
int cleanup() {
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

int main() {
    int last_state = 1; // Assume no flame initially (HIGH)
    int current_state;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("alert_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write startup message to log file
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s System started\n", timestamp);
    fflush(log_file);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = read_flame_sensor();

        if (current_state == 0 && last_state == 1) {
            // Flame detected (LOW to HIGH transition)
            printf("Flame detected!\n");
            log_alert();
            activate_buzzer(2000); // Activate buzzer for 2 seconds
        }

        last_state = current_state;
        gpioDelay(100 * 1000); // Delay for 100ms (microseconds)
    }

    // Cleanup and exit
    cleanup();
    printf("System stopped.\n");

    return 0;
}

