#include <string.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_TIME_MS 200
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the timestamp to the file
int log_touch_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to toggle the LED state
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_level);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_time = 0;

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 1) {
            int current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_TIME_MS * 1000) {
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_touch_event(timestamp) != 0) {
                        fprintf(stderr, "Error logging touch event.\n");
                    }
                    free(timestamp);
                }
                toggle_led();
                last_touch_time = current_time;
            }
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

