#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HR_REG 0x24 // Example register, adjust as needed
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int part_id;
    int hw_rev;
    int hr_data[MOVING_AVG_SIZE];
    int hr_index;
    int hr_count;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(int *hr);
int apply_moving_average(int *hr_data, int hr_value);
int validate_bpm(int bpm);
int log_data(int bpm);
void signal_handler(int signal);
int configure_sensor();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the Si1182 sensor
int configure_sensor() {
    // Example configuration (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x0F) < 0) { // Example register and value
        fprintf(stderr, "Error writing to sensor: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    if (i2cWriteByteData(i2c_handle, 0x19, 0x03) < 0) { // Example register and value
        fprintf(stderr, "Error writing to sensor: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

// Read sensor data
int read_sensor_data(int *hr) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, HR_REG);
        if (result >= 0) {
            *hr = result; // Assign the read value to the pointer
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Apply moving average filter
int apply_moving_average(int *hr_data, int hr_value) {
    hr_data[sensor_data.hr_index] = hr_value;
    sensor_data.hr_index = (sensor_data.hr_index + 1) % MOVING_AVG_SIZE;

    if (sensor_data.hr_count < MOVING_AVG_SIZE) {
        sensor_data.hr_count++;
        return -1; // Not enough data for average
    }

    int sum = 0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += hr_data[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Validate BPM value
int validate_bpm(int bpm) {
    if (bpm >= BPM_MIN && bpm <= BPM_MAX) {
        return 0; // Valid
    } else {
        fprintf(stderr, "Invalid BPM value: %d\n", bpm);
        return -1; // Invalid
    }
}

// Log data to file
int log_data(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Read sensor ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", hw_rev);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x82 || hw_rev != 0x01) {
        fprintf(stderr, "Incorrect sensor ID or revision. Expected PART_ID=0x82, HW_REV=0x01. Found PART_ID=0x%02X, HW_REV=0x%02X\n", part_id, hw_rev);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor data
    sensor_data.part_id = part_id;
    sensor_data.hw_rev = hw_rev;
    sensor_data.hr_index = 0;
    sensor_data.hr_count = 0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sensor_data.hr_data[i] = 0;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int hr_value;
        if (read_sensor_data(&hr_value) == 0) {
            int filtered_hr = apply_moving_average(sensor_data.hr_data, hr_value);
            if (filtered_hr != -1) {
                if (validate_bpm(filtered_hr) == 0) {
                    log_data(filtered_hr);
                }
            }
        }
        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

