#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO line
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    return 0;
}

// Function to detect a flame event
int detect_flame() {
    int current_level = gpioRead(FLAME_SENSOR_GPIO);
    int previous_level = gpioRead(FLAME_SENSOR_GPIO);

    while (running) {
        current_level = gpioRead(FLAME_SENSOR_GPIO);
        if (current_level == 0 && previous_level == 1) {
            return 1; // Flame detected (falling edge)
        }
        previous_level = current_level;
        gpioDelay(100); // Poll every 100ms
    }
    return 0; // No flame detected or interrupted
}

// Function to log the flame event
void log_flame_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (detect_flame()) {
            printf("FLAME DETECTED\n");
            log_flame_event();
        }
    }

    cleanup();
    return 0;
}

