// Define GPIO pins for touch sensors and counter outputs
#define TOUCH_SENSOR_START_PIN 5
#define COUNTER_OUTPUT_START_PIN 17
#define NUM_CHANNELS 8

// Global variables
static volatile int running = 1;
static int gpio_initialized = 0;

// Function prototypes
int read_touch_sensor(int pin);
int update_counter(int *counter, int channel);
int write_counter_to_gpio(int counter);
int log_touch_event(int channel, int counter);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a touch sensor
int read_touch_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to update the binary counter
int update_counter(int *counter, int channel) {
    *counter = (*counter + 1) % 256;
    return 0; // Indicate success
}

// Function to write the counter value to the GPIO pins
int write_counter_to_gpio(int counter) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = COUNTER_OUTPUT_START_PIN + i;
        int bit = (counter >> i) & 1;
        if (gpioWrite(pin, bit) != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, strerror(errno));
            return -1; // Indicate error
        }
    }
    return 0; // Indicate success
}

// Function to log the touch event to a file
int log_touch_event(int channel, int counter) {
