    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }
    gpio_initialized = 1;

    // Set GPIO modes for touch sensors and counter outputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int touch_pin = TOUCH_SENSOR_START_PIN + i;
        int counter_pin = COUNTER_OUTPUT_START_PIN + i;

        if (gpioSetMode(touch_pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d to input: %s\n", touch_pin, strerror(errno));
            goto cleanup;
        }
        if (gpioSetMode(counter_pin, PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d to output: %s\n", counter_pin, strerror(errno));
            goto cleanup;
        }
    }

    // Initialize the counter to 0
    int counter = 0;

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int touch_pin = TOUCH_SENSOR_START_PIN + i;
            int touch_value = read_touch_sensor(touch_pin);

            if (touch_value == 1) {
                if (update_counter(&counter, i) == 0) {
                    if (write_counter_to_gpio(counter) == 0) {
                        if (log_touch_event(i + 1, counter) != 0) {
                            fprintf(stderr, "Error logging touch event for channel %d\n", i + 1);
                        }
                        printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                    } else {
                        fprintf(stderr, "Error writing counter to GPIO pins\n");
                    }
                } else {
                    fprintf(stderr, "Error updating counter\n");
                }
            }
        }
        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup and exit
cleanup:
    if (gpio_initialized) {
        gpioTerminate();
    }
    return 0;
}

