#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Sampling rate (8 kHz)
#define SAMPLE_PERIOD_US 125

// LED on time (100 ms)
#define LED_ON_TIME_MS 100

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received. Shutting down gracefully...\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return 1;
    }

    fprintf(stdout, "Starting sound peak detection...\n");

    // Main loop
    while (program_running) {
        // Read microphone pin
        int mic_value = gpioRead(MIC_PIN);

        // Check for sound peak (HIGH reading)
        if (mic_value == 1) {
            // Get current time
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            // Print timestamp
            printf("%ld.%03ld\n", ts.tv_sec, ts.tv_nsec / 1000000);

            // Turn on LED
            gpioWrite(LED_PIN, 1);

            // Wait for LED on time
            gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to us

            // Turn off LED
            gpioWrite(LED_PIN, 0);
        }

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio

    fprintf(stdout, "Program terminated.\n");
    return 0;
}

