#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses (Example - adjust based on datasheet)
#define SI1175_REG_ALS_LSB 0x22
#define SI1175_REG_ALS_MSB 0x23

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting...\n");
}

// Function to initialize the Si1175 sensor
int init_si1175() {
    // Example initialization sequence (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x0F) < 0) return -1; // Reset
    gpioDelay(10); // Delay after reset
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) return -1; // Enable ALS
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) return -1; // ALS force measurement
    return 0;
}

// Function to read the ALS data from the Si1175 sensor
int read_als_data(uint16_t *als_data) {
    int lsb, msb;

    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB register: %d\n", lsb);
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS MSB register: %d\n", msb);
        return -1;
    }

    *als_data = (msb << 8) | lsb;
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1175_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1175 sensor
    if (init_si1175() < 0) {
        fprintf(stderr, "Error initializing Si1175 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si1175 sensor initialized successfully. Reading ALS data...\n");

    // Main loop
    while (!terminate) {
        uint16_t als_data;

        // Read ALS data
        if (read_als_data(&als_data) == 0) {
            // Log the raw sensor reading
            printf("ALS Data: %u\n", als_data);
        } else {
            fprintf(stderr, "Error reading ALS data\n");
        }

        // Delay for 100ms
        gpioDelay(100);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

