#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for each touch sensor channel
#define TP1 5
#define TP2 6
#define TP3 13
#define TP4 19
#define TP5 26
#define TP6 12
#define TP7 16
#define TP8 20

// Structure to hold GPIO pin numbers
struct gpio_pins {
    int tp1;
    int tp2;
    int tp3;
    int tp4;
    int tp5;
    int tp6;
    int tp7;
    int tp8;
};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a single touch sensor channel
int read_touch_channel(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to read all touch sensor channels and format the output
void read_all_channels(int *channel_values) {
    channel_values[0] = read_touch_channel(TP1);
    channel_values[1] = read_touch_channel(TP2);
    channel_values[2] = read_touch_channel(TP3);
    channel_values[3] = read_touch_channel(TP4);
    channel_values[4] = read_touch_channel(TP5);
    channel_values[5] = read_touch_channel(TP6);
    channel_values[6] = read_touch_channel(TP7);
    channel_values[7] = read_touch_channel(TP8);
}

// Function to print the formatted output with timestamp
void print_output(struct timespec ts, int *channel_values) {
    printf("[%09ld.%09ld] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           ts.tv_sec, ts.tv_nsec,
           channel_values[0], channel_values[1], channel_values[2], channel_values[3],
           channel_values[4], channel_values[5], channel_values[6], channel_values[7]);
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs
    gpioSetMode(TP1, PI_INPUT);
    gpioSetMode(TP2, PI_INPUT);
    gpioSetMode(TP3, PI_INPUT);
    gpioSetMode(TP4, PI_INPUT);
    gpioSetMode(TP5, PI_INPUT);
    gpioSetMode(TP6, PI_INPUT);
    gpioSetMode(TP7, PI_INPUT);
    gpioSetMode(TP8, PI_INPUT);

    // Array to store the state of each channel
    int channel_values[8];

    // Main loop
    while (program_running) {
        // Get the current time with nanosecond precision
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Read all touch sensor channels
        read_all_channels(channel_values);

        // Check for errors during channel reads
        for (int i = 0; i < 8; i++) {
            if (channel_values[i] == -1) {
                fprintf(stderr, "Error reading channel %d, exiting...\n", i + 1);
                program_running = 0; // Stop the loop on error
                break;
            }
        }

        // Print the output
        if (program_running) {
            print_output(ts, channel_values);
        }

        // Wait for 200 milliseconds
        usleep(200000); // 200 ms = 200000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

