#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range (8-bit)
#define PWM_RANGE 255

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

// Function to generate a random RGB color
RGBColor generate_random_color() {
    RGBColor color;
    color.red = rand() % 256;
    color.green = rand() % 256;
    color.blue = rand() % 256;
    return color;
}

// Function to interpolate between two RGB colors
RGBColor interpolate_color(RGBColor start_color, RGBColor end_color, float fraction) {
    RGBColor interpolated_color;
    interpolated_color.red = (int)(start_color.red + (end_color.red - start_color.red) * fraction);
    interpolated_color.green = (int)(start_color.green + (end_color.green - start_color.green) * fraction);
    interpolated_color.blue = (int)(start_color.blue + (end_color.blue - start_color.blue) * fraction);
    return interpolated_color;
}

// Function to set the RGB LED color using PWM
void set_led_color(RGBColor color) {
    // Common anode, so invert the color values
    int red_duty = PWM_RANGE - color.red;
    int green_duty = PWM_RANGE - color.green;
    int blue_duty = PWM_RANGE - color.blue;

    gpioPWM(RED_PIN, red_duty);
    gpioPWM(GREEN_PIN, green_duty);
    gpioPWM(BLUE_PIN, blue_duty);
}

int main() {
    // Open syslog for logging
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        closelog();
        return 1;
    }
    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, fp) != 1) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        fclose(fp);
        closelog();
        return 1;
    }
    fclose(fp);
    srand(seed);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Generate initial random color
    RGBColor current_color = generate_random_color();
    set_led_color(current_color);

    // Main loop
    while (program_running) {
        // Generate new random color
        RGBColor new_color = generate_random_color();

        // Interpolate between current and new color over 5 seconds (50 steps)
        for (int i = 0; i <= 50; i++) {
            float fraction = (float)i / 50.0;
            RGBColor interpolated_color = interpolate_color(current_color, new_color, fraction);
            set_led_color(interpolated_color);
            gpioDelay(100000); // 100ms delay (100000 microseconds)
        }

        // Update current color
        current_color = new_color;
    }

    // Turn off the LED
    set_led_color((RGBColor){0, 0, 0});

    // Release pigpio resources
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

