#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <signal.h>
#include <errno.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// GPIO pin for LED
#define LED_PIN 17

// Red value threshold
#define RED_THRESHOLD 200

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_raw_data(int fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void tcs34725_power_down(int fd);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Enable power and RGBC (AEN = 1, PON = 1)
    if (i2cWriteByteData(fd, TCS34725_ENABLE, 0x03) < 0) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set integration time (ATIME = 0xD5 for 154ms)
    if (i2cWriteByteData(fd, TCS34725_ATIME, 0xD5) < 0) {
        perror("Error writing to ATIME register");
        return -1;
    }

    return 0;
}

// Read raw RGBC data from the sensor
int tcs34725_read_raw_data(int fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t buffer[8];

    // Read 8 bytes starting from CDATA register
    if (read(fd, buffer, 8) != 8) {
        perror("Error reading data from sensor");
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Power down the sensor
void tcs34725_power_down(int fd) {
    if (i2cWriteByteData(fd, TCS34725_ENABLE, 0x00) < 0) {
        perror("Error writing to ENABLE register for power down");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        uint16_t red, green, blue, clear;

        // Read raw data from the sensor
        if (tcs34725_read_raw_data(i2c_fd, &red, &green, &blue, &clear) == 0) {
            // Calibrate the values (example calibration, adjust as needed)
            float calibrated_red   = (float)red   / 2.0;
            float calibrated_green = (float)green / 2.0;
            float calibrated_blue  = (float)blue  / 2.0;
            float calibrated_clear = (float)clear / 2.0;

            // Print the calibrated values
            printf("R: %.2f, G: %.2f, B: %.2f, C: %.2f\n", calibrated_red, calibrated_green, calibrated_blue, calibrated_clear);

            // Control the LED based on the red value
            if (calibrated_red > RED_THRESHOLD) {
                digitalWrite(LED_PIN, HIGH);
            } else {
                digitalWrite(LED_PIN, LOW);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting re-initialization.\n");
            // Attempt to re-initialize the sensor
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }

        // Wait 200ms
        delay(200);
    }

    // Cleanup
    tcs34725_power_down(i2c_fd);
    close(i2c_fd);
    digitalWrite(LED_PIN, LOW); // Turn off LED

    printf("Program finished.\n");

    return 0;
}

