void send_led_data(int *led_data, int num_leds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    int retries = 3;
    int result;
    unsigned char data[2];

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, 0x10); // Continuous high resolution mode
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        gpioDelay(180000); // 180ms delay

        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result == 2) {
            unsigned int raw_value = (data[0] << 8) | data[1];
            return (float)raw_value / 1.2; // Convert to lux
        } else {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read lux after multiple retries.\n");
    return -1.0; // Indicate error
}

// Map lux value to brightness level (0-255)
int map_lux_to_brightness(float lux) {
    if (lux < 0) return 0; // Handle error case

    if (lux > LUX_THRESHOLD) {
        return 255; // Max brightness
    } else {
        return (int)(255.0 * log10(lux + 1) / log10(LUX_THRESHOLD + 1)); // Logarithmic mapping
    }
}

