    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure PWM/wave for WS2812B
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(WS2812B_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(WS2812B_GPIO, PWM_RANGE);

    float lux;
    int brightness;
    int led_data[NUM_LEDS * 3]; // Array to hold RGB data for all LEDs

    while (!terminate) {
        // Read lux value
        lux = read_lux();

        if (lux >= 0) {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED color (simplified example)
            for (int i = 0; i < NUM_LEDS; i++) {
                // In a real implementation, you would calculate the color for each LED here.
                // For example, you might want to fade the LEDs based on their position.
                // For this example, we'll just set all LEDs to the same color.
                led_data[i * 3] = brightness;       // Red
                led_data[i * 3 + 1] = brightness;   // Green
                led_data[i * 3 + 2] = brightness;   // Blue
            }

            // Send LED data
