#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
int udp_socket = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(int channel, int speed);
int init_udp_socket(const char *ip, int port);
int read_bh1750(int fd);
void set_apa102_brightness(int spi_fd, int brightness);
void send_data_to_server(int socket, int brightness);
void signal_handler(int signal);
void cleanup();

// Structure for APA102 data
typedef struct {
    uint32_t start_frame;
    uint32_t led_frames[NUM_LEDS];
    uint32_t end_frame;
} apa102_data_t;

// Function to initialize I2C
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    uint8_t config_cmd = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize SPI
int init_spi(int channel, int speed) {
    int fd = wiringPiSPISetup(channel, speed);
    if (fd < 0) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize UDP socket
int init_udp_socket(const char *ip, int port) {
    int socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(socket);
        return -1;
    }

    return socket;
}

// Function to read data from BH1750 sensor
int read_bh1750(int fd) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Function to set APA102 LED strip brightness
void set_apa102_brightness(int spi_fd, int brightness) {
    apa102_data_t data;

    // Start frame (all zeros)
    data.start_frame = 0x00000000;

    // LED frames (brightness, blue, green, red)
    for (int i = 0; i < NUM_LEDS; i++) {
        data.led_frames[i] = (brightness << 24) | (0x00 << 16) | (0x00 << 8) | 0x00; // Brightness, Blue, Green, Red
    }

    // End frame (at least 16 bits of 0x00)
    data.end_frame = 0x00000000;

    // Send data via SPI
    unsigned char spi_data[4 * (NUM_LEDS + 2)];
    for (int i = 0; i < NUM_LEDS + 2; i++) {
        spi_data[i * 4 + 0] = (data.start_frame >> 24) & 0xFF;
        spi_data[i * 4 + 1] = (data.start_frame >> 16) & 0xFF;
        spi_data[i * 4 + 2] = (data.start_frame >> 8) & 0xFF;
        spi_data[i * 4 + 3] = data.start_frame & 0xFF;
    }

    wiringPiSPIDataRW(SPI_CHANNEL, spi_data, 4 * (NUM_LEDS + 2));
}

// Function to send data to the server
void send_data_to_server(int socket, int brightness) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return;
    }

    char message[32];
    snprintf(message, sizeof(message), "%d", brightness);

    if (sendto(socket, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error sending data to server");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        // Turn off LEDs before closing SPI
        set_apa102_brightness(spi_fd, 0);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    printf("Cleanup complete.\n");
}

