        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read light level from BH1750
        int light_level = read_bh1750(i2c_fd);
