#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define sensor addresses
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x40

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define APA102 start frame
#define APA102_START_FRAME_SIZE 4
#define APA102_START_FRAME_VALUE 0x00

// Define GPIO pins for APA102
#define APA102_MOSI_PIN 10 // BCM
#define APA102_SCK_PIN 11  // BCM

// Global variables
int i2c_fd1 = -1;
int i2c_fd2 = -1;
int i2c_fd3 = -1;
int spi_fd = -1;
bool running = true;

// Function prototypes
int init_i2c(int address);
int read_bh1750(int fd);
int init_spi();
void send_apa102_data(uint8_t brightness);
void fade_apa102(uint8_t target_brightness);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C device at address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read data from BH1750 sensor
int read_bh1750(int fd) {
    if (fd == -1) {
        return -1; // Sensor not initialized
    }

    // Send start measurement command (High Resolution Mode)
    if (wiringPiI2CWrite(fd, 0x10) == -1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 180ms)
    delay(180);

    // Read two bytes of data
    int msb = wiringPiI2CReadReg8(fd, 0x00);
    int lsb = wiringPiI2CReadReg8(fd, 0x01);

    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the bytes to get the light intensity
    int light_intensity = (msb << 8) | lsb;
    return light_intensity;
}

// Function to initialize SPI
int init_spi() {
    int fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to send APA102 data
void send_apa102_data(uint8_t brightness) {
    // Start frame (4 bytes of 0x00)
    for (int i = 0; i < APA102_START_FRAME_SIZE; i++) {
        for (int j = 0; j < 8; j++) {
            digitalWrite(APA102_MOSI_PIN, APA102_START_FRAME_VALUE & 0x80 ? HIGH : LOW);
            digitalWrite(APA102_SCK_PIN, HIGH);
            digitalWrite(APA102_SCK_PIN, LOW);
            APA102_START_FRAME_VALUE <<= 1;
        }
    }

    // LED data (brightness, green, blue, red)
    for (int i = 0; i < 4; i++) {
        // Brightness (global brightness)
        uint8_t data = brightness;
        for (int j = 0; j < 8; j++) {
            digitalWrite(APA102_MOSI_PIN, data & 0x80 ? HIGH : LOW);
            digitalWrite(APA102_SCK_PIN, HIGH);
            digitalWrite(APA102_SCK_PIN, LOW);
            data <<= 1;
        }

        // Green (0x00)
        data = 0x00;
        for (int j = 0; j < 8; j++) {
            digitalWrite(APA102_MOSI_PIN, data & 0x80 ? HIGH : LOW);
            digitalWrite(APA102_SCK_PIN, HIGH);
            digitalWrite(APA102_SCK_PIN, LOW);
            data <<= 1;
        }

        // Blue (0x00)
        data = 0x00;
        for (int j = 0; j < 8; j++) {
            digitalWrite(APA102_MOSI_PIN, data & 0x80 ? HIGH : LOW);
            digitalWrite(APA102_SCK_PIN, HIGH);
            digitalWrite(APA102_SCK_PIN, LOW);
            data <<= 1;
        }

        // Red (0x00)
        data = 0x00;
        for (int j = 0; j < 8; j++) {
            digitalWrite(APA102_MOSI_PIN, data & 0x80 ? HIGH : LOW);
            digitalWrite(APA102_SCK_PIN, HIGH);
            digitalWrite(APA102_SCK_PIN, LOW);
            data <<= 1;
        }
    }
}

// Function to fade APA102 brightness
void fade_apa102(uint8_t target_brightness) {
    uint8_t current_brightness = 0;
    int steps = 20; // Number of steps for the fade
    float increment = (float)(target_brightness - current_brightness) / steps;

    for (int i = 0; i < steps; i++) {
        current_brightness += increment;
        send_apa102_data(current_brightness);
        delay(25); // 500ms / 20 steps = 25ms per step
    }
    send_apa102_data(target_brightness);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;

    // Turn off the LED strip
    send_apa102_data(0);

    // Close I2C file descriptors
    if (i2c_fd1 != -1) close(i2c_fd1);
    if (i2c_fd2 != -1) close(i2c_fd2);
    if (i2c_fd3 != -1) close(i2c_fd3);

    // Close SPI file descriptor
    if (spi_fd != -1) close(spi_fd);

    // De-initialize wiringPi
    wiringPiSetup(); // Reinitialize to allow cleanup

    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins to output mode
    pinMode(APA102_MOSI_PIN, OUTPUT);
    pinMode(APA102_SCK_PIN, OUTPUT);

    // Initialize I2C
    i2c_fd1 = init_i2c(BH1750_ADDR_1);
    i2c_fd2 = init_i2c(BH1750_ADDR_2);
    i2c_fd3 = init_i2c(BH1750_ADDR_3);

    // Initialize SPI
    spi_fd = init_spi();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    while (running) {
        int light_intensity1 = (i2c_fd1 != -1) ? read_bh1750(i2c_fd1) : -1;
        int light_intensity2 = (i2c_fd2 != -1) ? read_bh1750(i2c_fd2) : -1;
        int light_intensity3 = (i2c_fd3 != -1) ? read_bh1750(i2c_fd3) : -1;

        int valid_readings = 0;
        int total_intensity = 0;

        if (light_intensity1 != -1) {
            total_intensity += light_intensity1;
            valid_readings++;
        }
        if (light_intensity2 != -1) {
            total_intensity += light_intensity2;
            valid_readings++;
        }
        if (light_intensity3 != -1) {
            total_intensity += light_intensity3;
            valid_readings++;
        }

        float average_intensity = 0.0;
        if (valid_readings > 0) {
            average_intensity = (float)total_intensity / valid_readings;
        }

        // Map light intensity to brightness (0-255)
        uint8_t brightness = (uint8_t)(average_intensity / 10.0); // Adjust scaling as needed
        if (brightness > 255) brightness = 255;

        // Fade to the new brightness
        fade_apa102(brightness);

        delay(100); // Delay between readings
    }

    return 0;
}

