#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to perform the self-test
int self_test() {
    int flame_detected = 0;
    for (int i = 0; i < 5; i++) {
        gpioDelay(100000); // 100ms delay
        if (gpioRead(FLAME_SENSOR_PIN) == 0) {
            flame_detected = 1;
        }
    }

    if (flame_detected) {
        fprintf(stderr, "Error: Flame detected during self-test!\n");
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, event);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Perform self-test
    if (self_test() != 0) {
        gpioTerminate();
        return 1;
    }

    log_event("Self-test passed.");

    // Main loop
    while (program_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_PIN);

        if (flame_detected == 0) {
            log_event("Flame detected!");
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            while (gpioRead(FLAME_SENSOR_PIN) == 0 && program_running) {
                gpioDelay(50000); // 50ms delay
            }
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
            log_event("Flame cleared!");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup GPIO resources
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    log_event("Program terminated.");
    return 0;
}

