#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MAX_LUX 1000

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_bh1750(int fd);
float calculate_average_lux();
void set_led_frequency(float lux);
void signal_handler(int signal);

// Structure for I2C configuration
typedef struct {
    char *bus;
    int addr;
} i2c_config_t;

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read lux value from BH1750
int read_bh1750(int fd) {
    unsigned char buf[2];
    int lux;

    // Send measurement mode command
    buf[0] = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux value
    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to calculate the average lux value
float calculate_average_lux() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to set the LED blinking frequency based on lux value
void set_led_frequency(float lux) {
    float frequency;

    if (lux <= 0) {
        frequency = 0.5; // Minimum frequency
    } else {
        frequency = 0.5 + (lux / (MAX_LUX + 1)) * (5.0 - 0.5); // Proportional frequency
        if (frequency > 5.0) {
            frequency = 5.0; // Maximum frequency
        }
    }

    // Calculate period in milliseconds
    float period_ms = 1000.0 / frequency;

    // Calculate on and off times for 50% duty cycle
    float on_time_ms = period_ms / 2.0;
    float off_time_ms = period_ms / 2.0;

    // Convert to microseconds
    int on_time_us = (int)on_time_ms * 1000;
    int off_time_us = (int)off_time_ms * 1000;

    // Blink the LED
    digitalWrite(GPIO_PIN, HIGH);
    usleep(on_time_us);
    digitalWrite(GPIO_PIN, LOW);
    usleep(off_time_us);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ambient light monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int lux = read_bh1750(i2c_fd);

        if (lux >= 0) {
            // Store lux value in circular buffer
            lux_buffer[buffer_index] = (float)lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average lux
            float average_lux = calculate_average_lux();

            // Set LED frequency
            set_led_frequency(average_lux);

            printf("Lux: %d, Average Lux: %.2f\n", lux, average_lux);
        } else {
            fprintf(stderr, "Error reading lux value. Skipping sample.\n");
        }

        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    digitalWrite(GPIO_PIN, LOW); // Turn off LED
    pinMode(GPIO_PIN, INPUT); // Set back to input

    printf("Program terminated.\n");
    return 0;
}

