#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the segment pattern for the digit '5' (common cathode)
const unsigned char digit_5 = 0b00100100; // a, c, d, f

// Function to shift out a byte to the 74HC595
void shiftOut(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set the data pin based on the current bit
        gpioWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock the data in
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Short delay for clock stability
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); // Short delay for clock stability
    }
}

// Function to display a digit on the 7-segment display
void displayDigit(unsigned char digit) {
    // Latch the data
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); // Short delay for latch stability
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1); // Short delay for latch stability
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    // Main loop to blink the digit '5'
    while (1) {
        // Display the digit '5'
        shiftOut(digit_5);
        displayDigit(digit_5);

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds

        // Clear the display (all segments off)
        shiftOut(0x00);
        displayDigit(0x00);

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // This part is never reached in this example, but it's good practice
    gpioTerminate();
    return 0;
}

