#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to blink the LED
void blink_led(int gpio_pin, int on_time_ms, int off_time_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(on_time_ms * 1000); // Delay for on time
    gpioWrite(gpio_pin, 0); // Turn LED off
    gpioDelay(off_time_ms * 1000); // Delay for off time
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output and initially low
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    // Set button pin as input with pull-up resistor and falling edge detection
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor
    if (gpioSetAlertFuncEx(BUTTON_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for button pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Press the button to stop the LED blinking.\n");

    // Main loop
    while (program_running) {
        blink_led(LED_PIN, 1, 1); // Blink LED for 1 second on, 1 second off

        // Check for button press (falling edge)
        if (gpioRead(BUTTON_PIN) == 0) {
            printf("Button pressed! LED blinking stopped.\n");
            program_running = 0; // Stop the loop
        }
    }

    // Cleanup: Turn off LED and terminate pigpio
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate(); // Terminate pigpio

    return 0;
}

