#define BUTTON_PIN 22

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(500);        // Wait 500ms
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(500);        // Wait 500ms
}

// Function to handle button press
void handle_button_press() {
    while (gpioRead(BUTTON_PIN) == 0 && program_running) {
        blink_led();
    }
    gpioWrite(LED_PIN, 0); // Turn LED off when button is released
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (gpioRead(BUTTON_PIN) == 1) {
            handle_button_press();
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup GPIO
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");

    return 0;
}

