#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM period (microseconds)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// PWM cycle time (microseconds)
#define PWM_CYCLE (PWM_PERIOD / 2)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the intensity of an RGB color channel
void set_color_intensity(int pin, int intensity) {
    if (intensity < 0 || intensity > 100) {
        fprintf(stderr, "Error: Intensity value out of range (0-100).\n");
        return;
    }

    // Calculate the on-time and off-time for the PWM cycle
    int on_time = (int)((float)intensity / 100.0 * PWM_CYCLE);
    int off_time = PWM_CYCLE - on_time;

    // Set the pin HIGH for the on-time
    gpioWrite(pin, 1);
    gpioDelay(on_time);

    // Set the pin LOW for the off-time
    gpioWrite(pin, 0);
    gpioDelay(off_time);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("RGB LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate random intensity values for each color channel
        int red_intensity = rand() % 101;
        int green_intensity = rand() % 101;
        int blue_intensity = rand() % 101;

        // Set the intensity of each color channel
        set_color_intensity(RED_PIN, red_intensity);
        set_color_intensity(GREEN_PIN, green_intensity);
        set_color_intensity(BLUE_PIN, blue_intensity);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

