#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x19
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define GPIO_PIN 17
#define IMPACT_DURATION_MS 50
#define LOG_FILE "impact_log.txt"

// Global variables
static int i2c_handle;
static volatile int running = 1;
static float impact_threshold = 2.0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_accelerometer(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void trigger_interrupt();
void log_data(float x, float y, float z, float magnitude);
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Configure accelerometer (10 Hz, enable all axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to initialize the GPIO pin
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6); // Enable auto-increment
    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, convert to G-force (assuming +/- 2G sensitivity)
    *x = (float)((int16_t)((buffer[1] << 8) | buffer[0])) / 16384.0f;
    *y = (float)((int16_t)((buffer[3] << 8) | buffer[2])) / 16384.0f;
    *z = (float)((int16_t)((buffer[5] << 8) | buffer[4])) / 16384.0f;

    return 0;
}

// Function to calculate the magnitude of the G-force vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to trigger the interrupt (set GPIO HIGH for 50ms)
void trigger_interrupt() {
    gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
    gpioDelay(IMPACT_DURATION_MS * 1000); // Delay for 50ms
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
}

// Function to log the data to a file
void log_data(float x, float y, float z, float magnitude) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %.4f, Y: %.4f, Z: %.4f, Magnitude: %.4f\n", s, x, y, z, magnitude);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is LOW
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        impact_threshold = atof(argv[1]);
        printf("Impact threshold set to: %.2f G\n", impact_threshold);
    }

