#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "color_log.csv"

// ADPD188BI Register Addresses (Example - Refer to datasheet for actual values)
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
void combine_als_data(uint8_t lsb, uint8_t msb, uint16_t *als);
void log_data(sensor_data_t data);
void control_led(uint16_t als);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ADPD188BI
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[8];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, (char *)buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    combine_als_data(buffer[0], buffer[1], &data->als);
    combine_als_data(buffer[2], buffer[3], &data->red);
    combine_als_data(buffer[4], buffer[5], &data->green);
    combine_als_data(buffer[6], buffer[7], &data->blue);

    return 0;
}

// Combine ALS LSB and MSB into a 16-bit unsigned value
void combine_als_data(uint8_t lsb, uint8_t msb, uint16_t *als) {
    *als = ((uint16_t)msb << 8) | lsb;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, data.als, data.red, data.green, data.blue);
    fflush(csv_file); // Ensure data is written to file immediately
}

// Control LED brightness using PWM
void control_led(uint16_t als) {
    // Map ALS value (0-65535) to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(((float)als / 65535.0) * 1000000.0);

    if (duty_cycle > 1000000) {
        duty_cycle = 1000000;
    }

    gpioPWM(LED_GPIO, duty_cycle);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(csv_file);
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        result = read_sensor_data(&sensor_data);
        if (result == 0) {
            log_data(sensor_data);
            control_led(sensor_data.als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue; // Skip to the next iteration of the loop
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

