#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds
#define NUM_CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0 // dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int init_gyro();
void calibrate_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
void log_data(float x, float y, float z);
void check_alert(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    // Enable the gyroscope (normal mode, 20 Hz ODR)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    printf("Gyroscope initialized successfully.\n");
    return 0;
}

// Calibrate the gyroscope
void calibrate_gyro() {
    int16_t raw_x, raw_y, raw_z;
    long x_sum = 0, y_sum = 0, z_sum = 0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return;
        }
        x_sum += raw_x;
        y_sum += raw_y;
        z_sum += raw_z;
        gpioDelay(SAMPLE_PERIOD_US); // Delay for 50ms
    }

    x_offset = (float)x_sum / NUM_CALIBRATION_SAMPLES;
    y_offset = (float)y_sum / NUM_CALIBRATION_SAMPLES;
    z_offset = (float)z_sum / NUM_CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
}

// Read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Apply calibration offsets
void apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)raw_x - x_offset;
    *calibrated_y = (float)raw_y - y_offset;
    *calibrated_z = (float)raw_z - z_offset;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check for alert condition
void check_alert(float x, float y, float z) {
    if (fabs(x) > ALERT_THRESHOLD || fabs(y) > ALERT_THRESHOLD || fabs(z) > ALERT_THRESHOLD) {
        fprintf(stderr, "ALERT: Angular velocity exceeded threshold!\n");
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        fprintf(log_file, "%s,ALERT: Angular velocity exceeded threshold!\n", timestamp);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate the gyroscope
    calibrate_gyro();

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Apply calibration
            apply_calibration(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Log data
            log_data(calibrated_x, calibrated_y, calibrated_z);

            // Check for alert
            check_alert(calibrated_x, calibrated_y, calibrated_z);
        } else {
            fprintf(stderr, "Error reading gyro data in main loop\n");
        }

        // Delay for 50ms
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

