#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <string.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_DEVID 0x00

// GPIO Pin for LED
#define LED_PIN 17

// Global Variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function Prototypes
int adxl345_init();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Function to initialize the ADXL345
int adxl345_init() {
    int devid;

    // Check Device ID
    devid = wiringPiI2CReadReg8(i2c_fd, ADXL345_DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid Device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set Data Format: Full Resolution, ±2g range
    if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register: %s\n", strerror(errno));
        return -1;
    }

    // Enable Measurement Mode
    if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = wiringPiI2CReadReg8(i2c_fd, ADXL345_DATAX0);
    x1 = wiringPiI2CReadReg8(i2c_fd, ADXL345_DATAX0 + 1);
    y0 = wiringPiI2CReadReg8(i2c_fd, ADXL345_DATAY0);
    y1 = wiringPiI2CReadReg8(i2c_fd, ADXL345_DATAY0 + 1);
    z0 = wiringPiI2CReadReg8(i2c_fd, ADXL345_DATAZ0);
    z1 = wiringPiI2CReadReg8(i2c_fd, ADXL345_DATAZ0 + 1);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x1 << 8) | x0);
