#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A 0x28
#define LSM303_MAG_MR_REG_M 0x02
#define LSM303_MAG_OUT_X_H_M 0x03

// Scaling factors
#define ACCEL_SCALE 0.000244f // +/- 2g range
#define MAG_SCALE 0.0011f    // +/- 1.3 Gauss range

// Global variables
int accel_handle = -1;
int mag_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensors();
sensor_data_t read_sensors();
float calculate_heading(sensor_data_t data);
int log_data(sensor_data_t data, float heading);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    accel_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", accel_handle);
        return -1;
    }

    mag_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", mag_handle);
        i2cClose(accel_handle);
        return -1;
    }

    return 0;
}

// Initialize accelerometer and magnetometer
int init_sensors() {
    // Enable accelerometer (100 Hz, all axes)
    if (i2cWriteByteData(accel_handle, LSM303_ACCEL_CTRL_REG1_A, 0x67) < 0) {
        fprintf(stderr, "Failed to write to accelerometer control register\n");
        return -1;
    }

    // Enable magnetometer (continuous conversion mode)
    if (i2cWriteByteData(mag_handle, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer mode register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and magnetometer data
sensor_data_t read_sensors() {
    sensor_data_t data;
    char buffer[6];

    // Read accelerometer data
    if (i2cReadI2CBlockData(accel_handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
    } else {
        data.accel_x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) * ACCEL_SCALE;
        data.accel_y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) * ACCEL_SCALE;
        data.accel_z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) * ACCEL_SCALE;
    }

    // Read magnetometer data
    if (i2cReadI2CBlockData(mag_handle, LSM303_MAG_OUT_X_H_M | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        data.mag_x = data.mag_y = data.mag_z = 0.0f;
    } else {
        data.mag_x = (float)((int16_t)(buffer[0] << 8 | buffer[1])) * MAG_SCALE;
        data.mag_y = (float)((int16_t)(buffer[2] << 8 | buffer[3])) * MAG_SCALE;
        data.mag_z = (float)((int16_t)(buffer[4] << 8 | buffer[5])) * MAG_SCALE;
    }

    return data;
}

// Calculate tilt-compensated heading
float calculate_heading(sensor_data_t data) {
    float roll = atan2(data.accel_y, data.accel_z);
    float pitch = atan2(-data.accel_x, sqrt(data.accel_y * data.accel_y + data.accel_z * data.accel_z));

    float mag_x_comp = data.mag_x * cos(pitch) + data.mag_z * sin(pitch);
    float mag_y_comp = data.mag_x * sin(roll) * sin(pitch) + data.mag_y * cos(roll) - data.mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp);

    // Convert to degrees
    heading = heading * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
int log_data(sensor_data_t data, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, heading, data.accel_x, data.accel_y, data.accel_z, data.mag_x, data.mag_y, data.mag_z);
    fflush(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (accel_handle >= 0) i2cClose(accel_handle);
    if (mag_handle >= 0) i2cClose(mag_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C and sensors
    if (init_i2c() < 0) {
        return 1;
    }

    if (init_sensors() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensors();
        float heading = calculate_heading(data);
        log_data(data, heading);
        gpioDelay(100); // Sample every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

