#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define sampling interval (10 ms)
#define SAMPLE_INTERVAL_US 10000

// Define CSV file name
#define CSV_FILE "audio_log.dat"

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *fp = NULL;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor_data(int handle, int16_t *data);
int16_t process_sensor_data(int16_t raw_data);
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, double tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close the CSV file if it is open
    if (fp != NULL) {
        fclose(fp);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Read sensor data from I2C
int read_sensor_data(int handle, int16_t *data) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Process sensor data (e.g., apply calibration)
int16_t process_sensor_data(int16_t raw_data) {
    // In a real application, apply calibration here
    return raw_data; // Return the raw data for now
}

// Calculate TDOA (simplified)
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    // This is a placeholder.  A real TDOA calculation would involve cross-correlation.
    // For simplicity, we'll just return the difference in absolute values.
    return (double)(abs(sensor1_data) - abs(sensor2_data));
}

// Log data to CSV file
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, double tdoa) {
    if (fprintf(fp, "%ld,%ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C communication for both sensors
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
