#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define REG_GYRO_XOUT 0x04
#define REG_GYRO_YOUT 0x06
#define REG_GYRO_ZOUT 0x08
#define REG_ACCEL_XOUT 0x0A
#define REG_ACCEL_YOUT 0x0C
#define REG_ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CS_PIN 8 // GPIO8 (BCM)

// Sensitivity values
#define GYRO_SENSITIVITY 0.005f // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025f // g/LSB

// Global variables
static int spi_handle;
static FILE *fp;
static volatile int running = 1;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
imu_data_t read_imu_data(int handle);
void log_data(FILE *fp, imu_data_t data);
void cleanup(int signum);

// Function to read a register from the ADIS16488A
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the command word (MSB = 0, 7-bit register address)
    tx_buf[0] = 0x00; // Read command
    tx_buf[1] = reg_addr << 1; // Register address (MSB = 0 for read)
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Function to write a register to the ADIS16488A
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the command word (MSB = 1, 7-bit register address)
    tx_buf[0] = 0x80; // Write command
    tx_buf[1] = reg_addr << 1; // Register address (MSB = 1 for write)
    tx_buf[2] = data & 0xFF; // LSB of data

    // Write the MSB of the data in a separate transaction
    char tx_buf_msb[3];
    char rx_buf_msb[3];
    tx_buf_msb[0] = 0x80; // Write command
    tx_buf_msb[1] = reg_addr << 1; // Register address (MSB = 1 for write)
    tx_buf_msb[2] = (data >> 8) & 0xFF; // MSB of data

    if (spiXfer(handle, tx_buf_msb, rx_buf_msb, 3) != 3) {
        fprintf(stderr, "SPI write error (MSB)\n");
        return -1;
    }

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI write error (LSB)\n");
        return -1;
    }

    return 0;
}

// Function to read IMU data from the ADIS16488A
imu_data_t read_imu_data(int handle) {
    imu_data_t data;
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    // Read gyroscope data
    if (spi_read_register(handle, REG_GYRO_XOUT, &raw_gyro_x) != 0) {
        data.gyro_x = 0.0f;
    } else {
        data.gyro_x = (float)((int16_t)raw_gyro_x) * GYRO_SENSITIVITY;
    }

    if (spi_read_register(handle, REG_GYRO_YOUT, &raw_gyro_y) != 0) {
        data.gyro_y = 0.0f;
    } else {
        data.gyro_y = (float)((int16_t)raw_gyro_y) * GYRO_SENSITIVITY;
    }

    if (spi_read_register(handle, REG_GYRO_ZOUT, &raw_gyro_z) != 0) {
        data.gyro_z = 0.0f;
    } else {
        data.gyro_z = (float)((int16_t)raw_gyro_z) * GYRO_SENSITIVITY;
    }

    // Read accelerometer data
    if (spi_read_register(handle, REG_ACCEL_XOUT, &raw_accel_x) != 0) {
        data.accel_x = 0.0f;
    } else {
        data.accel_x = (float)((int16_t)raw_accel_x) * ACCEL_SENSITIVITY;
    }

    if (spi_read_register(handle, REG_ACCEL_YOUT, &raw_accel_y) != 0) {
        data.accel_y = 0.0f;
    } else {
        data.accel_y = (float)((int16_t)raw_accel_y) * ACCEL_SENSITIVITY;
    }

    if (spi_read_register(handle, REG_ACCEL_ZOUT, &raw_accel_z) != 0) {
        data.accel_z = 0.0f;
    } else {
        data.accel_z = (float)((int16_t)raw_accel_z) * ACCEL_SENSITIVITY;
    }

    return data;
}

// Function to log IMU data to a CSV file
void log_data(FILE *fp, imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup function to be called on program termination
void cleanup(int signum) {
    running = 0;
    printf("Cleaning up...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (fp != NULL) {
        fclose(fp);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row to CSV file
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (running) {
        imu_data_t data = read_imu_data(spi_handle);
        log_data(fp, data);

        // Non-blocking delay
        int start_time = time(NULL);
        while (time(NULL) - start_time < 0.1 && running) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

