#define ADIS16448_REG_GYRO_YOUT 0x06
#define ADIS16448_REG_GYRO_ZOUT 0x08
#define ADIS16448_REG_ACCEL_XOUT 0x0A
#define ADIS16448_REG_ACCEL_YOUT 0x0C
#define ADIS16448_REG_ACCEL_ZOUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCEL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8 // GPIO8 (BCM)

int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a single register from ADIS16448
int16_t read_adis16448_register(int reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = (reg_addr | 0x80) & 0xFF; // Ensure bit 7 is set
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1; // Indicate error
    }

    // Combine the two bytes to form the 16-bit value
    return (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
}

