#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a single byte from an I2C register with retry
int read_register(int handle, uint8_t reg) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        }
        fprintf(stderr, "Error reading register 0x%02X: %s. Retrying...\n", reg, strerror(errno));
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register with retry
int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error writing to register 0x%02X: %s. Retrying...\n", reg, strerror(errno));
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    raw_accel_x = (read_register(handle, ACCEL_XOUT_H) << 8) | read_register(handle, ACCEL_XOUT_H + 1);
    raw_accel_y = (read_register(handle, ACCEL_XOUT_H + 2) << 8) | read_register(handle, ACCEL_XOUT_H + 3);
    raw_accel_z = (read_register(handle, ACCEL_XOUT_H + 4) << 8) | read_register(handle, ACCEL_XOUT_H + 5);

    // Read gyroscope data
    raw_gyro_x = (read_register(handle, GYRO_XOUT_H) << 8) | read_register(handle, GYRO_XOUT_H + 1);
    raw_gyro_y = (read_register(handle, GYRO_XOUT_H + 2) << 8) | read_register(handle, GYRO_XOUT_H + 3);
    raw_gyro_z = (read_register(handle, GYRO_XOUT_H + 4) << 8) | read_register(handle, GYRO_XOUT_H + 5);

    // Store the values
    *accel_x = raw_accel_x;
    *accel_y = raw_accel_y;
    *accel_z = raw_accel_z;
    *gyro_x = raw_gyro_x;
    *gyro_y = raw_gyro_y;
    *gyro_z = raw_gyro_z;

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6886
    if (write_register(i2c_handle, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

