#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <string.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_DEVID 0x00

// GPIO Pin for LED
#define LED_PIN 17

// Impact Threshold
#define IMPACT_THRESHOLD 2.5f

// Global Variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function Prototypes
int adxl345_init(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize ADXL345
int adxl345_init(int fd) {
    int retries = 3;
    while (retries > 0) {
        // Verify Device ID
        int device_id = wiringPiI2CReadReg8(fd, ADXL345_DEVID);
        if (device_id < 0) {
            fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
            retries--;
            delay(100); // Wait before retrying
            continue;
        }
        if (device_id != 0xE5) {
            fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0xE5)\n", device_id);
            retries--;
            delay(100); // Wait before retrying
            continue;
        }

        // Set Data Format: Full Resolution, ±2g range
        if (wiringPiI2CWriteReg8(fd, ADXL345_DATA_FORMAT, 0x0B) < 0) {
            fprintf(stderr, "Error setting data format: %s\n", strerror(errno));
            retries--;
            delay(100); // Wait before retrying
            continue;
        }

        // Set Power Control: Measurement Mode
        if (wiringPiI2CWriteReg8(fd, ADXL345_POWER_CTL, 0x08) < 0) {
            fprintf(stderr, "Error setting power control: %s\n", strerror(errno));
            retries--;
            delay(100); // Wait before retrying
            continue;
        }

        return 0; // Initialization successful
    }
    fprintf(stderr, "ADXL345 initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Read Acceleration Data
int read_acceleration(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    raw_x = (int16_t)((wiringPiI2CReadReg8(fd, ADXL345_DATAX0) << 8) | wiringPiI2CReadReg8(fd, ADXL345_DATAX0 + 1));
    raw_y = (int16_t)((wiringPiI2CReadReg8(fd, ADXL345_DATAY0) << 8) | wiringPiI2CReadReg8(fd, ADXL345_DATAY0 + 1));
    raw_z = (int16_t)((wiringPiI2CReadReg8(fd, ADXL345_DATAZ0) << 8) | wiringPiI2CReadReg8(fd, ADXL345_DATAZ0 + 1));

    if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Convert to g's (256 LSB/g)
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

// Calculate Magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log Impact Event
void log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
            timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Setup WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(ADXL345_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C setup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        return 1;
    }

    // Configure LED Pin
    pinMode(LED_PIN, OUTPUT);

    // Open Log File
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z, magnitude;

    printf("Monitoring accelerometer data... Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read Acceleration Data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Calculate Magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for Impact
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);

                // Turn on LED
                digitalWrite(LED_PIN, HIGH);
                delay(500);
                digitalWrite(LED_PIN, LOW);

                // Log Impact Event
                log_impact(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        delay(10); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    digitalWrite(LED_PIN, LOW); // Turn off LED

    printf("Program finished.\n");

    return 0;
}

