// Define constants
#define MMA8451Q_ADDRESS 0x1D
#define MMA8451Q_REG_STATUS 0x00
#define MMA8451Q_REG_OUT_X_MSB 0x01
#define MMA8451Q_REG_SYSMOD 0x0B
#define MMA8451Q_REG_ID 0x11
#define MMA8451Q_REG_CTRL_REG1 0x2A
#define MMA8451Q_REG_CTRL_REG2 0x2B
#define MMA8451Q_REG_CTRL_REG3 0x2C
#define MMA8451Q_REG_CTRL_REG4 0x2D
#define MMA8451Q_REG_XYZ_DATA_CFG 0x0E

#define LED_PIN 17 // BCM numbering
#define I2C_BUS 1

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int init_i2c(int bus, int address);
int init_gpio(int pin);
int init_mma8451q(int fd);
int read_mma8451q_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void control_led(int pin, int state);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize the I2C bus
int init_i2c(int bus, int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C bus %d at address 0x%02X: %s\n", bus, address, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize the GPIO pin
int init_gpio(int pin) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }
    pinMode(pin, OUTPUT);
    return 0;
}

// Function to initialize the MMA8451Q accelerometer
int init_mma8451q(int fd) {
    // Set to active mode and 800 Hz ODR
    if (wiringPiI2CWriteReg8(fd, MMA8451Q_REG_CTRL_REG1, 0x01) == -1) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set to +/- 2g range
    if (wiringPiI2CWriteReg8(fd, MMA8451Q_REG_XYZ_DATA_CFG, 0x00) == -1) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %s\n", strerror(errno));
        return -1;
    }

    // Verify sensor ID
    int id = wiringPiI2CReadReg8(fd, MMA8451Q_REG_ID);
    if (id == -1) {
        fprintf(stderr, "Error reading ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x2A) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_mma8451q_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    x_msb = wiringPiI2CReadReg8(fd, MMA8451Q_REG_OUT_X_MSB);
    x_lsb = wiringPiI2CReadReg8(fd, MMA8451Q_REG_OUT_X_MSB + 1);
    y_msb = wiringPiI2CReadReg8(fd, MMA8451Q_REG_OUT_X_MSB + 2);
    y_lsb = wiringPiI2CReadReg8(fd, MMA8451Q_REG_OUT_X_MSB + 3);
    z_msb = wiringPiI2CReadReg8(fd, MMA8451Q_REG_OUT_X_MSB + 4);
    z_lsb = wiringPiI2CReadReg8(fd, MMA8451Q_REG_OUT_X_MSB + 5);

    if (x_msb == -1 || x_lsb == -1 || y_msb == -1 || y_lsb == -1 || z_msb == -1 || z_lsb == -1) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log data to a file
void log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(int pin, int state) {
    digitalWrite(pin, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MMA8451Q_ADDRESS);
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(LED_PIN) == -1) {
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q(i2c_fd) == -1) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    accelerometer_data_t data;
    double magnitude;

    // Main loop
    while (running) {
        // Read accelerometer data
        if (read_mma8451q_data(i2c_fd, &data.x, &data.y, &data.z) == -1) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(data.x, data.y, data.z);

        // Check for impact
        if (magnitude > 2048.0) {
            printf("Impact detected! Magnitude: %.2f\n", magnitude);
            log_data(data.x, data.y, data.z, magnitude);
            control_led(LED_PIN, HIGH); // Turn on LED
            delay(500);
            control_led(LED_PIN, LOW);  // Turn off LED
        }

        delay(100); // Poll every 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    digitalWrite(LED_PIN, LOW); // Ensure LED is off

