#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5273 I2C address
#define TMAG5273_ADDR 0x0E

// TMAG5273 register addresses
#define TMAG5273_X_AXIS_REG 0x00
#define TMAG5273_Y_AXIS_REG 0x02
#define TMAG5273_Z_AXIS_REG 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, TMAG5273_ADDR, 0); // Bus 1, address 0x0E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from TMAG5273
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[6];

    // Read X, Y, and Z axis data (2 bytes each)
    if (i2cReadI2CBlockData(i2c_handle, TMAG5273_X_AXIS_REG, buf, 6) != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", i2c_handle);
        data.x = 0; // Set to 0 to indicate error
        data.y = 0;
        data.z = 0;
        return data;
    }

    // Combine the bytes to form 16-bit signed integers
    data.x = (int16_t)((buf[1] << 8) | buf[0]);
    data.y = (int16_t)((buf[3] << 8) | buf[2]);
    data.z = (int16_t)((buf[5] << 8) | buf[4]);

    return data;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("magnetic_field_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        if (data.x != 0 || data.y != 0 || data.z != 0) {
            log_data(data);
        }
        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

