#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32

// GPIO pin for interrupt
#define INTERRUPT_PIN 17

// Global variables
static int i2c_fd;
static int event_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int adxl345_init(int fd);
int adxl345_read_register(int fd, int reg);
int adxl345_write_register(int fd, int reg, int value);
int adxl345_read_acceleration(int fd, int *x, int *y, int *z);
void interrupt_handler(void);
void signal_handler(int signal);

// Function to initialize the ADXL345
int adxl345_init(int fd) {
    int devid;

    // Verify device ID
    devid = adxl345_read_register(fd, ADXL345_REG_DEVID);
    if (devid != 0xAD) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set to standby mode
    if (adxl345_write_register(fd, ADXL345_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set standby mode\n");
        return -1;
    }

    return 0;
}

// Function to read a register from the ADXL345
int adxl345_read_register(int fd, int reg) {
    int value = wiringPiI2CReadReg8(fd, reg);
    if (value == -1) {
        fprintf(stderr, "Error: Failed to read register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a register to the ADXL345
int adxl345_write_register(int fd, int reg, int value) {
    int result = wiringPiI2CWriteReg8(fd, reg, value);
    if (result == -1) {
        fprintf(stderr, "Error: Failed to write register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int fd, int *x, int *y, int *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = adxl345_read_register(fd, ADXL345_REG_DATAX0);
    x1 = adxl345_read_register(fd, ADXL345_REG_DATAX0 + 1);
    y0 = adxl345_read_register(fd, ADXL345_REG_DATAX0 + 2);
    y1 = adxl345_read_register(fd, ADXL345_REG_DATAX0 + 3);
    z0 = adxl345_read_register(fd, ADXL345_REG_DATAX0 + 4);
    z1 = adxl345_read_register(fd, ADXL345_REG_DATAX0 + 5);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0;
}

// Interrupt handler function
void interrupt_handler(void) {
    int x, y, z;
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    // Read acceleration data
    if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
        // Get current timestamp
        gettimeofday(&tv, NULL);
        tm_info = localtime(&tv.tv_sec);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        snprintf(timestamp + strlen(timestamp), 10, ".%03d", (int)(tv.tv_usec / 1000));

        // Write data to log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Failed to read acceleration data in interrupt handler\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main(void) {
    int ret;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = wiringPiI2CSetup(ADXL345_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: Failed to initialize ADXL345\n");
        close(i2c_fd);
        return 1;
    }

    // Set interrupt pin as input
    pinMode(INTERRUPT_PIN, INPUT);

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt
    ret = wiringPiISR(INTERRUPT_PIN, INT_EDGE_FALLING, interrupt_handler);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set up interrupt: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Poll the event file descriptor
        ret = poll(&event_fd, 1, 100); // Timeout of 100ms
        if (ret == -1) {
            fprintf(stderr, "Error: poll() failed: %s\n", strerror(errno));
            break;
        } else if (ret > 0) {
            // Interrupt occurred, interrupt_handler will be called
        }
    }

    // Clean up
    printf("Cleaning up...\n");

    // Disable interrupts
    adxl345_write_register(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00);

    // Close log file
    fclose(log_file);

    // Close I2C device
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

