    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // Bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configures the LSM6DSR sensor
int configure_sensor() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x69) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%X (expected 0x69)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: ±2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, ODR_104HZ | ACCEL_FS_2G) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: ±250 dps range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, ODR_104HZ | GYRO_FS_250DPS) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Reads accelerometer and gyroscope data from the sensor
int read_sensor_data(sensor_data_t *accel_data, sensor_data_t *gyro_data) {
    char buffer[12];

    // Read accelerometer data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Read gyroscope data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer + 6, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Convert raw data to g and dps
    accel_data->x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) / 16384.0f; // 16384 LSB/g for ±2g
    accel_data->y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) / 16384.0f;
    accel_data->z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) / 16384.0f;

    gyro_data->x = (float)((int16_t)(buffer[7] << 8 | buffer[6])) / 131.0f; // 131 LSB/dps for ±250 dps
    gyro_data->y = (float)((int16_t)(buffer[9] << 8 | buffer[8])) / 131.0f;
    gyro_data->z = (float)((int16_t)(buffer[11] << 8 | buffer[10])) / 131.0f;

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_acceleration_magnitude(sensor_data_t accel_data) {
    return sqrt(accel_data.x * accel_data.x + accel_data.y * accel_data.y + accel_data.z * accel_data.z);
}

// Logs the sensor data to a CSV file
void log_data(sensor_data_t accel_data, sensor_data_t gyro_data, float acceleration_magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, accel_data.x, accel_data.y, accel_data.z, gyro_data.x, gyro_data.y, gyro_data.z, acceleration_magnitude, (float)gpioTick() / 1000000.0);
    fflush(log_file); // Ensure data is written to file immediately
}

// Implements the fall detection state machine
void fall_detection(float acceleration_magnitude) {
    static int state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT
    static time_t freefall_start_time = 0;

    switch (state) {
        case 0: // IDLE
            if (acceleration_magnitude < FREEFALL_THRESHOLD) {
                state = 1; // Transition to FREEFALL
                freefall_start_time = time(NULL);
            }
            break;
        case 1: // FREEFALL
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                state = 2; // Transition to IMPACT
                printf("Impact detected!\n");
            } else if (difftime(time(NULL), freefall_start_time) > FREEFALL_WINDOW) {
                state = 0; // Transition back to IDLE if freefall window expires
                printf("Freefall window expired.\n");
            }
            break;
        case 2: // IMPACT
            state = 0; // Reset to IDLE after impact
            break;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z,Accel_Magnitude,Timestamp_us\n");
    }
    rewind(log_file);

    sensor_data_t accel_data, gyro_data;
    float acceleration_magnitude;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&accel_data, &gyro_data) == 0) {
            // Calculate acceleration magnitude
            acceleration_magnitude = calculate_acceleration_magnitude(accel_data);

            // Log the data
            log_data(accel_data, gyro_data, acceleration_magnitude);

            // Perform fall detection
            fall_detection(acceleration_magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Delay for approximately 104 Hz (1000000 / 104 = 9613 us)
        gpioDelay(9613); // Delay in microseconds
    }

    // Close the log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

