#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define WHO_AM_I 0x02
#define GYRO_XOUT_L 0x04
#define GYRO_XOUT_H 0x05

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define CS_PIN 8 // GPIO8 (CE0)

// Scale Factor
#define SCALE_FACTOR 0.0305f

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t address, uint16_t *data);
int spi_write_register(uint8_t address, uint16_t data);
float read_gyro_rate();
void log_data(float gyro_rate);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t address, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address & 0x7F; // Clear MSB for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Read Gyro Rate Function
float read_gyro_rate() {
    uint16_t raw_data;
    if (spi_read_register(GYRO_XOUT_L, &raw_data) != 0) {
        fprintf(stderr, "Error reading gyro rate\n");
        return 0.0f;
    }
    return (float)raw_data * SCALE_FACTOR;
}

// Log Data Function
void log_data(float gyro_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, gyro_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

// Initialization Function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Gyro Rate (deg/s)\n");
    }

    // Verify WHO_AM_I register
    uint16_t who_am_i;
    if (spi_read_register(WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    if (who_am_i != 0x56) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%02X\n", who_am_i);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    printf("ADIS16266 WHO_AM_I check passed: 0x%02X\n", who_am_i);

    return 0;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        float gyro_rate = read_gyro_rate();
        log_data(gyro_rate);
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

