#include <string.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 8.75f // mdps/LSB
#define SAMPLE_RATE_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Set CTRL_REG1 to 0x0F (Normal mode, all axes enabled, 100Hz ODR)
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status == 0) break;
        fprintf(stderr, "Error writing to CTRL_REG1, retrying... (%d retries left)\n", retries);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Set CTRL_REG4 to 0x00 (250 dps full scale)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status == 0) break;
        fprintf(stderr, "Error writing to CTRL_REG4, retrying... (%d retries left)\n", retries);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;
    int status;
    int retries = 3;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buf, 6);
        if (status == 6) break;
        fprintf(stderr, "Error reading gyro data, retrying... (%d retries left)\n", retries);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read gyro data after multiple retries.\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / 114.285f;
    *y = (float)raw_y / 114.285f;
    *z = (float)raw_z / 114.285f;

    return 0;
}

// Log data to CSV file
void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error reading WHO_AM_I register or incorrect value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("WHO_AM_I register verified successfully.\n");

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }
        gpioDelay(SAMPLE_RATE_MS * 1000); // Sample every 10ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

