#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the GPIO level
        gpio_status = gpioRead(FLAME_SENSOR_GPIO);

        if (gpio_status == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            fprintf(log_file, "ERROR: Failed to read GPIO %d\n", FLAME_SENSOR_GPIO);
            fflush(log_file);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event
            if (gpio_status == 0) {
                fprintf(log_file, "%s – Flame detected: YES\n", timestamp);
                fflush(log_file);
                printf("FLAME DETECTED!\n");
            } else {
                fprintf(log_file, "%s – Flame detected: NO\n", timestamp);
                fflush(log_file);
            }
        }

        // Wait for 500ms
        gpioDelay(500);
    }

    // Cleanup and exit
    printf("Closing log file...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

