#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C

// Define the register addresses for X, Y, and Z axis data
#define REG_X_LSB 0x02
#define REG_X_MSB 0x03
#define REG_Y_LSB 0x04
#define REG_Y_MSB 0x05
#define REG_Z_LSB 0x06
#define REG_Z_MSB 0x07

// Define the sensor-absent condition (example value)
#define SENSOR_ABSENT_VALUE 0xFFFF

// Global variables for I2C handle and file pointer
int i2c_handle;
FILE *log_file;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
char* get_iso8601_timestamp();
int write_data_to_file(const char *timestamp, int16_t x, int16_t y, int16_t z);
void handle_error(const char *message);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        handle_error("Failed to open vibration_log.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    sensor_data_t sensor_data;
    while (1) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Get the current timestamp
            char *timestamp = get_iso8601_timestamp();

            // Write the data to the file
            if (write_data_to_file(timestamp, sensor_data.x, sensor_data.y, sensor_data.z) != 0) {
                handle_error("Failed to write data to file");
            }

            free(timestamp); // Free the allocated timestamp memory
        } else {
            handle_error("Failed to read sensor data");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    return 0;
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Function to read sensor data from the D7S-0001
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;

    // Read X, Y, and Z axis data
    result = i2cReadI2CBlockData(i2c_handle, REG_X_LSB, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return 1;
    }

    // Combine LSB and MSB for each axis
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    // Check for sensor-absent condition
    if (*x == SENSOR_ABSENT_VALUE && *y == SENSOR_ABSENT_VALUE && *z == SENSOR_ABSENT_VALUE) {
        fprintf(stderr, "Sensor absent condition detected\n");
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to write data to the CSV file
int write_data_to_file(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
        return 1;
    }
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

