#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_sensor_data(int sensor1_state, int sensor2_state);
void handle_halt_condition(int sensor1_state, int sensor2_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("conveyor_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop to continuously monitor the sensors
    while (program_running) {
        // Read the state of both sensors
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log the sensor data
        if (log_sensor_data(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging sensor data.\n");
        }

        // Check for the halt condition
        handle_halt_condition(sensor1_state, sensor2_state);

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log the sensor data to a file
