#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x00
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define DATA_RATE 0x01 // 100 Hz
#define TILT_THRESHOLD 45.0
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor();
int configure_sensor();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify sensor identity
int verify_sensor() {
    char who_am_i;
    int result = i2cReadByteData(i2c_fd, WHO_AM_I_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    who_am_i = (char)result;

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x2A)\n", who_am_i);
        return -1;
    }

    printf("Sensor verification successful. WHO_AM_I = 0x%02X\n", who_am_i);
    return 0;
}

// Configure the sensor
int configure_sensor() {
    // Standby mode
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, DATA_RATE) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (data rate): %s\n", strerror(errno));
        return -1;
    }

    // Enable active mode
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, DATA_RATE | 0x02) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active mode): %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor configuration successful.\n");
    return 0;
}

// Read raw accelerometer data
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_fd, OUT_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[0] << 4) | (buffer[1] >> 4));
    *y = (int16_t)((buffer[2] << 4) | (buffer[3] >> 4));
    *z = (int16_t)((buffer[4] << 4) | (buffer[5] >> 4));

    return 0;
}

// Calculate tilt angle
double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_rad = atan2(x, sqrt(y * y + z * z));
    double tilt_deg = x_rad * 180 / M_PI;
    return tilt_deg;
}

// Log fall event
int log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);

    printf("Fall logged: %s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() < 0) {
        i2cClose(i2c_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double tilt;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&x, &y, &z) == 0) {
            // Calculate tilt
            tilt = calculate_tilt(x, y, z);

            // Check for fall event
            if (fabs(tilt) > TILT_THRESHOLD) {
                log_fall(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

