#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration parameters
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detection threshold (mG)
#define METAL_THRESHOLD 800.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
magnetometer_data_t calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z);
float calculate_magnitude(magnetometer_data_t data);
void write_to_log(magnetometer_data_t data);
void check_metal_detection(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the LIS3MDL magnetometer
int configure_magnetometer() {
    int retries = 3;
    int status;

    // Set output data rate to 10 Hz and enable continuous conversion
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); // 0x70 = 0b01110000
        if (status >= 0) break;
        fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
        gpioDelay(100000); // 100ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00); // 0x00 = +/- 4 gauss
        if (status >= 0) break;
        fprintf(stderr, "Error writing to CTRL_REG3, retrying...\n");
        gpioDelay(100000); // 100ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG3 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read raw magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;
    int retries = 3;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L | 0x80, buffer, 6); // Read multiple bytes with auto-increment
        if (status == 6) break;
        fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        gpioDelay(100000); // 100ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read magnetometer data after multiple retries.\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate raw data using offset and scale
magnetometer_data_t calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    magnetometer_data_t calibrated_data;
    calibrated_data.x = (float)raw_x * X_SCALE + X_OFFSET;
    calibrated_data.y = (float)raw_y * Y_SCALE + Y_OFFSET;
    calibrated_data.z = (float)raw_z * Z_SCALE + Z_OFFSET;
    return calibrated_data;
}

// Calculate the magnitude of the magnetic field vector
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Write data to log file
void write_to_log(magnetometer_data_t data) {
    fprintf(log_file, "%.3f,%.3f,%.3f\n", data.x, data.y, data.z);
    fflush(log_file);
}

// Check for metal detection
void check_metal_detection(float magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.3f mG\n", magnitude);
    }
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    magnetometer_data_t calibrated_data;
    float magnitude;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate data
            calibrated_data = calibrate_data(raw_x, raw_y, raw_z);

