FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(uint8_t reg_addr, uint8_t data);
int adxl354b_reset();
int adxl354b_verify_partid();
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Read Function with Retry
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    int retries = 3;

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    memset(rx_buf, 0, sizeof(rx_buf));
    memset(tx_buf + 1, 0, len); // Pad with zeros for reading

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) == 0) {
            memcpy(data, rx_buf + 1, len);
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read failed, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Failure
}

// SPI Write Function with Retry
int spi_write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 3;

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI write failed, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "SPI write failed after multiple retries.\n");
    return -1; // Failure
}

// ADXL354B Reset Function
int adxl354b_reset() {
    if (spi_write_register(ADXL354B_RESET_REG, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Verify Part ID Function
int adxl354b_verify_partid() {
    uint8_t partid;
    if (spi_read_register(ADXL354B_PARTID_REG, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID.\n");
        return -1;
    }

    if (partid != 0xAD) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    printf("PARTID verified: 0x%02X\n", partid);
    return 0;
}

