// ADIS16362 Register Addresses
#define ADIS16362_REG_XGYRO_OUT 0x04
#define ADIS16362_REG_YGYRO_OUT 0x06
#define ADIS16362_REG_ZGYRO_OUT 0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05f
#define ACCEL_SCALE 0.0025f

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE_PIN 8 // BCM
#define SPI_BAUD_RATE 1000000
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Function prototypes
int initialize_spi();
int read_register(uint8_t address, uint16_t *data);
int write_register(uint8_t address, uint16_t data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD_RATE, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Reads data from a specific register
int read_register(uint8_t address, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error reading from SPI\n");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Writes data to a specific register
int write_register(uint8_t address, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data & 0xFF; // LSB of data

