#include <time.h>
#include <string.h>

#define GPIO_PIN 17
#define CHIP_NUMBER 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int pigpio_init_result;
    int gpio_mode_result;
    int gpio_read_result;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO17 as input
    gpio_mode_result = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_mode_result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", GPIO_PIN, gpio_mode_result);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the sensor value
        gpio_read_result = gpioRead(GPIO_PIN);
        if (gpio_read_result < 0) {
            fprintf(stderr, "Failed to read GPIO%d: %d\n", GPIO_PIN, gpio_read_result);
            break; // Exit loop on read error
        }

        // Check if obstacle is detected (LOW signal)
        if (gpio_read_result == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log obstacle detection
            printf("[%s] Self-parking sequence started\n", timestamp);

            // Simulate self-parking routine
            printf("Simulating self-parking routine...\n");
            gpioDelay(2000); // Simulate 2 seconds

            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log self-parking completion
            printf("[%s] Self-parking sequence completed\n", timestamp);

            // Wait for a while before checking again
            gpioDelay(5000); // Wait 5 seconds
        } else {
            // No obstacle detected, wait before next check
            gpioDelay(1000); // Wait 1 second
        }
    }

    // Clean up and exit
    gpioTerminate();
    printf("Self-parking system stopped.\n");
    return 0;
}

