#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR1_PIN);
    int sensor2_value = gpioRead(SENSOR2_PIN);
    return (sensor1_value << 1) | sensor2_value; // Combine into a single integer
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int sensor_data) {
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Get current time
    time(&current_time);
    time_info = localtime(&current_time);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    // Print the sensor data with the timestamp
    printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
           (sensor_data & 1) ? "Clear" : "Obstacle",
           (sensor_data & 2) ? "Clear" : "Obstacle");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the sensor values
        int sensor_data = read_sensors();

        // Log the sensor data
        log_sensor_data(sensor_data);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

