#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CS_PIN 8 // GPIO8 (BCM)

// Scale Factor
#define SCALE_FACTOR 0.02 // degrees/second per LSB

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t address, int16_t *data);
float convert_to_degrees_per_second(int16_t raw_data);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(uint8_t address, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Set MSB of address for read operation
    tx_buf[0] = address | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading MSB
    tx_buf[2] = 0x00; // Dummy byte for reading LSB

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Combine MSB and LSB to form the 16-bit data
    *data = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    return 0;
}

// Convert to Degrees per Second Function
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data * SCALE_FACTOR;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);
    gpioWrite(SPI_CS_PIN, 1); // Deactivate CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Reading ADIS16266 gyroscope data...\n");

    while (!terminate) {
        int16_t x_raw, y_raw, z_raw;
        float x_deg_sec, y_deg_sec, z_deg_sec;

        // Read gyroscope data
        if (spi_read_register(ADIS16266_XGYRO_OUT, &x_raw) != 0) {
            fprintf(stderr, "Failed to read X gyroscope data\n");
            continue; // Skip to the next iteration
        }
        if (spi_read_register(ADIS16266_YGYRO_OUT, &y_raw) != 0) {
            fprintf(stderr, "Failed to read Y gyroscope data\n");
            continue;
        }
        if (spi_read_register(ADIS16266_ZGYRO_OUT, &z_raw) != 0) {
            fprintf(stderr, "Failed to read Z gyroscope data\n");
            continue;
        }

        // Convert to degrees per second
        x_deg_sec = convert_to_degrees_per_second(x_raw);
        y_deg_sec = convert_to_degrees_per_second(y_raw);
        z_deg_sec = convert_to_degrees_per_second(z_raw);

        // Print the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_deg_sec, y_deg_sec, z_deg_sec);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

