// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_REG_STATUS 0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_ID 0x0D
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_M_CTRL_REG1 0x5B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to initialize the FXOS8700 sensor
int initialize_sensor(int handle) {
    // Check device ID
    int id = read_register(handle, FXOS8700_REG_ID);
    if (id != 0xC7) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", id);
        return -1;
    }
    printf("FXOS8700 device ID: 0x%02X\n", id);

    // Set accelerometer to active mode, 100 Hz ODR
    if (write_register(handle, FXOS8700_REG_CTRL_REG1, 0x01) != 0) {
        return -1;
    }

    // Set magnetometer to hybrid mode, 8-average
    if (write_register(handle, FXOS8700_REG_M_CTRL_REG1, 0x18) != 0) {
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buffer, 12);
        if (result == 12) {
            // Combine bytes to form 14-bit accelerometer data
            *accel_x = (int16_t)((buffer[0] << 6) | (buffer[1] >> 2));
            *accel_y = (int16_t)((buffer[2] << 6) | (buffer[3] >> 2));
            *accel_z = (int16_t)((buffer[4] << 6) | (buffer[5] >> 2));

            // Combine bytes to form 16-bit magnetometer data
            *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
            *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
            *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data: %d. Retrying...\n", result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Indicate failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            // Print sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

