#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_S 5
#define PAUSE_DURATION_S 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Monitoring sound sensor on GPIO%d with threshold %d...\n", GPIO_PIN, threshold);

    while (program_running) {
        high_count = 0;
        time_t start_time = time(NULL);

        while (program_running && (time(NULL) - start_time) < WINDOW_DURATION_S) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
        }

        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        if (high_count > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s Status: %d high readings\n", timestamp, high_count);
        }

        gpioDelay(PAUSE_DURATION_S * 1000000); // pigpioDelay takes microseconds
    }

    gpioTerminate();
    return 0;
}

