#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27
#define UNLOCK_DURATION 5 // seconds
#define CODE_LENGTH 6

volatile sig_atomic_t program_running = 1;

// Function to generate a random six-digit code
int generate_code() {
    return (rand() % 900000) + 100000;
}

// Function to unlock a door for a specified duration
void unlock_door(int gpio_pin, int duration_seconds) {
    gpioWrite(gpio_pin, 1); // Activate relay (UNLOCK)
    gpioDelay(duration_seconds * 1000000); // Delay for specified duration (microseconds)
    gpioWrite(gpio_pin, 0); // Deactivate relay (LOCK)
}

// Function to log access to a file
void log_access(int code) {
    FILE *fp = fopen("access_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening access_log.txt for writing!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%06d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, code);
    fclose(fp);
}

// Function to handle user input and compare with the code
int handle_user_input(int code) {
    char input[CODE_LENGTH + 1];
    int entered_code;

    printf("Enter the code: ");
    if (fgets(input, sizeof(input), stdin) == NULL) {
        fprintf(stderr, "Error reading input!\n");
        return 0; // Indicate failure
    }

    // Remove trailing newline character
    input[strcspn(input, "\n")] = 0;

    entered_code = atoi(input);

    if (entered_code == code) {
        printf("Access granted!\n");
        return 1; // Indicate success
    } else {
        printf("Access denied!\n");
        return 0; // Indicate failure
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed!\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Set initial state to LOW (locked)
    gpioWrite(DOOR_A_GPIO, 0);
    gpioWrite(DOOR_B_GPIO, 0);

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Generate a random code
        int code = generate_code();
        printf("Generated code: %d\n", code);

        // Unlock Door A
        printf("Unlocking Door A...\n");
        unlock_door(DOOR_A_GPIO, UNLOCK_DURATION);

        // Handle user input for Door A
        if (handle_user_input(code)) {
            // Log access
            log_access(code);
        }

        // Unlock Door B
        printf("Unlocking Door B...\n");
        unlock_door(DOOR_B_GPIO, UNLOCK_DURATION);

        // Handle user input for Door B
        if (handle_user_input(code)) {
            // Log access
            log_access(code);
        }
    }

    // Cleanup
    gpioWrite(DOOR_A_GPIO, 0); // Lock Door A
    gpioWrite(DOOR_B_GPIO, 0); // Lock Door B
    gpioTerminate();

    printf("Door access control system stopped.\n");
    return 0;
}

