#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_CONVERSION_TIME_US 180000 // 180 ms
#define LOG_FILE "light_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
float read_lux();
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    int bus;
    int address;
    int mode;
} sensor_config_t;


// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure BH1750FVI sensor
int configure_sensor() {
    int result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Error configuring sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750FVI sensor
float read_lux() {
    int raw_value;
    int retries = 3;

    while (retries > 0) {
        raw_value = i2cReadWordData(i2c_handle, 0x00);
        if (raw_value >= 0) {
            // Success, break the retry loop
            break;
        } else {
            fprintf(stderr, "Error reading sensor data: %d, retries remaining: %d\n", raw_value, retries);
            gpioDelay(10000); // Wait 10ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        return -1.0; // Indicate error
    }

    // Convert raw value to lux
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    printf("Light sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

