    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    printf("Light sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
