#define PWM_RANGE 1000
#define TCP_PORT 12345
#define AUTH_SECRET "MySecretKey"
#define AUTH_STRING "MOTION_DETECTED:"
#define AUTH_STRING_LEN (sizeof(AUTH_STRING) - 1)
#define AUTH_SECRET_LEN (sizeof(AUTH_SECRET) - 1)
#define AUTH_STRING_SECRET_LEN (AUTH_STRING_LEN + AUTH_SECRET_LEN + 1) // +1 for space
#define SAMPLE_PERIOD_MS 20
#define PLAYBACK_DURATION_S 5
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int tcp_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_data(unsigned short *touch_data);
int authenticate_command(const char *command);
void play_tone(int frequency);
void log_frequency(int frequency);
void signal_handler(int signal);

// MPR121 Initialization
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        perror("Error: MPR121 soft reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode 0 to touch mode
        perror("Error: MPR121 Electrode 0 config failed");
        return -1;
    }

    // Configure Electrode 1
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0C) < 0) { // Set Electrode 1 to touch mode
        perror("Error: MPR121 Electrode 1 config failed");
        return -1;
    }

    // Configure Electrode 2
    if (i2cWriteByteData(i2c_handle, 0x60, 0x0C) < 0) { // Set Electrode 2 to touch mode
        perror("Error: MPR121 Electrode 2 config failed");
        return -1;
    }

    // Configure Electrode 3
    if (i2cWriteByteData(i2c_handle, 0x61, 0x0C) < 0) { // Set Electrode 3 to touch mode
        perror("Error: MPR121 Electrode 3 config failed");
        return -1;
    }

    // Configure Electrode 4
    if (i2cWriteByteData(i2c_handle, 0x62, 0x0C) < 0) { // Set Electrode 4 to touch mode
        perror("Error: MPR121 Electrode 4 config failed");
        return -1;
    }

    // Configure Electrode 5
    if (i2cWriteByteData(i2c_handle, 0x63, 0x0C) < 0) { // Set Electrode 5 to touch mode
        perror("Error: MPR121 Electrode 5 config failed");
        return -1;
    }

    // Configure Electrode 6
    if (i2cWriteByteData(i2c_handle, 0x64, 0x0C) < 0) { // Set Electrode 6 to touch mode
        perror("Error: MPR121 Electrode 6 config failed");
        return -1;
    }

    // Configure Electrode 7
    if (i2cWriteByteData(i2c_handle, 0x65, 0x0C) < 0) { // Set Electrode 7 to touch mode
        perror("Error: MPR121 Electrode 7 config failed");
        return -1;
    }

    // Configure Electrode 8
    if (i2cWriteByteData(i2c_handle, 0x66, 0x0C) < 0) { // Set Electrode 8 to touch mode
        perror("Error: MPR121 Electrode 8 config failed");
        return -1;
    }

    // Configure Electrode 9
    if (i2cWriteByteData(i2c_handle, 0x67, 0x0C) < 0) { // Set Electrode 9 to touch mode
        perror("Error: MPR121 Electrode 9 config failed");
        return -1;
    }

    // Configure Electrode 10
    if (i2cWriteByteData(i2c_handle, 0x68, 0x0C) < 0) { // Set Electrode 10 to touch mode
        perror("Error: MPR121 Electrode 10 config failed");
        return -1;
    }

    // Configure Electrode 11
    if (i2cWriteByteData(i2c_handle, 0x69, 0x0C) < 0) { // Set Electrode 11 to touch mode
        perror("Error: MPR121 Electrode 11 config failed");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        perror("Error: MPR121 enable electrodes failed");
        return -1;
    }

    return 0;
}

// MPR121 Read Touch Data
int mpr121_read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        perror("Error: MPR121 read touch data failed");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Authenticate Command
int authenticate_command(const char *command) {
    if (strncmp(command, AUTH_STRING, AUTH_STRING_LEN) == 0) {
        char expected_secret[AUTH_SECRET_LEN];
        snprintf(expected_secret, AUTH_SECRET_LEN, "%s %s", AUTH_STRING, AUTH_SECRET);
        if (strncmp(command + AUTH_STRING_LEN, expected_secret, AUTH_SECRET_LEN) == 0) {
            return 1; // Authenticated
        }
    }
    return 0; // Not authenticated
