    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM GPIO as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);

    // Open TCP socket
    tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_socket < 0) {
        perror("Error: Socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to port
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(tcp_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error: Socket bind failed");
        close(tcp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(tcp_socket, 1) < 0) {
        perror("Error: Socket listen failed");
        close(tcp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Log file open failed");
        close(tcp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Server listening on port %d...\n", TCP_PORT);

    while (!terminate) {
        // Accept connection
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(tcp_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            perror("Error: Socket accept failed");
            continue; // Continue listening
        }

        printf("Connection accepted\n");

        char buffer[1024];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received: %s\n", buffer);

            if (authenticate_command(buffer)) {
                printf("Command authenticated\n");

                unsigned short touch_data;
                if (mpr121_read_touch_data(&touch_data) == 0) {
                    int frequency = 0;
                    if (touch_data & (1 << 0)) {
                        frequency = 200;
                    } else if (touch_data & (1 << 1)) {
                        frequency = 400;
                    } else if (touch_data & (1 << 2)) {
                        frequency = 800;
                    } else if (touch_data & (1 << 3)) {
                        frequency = 1600;
                    } else if (touch_data & (1 << 4)) {
                        frequency = 3200;
                    } else if (touch_data & (1 << 5)) {
                        frequency = 6400;
                    } else if (touch_data & (1 << 6)) {
                        frequency = 12800;
                    } else if (touch_data & (1 << 7)) {
                        frequency = 25600;
                    } else if (touch_data & (1 << 8)) {
                        frequency = 51200;
                    } else if (touch_data & (1 << 9)) {
                        frequency = 102400;
                    } else if (touch_data & (1 << 10)) {
                        frequency = 204800;
                    } else if (touch_data & (1 << 11)) {
                        frequency = 409600;
                    }

                    if (frequency > 0) {
                        printf("Playing tone at %d Hz\n", frequency);
                        play_tone(frequency);
                        log_frequency(frequency);

                        gpioDelay(PLAYBACK_DURATION_S * 1000); // Play for 5 seconds
                        gpioPWM(PWM_GPIO, 0); // Stop PWM
                    } else {
                        printf("No touch detected, skipping tone\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to read touch data\n");
                }
            } else {
                printf("Command rejected\n");
            }
        } else if (bytes_received == 0) {
            printf("Client disconnected\n");
        } else {
            perror("Error: Receive failed");
        }

        close(client_socket);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    i2cClose(i2c_handle);
    close(tcp_socket);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

