                    } else if (touch_data & (1 << 9)) {
                        frequency = 102400;
                    } else if (touch_data & (1 << 10)) {
                        frequency = 204800;
                    } else if (touch_data & (1 << 11)) {
                        frequency = 409600;
                    }

                    if (frequency > 0) {
                        printf("Playing tone at %d Hz\n", frequency);
                        play_tone(frequency);
                        log_frequency(frequency);

                        gpioDelay(PLAYBACK_DURATION_S * 1000); // Play for 5 seconds
                        gpioPWM(PWM_GPIO, 0); // Stop PWM
                    } else {
                        printf("No touch detected, skipping tone\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to read touch data\n");
                }
            } else {
                printf("Command rejected\n");
            }
        } else if (bytes_received == 0) {
            printf("Client disconnected\n");
        } else {
            perror("Error: Receive failed");
        }

        close(client_socket);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    i2cClose(i2c_handle);
    close(tcp_socket);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

