// LSM303DLHC Magnetometer I2C Address
#define LSM303_ADDRESS 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_OUT_X_L_M 0x08
#define LSM303_OUT_X_H_M 0x09
#define LSM303_OUT_Y_L_M 0x0A
#define LSM303_OUT_Y_H_M 0x0B
#define LSM303_OUT_Z_L_M 0x0C
#define LSM303_OUT_Z_H_M 0x0D
#define LSM303_CTRL_REG1_M 0x20

// GPIO Pin for LED (BCM numbering)
#define LED_PIN 17

// PWM Frequency (Hz)
#define PWM_FREQUENCY 1000

// Global Variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_i2c(int address);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_z_magnitude(int16_t z);
void set_led_brightness(int brightness);
void log_error(const char *message);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        perror("wiringPiI2CSetup failed");
        return -1;
    }

    // Enable magnetometer (Continuous conversion mode)
    if (wiringPiI2CWriteReg8(fd, LSM303_CTRL_REG1_M, 0x70) == -1) {
        perror("Failed to write to CTRL_REG1_M");
        return -1;
    }

    return fd;
}

// Read Magnetometer Data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = wiringPiI2CReadReg8(fd, LSM303_OUT_X_L_M);
    x_h = wiringPiI2CReadReg8(fd, LSM303_OUT_X_H_M);
    y_l = wiringPiI2CReadReg8(fd, LSM303_OUT_Y_L_M);
    y_h = wiringPiI2CReadReg8(fd, LSM303_OUT_Y_H_M);
    z_l = wiringPiI2CReadReg8(fd, LSM303_OUT_Z_L_M);
    z_h = wiringPiI2CReadReg8(fd, LSM303_OUT_Z_H_M);

    if (x_l == -1 || x_h == -1 || y_l == -1 || y_h == -1 || z_l == -1 || z_h == -1) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Calculate Z-axis Magnitude
float calculate_z_magnitude(int16_t z) {
    return (float)z; // Raw Z-axis value
}

// Set LED Brightness using PWM
void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 1023) brightness = 1023;

    pwmWrite(LED_PIN, brightness);
}

// Log Error to File
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(LSM303_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Open Log File
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Set LED Pin to PWM Output Mode
    pinMode(LED_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(192); // Adjust clock for desired frequency
    pwmSetRange(1024); // Adjust range for desired resolution

    // Set PWM Frequency
    pwmSetRange(1024); // Adjust range for desired resolution
    pwmSetClock(192); // Adjust clock for desired frequency

    // Register Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float z_magnitude;
    int brightness;

    // Main Loop
    while (program_running) {
        // Read Magnetometer Data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate Z-axis Magnitude
            z_magnitude = calculate_z_magnitude(z);

            // Map Z-axis Magnitude to LED Brightness (0-1023)
            brightness = (int)(z_magnitude * 1023.0 / 1000.0); // Assuming max magnitude is 1000

            // Set LED Brightness
            set_led_brightness(brightness);
        } else {
            log_error("Failed to read magnetometer data, skipping PWM update.");
        }

        // Delay for 100ms
        delay(100);
    }

    // Cleanup
    pwmWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

