#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} hard_iron_offsets_t;

// Circular buffer for storing magnetometer readings
#define BUFFER_SIZE 100
magnetometer_data_t data_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int configure_hmc5883l();
magnetometer_data_t read_magnetometer_data();
hard_iron_offsets_t calculate_hard_iron_offsets();
magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t raw_data, hard_iron_offsets_t offsets);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the HMC5883L
int configure_hmc5883l() {
    // Configuration register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configuration register B: Gain = 5
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Calculate hard-iron offsets
hard_iron_offsets_t calculate_hard_iron_offsets() {
    hard_iron_offsets_t offsets;
    long long x_sum = 0, y_sum = 0, z_sum = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        x_sum += data_buffer[i].x;
        y_sum += data_buffer[i].y;
        z_sum += data_buffer[i].z;
    }

    offsets.x_offset = (float)x_sum / BUFFER_SIZE;
    offsets.y_offset = (float)y_sum / BUFFER_SIZE;
    offsets.z_offset = (float)z_sum / BUFFER_SIZE;

    return offsets;
}

// Apply hard-iron offsets to raw data
magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t raw_data, hard_iron_offsets_t offsets) {
    magnetometer_data_t corrected_data;
    corrected_data.x = raw_data.x - offsets.x_offset;
    corrected_data.y = raw_data.y - offsets.y_offset;
    corrected_data.z = raw_data.z - offsets.z_offset;
    return corrected_data;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure HMC5883L
    if (configure_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Store data in circular buffer
        data_buffer[buffer_index] = raw_data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Calculate hard-iron offsets
        hard_iron_offsets_t offsets = calculate_hard_iron_offsets();

        // Apply offsets and print corrected data
        magnetometer_data_t corrected_data = apply_hard_iron_offsets(raw_data, offsets);
        printf("X: %d, Y: %d, Z: %d\n", corrected_data.x, corrected_data.y, corrected_data.z);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

