#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define INT1_CFG_A 0x30
#define INT1_THS_A 0x32
#define INT1_DURATION_A 0x33

// GPIO pin for INT1 interrupt
#define INT1_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x, y, z;
} acceleration_data_t;

// Circular buffer
acceleration_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int initialize_lsm303d();
acceleration_data_t read_acceleration_data();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void dump_buffer();
void signal_handler(int signal);

