volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize LSM303D
    if (initialize_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set INT1 pin as input
    gpioSetMode(INT1_PIN, PI_INPUT);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INT1_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    printf("LSM303D monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read acceleration data
        acceleration_data_t data = read_acceleration_data();

        // Store data in circular buffer
        buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Delay for approximately 10ms (100Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Disable accelerometer
    i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x00);

    // Close I2C file descriptor
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("LSM303D monitor stopped.\n");

    return 0;
}

// Function to initialize the LSM303D
int initialize_lsm303d() {
    // Open I2C device
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Verify device identity (optional, but good practice)
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F); // WHO_AM_I register
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return 1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        i2cClose(i2c_handle);
        return 1;
    }

    // Configure accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) { // Enable all axes, 100Hz ODR
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        i2cClose(i2c_handle);
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) { // +/- 2g range
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        i2cClose(i2c_handle);
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, INT1_CFG_A, 0x2A) < 0) { // Enable interrupt on any axis exceeding threshold
        fprintf(stderr, "Failed to write to INT1_CFG_A\n");
        i2cClose(i2c_handle);
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, INT1_THS_A, 0x3F) < 0) { // Set threshold to 2000mg (0x3F)
        fprintf(stderr, "Failed to write to INT1_THS_A\n");
        i2cClose(i2c_handle);
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, INT1_DURATION_A, 0x00) < 0) { // Set duration to 0 (immediate trigger)
        fprintf(stderr, "Failed to write to INT1_DURATION_A\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Function to read acceleration data from the LSM303D
acceleration_data_t read_acceleration_data() {
    acceleration_data_t data;
    char raw_data[6];

    // Read 6 bytes of data (X, Y, Z axes)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, raw_data, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on failure
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    data.y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    data.z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return data;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    dump_buffer();
}

// Function to dump the contents of the circular buffer to the console
void dump_buffer() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Interrupt triggered!\n", timestamp);

    int start_index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE; // Calculate starting index
    for (int i = 0; i < 10; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        printf("  %d: X=%6d, Y=%6d, Z=%6d\n", i + 1, buffer[index].x, buffer[index].y, buffer[index].z);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

