    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SOLENOID_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SOLENOID_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set both GPIOs to LOW initially
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Activate solenoid 1
        gpioWrite(SOLENOID_1_GPIO, 1);
        gpioWrite(SOLENOID_2_GPIO, 0);
        nanosleep(NULL, 500000000); // 500ms

        // Activate solenoid 2
        gpioWrite(SOLENOID_1_GPIO, 0);
        gpioWrite(SOLENOID_2_GPIO, 1);
        nanosleep(NULL, 500000000); // 500ms
    }

    // Cleanup before exiting
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);
    gpioTerminate();

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

