// Global variables for UART handles
int uart1_handle = -1;
int uart2_handle = -1;

// Function prototypes
int initialize_gpio();
int initialize_uart(const char *port);
int read_code(int uart_handle, char *code, int code_length);
int compare_codes(const char *code1, const char *code2);
int control_relay(int gpio_pin, int state);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int uart1_handle;
    int uart2_handle;
    int relay1_gpio;
    int relay2_gpio;
    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];
} ProgramState;

ProgramState state;

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize a UART port
int initialize_uart(const char *port) {
    int handle = serOpen(port, 9600, 0); // 9600 baud, 8N1
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART port %s: %d\n", port, handle);
        return -1;
    }
    return handle;
}

// Function to read a code from a UART port
int read_code(int uart_handle, char *code, int code_length) {
    int i = 0;
    char c;
    long start_time = time(NULL);

    while (i < code_length) {
        if (serDataAvailable(uart_handle) > 0) {
            c = serReadByte(uart_handle);
            if (c >= '0' && c <= '9') {
                code[i++] = c;
            } else {
                // Reset the buffer if a non-digit character is received
                i = 0;
                code[0] = '\0'; // Ensure null termination
                fprintf(stderr, "Invalid character received on UART %d\n", uart_handle);
                return -1; // Indicate failure
            }
        } else {
            // Check for timeout
            if (time(NULL) - start_time > TIMEOUT_SECONDS) {
                fprintf(stderr, "Timeout reading from UART %d\n", uart_handle);
                return -1; // Indicate timeout
            }
            gpioDelay(100); // Small delay to avoid busy-waiting
        }
    }

    code[i] = '\0'; // Null-terminate the string
    return 0; // Indicate success
}

// Function to compare two codes using constant-time string comparison
int compare_codes(const char *code1, const char *code2) {
    int result = 0;
    for (int i = 0; i < CODE_LENGTH; i++) {
        result |= (code1[i] ^ code2[i]);
    }
    return (result == 0);
}

// Function to control the relay (lock)
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);

    // Lock both relays
    control_relay(state.relay1_gpio, 0);
    control_relay(state.relay2_gpio, 0);

    // Close UART ports
    if (state.uart1_handle >= 0) {
        serClose(state.uart1_handle);
    }
    if (state.uart2_handle >= 0) {
        serClose(state.uart2_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize program state
    state.relay1_gpio = RELAY1_GPIO;
    state.relay2_gpio = RELAY2_GPIO;

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize UART ports
    state.uart1_handle = initialize_uart(UART1_PORT);
    if (state.uart1_handle < 0) {
        gpioTerminate();
        return 1;
    }

    state.uart2_handle = initialize_uart(UART2_PORT);
    if (state.uart2_handle < 0) {
        serClose(state.uart1_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(state.relay1_gpio, PI_OUTPUT);
    gpioSetMode(state.relay2_gpio, PI_OUTPUT);

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read codes from both UART ports
        if (read_code(state.uart1_handle, state.code1, CODE_LENGTH) == 0) {
            printf("Code 1: %s\n", state.code1);
        }
        if (read_code(state.uart2_handle, state.code2, CODE_LENGTH) == 0) {
            printf("Code 2: %s\n", state.code2);
        }

        // Check if both codes are valid and match the expected code
        if (strlen(state.code1) == CODE_LENGTH && strlen(state.code2) == CODE_LENGTH &&
            compare_codes(state.code1, state.code2) && compare_codes(state.code1, EXPECTED_CODE)) {
            printf("Authentication successful!\n");

            // Unlock the doors
            if (control_relay(state.relay1_gpio, 1) != 0 || control_relay(state.relay2_gpio, 1) != 0) {
                fprintf(stderr, "Failed to unlock doors\n");
            }

            // Wait for 2 seconds
            gpioDelay(2000000); // 2 seconds in microseconds

            // Lock the doors
            if (control_relay(state.relay1_gpio, 0) != 0 || control_relay(state.relay2_gpio, 0) != 0) {
                fprintf(stderr, "Failed to lock doors\n");
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100000); // 0.1 seconds in microseconds
    }

    return 0;
}

