#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define RELAY_ACTIVATION_TIME_S 1
#define FAILSAFE_TIMEOUT_S 10

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_pir_sensor();
void activate_relay();
void deactivate_relay();
void log_event(int priority, const char *message);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_event(LOG_INFO, "Signal received, shutting down...");
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        log_event(LOG_ERR, "Failed to set PIR sensor pin mode");
        cleanup();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set relay pin mode");
        cleanup();
        return -1;
    }

    deactivate_relay(); // Ensure relay is off on startup

    log_event(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate the relay
void activate_relay() {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to activate relay");
    } else {
        log_event(LOG_INFO, "Relay activated");
    }
}

// Deactivate the relay
void deactivate_relay() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to deactivate relay");
    } else {
        log_event(LOG_INFO, "Relay deactivated");
    }
}

// Log an event to syslog
void log_event(int priority, const char *message) {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Cleanup GPIO and terminate pigpio
void cleanup() {
    log_event(LOG_INFO, "Cleaning up...");
    deactivate_relay(); // Ensure relay is off before exiting
    if (pigpio_initialized) {
        gpioTerminate();
    }
    log_event(LOG_INFO, "Cleanup complete");
}

