    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    time_t last_motion_time = 0;
    int motion_detected = 0;

    log_event(LOG_INFO, "Motion detection system started");

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            time_t current_time = time(NULL);
            if (!motion_detected) {
                log_event(LOG_INFO, "Motion detected");
                activate_relay();
                last_motion_time = current_time;
                motion_detected = 1;
            } else {
                // Check for failsafe timeout
                if (difftime(current_time, last_motion_time) > FAILSAFE_TIMEOUT_S) {
                    log_event(LOG_WARNING, "Failsafe triggered: Continuous motion detected");
                    deactivate_relay();
                    log_event(LOG_INFO, "System shutting down due to failsafe");
                    running = 0;
                }
            }
        } else {
            motion_detected = 0;
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    cleanup();
    return 0;
}

