#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the timer interval in seconds
#define TIMER_INTERVAL 60

// Define the relay activation duration in seconds
#define RELAY_DURATION 300

// Define the pause duration between relay activations in seconds
#define PAUSE_DURATION 60

// Define the total number of relays
#define NUM_RELAYS 4

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void timer_callback(int timer_id);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_message(const char *message);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");

    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Release GPIO resources
    gpioTerminate();

    // Close syslog
    closelog();

    // Exit the program
    exit(0);
}

// Timer callback function
void timer_callback(int timer_id) {
    // This function is called every TIMER_INTERVAL seconds
    // It drives the state machine for the irrigation cycle

    // Get the current time
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    // Log the timer event
    char message[256];
    snprintf(message, sizeof(message), "Timer %d fired at %s", timer_id, buf);
    log_message(message);

    // Implement the state machine logic
    static int current_relay = 1; // Start with relay 1
    static int relay_active = 0;  // Flag to indicate if a relay is currently active
    static time_t relay_start_time = 0; // Time when the current relay was activated

    if (!relay_active) {
        // Activate the current relay
        activate_relay(current_relay);
        relay_active = 1;
        relay_start_time = time(NULL);

        // Log the relay activation event
        snprintf(message, sizeof(message), "Relay %d activated at %s", current_relay, buf);
        log_message(message);
    } else {
        // Check if the current relay has been active for RELAY_DURATION seconds
        if (difftime(time(NULL), relay_start_time) >= RELAY_DURATION) {
            // Deactivate the current relay
            deactivate_relay(current_relay);
            relay_active = 0;

            // Log the relay deactivation event
            snprintf(message, sizeof(message), "Relay %d deactivated at %s", current_relay, buf);
            log_message(message);

            // Insert a pause of PAUSE_DURATION seconds
            sleep(PAUSE_DURATION);

            // Move to the next relay
            current_relay++;
            if (current_relay > NUM_RELAYS) {
                current_relay = 1; // Loop back to the first relay
            }
        }
    }
}

// Function to activate a relay
void activate_relay(int relay_number) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message("Invalid relay number");
            return;
    }

    if (gpioWrite(pin, 0) != 0) { // Active LOW
        char message[256];
        snprintf(message, sizeof(message), "Error writing to GPIO %d", pin);
        log_message(message);
        perror("gpioWrite");
        return;
    }
}

// Function to deactivate a relay
void deactivate_relay(int relay_number) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message("Invalid relay number");
            return;
    }

    if (gpioWrite(pin, 1) != 0) { // Active LOW
        char message[256];
        snprintf(message, sizeof(message), "Error writing to GPIO %d", pin);
        log_message(message);
        perror("gpioWrite");
        return;
    }
}

// Function to log messages to syslog
void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        perror("gpioInitialise");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            char message[256];
            snprintf(message, sizeof(message), "Error setting GPIO %d as output", pins[i]);
            log_message(message);
            perror("gpioSetMode");
            gpioTerminate();
            closelog();
            return 1;
        }
        // Initialize relays to OFF (HIGH)
        if (gpioWrite(pins[i], 1) != 0) {
            char message[256];
            snprintf(message, sizeof(message), "Error writing to GPIO %d", pins[i]);
            log_message(message);
            perror("gpioWrite");
            gpioTerminate();
            closelog();
            return 1;
        }
    }

    // Set up the timer
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, 0) != 0) {
        log_message("Error setting up timer");
        perror("gpioSetTimerFuncEx");
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message("Irrigation system started");

    // Main loop
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    closelog();
    return 0;
}

