        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            char message[256];
            snprintf(message, sizeof(message), "Error setting GPIO %d as output", pins[i]);
            log_message(message);
            perror("gpioSetMode");
            gpioTerminate();
            closelog();
            return 1;
        }
        // Initialize relays to OFF (HIGH)
        if (gpioWrite(pins[i], 1) != 0) {
            char message[256];
            snprintf(message, sizeof(message), "Error writing to GPIO %d", pins[i]);
            log_message(message);
            perror("gpioWrite");
            gpioTerminate();
            closelog();
            return 1;
        }
    }

    // Set up the timer
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, 0) != 0) {
        log_message("Error setting up timer");
        perror("gpioSetTimerFuncEx");
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message("Irrigation system started");

    // Main loop
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    closelog();
    return 0;
}

