#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 1000
#define DELAY_US (1000000 / SAMPLE_RATE) // Delay in microseconds

// Data structure for acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

// Circular buffer structure
typedef struct {
    accel_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd = -1;
circular_buffer_t accel_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_accel_data(int fd, accel_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, accel_data_t data);
accel_data_t get_latest_data(circular_buffer_t *buffer);
void signal_handler(int sig);
void timer_callback(int sig);
void cleanup();

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read acceleration data from MPU6050
int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buf[6];

    if (read(fd, buf, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, accel_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Get the latest data from the circular buffer
accel_data_t get_latest_data(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        accel_data_t empty_data = {0, 0, 0};
        return empty_data;
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->buffer[index];
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Timer callback function
void timer_callback(int sig) {
    accel_data_t data;
    if (read_accel_data(i2c_fd, &data) == 0) {
        add_to_buffer(&accel_buffer, data);
    } else {
        fprintf(stderr, "Error reading accelerometer data in timer callback.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    // No need to explicitly delete the circular buffer as it's a struct
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize circular buffer
    accel_buffer.head = 0;
    accel_buffer.tail = 0;
    accel_buffer.count = 0;

    // Set up timer
    struct sigaction sa;
    struct itimerspec its;
    struct sigevent sev;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = timer_callback;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_int = 0;

    if (timer_create(CLOCK_REALTIME, &sev, &i2c_fd) == -1) {
        perror("timer_create");
        cleanup();
        return 1;
    }

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = DELAY_US * 1000; // Convert microseconds to nanoseconds
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = DELAY_US * 1000;

    if (timer_settime(i2c_fd, 0, &its, NULL) == -1) {
        perror("timer_settime");
        cleanup();
        return 1;
    }

    printf("MPU6050 data acquisition started. Sampling at %d Hz. Press Ctrl+C to exit.\n", SAMPLE_RATE);

    // Main loop
    while (!terminate) {
        // Do other tasks here, if needed
        pause(); // Wait for a signal
    }

    // Stop the timer
    if (i2c_fd != -1) {
        timer_delete(i2c_fd);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

