#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the prime number intervals in seconds
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variables to store the last toggle times for each relay
static struct timespec last_toggle_time[4] = {{0, 0}, {0, 0}, {0, 0}, {0, 0}};

// Function prototypes
void signal_handler(int signal);
void toggle_relay(int relay_pin);
void set_relay_state(int relay_pin, int state);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to toggle the state of a relay
void toggle_relay(int relay_pin) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    int relay_index = -1;
    if (relay_pin == RELAY1_PIN) relay_index = 0;
    else if (relay_pin == RELAY2_PIN) relay_index = 1;
    else if (relay_pin == RELAY3_PIN) relay_index = 2;
    else if (relay_pin == RELAY4_PIN) relay_index = 3;

    if (relay_index == -1) {
        fprintf(stderr, "Error: Invalid relay pin: %d\n", relay_pin);
        return;
    }

    // Calculate the time elapsed since the last toggle
    double elapsed_time = (current_time.tv_sec - last_toggle_time[relay_index].tv_sec) +
                          (current_time.tv_nsec - last_toggle_time[relay_index].tv_nsec) / 1000000000.0;

    // Check if the interval has elapsed
    if (elapsed_time >= (double)(((relay_index == 0) ? INTERVAL1 : ((relay_index == 1) ? INTERVAL2 : ((relay_index == 2) ? INTERVAL3 : INTERVAL4))));
    {
        // Get the current state of the relay
        int current_state = gpioRead(relay_pin);

        // Toggle the relay state
        int new_state = !current_state;

        // Set the new state of the relay
        set_relay_state(relay_pin, new_state);

        // Update the last toggle time
        last_toggle_time[relay_index] = current_time;

        printf("Relay %d toggled to state %d\n", relay_pin, new_state);
    }
}

// Function to set the state of a relay
void set_relay_state(int relay_pin, int state) {
    int result = gpioWrite(relay_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d (error code %d)\n", relay_pin, result);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        toggle_relay(RELAY1_PIN);
        toggle_relay(RELAY2_PIN);
        toggle_relay(RELAY3_PIN);
        toggle_relay(RELAY4_PIN);

        // Small delay to prevent excessive CPU usage
        usleep(10000); // 10 milliseconds
    }

    return 0;
}

