#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define relay activation duration (in seconds)
#define RELAY_DURATION 3

// Define cooldown period (in seconds)
#define COOLDOWN_PERIOD 5

// Global variables
static volatile int running = 1;
static time_t last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Deinitialize pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
int activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn on relay
    return 0;
}

// Log alarm event to file
int log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening alarm_log.txt");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 0) { // Assuming sound sensor outputs 0 when sound is detected
            time_t current_time = time(NULL);

            // Check cooldown period
            if (difftime(current_time, last_activation_time) >= COOLDOWN_PERIOD) {
                printf("Sound detected! Activating relay.\n");
                activate_relay();
                log_alarm();
                last_activation_time = current_time;
                gpioDelay(RELAY_DURATION * 1000000); // Delay for relay duration (in microseconds)
                gpioWrite(RELAY_PIN, 0); // Turn off relay after duration
            } else {
                printf("Sound detected, but cooldown period active. Ignoring.\n");
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Deinitialize pigpio

    return 0;
}

