#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor (LSB/degree/sec)
#define GYRO_SCALE_FACTOR 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define VELOCITY_THRESHOLD 50.0

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t gyro_buffer;

// Function prototypes
int init_i2c(int addr);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_angular_velocity(int16_t x, int16_t y, int16_t z);
void add_to_buffer(circular_buffer_t *cb, float value);
float get_latest_reading(circular_buffer_t *cb);
void check_threshold(float velocity);
void signal_handler(int sig);
void init_circular_buffer(circular_buffer_t *cb);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C communication
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (write(i2c_fd, (char *)&GYRO_XOUT_H, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        if (read(i2c_fd, (char *)buffer, 6) != 6) {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        *x = (int16_t)((buffer[0] << 8) | buffer[1]);
        *y = (int16_t)((buffer[2] << 8) | buffer[3]);
        *z = (int16_t)((buffer[4] << 8) | buffer[5]);
        return 0; // Success
    }

    fprintf(stderr, "Failed to read gyro data after multiple retries.\n");
    return -1; // Failure
}

// Calculate angular velocity in degrees/second
float calculate_angular_velocity(int16_t x, int16_t y, int16_t z) {
    float x_rate = x / GYRO_SCALE_FACTOR;
    float y_rate = y / GYRO_SCALE_FACTOR;
    float z_rate = z / GYRO_SCALE_FACTOR;

    return sqrt(x_rate * x_rate + y_rate * y_rate + z_rate * z_rate);
}

// Add a new reading to the circular buffer
void add_to_buffer(circular_buffer_t *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the latest reading from the circular buffer
float get_latest_reading(circular_buffer_t *cb) {
    if (cb->count > 0) {
        int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        return cb->buffer[index];
    } else {
        return 0.0; // Return 0 if the buffer is empty
    }
}

// Check if the angular velocity exceeds the threshold
void check_threshold(float velocity) {
    if (velocity > VELOCITY_THRESHOLD) {
        printf("Angular velocity exceeded threshold: %.2f degrees/second\n", velocity);
    }
}

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

int main() {
    int16_t gyro_x, gyro_y, gyro_z;
    float angular_velocity;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Wake up the MPU-6050 (set power management register to 0)
    uint8_t wake_up_data = 0x00;
    if (write(i2c_fd, (char *)&PWR_MGMT_1, 1) != 1) {
        perror("Error writing to I2C device (wake up)");
        close(i2c_fd);
        return 1;
    }
    if (write(i2c_fd, (char *)&wake_up_data, 1) != 1) {
        perror("Error writing to I2C device (wake up)");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    printf("MPU-6050 Gyroscope Data Acquisition\n");

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate angular velocity
            angular_velocity = calculate_angular_velocity(gyro_x, gyro_y, gyro_z);

            // Add to circular buffer
            add_to_buffer(&gyro_buffer, angular_velocity);

            // Check threshold
            check_threshold(angular_velocity);
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        usleep(10000); // 10ms delay
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

