int log_data(FILE *fp, const sensor_data_t *data);
int log_error(FILE *fp, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int init_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Send command to the sensor
int send_command(int fd, const unsigned char *command, int length) {
    if (write(fd, command, length) != length) {
        perror("Error writing to UART");
        return -1;
    }
    return 0;
}

// Read response from the sensor with timeout
int read_response(int fd, unsigned char *response, int length, int timeout_sec) {
    fd_set readfds;
    struct timeval timeout;
    int retval;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = timeout_sec;
    timeout.tv_usec = 0;

    retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select()");
        return -1;
    } else if (retval) {
        ssize_t bytes_read = read(fd, response, length);
        if (bytes_read != length) {
            fprintf(stderr, "Error reading from UART (expected %d, got %zd)\n", length, bytes_read);
            return -1;
        }
        return 0;
    } else {
        fprintf(stderr, "Timeout reading from UART\n");
        return -1;
    }
}

// Calculate checksum
int calculate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 0; i < length - 1; i++) {
        checksum += data[i];
    }
    return checksum;
}

// Verify checksum
int verify_checksum(const unsigned char *data, int length, unsigned char checksum) {
    return (calculate_checksum(data, length) == checksum);
}

// Parse CO2 data
int parse_co2_data(const unsigned char *response, int length, sensor_data_t *data) {
    if (length != CO2_RESPONSE_LENGTH) {
        fprintf(stderr, "Invalid response length: %d\n", length);
        return -1;
    }

    if (!verify_checksum(response, length, response[8])) {
        fprintf(stderr, "Checksum mismatch\n");
        return -1;
    }

    data->co2_ppm = (response[1] << 8) | response[0];
    data->timestamp_us = 0; // Not implemented, using 0 for now
    data->error = 0;

    return 0;
}

// Log data to file
int log_data(FILE *fp, const sensor_data_t *data) {
    char json_string[256];
    snprintf(json_string, sizeof(json_string), "{\"timestamp_us\": %ld, \"co2_ppm\": %d, \"error\": %d}\n",
             data->timestamp_us, data->co2_ppm, data->error);

    if (fputs(json_string, fp) == EOF) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Log error to file
int log_error(FILE *fp, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fflush(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log files
    co2_log_file = fopen("co2_log.json", "a");
    if (co2_log_file == NULL) {
        perror("Error opening co2_log.json");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    co2_error_file = fopen("co2_error.log", "a");
    if (co2_error_file == NULL) {
        perror("Error opening co2_error.log");
        fclose(co2_log_file);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // CO2 command sequence (0x20 0x01 0x00 0x00 0x00 0x00 0x00 0x00 0x00)
    unsigned char co2_command[CO2_COMMAND_LENGTH] = {0x20, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    unsigned char co2_response[CO2_RESPONSE_LENGTH];
    sensor_data_t sensor_data;
    int retries = 0;

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            // Send command
            if (send_command(uart_fd, co2_command, CO2_COMMAND_LENGTH) != 0) {
                log_error(co2_error_file, "Error sending command");
                break; // Exit retry loop on command send error
            }

            // Wait for response
            if (read_response(uart_fd, co2_response, CO2_RESPONSE_LENGTH, TIMEOUT_SEC) == 0) {
                // Parse data
                if (parse_co2_data(co2_response, CO2_RESPONSE_LENGTH, &sensor_data) == 0) {
                    // Log data
                    if (log_data(co2_log_file, &sensor_data) != 0) {
                        log_error(co2_error_file, "Error logging data");
                    }
                    printf("%s", (char*)co2_response); // Print to stdout
                    break; // Exit retry loop on successful read
                } else {
                    log_error(co2_error_file, "Error parsing data");
                }
            } else {
                log_error(co2_error_file, "Error reading response");
            }

            retries++;
            gpioDelay(10); // Small delay before retrying
        }

        if (retries == MAX_RETRIES) {
            log_error(co2_error_file, "Max retries reached, skipping reading");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next sample
    }

    // Cleanup
    close(uart_fd);
    fclose(co2_log_file);
    fclose(co2_error_file);
    gpioTerminate();

    return 0;
}

