#include <signal.h>
#include <unistd.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Hard-iron offsets
#define X_OFFSET 100.0
#define Y_OFFSET -50.0

// Target heading
#define TARGET_HEADING 90.0

// Deviation threshold
#define HEADING_THRESHOLD 10.0

// Circular buffer size
#define BUFFER_SIZE 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void apply_hard_iron_compensation(float heading);
void store_heading(float heading);
float retrieve_heading(int index);
void control_gpio(float heading);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the HMC5883L magnetometer
int initialize_hmc5883l() {
    // Set configuration register A (0x00) to 0x70 (8-average, 15 Hz, normal measurement)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Set configuration register B (0x01) to 0xA0 (Gain = 5)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set mode register (0x02) to 0x00 (Continuous measurement mode)
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Reads raw magnetometer data from the HMC5883L
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculates the heading in degrees from the X and Y magnetometer readings
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Applies hard-iron compensation to the heading
void apply_hard_iron_compensation(float heading) {
    // This is a placeholder.  Hard-iron compensation typically involves
    // subtracting offsets from the raw X and Y values before calculating the heading.
    // However, since we are calculating the heading first, we can't directly apply
    // the offsets here.  A more accurate approach would be to apply the offsets
    // to the raw X and Y values before calculating the heading.
    // For simplicity, we'll just return the original heading.
    heading = heading; // Placeholder
}

// Stores the compensated heading in the circular buffer
void store_heading(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Retrieves a heading from the circular buffer
float retrieve_heading(int index) {
    return heading_buffer[index];
}

// Controls the GPIO pin based on the heading deviation
void control_gpio(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Apply hard-iron compensation
            apply_hard_iron_compensation(heading);

            // Store heading in circular buffer
            store_heading(heading);

            // Control GPIO pin
            control_gpio(heading);

            // Print heading (optional)
            printf("Heading: %.2f\n", heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else if (initialize_hmc5883l() < 0) {
                fprintf(stderr, "HMC5883L re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Delay for 100ms
        gpioDelay(100);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low before exiting
    gpioTerminate();

    return 0;
}

