#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define I2C_ADDR 0x23
#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22
#define LUX_THRESHOLD_1 50
#define LUX_THRESHOLD_2 150
#define LUX_THRESHOLD_3 300
#define LOG_FILE "lighting_log.txt"
#define I2C_RETRY_COUNT 3

// Global variables
static volatile int keepRunning = 1;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
int init_i2c(int addr);
int read_lux(int fd);
void control_relays(int lux);
void log_data(int lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);

// Function to initialize I2C
int init_i2c(int addr) {
    int fd = wiringPiI2CSetup(addr);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read lux value from BH1750
int read_lux(int fd) {
    int lux = -1;
    int retry = 0;

    while (retry < I2C_RETRY_COUNT) {
        wiringPiI2CWrite(fd, 0x10); // Start measurement in high resolution mode
        delay(120); // Wait for measurement
        lux = wiringPiI2CReadReg16(fd, 0x00); // Read the lux value
        if (lux != -1) {
            lux = (lux / 1.2); // Convert to lux
            return lux;
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %s\n", retry + 1, strerror(errno));
            retry++;
            delay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read lux after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Indicate error
}

// Function to control RGB relays based on lux value
void control_relays(int lux) {
    int red_state = 0;
    int green_state = 0;
    int blue_state = 0;

    if (lux < LUX_THRESHOLD_1) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_2) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_3) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    digitalWrite(RED_PIN, red_state);
    digitalWrite(GREEN_PIN, green_state);
    digitalWrite(BLUE_PIN, blue_state);

    log_data(lux, red_state, green_state, blue_state);
}

// Function to log data to file
void log_data(int lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Lux: %d, Red: %d, Green: %d, Blue: %d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    keepRunning = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    // Initialize WiringPi with BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
