    pinMode(RED_PIN, OUTPUT);
    pinMode(GREEN_PIN, OUTPUT);
    pinMode(BLUE_PIN, OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Ambient light control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        int lux = read_lux(i2c_fd);
        if (lux != -1) {
            control_relays(lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
