#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIO pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Distance threshold for forward/backward
#define DISTANCE_THRESHOLD 50

// Global variables for distance readings (simulated)
int distance_a = 40; // Initial distance for Motor A
int distance_b = 60; // Initial distance for Motor B

// Function prototypes
void motor_forward(int motor_a_distance, int motor_b_distance);
void motor_backward(int motor_a_distance, int motor_b_distance);
void motor_stop();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    motor_stop();
    gpioTerminate();
    exit(0);
}

// Function to set motor A forward
void motor_forward(int motor_a_distance, int motor_b_distance) {
    gpioWrite(MOTOR_A_IN1, 1);
    gpioWrite(MOTOR_B_IN3, 1);

    // Calculate PWM duty cycle for Motor A
    int duty_cycle_a = (motor_a_distance < DISTANCE_THRESHOLD) ? (motor_a_distance * 255 / DISTANCE_THRESHOLD) : 0;
    gpioPWM(MOTOR_A_IN2, duty_cycle_a);

    // Calculate PWM duty cycle for Motor B
    int duty_cycle_b = (motor_b_distance < DISTANCE_THRESHOLD) ? (motor_b_distance * 255 / DISTANCE_THRESHOLD) : 0;
    gpioPWM(MOTOR_B_IN4, duty_cycle_b);
}

// Function to set motor A backward
void motor_backward(int motor_a_distance, int motor_b_distance) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_B_IN3, 0);

    // Calculate PWM duty cycle for Motor A
    int duty_cycle_a = (motor_a_distance >= DISTANCE_THRESHOLD) ? (DISTANCE_THRESHOLD - motor_a_distance) * 255 / DISTANCE_THRESHOLD : 0;
    gpioPWM(MOTOR_A_IN2, duty_cycle_a);

    // Calculate PWM duty cycle for Motor B
    int duty_cycle_b = (motor_b_distance >= DISTANCE_THRESHOLD) ? (DISTANCE_THRESHOLD - motor_b_distance) * 255 / DISTANCE_THRESHOLD : 0;
    gpioPWM(MOTOR_B_IN4, duty_cycle_b);
}

// Function to stop both motors
void motor_stop() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
}

int main(int argc, char *argv[]) {
    // Check for command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    distance_a = atoi(argv[1]);
    distance_b = atoi(argv[2]);

    // Validate distance readings
    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Error: Distance values must be between 10 and 100.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (1) {
        if (distance_a < DISTANCE_THRESHOLD) {
            motor_forward(distance_a, distance_b);
        } else {
            motor_backward(distance_a, distance_b);
        }
        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

