#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for L293D driver
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22

// Define GPIO pins for buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define motor parameters
#define STEPS_PER_REVOLUTION 2048
#define LOCK_UNLOCK_STEPS 512
#define INTER_STEP_DELAY_US 2000 // 2ms

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void cleanup(int signal);
void lock_door();
void unlock_door();
void step_motor(int step);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;

    // De-energize all motor coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    for (int i = 0; i < LOCK_UNLOCK_STEPS; i++) {
        step_motor(i % 4);
    }
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    for (int i = 0; i < LOCK_UNLOCK_STEPS; i++) {
        step_motor(3 - (i % 4)); // Reverse the step sequence for counter-clockwise rotation
    }
    printf("Door unlocked.\n");
}

// Function to control a single step of the motor
void step_motor(int step) {
    switch (step) {
        case 0:
            gpioWrite(IN1, 1);
            gpioWrite(IN2, 0);
            gpioWrite(IN3, 1);
            gpioWrite(IN4, 0);
            break;
        case 1:
            gpioWrite(IN1, 0);
            gpioWrite(IN2, 1);
            gpioWrite(IN3, 1);
            gpioWrite(IN4, 0);
            break;
        case 2:
            gpioWrite(IN1, 0);
            gpioWrite(IN2, 1);
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 1);
            break;
        case 3:
            gpioWrite(IN1, 1);
            gpioWrite(IN2, 0);
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 1);
            break;
        default:
            fprintf(stderr, "Invalid step value: %d\n", step);
            break;
    }
    gpioDelay(INTER_STEP_DELAY_US);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins for L293D driver as outputs
    if (gpioSetMode(IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN1 as output\n");
        cleanup(0);
        return 1;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN2 as output\n");
        cleanup(0);
        return 1;
    }
    if (gpioSetMode(IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN3 as output\n");
        cleanup(0);
        return 1;
    }
    if (gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN4 as output\n");
        cleanup(0);
        return 1;
    }

    // Configure GPIO pins for buttons as inputs with pull-up resistors
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LOCK_BUTTON as input\n");
        cleanup(0);
        return 1;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on LOCK_BUTTON\n");
        cleanup(0);
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set UNLOCK_BUTTON as input\n");
        cleanup(0);
        return 1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on UNLOCK_BUTTON\n");
        cleanup(0);
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Door control system started. Press LOCK button to lock, UNLOCK button to unlock. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for LOCK button press
        if (gpioRead(LOCK_BUTTON) == 0) {
            lock_door();
            gpioDelay(500000); // Debounce delay (0.5 seconds)
        }

        // Check for UNLOCK button press
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            unlock_door();
            gpioDelay(500000); // Debounce delay (0.5 seconds)
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    return 0;
}

