#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Servo motor GPIO
#define SERVO_PIN 18

// PWM parameters
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000  // 50Hz (20ms period)
#define PWM_RANGE 2000   // PWM range (0-2000)

// Servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Log file name
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int init_i2c(int addr);
int read_raw_accel(int fd, int *x, int *y, int *z);
void calculate_pitch_roll(int x, int y, int z, float *pitch, float *roll);
int map_angle_to_pulse_width(float angle);
int set_servo_pulse_width(int pulse_width);
int log_data(float pitch, float roll, int pulse_width);
void signal_handler(int signal);

// Exponential backoff retry function
int retry_i2c_read(int fd, int reg, int retries, int delay_ms)
{
    int result = -1;
    for (int i = 0; i < retries; ++i)
    {
        result = wiringPiI2CReadReg16(fd, reg);
        if (result >= 0)
        {
            return result;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", i + 1, retries, strerror(errno));
        delay(delay_ms);
        delay_ms *= 2; // Exponential backoff
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", retries);
    return -1; // Indicate failure
}

// Initialize I2C communication
int init_i2c(int addr)
{
    int fd = wiringPiI2CSetup(addr);
    if (fd == -1)
    {
        fprintf(stderr, "Failed to initialize I2C communication: %s\n", strerror(errno));
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) == -1)
    {
        fprintf(stderr, "Failed to wake up MPU-6050: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

// Read raw accelerometer data
int read_raw_accel(int fd, int *x, int *y, int *z)
{
    int x_high, x_low, y_high, y_low, z_high, z_low;

    x_high = retry_i2c_read(fd, ACCEL_XOUT_H, 3, 10); // Retry 3 times with 10ms delay
    x_low = retry_i2c_read(fd, ACCEL_XOUT_H + 1, 3, 10);
    y_high = retry_i2c_read(fd, ACCEL_YOUT_H, 3, 10);
    y_low = retry_i2c_read(fd, ACCEL_YOUT_H + 1, 3, 10);
    z_high = retry_i2c_read(fd, ACCEL_ZOUT_H, 3, 10);
    z_low = retry_i2c_read(fd, ACCEL_ZOUT_H + 1, 3, 10);

    if (x_high == -1 || x_low == -1 || y_high == -1 || y_low == -1 || z_high == -1 || z_low == -1)
    {
        return -1; // Indicate failure
    }

    *x = (x_high << 8) | x_low;
    *y = (y_high << 8) | y_low;
    *z = (z_high << 8) | z_low;

    // Convert to signed 16-bit integers
    if (*x >= 0x8000) *x -= 0x10000;
    if (*y >= 0x8000) *y -= 0x10000;
    if (*z >= 0x8000) *z -= 0x10000;

    return 0; // Indicate success
}

// Calculate pitch and roll angles
void calculate_pitch_roll(int x, int y, int z, float *pitch, float *roll)
{
    *pitch = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    *roll = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
}

// Map angle to servo pulse width
int map_angle_to_pulse_width(float angle)
{
    // Assuming a linear relationship between angle and pulse width
    // You may need to calibrate this based on your servo motor
    float pulse_width = SERVO_MIN_PULSE_WIDTH + (angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);
    return (int)pulse_width;
}

// Set servo pulse width using sysfs PWM interface
int set_servo_pulse_width(int pulse_width)
{
    char pwm_chip_path[64];
    char pwm_num_str[4];
    char period_path[64];
    char duty_cycle_path[64];
    FILE *period_file, *duty_cycle_file;

    // Construct paths
    snprintf(pwm_chip_path, sizeof(pwm_chip_path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_NUM);
    snprintf(period_path, sizeof(period_path), "%s/period", pwm_chip_path);
    snprintf(duty_cycle_path, sizeof(duty_cycle_path), "%s/duty_cycle", pwm_chip_path);

    // Set PWM period
    period_file = fopen(period_path, "w");
    if (period_file == NULL)
    {
        fprintf(stderr, "Failed to open period file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(period_file, "%d", PWM_PERIOD);
    fclose(period_file);

    // Set PWM duty cycle
    duty_cycle_file = fopen(duty_cycle_path, "w");
    if (duty_cycle_file == NULL)
    {
        fprintf(stderr, "Failed to open duty_cycle file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(duty_cycle_file, "%d", pulse_width);
    fclose(duty_cycle_file);

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int pulse_width)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, pulse_width);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;

    // Stop the servo motor
    set_servo_pulse_width(0);

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Release PWM resources (optional, but good practice)
    char pwm_chip_path[64];
    char pwm_num_str[4];
    snprintf(pwm_chip_path, sizeof(pwm_chip_path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_NUM);
    snprintf(pwm_num_str, sizeof(pwm_num_str), "%d", PWM_NUM);
    char export_path[64];
    snprintf(export_path, sizeof(export_path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    FILE *export_file = fopen(export_path, "w");
    if (export_file != NULL) {
        fprintf(export_file, "%s", pwm_num_str);
        fclose(export_file);
    }

    exit(0);
}

int main()
{
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1)
    {
        fprintf(stderr, "Failed to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd == -1)
    {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int x, y, z;
    float pitch, roll;
    int pulse_width;

    // Main loop
    while (running)
    {
        // Read accelerometer data
        if (read_raw_accel(i2c_fd, &x, &y, &z) == 0)
        {
            // Calculate pitch and roll
            calculate_pitch_roll(x, y, z, &pitch, &roll);

            // Map angle to pulse width
            pulse_width = map_angle_to_pulse_width(pitch); // Use pitch for angle

            // Set servo pulse width
            if (set_servo_pulse_width(pulse_width) == 0)
            {
                // Log data
                log_data(pitch, roll, pulse_width);
            }
            else
            {
                fprintf(stderr, "Failed to set servo pulse width.\n");
            }
        }
        else
        {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        delay(100); // Delay for 100ms
    }

    return 0;
}

