#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the PWM frequency
#define PWM_FREQUENCY 100

// Define the fade duration in seconds
#define FADE_DURATION 1800

// Define the number of schedule entries
#define MAX_SCHEDULE_ENTRIES 100

// Structure to store schedule entries
typedef struct {
    int hour, minute, second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
schedule_entry_t schedule[MAX_SCHEDULE_ENTRIES];
int schedule_size = 0;
int running = 1; // Flag to control the main loop

// Function prototypes
int read_schedule_file(const char *filename);
int parse_schedule_entry(const char *line, schedule_entry_t *entry);
int is_current_time(int hour, int minute, int second);
int set_relay_state(int relay_number, int state);
int fade_relay(int relay_number, int target_state, int duration);
void signal_handler(int signal);

// Function to read the schedule file
int read_schedule_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    schedule_size = 0;

    while (fgets(line, sizeof(line), fp) != NULL && schedule_size < MAX_SCHEDULE_ENTRIES) {
        if (parse_schedule_entry(line, &schedule[schedule_size]) == 0) {
            schedule_size++;
        } else {
            fprintf(stderr, "Invalid schedule entry: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// Function to parse a schedule entry from a line
int parse_schedule_entry(const char *line, schedule_entry_t *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%s", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, entry->on_off) != 4) {
        return -1; // Parsing failed
    }

    if (entry->relay_number < 1 || entry->relay_number > 4) {
        return -1; // Invalid relay number
    }

    if (strcmp(entry->on_off, "on") != 0 && strcmp(entry->on_off, "off") != 0) {
        return -1; // Invalid on/off value
    }

    return 0; // Parsing successful
}

// Function to check if the current time matches a schedule entry
int is_current_time(int hour, int minute, int second) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    return (t->tm_hour == hour && t->tm_min == minute && t->tm_sec == second);
}

// Function to set the state of a relay
int set_relay_state(int relay_number, int state) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    if (state == 1) {
        gpioWrite(pin, 1); // Turn on the relay
    } else {
        gpioWrite(pin, 0); // Turn off the relay
    }
    return 0;
}

// Function to fade the brightness of a relay using PWM
int fade_relay(int relay_number, int target_state, int duration) {
    int pin;
    int current_state = 0; // Assume off initially

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    if (target_state == 1) {
        current_state = 0; // Start from off
    } else {
        current_state = 1; // Start from on
    }

    int steps = 100; // Number of PWM steps
    int delay_ms = duration * 1000 / steps; // Delay in milliseconds

    for (int i = 0; i <= steps; i++) {
        int duty_cycle = (int)(((float)i / steps) * 100.0);

        if (target_state == 1) {
            gpioPWM(pin, duty_cycle); // Increase brightness
        } else {
            gpioPWM(pin, 100 - duty_cycle); // Decrease brightness
        }

        gpioDelay(delay_ms);
    }

    if (target_state == 1) {
        gpioPWM(pin, 100); // Ensure full brightness
    } else {
        gpioPWM(pin, 0); // Ensure off
    }

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop

    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

