// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0    // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 30000       // Timeout in microseconds (30ms)

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    float frequency;

    if (distance < MIN_DISTANCE) {
        frequency = MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        frequency = MIN_FREQUENCY;
    } else {
        frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    return frequency;
}

// Function to set the PWM frequency
void setBuzzerFrequency(float frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: Frequency out of range (%f Hz)\n", frequency);
        return;
    }

    int range = 1000; // PWM range (adjust as needed)
    int dutycycle = 500; // 50% duty cycle
    int period = 1000000 / frequency; // Period in microseconds
    int pwm_range = period / 2; // Half the period for 50% duty cycle

    gpioSetPWMfrequency(BUZZER_PIN, frequency);
    gpioPWM(BUZZER_PIN, dutycycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range and frequency (initial values)
    gpioSetPWMrange(BUZZER_PIN, 1000);
    gpioSetPWMfrequency(BUZZER_PIN, 1000); // Initial frequency
    gpioPWM(BUZZER_PIN, 500); // Initial duty cycle (50%)

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_width = getPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to a frequency
        float frequency = mapDistanceToFrequency(distance);

        // Set the buzzer frequency
        setBuzzerFrequency(frequency);

        // Delay to achieve approximately 50 Hz loop rate
        gpioDelay(20000); // 20 ms delay
    }

    // Clean up and exit
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();         // Terminate pigpio
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

