#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, float duty_cycle) {
    if (duty_cycle < 0.0 || duty_cycle > 1.0) {
        fprintf(stderr, "Error: Duty cycle must be between 0.0 and 1.0\n");
        return -1; // Indicate an error
    }

    // Common anode: Invert the duty cycle
    int pwm_value = (int)((1.0 - duty_cycle) * 255.0); // Map 0.0-1.0 to 255-0

    if (gpioPWM(gpio_pin, pwm_value) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to calculate the proximity value using a sine wave
float calculate_proximity() {
    static float time = 0.0;
    time += 0.01; // Increment time by a small value
    if (time > 2 * M_PI) {
        time -= 2 * M_PI;
    }
    return sin(time);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for all three pins
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Calculate proximity value
        float proximity = calculate_proximity();

        // Calculate RGB values based on proximity
        float red_value = 0.0;
        float green_value = 0.0;
        float blue_value = 0.0;

        if (proximity >= 0.0 && proximity < 0.33) {
            // Blue to Green
            red_value = 0.0;
            green_value = proximity / 0.33 * 1.0;
            blue_value = 1.0 - green_value;
        } else if (proximity >= 0.33 && proximity < 0.66) {
            // Green to Red
            red_value = (proximity - 0.33) / 0.33 * 1.0;
            green_value = 1.0 - red_value;
            blue_value = 0.0;
        } else {
            // Red to Blue
            red_value = 1.0 - (proximity - 0.66) / 0.34 * 1.0;
            green_value = 0.0;
            blue_value = red_value;
        }

        // Set PWM duty cycles for RGB LED
        if (set_pwm_duty_cycle(RED_PIN, red_value) != 0) {
            program_running = 0; // Stop the loop on error
        }
        if (set_pwm_duty_cycle(GREEN_PIN, green_value) != 0) {
            program_running = 0; // Stop the loop on error
        }
        if (set_pwm_duty_cycle(BLUE_PIN, blue_value) != 0) {
            program_running = 0; // Stop the loop on error
        }

        // Delay for a short period
        usleep(10000); // 10ms
    }

    // Turn off the LED before exiting
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

