#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor (LSB/degree/sec)
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
char* format_data(gyro_data_t data);
int write_to_log(char *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buf[6];

    // Read 6 bytes of data starting from GYRO_XOUT_H
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (buf[0] << 8) | buf[1];
    int16_t gyro_y = (buf[2] << 8) | buf[3];
    int16_t gyro_z = (buf[4] << 8) | buf[5];

    // Convert to degrees per second
    data.x = (float)gyro_x / GYRO_SENSITIVITY;
    data.y = (float)gyro_y / GYRO_SENSITIVITY;
    data.z = (float)gyro_z / GYRO_SENSITIVITY;

    return data;
}

// Format data into a string
char* format_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char buffer[100]; // Static buffer to hold the formatted string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(buffer, sizeof(buffer), "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    return buffer;
}

// Write data to log file
int write_to_log(char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s", data) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Gyroscope data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data();

        // Format data
        char *formatted_data = format_data(gyro_data);

        // Write to log file
        if (write_to_log(formatted_data) != 0) {
            fprintf(stderr, "Error writing data to log file. Continuing...\n");
        }

        // Sleep for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    printf("Closing I2C connection...\n");
    i2cClose(i2c_handle);

    printf("Closing log file...\n");
    fclose(log_file);

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

