#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523, 587, 659, 698, 784, 880};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM duty cycle (50%)
#define PWM_DUTY_CYCLE 128

// Global flag to indicate button press
volatile int button_pressed = 0;

// Global flag to indicate melody playing
volatile int melody_playing = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// ISR function for button press
void button_isr(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) // Button pressed (active low)
    {
        if (current_tick - last_tick > DEBOUNCE_TIME * 1000) // Debounce
        {
            button_pressed = 1;
            last_tick = current_tick;
        }
    }
    else
    {
        button_pressed = 0;
    }
}

// Function to play the melody
void play_melody()
{
    int i;
    for (i = 0; i < melody_length; i++)
    {
        gpioPWM(BUZZER_PIN, PWM_DUTY_CYCLE);
        gpioSetPWMfrequency(BUZZER_PIN, melody[i]);
        gpioDelay(200); // Play each note for 200ms
    }
    melody_playing = 0;
}

// Function to stop the melody
void stop_melody()
{
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    melody_playing = 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency for the buzzer
    gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM duty cycle
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set ISR for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        if (button_pressed)
        {
            if (!melody_playing)
            {
                printf("Button pressed, playing melody...\n");
                play_melody();
            }
            else
            {
                printf("Button pressed during melody, stopping melody...\n");
                stop_melody();
            }
            button_pressed = 0; // Reset the flag
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

