#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3

volatile sig_atomic_t program_running = 1;

// Structure to hold the sliding window of vibration events
typedef struct {
    int values[WINDOW_SIZE];
    int index;
    int count;
} SlidingWindow;

// Function to initialize the sliding window
void slidingWindow_init(SlidingWindow *window) {
    window->index = 0;
    window->count = 0;
    memset(window->values, 0, sizeof(window->values));
}

// Function to add a new value to the sliding window
void slidingWindow_add(SlidingWindow *window, int value) {
    window->values[window->index] = value;
    window->index = (window->index + 1) % WINDOW_SIZE;
    if (window->count < WINDOW_SIZE) {
        window->count++;
    }
}

// Function to check if the earthquake threshold is met
int slidingWindow_checkThreshold(SlidingWindow *window) {
    int highCount = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->values[i] == 1) {
            highCount++;
        }
    }
    return (highCount >= EARTHQUAKE_THRESHOLD);
}

// Function to get the current ISO 8601 timestamp
void getIso8601Timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to log an event to the log file
void logEvent(int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    char timestamp[21];
    getIso8601Timestamp(timestamp);

    if (fprintf(fp, "%s %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", LOG_FILE);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", LOG_FILE);
    }
}

// Function to handle the vibration event
void handleVibrationEvent(int gpio, int level, uint32_t tick) {
    if (gpio == GPIO_PIN) {
        logEvent(level);
        slidingWindow_add(&vibrationWindow, level);
        if (slidingWindow_checkThreshold(&vibrationWindow)) {
            char timestamp[21];
            getIso8601Timestamp(timestamp);
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
        }
    }
}

