#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_magnetometer();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z);
float calculate_heading(int16_t x, int16_t y);
const char *get_compass_direction(float heading);
void log_data(int16_t x, int16_t y, int16_t z, int16_t calibrated_x, int16_t calibrated_y, int16_t calibrated_z, float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the magnetometer
int config_magnetometer() {
    // Set CRA_REG_M to 0x18 (0b00011000) for 75 Hz output rate
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) {
        fprintf(stderr, "Error writing to CRA_REG_M\n");
        return -1;
    }

    // Set MR_REG_M to 0x00 (Continuous conversion mode)
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_magnetometer(int16_t x, int16_t y, int16_t z, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z) {
    *calibrated_x = x - X_OFFSET;
    *calibrated_y = y - Y_OFFSET;
    *calibrated_z = z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Get compass direction from heading
const char *get_compass_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading >= 22.5 && heading < 67.5) return "NE";
    if (heading >= 67.5 && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    if (heading >= 292.5 && heading < 337.5) return "NW";
    return "Unknown";
}

// Log data to CSV file
void log_data(int16_t x, int16_t y, int16_t z, int16_t calibrated_x, int16_t calibrated_y, int16_t calibrated_z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure magnetometer
    if (config_magnetometer() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }
    fseek(log_file, 0, SEEK_END);

    int16_t x, y, z;
    int16_t calibrated_x, calibrated_y, calibrated_z;
    float heading;
    const char *direction;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Get compass direction
            direction = get_compass_direction(heading);

            // Log data
            log_data(x, y, z, calibrated_x, calibrated_y, calibrated_z, heading);

            // Print compass direction and heading to console
            printf("Direction: %s, Heading: %.2f\n", direction, heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

