#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "relay_log.json"

// Global variables
static volatile int relay_state = 0; // 0: OFF, 1: ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);
void log_relay_state(int state);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTime(PI_TIME_RELATIVE, NULL, NULL);

    // Debounce the touch sensor
    if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
        last_touch_time = current_time;

        // Toggle the relay state
        relay_state = !relay_state;

        // Control the relay
        gpioWrite(RELAY_PIN, relay_state);

        // Log the relay state
        log_relay_state(relay_state);
    }
}

// Function to log the relay state to a JSON file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Force relay OFF
    gpioWrite(RELAY_PIN, 0);

    // Log the final OFF state
    log_relay_state(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt on touch sensor pin
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

