#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for servos
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo angles (degrees)
#define SERVO_ANGLE_0 0
#define SERVO_ANGLE_45 45
#define SERVO_ANGLE_90 90
#define SERVO_ANGLE_135 135
#define SERVO_ANGLE_180 180

// Define moisture threshold
#define MOISTURE_THRESHOLD 50

// Define watering cycle parameters
#define WATERING_DURATION 5 // seconds
#define WAIT_DURATION 5      // seconds

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int set_servo_angle(int gpio, int angle);
int open_valve();
int close_valve();
int sweep_nozzle();
int read_simulated_moisture();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping program...\n", signal);

    // Stop both servos
    set_servo_angle(VALVE_GPIO, 0);
    set_servo_angle(NOZZLE_GPIO, 0);

    // Cleanup pigpio
    gpioTerminate();

    exit(0);
}

// Function to set servo angle
int set_servo_angle(int gpio, int angle) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo angle for GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to open the valve
int open_valve() {
    return set_servo_angle(VALVE_GPIO, SERVO_ANGLE_90);
}

// Function to close the valve
int close_valve() {
    return set_servo_angle(VALVE_GPIO, SERVO_ANGLE_0);
}

// Function to sweep the nozzle
int sweep_nozzle() {
    int angles[] = {SERVO_ANGLE_0, SERVO_ANGLE_45, SERVO_ANGLE_90, SERVO_ANGLE_135, SERVO_ANGLE_180};
    int num_angles = sizeof(angles) / sizeof(angles[0]);
    int i;

    for (i = 0; i < num_angles; i++) {
        if (set_servo_angle(NOZZLE_GPIO, angles[i]) != 0) {
            fprintf(stderr, "Error setting nozzle angle to %d\n", angles[i]);
            return -1;
        }
        gpioDelay(2000); // Wait 2 seconds
    }
    return 0;
}

// Function to read simulated moisture
int read_simulated_moisture() {
    static int moisture_level = 20;
    moisture_level += 20;
    if (moisture_level > 100) {
        moisture_level = 20;
    }
    gpioDelay(1000); // Simulate reading every 1 second
    return moisture_level;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture = read_simulated_moisture();
        printf("Moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold, starting watering cycle...\n");

            // Open the valve
            if (open_valve() != 0) {
                fprintf(stderr, "Error opening valve, aborting watering cycle.\n");
                program_running = 0; // Stop the program if valve fails
                break;
            }

            // Sweep the nozzle
            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Error sweeping nozzle.\n");
            }

            // Water for a duration
            gpioDelay(WATERING_DURATION * 1000); // Convert seconds to milliseconds

            // Close the valve
            if (close_valve() != 0) {
                fprintf(stderr, "Warning: Error closing valve.\n");
            }

            // Wait before the next cycle
            gpioDelay(WAIT_DURATION * 1000); // Convert seconds to milliseconds
        } else {
            printf("Moisture above threshold, skipping watering cycle.\n");
            gpioDelay(WAIT_DURATION * 1000); // Wait even if not watering
        }
    }

    // Cleanup pigpio
    gpioTerminate();

    printf("Plant watering system stopped.\n");
    return 0;
}

