#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // 50ms timeout in microseconds
#define TRIGGER_PULSE_US 10   // 10us trigger pulse
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 400.0    // Maximum distance in cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio(gpio_config_t *config);
void trigger_sensor(int trigger_pin);
long pulse_in(int echo_pin, int level, int timeout_us);
float calculate_distance(long pulse_duration_us);
void log_distance(float distance);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trigger_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);

    gpioWrite(config->trigger_pin, 0); // Ensure trigger is low initially

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(trigger_pin, 0);
}

// Measure the echo pulse duration
long pulse_in(int echo_pin, int level, int timeout_us) {
    long start_tick = 0, end_tick = 0;
    int start_sec, start_micros, end_sec, end_micros;

    // Wait for rising edge
    int count = 0;
    while (gpioRead(echo_pin) != level) {
        if (count++ > timeout_us) return -1; // Timeout
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    gpioTime(0, &start_sec, &start_micros);
    start_tick = (long)start_sec * 1000000 + start_micros;

    // Wait for falling edge
    count = 0;
    while (gpioRead(echo_pin) == level) {
        if (count++ > timeout_us) return -1; // Timeout
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    gpioTime(0, &end_sec, &end_micros);
    end_tick = (long)end_sec * 1000000 + end_micros;

    return end_tick - start_tick;
}

// Calculate distance from pulse duration
float calculate_distance(long pulse_duration_us) {
    if (pulse_duration_us < 0) return -1.0; // Error condition
    float distance = (pulse_duration_us / 1000000.0) * SPEED_OF_SOUND / 2.0;
    return distance;
}

// Log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    gpio_config_t gpio_config = {TRIGGER_PIN, ECHO_PIN};
    long pulse_duration;
    float distance;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&gpio_config) != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic distance sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Trigger the sensor
        trigger_sensor(gpio_config.trigger_pin);

        // Measure the echo pulse duration
        pulse_duration = pulse_in(gpio_config.echo_pin, 1, TIMEOUT_US);

        if (pulse_duration < 0) {
            fprintf(stderr, "Error: Timeout or error reading echo pulse.\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
        } else {
            // Calculate the distance
            distance = calculate_distance(pulse_duration);

            // Validate the distance
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
                fprintf(log_file, "-1\n");
                fflush(log_file);
            } else {
                // Log the distance
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            }
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

