#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor (LSB/degree/sec)
#define GYRO_SENSITIVITY 131.0

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Disable sleep mode

    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[6];

    // Read all six bytes at once
    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *gyro_x = (int16_t)((data[0] << 8) | data[1]);
    *gyro_y = (int16_t)((data[2] << 8) | data[3]);
    *gyro_z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int16_t gyro_x, gyro_y, gyro_z;

        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert raw data to degrees per second
            float gyro_x_dps = (float)gyro_x / GYRO_SENSITIVITY;
            float gyro_y_dps = (float)gyro_y / GYRO_SENSITIVITY;
            float gyro_z_dps = (float)gyro_z / GYRO_SENSITIVITY;

            // Print the data
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Delay for 100 milliseconds
        usleep(100000); // 100 ms
    }

    // The program should never reach here due to the infinite loop,
    // but it's good practice to include cleanup code.
    close(i2c_fd);
    return 0;
}

