#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering duration in seconds
#define WATERING_DURATION 5

// Define the cycle duration in seconds (24 hours)
#define CYCLE_DURATION 86400

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int gpio_pin);
void deactivate_relay(int gpio_pin);
void log_watering_cycle_start();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set the GPIO pins as outputs with active-low semantics
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Deactivate all relays initially
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    return 0; // Indicate success
}

// Function to activate a relay
void activate_relay(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set the pin LOW to activate the relay
    printf("Relay on GPIO %d activated\n", gpio_pin);
}

// Function to deactivate a relay
void deactivate_relay(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set the pin HIGH to deactivate the relay
    printf("Relay on GPIO %d deactivated\n", gpio_pin);
}

// Function to log the start time of a watering cycle
void log_watering_cycle_start() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s\n", s);
    fclose(fp);
    printf("Watering cycle started at %s\n", s);
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Plant watering system started\n");

    // Main loop
    while (program_running) {
        // Log the start of the watering cycle
        log_watering_cycle_start();

        // Activate relays sequentially
        activate_relay(RELAY1_PIN);
        gpioDelay(WATERING_DURATION * 1000000); // Delay for watering duration (in microseconds)
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        gpioDelay(WATERING_DURATION * 1000000); // Delay for watering duration (in microseconds)
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        gpioDelay(WATERING_DURATION * 1000000); // Delay for watering duration (in microseconds)
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        gpioDelay(WATERING_DURATION * 1000000); // Delay for watering duration (in microseconds)
        deactivate_relay(RELAY4_PIN);

        // Wait for the remaining time in the cycle
        gpioDelay((CYCLE_DURATION - (4 * WATERING_DURATION)) * 1000000); // Delay for remaining cycle time (in microseconds)
    }

    // This point is reached only if program_running is set to 0 by the signal handler
    printf("Plant watering system stopped\n");

    return 0;
}

