#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to store gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to store timestamped gyroscope data
typedef struct {
    gyro_data_t data;
    long long timestamp;
} gyro_reading_t;

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
gyro_reading_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_gyro_data(gyro_data_t *data);
void update_led(gyro_data_t data);
void add_to_buffer(gyro_reading_t reading);
gyro_reading_t get_from_buffer(int index);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication.\n");
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (wiringPiI2CWriteReg8(i2c_fd, PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050.\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    int retries = 3;
    while (retries > 0) {
        int16_t x = wiringPiI2CReadReg16(i2c_fd, GYRO_XOUT_H);
        int16_t y = wiringPiI2CReadReg16(i2c_fd, GYRO_YOUT_H);
        int16_t z = wiringPiI2CReadReg16(i2c_fd, GYRO_ZOUT_H);

        if (x != -1 && y != -1 && z != -1) {
            data->x = x;
            data->y = y;
            data->z = z;
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
            retries--;
            delay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Error: Failed to read gyroscope data after multiple retries.\n");
    return -1; // Failure
}

// Function to update the LED based on gyroscope data
void update_led(gyro_data_t data) {
    if (fabs(data.x) > 250 || fabs(data.y) > 250 || fabs(data.z) > 250) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Function to add data to the circular buffer
void add_to_buffer(gyro_reading_t reading) {
    gyro_buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get data from the circular buffer
gyro_reading_t get_from_buffer(int index) {
    return gyro_buffer[index];
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU-6050 Gyroscope Data Acquisition\n");

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;
        gyro_reading_t gyro_reading;

        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Get timestamp
            gyro_reading.timestamp = millis();
            gyro_reading.data = gyro_data;

            // Add data to circular buffer
            add_to_buffer(gyro_reading);

            // Update LED
            update_led(gyro_data);

            // Print data (optional)
            //printf("X: %d, Y: %d, Z: %d\n", gyro_data.x, gyro_data.y, gyro_data.z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Attempting to re-initialize I2C.\n");
            // Attempt to re-initialize I2C
            if (init_i2c() == -1) {
                fprintf(stderr, "Error: Failed to re-initialize I2C. Exiting.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }

        delay(50); // Sample at approximately 20 Hz
    }

    // Clean up
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(i2c_fd); // Close I2C file descriptor

    printf("Program terminated.\n");
    return 0;
}

