#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-9250 Register Addresses
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define CS_GPIO     8       // GPIO8 (BCM)

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg);
int spi_write_register(int reg, int value);
int read_gyro_data(float *x_rate, float *y_rate, float *z_rate);
char *get_iso8601_timestamp(char *timestamp);
int log_data(const char *timestamp, float x_rate, float y_rate, float z_rate);
void signal_handler(int signal);
int initialize_mpu9250();

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(int reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read operation
    tx[1] = 0x00;       // Dummy byte for reading

    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    return (rx[1] << 8) | rx[0]; // Combine the two bytes
}

// SPI Write Register Function
int spi_write_register(int reg, int value) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write operation
    tx[1] = value & 0xFF;

    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Read Gyro Data Function
int read_gyro_data(float *x_rate, float *y_rate, float *z_rate) {
    int16_t raw_x, raw_y, raw_z;

    raw_x = (int16_t)((spi_read_register(GYRO_XOUT_H) << 8) | spi_read_register(GYRO_XOUT_L));
    raw_y = (int16_t)((spi_read_register(GYRO_YOUT_H) << 8) | spi_read_register(GYRO_YOUT_L));
    raw_z = (int16_t)((spi_read_register(GYRO_ZOUT_H) << 8) | spi_read_register(GYRO_ZOUT_L));

    // Convert to degrees per second (assuming +/- 250 dps sensitivity)
    *x_rate = (float)raw_x / 131.0;
    *y_rate = (float)raw_y / 131.0;
    *z_rate = (float)raw_z / 131.0;

    return 0;
}

// Get ISO 8601 Timestamp Function
char *get_iso8601_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 30 - strlen(timestamp), ".%09ldZ", ts.tv_nsec);
    return timestamp;
}

// Log Data Function
int log_data(const char *timestamp, float x_rate, float y_rate, float z_rate) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    int result = fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate);
    if (result < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Initialize MPU-9250 Function
int initialize_mpu9250() {
    // Wake up the MPU-9250
    if (spi_write_register(PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error waking up MPU-9250.\n");
        return -1;
    }

    // Configure gyroscope sensitivity (+/- 250 dps)
    if (spi_write_register(GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error configuring gyroscope sensitivity.\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS GPIO as output
    gpioSetMode(CS_GPIO, PI_OUTPUT);
    gpioWrite(CS_GPIO, 1); // De-assert CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-9250
    if (initialize_mpu9250() != 0) {
        fprintf(stderr, "MPU-9250 initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x_rate, y_rate, z_rate;
    char timestamp[30];

    // Main loop
    while (!terminate) {
        // Read gyro data
        if (read_gyro_data(&x_rate, &y_rate, &z_rate) == 0) {
            // Get timestamp
            get_iso8601_timestamp(timestamp);

            // Log data
            if (log_data(timestamp, x_rate, y_rate, z_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

