int read_gyro_data(float *x, float *y, float *z) {
    char tx_buf[1], rx_buf[6];
    tx_buf[0] = MPU6050_GYRO_XOUT_H | 0x80; // Read multiple bytes

    if (spiXfer(spi_handle, tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "Error reading from MPU6050\n");
        return -1;
    }

    int16_t gyro_x = (rx_buf[1] << 8) | rx_buf[2];
