void print_buffer_as_csv() {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               gyro_buffer[index].timestamp.tv_sec,
               gyro_buffer[index].timestamp.tv_nsec,
               gyro_buffer[index].x,
               gyro_buffer[index].y,
               gyro_buffer[index].z);
    }
}

