    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, skipping sample.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US); // Delay for 10ms (100Hz)
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    // Print the buffer as CSV
    print_buffer_as_csv();

    return 0;
}

