#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// LED GPIO pin
#define LED_PIN 21

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch);
void control_led(float roll, float pitch);
void log_data(float roll, float pitch);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read raw accelerometer data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate roll and pitch
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    *roll = atan2(accel_y, accel_z) * 180 / M_PI;
    *pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45 || fabs(pitch) > 45) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    float roll, pitch;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z) == 0) {
            // Calculate roll and pitch
            calculate_roll_pitch(accel_x, accel_y, accel_z, &roll, &pitch);

            // Print roll and pitch to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

            // Control LED
            control_led(roll, pitch);

            // Log data to file
            log_data(roll, pitch);
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

