#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0        // CPOL=0, CPHA=0

// Define GPIO pin for chip select (CS/CE0)
#define CS_PIN 8

// Define ADXRS290 register addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    long long timestamp_us;
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int spi_read_register(uint8_t reg_addr, uint8_t *data);
int spi_write_register(uint8_t reg_addr, uint8_t data);
int read_gyro_data(gyro_data_t *data);
int log_data(gyro_data_t data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read a register from the ADXRS290
int spi_read_register(uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00;            // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// Function to write a register to the ADXRS290
int spi_write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    uint8_t x_rate_msb, x_rate_lsb, y_rate_msb, y_rate_lsb;

    if (spi_read_register(ADXRS290_REG_X_RATE, &x_rate_msb) != 0) {
        fprintf(stderr, "Error reading X rate MSB\n");
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_X_RATE + 1, &x_rate_lsb) != 0) {
        fprintf(stderr, "Error reading X rate LSB\n");
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_Y_RATE, &y_rate_msb) != 0) {
        fprintf(stderr, "Error reading Y rate MSB\n");
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_Y_RATE + 1, &y_rate_lsb) != 0) {
        fprintf(stderr, "Error reading Y rate LSB\n");
        return -1;
    }

    data->x_rate = (int16_t)((x_rate_msb << 8) | x_rate_lsb);
    data->y_rate = (int16_t)((y_rate_msb << 8) | y_rate_lsb);

    return 0;
}

// Function to log data to a CSV file
int log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (fprintf(fp, "%lld,%d,%d\n", data.timestamp_us, data.x_rate, data.y_rate) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open CSV file for writing
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write CSV header
    fprintf(fp, "timestamp_us,x_rate,y_rate\n");

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    gyro_data_t gyro_data;
    int retry_count = 0;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            if (log_data(gyro_data) != 0) {
                fprintf(stderr, "Error logging data, retrying SPI initialization...\n");
                retry_count++;
                if (retry_count > 3) {
                    fprintf(stderr, "Too many retries, exiting.\n");
                    terminate = 1;
                }
                spiClose(spi_handle);
                gpioTerminate();
                if (initialize() != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting.\n");
                    terminate = 1;
                }
            } else {
                retry_count = 0; // Reset retry count on success
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying SPI initialization...\n");
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Too many retries, exiting.\n");
                terminate = 1;
            }
            spiClose(spi_handle);
            gpioTerminate();
            if (initialize() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                terminate = 1;
            }
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

