    if (spi_read_register(ADXRS290_REG_X_RATE, &x_rate_msb) != 0) {
        fprintf(stderr, "Error reading X rate MSB\n");
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_X_RATE + 1, &x_rate_lsb) != 0) {
        fprintf(stderr, "Error reading X rate LSB\n");
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_Y_RATE, &y_rate_msb) != 0) {
        fprintf(stderr, "Error reading Y rate MSB\n");
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_Y_RATE + 1, &y_rate_lsb) != 0) {
        fprintf(stderr, "Error reading Y rate LSB\n");
        return -1;
    }

    data->x_rate = (int16_t)((x_rate_msb << 8) | x_rate_lsb);
    data->y_rate = (int16_t)((y_rate_msb << 8) | y_rate_lsb);

    return 0;
}

// Function to log data to a CSV file
int log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (fprintf(fp, "%lld,%d,%d\n", data.timestamp_us, data.x_rate, data.y_rate) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open CSV file for writing
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write CSV header
    fprintf(fp, "timestamp_us,x_rate,y_rate\n");

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    gyro_data_t gyro_data;
    int retry_count = 0;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            if (log_data(gyro_data) != 0) {
                fprintf(stderr, "Error logging data, retrying SPI initialization...\n");
                retry_count++;
                if (retry_count > 3) {
                    fprintf(stderr, "Too many retries, exiting.\n");
                    terminate = 1;
                }
                spiClose(spi_handle);
                gpioTerminate();
                if (initialize() != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting.\n");
                    terminate = 1;
                }
            } else {
                retry_count = 0; // Reset retry count on success
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying SPI initialization...\n");
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Too many retries, exiting.\n");
                terminate = 1;
            }
            spiClose(spi_handle);
            gpioTerminate();
            if (initialize() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                terminate = 1;
            }
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

