#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define DEBOUNCE_DELAY_MS 500

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void sensor_callback(int gpio, int level, uint32_t tick);
void trigger_alert();
void log_event();
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Cleanup
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio

    exit(0);
}

// Sensor callback function
void sensor_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();
    uint32_t diff = current_tick - last_tick;

    if (diff > DEBOUNCE_DELAY_MS * 1000) { // Debounce
        last_tick = current_tick;

        if (gpio == SENSOR_1_PIN) {
            gpioWrite(ALERT_PIN, level);
        } else if (gpio == SENSOR_2_PIN) {
            gpioWrite(ALERT_PIN, level);
        }

        if (gpioRead(SENSOR_1_PIN) == 1 && gpioRead(SENSOR_2_PIN) == 1) {
            trigger_alert();
        }
    }
}

// Trigger alert function
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
    gpioDelay(ALERT_DURATION_MS * 1000); // Wait for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
    log_event(); // Log the event
}

