void log_event() {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buffer;
}

