        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic event detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

