#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SPI_CE0 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define LED_PIN 17

// Define ADXRS290 register addresses
#define ADXRS290_X_RATE_REG 0x00
#define ADXRS290_Y_RATE_REG 0x02
#define ADXRS290_TEMP_REG 0x04
#define ADXRS290_DIAG_REG 0x06
#define ADXRS290_GLOB_CMD 0x08

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define circular buffer size
#define BUFFER_SIZE 100

// Define threshold for angular rate
#define THRESHOLD 20.0

// Structure to store gyroscope data
typedef struct {
    struct timespec timestamp;
    float x_rate;
    float y_rate;
    float temperature;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(uint8_t address, uint16_t *data);
int spi_write_register(uint8_t address, uint16_t data);
void circular_buffer_init(circular_buffer_t *cb);
int circular_buffer_add(circular_buffer_t *cb, gyro_data_t data);
int circular_buffer_get(circular_buffer_t *cb, gyro_data_t *data, int index);
void signal_handler(int signal);

// SPI read function
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Set read bit (MSB) in the address
    tx_buf[0] = address | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading MSB
    tx_buf[2] = 0x00; // Dummy byte for reading LSB

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// SPI write function
int spi_write_register(uint8_t address, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address & 0x7F; // Clear read bit
    tx_buf[1] = (data >> 8) & 0xFF; // MSB
    tx_buf[2] = data & 0xFF;      // LSB

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Circular buffer initialization function
void circular_buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

// Circular buffer add function
int circular_buffer_add(circular_buffer_t *cb, gyro_data_t data) {
    if (cb->count == BUFFER_SIZE) {
        // Buffer is full, overwrite the oldest data
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    return 0;
}

// Circular buffer get function
int circular_buffer_get(circular_buffer_t *cb, gyro_data_t *data, int index) {
    if (index < 0 || index >= cb->count) {
        return -1; // Invalid index
    }
    int actual_index = (cb->tail + index) % BUFFER_SIZE;
    *data = cb->buffer[actual_index];
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_init(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t x_rate_raw, y_rate_raw, temperature_raw;
    float x_rate, y_rate, temperature;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read X-axis angular rate
        if (spi_read_register(ADXRS290_X_RATE_REG, &x_rate_raw) != 0) {
            fprintf(stderr, "Error reading X-axis rate\n");
            continue;
        }

        // Read Y-axis angular rate
        if (spi_read_register(ADXRS290_Y_RATE_REG, &y_rate_raw) != 0) {
            fprintf(stderr, "Error reading Y-axis rate\n");
            continue;
        }

        // Read temperature
        if (spi_read_register(ADXRS290_TEMP_REG, &temperature_raw) != 0) {
            fprintf(stderr, "Error reading temperature\n");
            continue;
        }

        // Convert raw data to degrees per second (adjust scaling as needed)
        x_rate = (float)x_rate_raw / 100.0; // Example scaling, adjust based on datasheet
        y_rate = (float)y_rate_raw / 100.0; // Example scaling, adjust based on datasheet
        temperature = (float)temperature_raw / 100.0; // Example scaling, adjust based on datasheet

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }

        // Store data in circular buffer
        gyro_data_t gyro_data;
        gyro_data.timestamp = ts;
        gyro_data.x_rate = x_rate;
        gyro_data.y_rate = y_rate;
        gyro_data.temperature = temperature;
        circular_buffer_add(&gyro_buffer, gyro_data);

        // Check threshold and control LED
        if (fabs(x_rate) > THRESHOLD || fabs(y_rate) > THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn LED on
        } else {
            gpioWrite(LED_PIN, 0); // Turn LED off
        }

        // Print data (optional)
        printf("X: %.2f deg/s, Y: %.2f deg/s, Temp: %.2f C\n", x_rate, y_rate, temperature);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

