#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Global variable to store the total fade duration
int total_duration = 0;

// Function prototypes
void fade_lamp(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to fade a lamp
void fade_lamp(int gpio, int duration) {
    int start_time = time(NULL);
    int current_time;
    int duty_cycle;

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    while (1) {
        current_time = time(NULL);
        if (current_time - start_time >= duration) {
            break;
        }

        // Calculate the duty cycle based on the elapsed time
        duty_cycle = (int)(((float)(current_time - start_time) / duration) * 255.0);

        // Set the PWM duty cycle
        gpioPWM(gpio, duty_cycle);

        // Small delay to control the fading speed
        usleep(10000); // 10ms
    }

    // Turn off the lamp after fading
    gpioPWM(gpio, 0);
    printf("Lamp on GPIO %d faded to off.\n", gpio);
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the total duration from the command-line argument
    total_duration = atoi(argv[1]);

    // Validate the total duration
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, total_duration / 3);
    fade_lamp(LAMP2_GPIO, total_duration / 3);
    fade_lamp(LAMP3_GPIO, total_duration / 3);

    // Ensure all lamps are off before exiting
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    printf("Sunset simulation complete.\n");

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

