#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for traffic lights (BCM numbering)
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define FLASH_PIN 24

// Define timing constants (in seconds)
#define RED_TIME    10
#define RED_YELLOW_TIME 2
#define GREEN_TIME  10
#define YELLOW_TIME 3
#define FLASH_TIME  1

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to transition to the red state
int transition_red() {
    if (set_gpio_state(RED_PIN, 0) != 0) return -1;
    if (set_gpio_state(YELLOW_PIN, 1) != 0) return -1;
    if (set_gpio_state(GREEN_PIN, 1) != 0) return -1;
    if (set_gpio_state(FLASH_PIN, 1) != 0) return -1;
    printf("Transitioned to RED\n");
    return 0;
}

// Function to transition to the red + yellow state
int transition_red_yellow() {
    if (set_gpio_state(RED_PIN, 0) != 0) return -1;
    if (set_gpio_state(YELLOW_PIN, 0) != 0) return -1;
    if (set_gpio_state(GREEN_PIN, 1) != 0) return -1;
    if (set_gpio_state(FLASH_PIN, 1) != 0) return -1;
    printf("Transitioned to RED + YELLOW\n");
    return 0;
}

// Function to transition to the green state
int transition_green() {
    if (set_gpio_state(RED_PIN, 1) != 0) return -1;
    if (set_gpio_state(YELLOW_PIN, 1) != 0) return -1;
    if (set_gpio_state(GREEN_PIN, 0) != 0) return -1;
    if (set_gpio_state(FLASH_PIN, 1) != 0) return -1;
    printf("Transitioned to GREEN\n");
    return 0;
}

