int transition_red_after_flash() {
    if (set_gpio_state(RED_PIN, 0) != 0) return -1;
    if (set_gpio_state(YELLOW_PIN, 1) != 0) return -1;
    if (set_gpio_state(GREEN_PIN, 1) != 0) return -1;
    if (set_gpio_state(FLASH_PIN, 1) != 0) return -1;
    printf("Transitioned to RED after FLASH\n");
    return 0;
