    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RED_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set YELLOW_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GREEN_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(FLASH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FLASH_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Red state
        if (transition_red() != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(RED_TIME * 1000000); // 10 seconds

        // Red + Yellow state
        if (transition_red_yellow() != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(RED_YELLOW_TIME * 1000000); // 2 seconds

        // Green state
        if (transition_green() != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(GREEN_TIME * 1000000); // 10 seconds

        // Yellow state
        if (transition_yellow() != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(YELLOW_TIME * 1000000); // 3 seconds

        // Flash state
        if (transition_flash() != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(FLASH_TIME * 1000000); // 1 second

