#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE_NAME "flame_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int log_flame_detection();
int activate_buzzer_led(int state);
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_PIN);
    if (reading < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", reading);
        return -1; // Indicate error
    }
    return reading;
}

// Function to log flame detection to a file
int log_flame_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to activate the buzzer and LED
int activate_buzzer_led(int state) {
    if (gpioWrite(BUZZER_PIN, state) < 0) {
        fprintf(stderr, "Error writing to buzzer pin.\n");
        return -1;
    }
    if (gpioWrite(LED_PIN, state) < 0) {
        fprintf(stderr, "Error writing to LED pin.\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting flame sensor pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flame_detected = 0;
    int consecutive_low_reads = 0;

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (sensor_value == 0) {
            consecutive_low_reads++;
            if (consecutive_low_reads >= 3) {
                if (!flame_detected) {
                    printf("Flame detected!\n");
                    if (log_flame_detection() == 0) {
                        printf("Flame detection logged.\n");
                    } else {
                        fprintf(stderr, "Error logging flame detection.\n");
                    }
