#define DISPENSE_DURATION 1000

// Define half dispense duration in milliseconds
#define HALF_DISPENSE_DURATION (DISPENSE_DURATION / 2)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void dispense_solenoid(int pin, int duration_ms);
void deactivate_solenoid(int pin);
void log_dispense_event(int pin1, int pin2, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Exiting gracefully...\n");
        program_running = 0;

        // Deactivate solenoids
        deactivate_solenoid(SOLENOID_1_PIN);
        deactivate_solenoid(SOLENOID_2_PIN);

        // Terminate pigpio library
        gpioTerminate();

        exit(0);
    }
}

