    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a solenoid for a specified duration
void dispense_solenoid(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Activate solenoid
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    deactivate_solenoid(pin); // Deactivate solenoid
}

// Function to deactivate a solenoid
void deactivate_solenoid(int pin) {
    gpioWrite(pin, 0); // Deactivate solenoid
}

// Function to log dispense events to a file
void log_dispense_event(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening dispense_log.txt for writing\n");
        return; // Exit if file opening fails
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Solenoid %d, Solenoid %d, Duration: %d ms\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pin1, pin2, duration_ms);

    fclose(fp);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense from solenoid 1
        dispense_solenoid(SOLENOID_1_PIN, HALF_DISPENSE_DURATION);

        // Dispense from solenoid 2
        dispense_solenoid(SOLENOID_2_PIN, HALF_DISPENSE_DURATION);

        // Log the dispense event
        log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Deactivate solenoids and terminate pigpio (should not reach here if signal handler works)
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    return 0;
}

