#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENB 25

// Ultrasonic Sensor
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// PID Gains
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Motor Speed Limits
#define MAX_SPEED 255
#define MIN_SPEED -255

// Global Variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// PID Variables
float integral = 0.0;
float previous_error = 0.0;

// Function Prototypes
void signal_handler(int signal);
void stop_motors();
void set_motor_speed(int motor_a_pin, int motor_b_pin, int motor_a_speed, int motor_b_speed);
float simulate_tilt_error();
float simulate_distance();
float calculate_pid(float setpoint, float actual_value);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Stop Motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(MOTOR_A_ENA, 0);
    gpioPWM(MOTOR_B_ENB, 0);
}

// Set Motor Speed
void set_motor_speed(int motor_a_pin, int motor_b_pin, int motor_a_speed, int motor_b_speed) {
    // Clamp motor speeds
    if (motor_a_speed > MAX_SPEED) motor_a_speed = MAX_SPEED;
    if (motor_a_speed < MIN_SPEED) motor_a_speed = MIN_SPEED;
    if (motor_b_speed > MAX_SPEED) motor_b_speed = MAX_SPEED;
    if (motor_b_speed < MIN_SPEED) motor_b_speed = MIN_SPEED;

    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(motor_a_pin, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENA, abs(motor_a_speed));
    } else if (motor_a_speed < 0) {
        gpioWrite(motor_a_pin, 0);
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioPWM(MOTOR_A_ENA, abs(motor_a_speed));
    } else {
        gpioWrite(motor_a_pin, 0);
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENA, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(motor_b_pin, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENB, abs(motor_b_speed));
    } else if (motor_b_speed < 0) {
        gpioWrite(motor_b_pin, 0);
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioPWM(MOTOR_B_ENB, abs(motor_b_speed));
    } else {
        gpioWrite(motor_b_pin, 0);
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENB, 0);
    }
}

// Simulate Tilt Error
float simulate_tilt_error() {
    return (float)(rand() % 21 - 10); // Random float between -10.0 and 10.0
}

// Simulate Distance
float simulate_distance() {
    return (float)(rand() % 400 + 2); // Random float between 2.0 and 400.0
}

// Calculate PID Output
float calculate_pid(float setpoint, float actual_value) {
    float error = setpoint - actual_value;
    integral += error;
    float derivative = error - previous_error;
    float output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

// Log Data
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENB, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize PWM
    gpioSetPWMfrequency(MOTOR_A_ENA, 1000); // 1 kHz
    gpioSetPWMfrequency(MOTOR_B_ENB, 1000); // 1 kHz
    gpioSetPWMrange(MOTOR_A_ENA, 255);
    gpioSetPWMrange(MOTOR_B_ENB, 255);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate sensor readings
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        // Calculate PID output
        float pid_output = calculate_pid(0.0, tilt_error); // Setpoint is 0

        // Obstacle avoidance
        int motor_a_speed = 0;
        int motor_b_speed = 0;
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -128; // Reverse Motor A
            motor_b_speed = -128; // Reverse Motor B
        } else {
            motor_a_speed = (int)pid_output;
            motor_b_speed = (int)pid_output;
        }

        // Set motor speeds
        set_motor_speed(MOTOR_A_FORWARD, MOTOR_B_FORWARD, motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

