    return output;
}

// Log Data
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENB, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize PWM
    gpioSetPWMfrequency(MOTOR_A_ENA, 1000); // 1 kHz
    gpioSetPWMfrequency(MOTOR_B_ENB, 1000); // 1 kHz
    gpioSetPWMrange(MOTOR_A_ENA, 255);
    gpioSetPWMrange(MOTOR_B_ENB, 255);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate sensor readings
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        // Calculate PID output
        float pid_output = calculate_pid(0.0, tilt_error); // Setpoint is 0

        // Obstacle avoidance
        int motor_a_speed = 0;
        int motor_b_speed = 0;
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -128; // Reverse Motor A
            motor_b_speed = -128; // Reverse Motor B
        } else {
            motor_a_speed = (int)pid_output;
            motor_b_speed = (int)pid_output;
        }

        // Set motor speeds
        set_motor_speed(MOTOR_A_FORWARD, MOTOR_B_FORWARD, motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

