// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN to input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN to output\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    int current_relay_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_relay_state);
}

// Function to debounce the touch sensor
void debounce() {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
            debounce();
        }
        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

