#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Default sensitivity
#define DEFAULT_SENSITIVITY 1.0

// ALSA device name
#define ALSA_DEVICE "default"

// ALSA parameters
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16
#define PERIOD_SIZE 1024

// Global variables
snd_pcm_t *pcm_handle;
int running = 1;
double sensitivity = DEFAULT_SENSITIVITY;

// Function prototypes
double calculate_rms(const short *buffer, int buffer_size);
void map_amplitude_to_rgb(double rms_amplitude, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);
int initialize_alsa();
void cleanup_alsa();

// Function to calculate RMS amplitude
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    double mean_square = sum_of_squares / buffer_size;
    return sqrt(mean_square);
}

// Function to map RMS amplitude to RGB color values
void map_amplitude_to_rgb(double rms_amplitude, int *red, int *green, int *blue) {
    // Scale RMS amplitude by sensitivity
    double scaled_amplitude = rms_amplitude * sensitivity;

    // Normalize amplitude to a range of 0-1
    double normalized_amplitude = scaled_amplitude / 32768.0; // Assuming 16-bit signed integers
    if (normalized_amplitude > 1.0) normalized_amplitude = 1.0;
    if (normalized_amplitude < 0.0) normalized_amplitude = 0.0;

    // Map amplitude to RGB values (example: sine wave)
    double hue = normalized_amplitude * M_PI * 2.0; // Map 0-1 to 0-2pi
    *red   = (int)(128 + 127 * sin(hue + 2 * M_PI / 3));
    *green = (int)(128 + 127 * sin(hue));
    *blue  = (int)(128 + 127 * sin(hue - 2 * M_PI / 3));

    // Ensure values are within the valid range (0-255)
    if (*red < 0) *red = 0;
    if (*red > 255) *red = 255;
    if (*green < 0) *green = 0;
    if (*green > 255) *green = 255;
    if (*blue < 0) *blue = 0;
    if (*blue > 255) *blue = 255;
}

// Function to set the RGB LED color using software PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize ALSA
int initialize_alsa() {
    snd_pcm_hw_params_t *hw_params;
    int err;

    // Open PCM device for capture
    if ((err = snd_pcm_open(&pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set format
    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set sample rate
    int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: Sample rate changed to %d\n", rate);
    }

    // Set period size
    snd_pcm_uframes_t period_size = PERIOD_SIZE;
    if ((err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &period_size, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Prepare PCM device
    if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    printf("ALSA initialized successfully.\n");
    return 0;
}

// Function to cleanup ALSA
void cleanup_alsa() {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
        printf("ALSA closed.\n");
    }
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Error: Sensitivity must be a positive number. Using default value.\n");
            sensitivity = DEFAULT_SENSITIVITY;
        }
        printf("Using sensitivity: %f\n", sensitivity);
    } else {
        printf("Using default sensitivity: %f\n", sensitivity);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Initialize ALSA
    if (initialize_alsa() != 0) {
        fprintf(stderr, "ALSA initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Allocate buffer for audio data
    short *buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (!buffer) {
        fprintf(stderr, "Error allocating memory for audio buffer.\n");
        cleanup_alsa();
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int err;

        // Read audio data from ALSA
        if ((err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE)) != PERIOD_SIZE) {
            if (err == -EPIPE) {
                // EPIPE occurred, recover
                fprintf(stderr, "Overrun occurred, recovering...\n");
                snd_pcm_prepare(pcm_handle);
            } else if (err == -ESTRPIPE) {
                // Device suspended, resume
                fprintf(stderr, "Device suspended, resuming...\n");
                snd_pcm_resume(pcm_handle);
            } else {
                fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(err));
            }
        } else {
            // Calculate RMS amplitude
            double rms_amplitude = calculate_rms(buffer, PERIOD_SIZE);

            // Map amplitude to RGB color values
            int red, green, blue;
            map_amplitude_to_rgb(rms_amplitude, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            // Print status message
            printf("RMS Amplitude: %f, RGB: (%d, %d, %d)\n", rms_amplitude, red, green, blue);
        }

        // Delay for 10ms
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    free(buffer);
    cleanup_alsa();
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

