#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x92
#define TCS34725_RDATA 0x94
#define TCS34725_GDATA 0x96
#define TCS34725_BDATA 0x98

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_tcs34725();
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME) to 154ms (0xD5)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error: Could not set integration time\n");
        return -1;
    }

    return 0;
}

// Read color data from the TCS34725 sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result;

    result = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (result < 0) {
        fprintf(stderr, "Error: Could not read clear data\n");
        *clear = 0; // Set to 0 on error
    } else {
        *clear = (uint16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (result < 0) {
        fprintf(stderr, "Error: Could not read red data\n");
        *red = 0; // Set to 0 on error
    } else {
        *red = (uint16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (result < 0) {
        fprintf(stderr, "Error: Could not read green data\n");
        *green = 0; // Set to 0 on error
    } else {
        *green = (uint16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (result < 0) {
        fprintf(stderr, "Error: Could not read blue data\n");
        *blue = 0; // Set to 0 on error
    } else {
        *blue = (uint16_t)result;
    }

    return 0;
}

// Log the color data to a CSV file
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (init_tcs34725() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open color_data.csv for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row
    fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;

    // Main loop
    while (!terminate) {
        // Read color data
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            // Log the data
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error: Failed to read color data. Logging zeros.\n");
            log_data(0, 0, 0, 0);
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

