#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;

    // Turn off all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Function to simulate sunrise
void sunrise() {
    int i;
    for (i = 0; i <= 100 && program_running; i++) {
        gpioWrite(RELAY1_PIN, (i % 2 == 0) ? 0 : 1);
        gpioWrite(RELAY2_PIN, (i % 2 == 0) ? 0 : 1);
        gpioWrite(RELAY3_PIN, (i % 2 == 0) ? 0 : 1);
        gpioWrite(RELAY4_PIN, (i % 2 == 0) ? 0 : 1);
        gpioDelay(SUNRISE_DURATION / 100); // Simulate PWM with a delay
    }
}

// Function to simulate daytime
void daytime() {
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
    sleep(DAYTIME_DURATION);
}

// Function to simulate sunset
void sunset() {
    int i;
    for (i = 100; i >= 0 && program_running; i--) {
        gpioWrite(RELAY1_PIN, (i % 2 == 0) ? 0 : 1);
        gpioWrite(RELAY2_PIN, (i % 2 == 0) ? 0 : 1);
        gpioWrite(RELAY3_PIN, (i % 2 == 0) ? 0 : 1);
        gpioWrite(RELAY4_PIN, (i % 2 == 0) ? 0 : 1);
        gpioDelay(SUNSET_DURATION / 100); // Simulate PWM with a delay
    }
}

// Function to simulate nighttime
void nighttime() {
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
    sleep(NIGHTTIME_DURATION);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sunrise/Sunset simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
    gpioTerminate();

    return 0;
}

