#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_CAPTURE_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log motion events to a file
void log_motion_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to capture video using raspivid
int capture_video() {
    char command[256];
    char timestamp[25];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 25, "%Y%m%d_%H%M%S", timeinfo);

    snprintf(command, sizeof(command), "raspivid -o %s%s.h264 -t %d000", VIDEO_DIR, timestamp, VIDEO_CAPTURE_DURATION_S);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: Failed to execute raspivid command.\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid command failed with exit status %d.\n", WEXITSTATUS(status));
        return -1;
    }

    printf("Video captured: %s%s.h264\n", VIDEO_DIR, timestamp);
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    int sensor_value;
    int last_state = 1; // Assume initially no motion (HIGH)
    time_t last_motion_time = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value == 0 && last_state == 1) { // Motion detected (LOW)
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= (DEBOUNCE_DELAY_MS / 1000.0)) {
                char *timestamp = get_iso8601_timestamp();
                log_motion_event(timestamp);
                free(timestamp);

                if (capture_video() != 0) {
                    fprintf(stderr, "Error: Video capture failed.\n");
                }

                last_motion_time = current_time;
            }
        }

        last_state = sensor_value;
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

