#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address (AD0 low)
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void process_gyro_data(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps);
void log_data(float x_degps, float y_degps, float z_degps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU-6050 (set sleep bit to 0)
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0);
        if (status != 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Configure gyroscope range (+/- 250 deg/s)
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Initialization failed
}

// Read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Process raw data and convert to degrees per second
void process_gyro_data(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps) {
    *x_degps = (float)x / GYRO_SENSITIVITY;
    *y_degps = (float)y / GYRO_SENSITIVITY;
    *z_degps = (float)z / GYRO_SENSITIVITY;
}

// Log data to file
void log_data(float x_degps, float y_degps, float z_degps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", timestamp_ms, x_degps, y_degps, z_degps);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float x_degps, y_degps, z_degps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Process data
            process_gyro_data(x, y, z, &x_degps, &y_degps, &z_degps);

            // Log data
            log_data(x_degps, y_degps, z_degps);
        } else {
            fprintf(stderr, "Error reading gyro data, attempting to re-initialize...\n");
            // Attempt to re-initialize the sensor
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Failed to re-initialize MPU-6050\n");
            }
        }

        gpioDelay(10000); // 10ms delay (100Hz sampling rate)
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

