#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int gpio_pin, int moisture_level);
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initially deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Read moisture sensor (simulated)
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    unsigned int seed = time(NULL);
    srand(seed);

    // Generate a random moisture level between 0 and 100
    int moisture_level = rand() % 101;

    return moisture_level;
}

// Control relay based on moisture level
void control_relay(int gpio_pin, int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        // Activate relay (drive pin LOW)
        gpioWrite(gpio_pin, 0);
    } else {
        // Deactivate relay (drive pin HIGH)
        gpioWrite(gpio_pin, 1);
    }
}

// Log data to file
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    FILE *fp = fopen("irrigation_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            moisture_level,
            relay1_state == 0 ? "ON" : "OFF",
            relay2_state == 0 ? "ON" : "OFF",
            relay3_state == 0 ? "ON" : "OFF",
            relay4_state == 0 ? "ON" : "OFF");

    fclose(fp);
}

int main() {
    // Install signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read moisture sensor
        int moisture_level = read_moisture_sensor();
        printf("Moisture level: %d\n", moisture_level);

        // Control relays
        control_relay(RELAY1_PIN, moisture_level);
        control_relay(RELAY2_PIN, moisture_level);
        control_relay(RELAY3_PIN, moisture_level);
        control_relay(RELAY4_PIN, moisture_level);

        // Get relay states
        int relay1_state = gpioRead(RELAY1_PIN);
        int relay2_state = gpioRead(RELAY2_PIN);
        int relay3_state = gpioRead(RELAY3_PIN);
        int relay4_state = gpioRead(RELAY4_PIN);

        // Log data
        log_data(moisture_level, relay1_state, relay2_state, relay3_state, relay4_state);

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
    gpioTerminate();

    return 0;
}

