#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// Free-fall threshold
#define FREEFALL_THRESHOLD 0.2

// GPIO pin for alarm
#define ALARM_PIN 27

// I2C file descriptor
static int i2c_fd = -1;

// Function prototypes
int adxl345_init(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
bool is_freefall(float x, float y, float z);
void trigger_alarm(int pin);
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int adxl345_init(int fd) {
    if (wiringPiI2CWriteReg8(fd, POWER_CTL, 0x08) < 0) { // Enable measurement mode
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, DATA_FORMAT, 0x08) < 0) { // Set range to +/- 2g
        fprintf(stderr, "Error writing to DATA_FORMAT register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

