#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define MAX_PULSE_WIDTH 23200 // us
#define TIMEOUT_MS 100
#define TRIGGER_PULSE_US 10

// Global variables
static volatile unsigned int rising_tick = 0;
static volatile unsigned int falling_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_occurred = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        rising_tick = tick;
        echo_received = 1;
        timeout_occurred = 0; // Reset timeout flag
        pthread_mutex_unlock(&mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&mutex);
        falling_tick = tick;
        if (rising_tick != 0) {
            unsigned int pulse_width = falling_tick - rising_tick;
            if (pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Error: Pulse width exceeds maximum allowed value (%d us). Discarding measurement.\n", MAX_PULSE_WIDTH);
                echo_received = 0; // Reset echo received flag
                timeout_occurred = 0; // Reset timeout flag
            } else {
                double distance = calculate_distance(pulse_width);
                if (distance > 0 && distance <= MAX_DISTANCE) {
                    log_distance(distance);
                } else {
                    fprintf(stderr, "Error: Invalid distance calculated (%lf cm). Discarding measurement.\n", distance);
                }
            }
        } else {
            fprintf(stderr, "Error: Missing rising edge. Discarding measurement.\n");
            timeout_occurred = 1; // Set timeout flag
        }
        echo_received = 0; // Reset echo received flag
        pthread_mutex_unlock(&mutex);
    }
}

// Function to calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    unsigned int timestamp_ns = (unsigned int)(ts.tv_sec * 1000000000 + ts.tv_nsec);

    if (log_file != NULL) {
        fprintf(log_file, "%u,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Install interrupt callbacks
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(TIMEOUT_MS * 1000); // Delay between trigger cycles

        // Check for timeout
        pthread_mutex_lock(&mutex);
        if (echo_received == 0 && timeout_occurred == 0) {
            fprintf(stderr, "Error: Timeout occurred. No echo received within %d ms.\n", TIMEOUT_MS);
            timeout_occurred = 1; // Set timeout flag
        }
        pthread_mutex_unlock(&mutex);
    }

    return 0;
}

