#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18 // Or 0x19, check your sensor
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define BUZZER_GPIO 17
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define NUM_RETRIES 3

// Global variables
static int i2c_handle;
static volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_lis3dh();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
bool detect_freefall(float magnitude);
bool detect_impact(float magnitude);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH accelerometer
int init_lis3dh() {
    int retries = NUM_RETRIES;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x27) >= 0) { // Enable all axes, 100Hz data rate
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to initialize CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    retries = NUM_RETRIES;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) >= 0) { // +/- 2g full scale
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to initialize CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];
    int retries = NUM_RETRIES;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, raw_data, 6) == 6) {
            break;
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read accelerometer data after multiple retries.\n");
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to g-force units
    data.x = (float)((int16_t)((raw_data[1] << 8) | raw_data[0])) / 16384.0f; // +/- 2g
    data.y = (float)((int16_t)((raw_data[3] << 8) | raw_data[2])) / 16384.0f;
    data.z = (float)((int16_t)((raw_data[5] << 8) | raw_data[4])) / 16384.0f;

    return data;
}

