    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Calculate the number of steps required to draw a 50mm square
    // Assuming 2048 steps per revolution and 1/64 gear ratio
    // This is a simplified calculation and may need adjustment based on your specific setup
    float steps_per_mm = 2048.0 / 64.0 / 360.0 * 50.0; // Steps per mm for 50mm square
    int side_length_steps = (int)steps_per_mm;

    printf("Drawing a square with side length of %d steps...\n", side_length_steps);

    // Draw the square
    draw_square(side_length_steps);

    // Stop motors and clean up
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

