int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
void log_acceleration(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the LIS3DH accelerometer
int init_lis3dh(int i2c_handle) {
    // Enable accelerometer, set ODR to 100Hz, and set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, 0x20, 0x67) != 0) { // CTRL_REG1
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set high-resolution mode (12-bit)
    if (i2cWriteByteData(i2c_handle, 0x23, 0x00) != 0) { // CTRL_REG3
        fprintf(stderr, "Error writing to CTRL_REG3\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, 0x28, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw acceleration data to g-force units
float convert_to_g(int16_t raw_value) {
    // Sensitivity for +/- 2g range and 12-bit resolution is 0.061 mg/LSB
    // Convert mg to g: 0.061 mg/LSB * 1000 mg/g = 0.061 g/LSB
    return (float)raw_value * 0.061f / 1000.0f;
}

// Function to log acceleration data to a file
void log_acceleration(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: X=%.3f g, Y=%.3f g, Z=%.3f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to shut down the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Error: Threshold must be greater than 0.0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g-force units
            x_g = convert_to_g(raw_x);
            y_g = convert_to_g(raw_y);
            z_g = convert_to_g(raw_z);

            // Check if any axis exceeds the threshold
            if (fabs(x_g) > threshold || fabs(y_g) > threshold || fabs(z_g) > threshold) {
                log_acceleration(x_g, y_g, z_g);
                shutdown_system();
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, continuing...\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

