    printf("Turning Right\n");
}

void stop() {
    printf("Stopping\n");
}

// Define the circular buffer
#define BUFFER_SIZE 5
int sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function to add a sensor reading to the circular buffer
void addToBuffer(int reading) {
    sensor_buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if the center sensor has detected no line for BUFFER_SIZE consecutive readings
int isCenterSensorAbsent() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_buffer[i] == 0) {
            return 0; // Center sensor detected line at least once
        }
    }
    return 1; // Center sensor detected no line for all readings
}

// Function to handle the alert (LED/buzzer)
void handleAlert() {
    gpioWrite(ALERT_LED_PIN, 1); // Turn on LED/buzzer
    gpioDelay(2000);             // Wait for 2 seconds
    gpioWrite(ALERT_LED_PIN, 0); // Turn off LED/buzzer
}

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input or output
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Read sensor values
        int left_sensor = gpioRead(LEFT_SENSOR_PIN);
        int center_sensor = gpioRead(CENTER_SENSOR_PIN);
        int right_sensor = gpioRead(RIGHT_SENSOR_PIN);

        // Add center sensor reading to the circular buffer
        addToBuffer(center_sensor);

        // Log sensor readings (for debugging)
        printf("Left: %d, Center: %d, Right: %d\n", left_sensor, center_sensor, right_sensor);

        // Check for errors
        if (left_sensor == PI_BAD_GPIO || center_sensor == PI_BAD_GPIO || right_sensor == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor values\n");
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Check if the center sensor is absent
        if (isCenterSensorAbsent()) {
            handleAlert();
        }

        // Control the robot based on sensor readings
        if (center_sensor == 0) {
            moveForward();
        } else if (left_sensor == 0) {
            turnLeft();
        } else if (right_sensor == 0) {
            turnRight();
        } else {
            stop();
        }

        // Delay for 10ms
        gpioDelay(10000);
    }

    return 0;
}

