#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define THRESHOLD 5.0 // mT
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 50
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_magnetic_field(float *field);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7210_address;
    int relay_gpio;
    float threshold;
    int sample_interval_ms;
} Config;

Config config = {
    I2C_BUS,
    SI7210_ADDR,
    RELAY_GPIO,
    THRESHOLD,
    SAMPLE_INTERVAL_MS
};

int main() {
    float magnetic_field;
    int relay_state = 0; // 0 = off, 1 = on
    int retries;

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_magnetic_field(&magnetic_field) == 0) {
                break; // Success, exit retry loop
            } else {
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == MAX_RETRIES) {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "Timeout reading magnetic field after %d retries.", MAX_RETRIES);
            log_event(error_message);
            continue; // Skip to the next iteration
        }

        // Log magnetic field reading
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "%s Magnetic field: %.2f mT", get_iso8601_timestamp(), magnetic_field);
        log_event(log_message);

        // Control relay based on threshold
        if (magnetic_field > config.threshold) {
            if (relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_event("Relay activated");
                } else {
                    log_event("Error activating relay");
                }
            }
        } else {
            if (relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_event("Relay deactivated");
                } else {
                    log_event("Error deactivating relay");
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(config.relay_gpio, 0); // Deactivate relay
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.si7210_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read magnetic field data from Si7210
int read_magnetic_field(float *field) {
    char buf[2];
    int16_t raw_value;
    int result;

    // Read two bytes from register 0x00 (magnetic field data)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Error reading magnetic field data: %d", result);
        log_event(error_message);
        return 1;
    }

    // Combine the two bytes into a 16-bit integer
    raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to milliteslas (mT) - Adjust scaling as needed based on Si7210 datasheet
    *field = (float)raw_value * 0.1; // Example scaling, adjust accordingly

    return 0;
}

// Control the relay (GPIO 17)
int control_relay(int state) {
    gpioWrite(config.relay_gpio, state);
    return 0;
}

// Log events to file
int log_event(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file); // Ensure immediate write to file
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
        return 1;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    log_event("Program terminated by user");
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buffer;
}

