        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (server_socket != -1) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

