#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define MEASUREMENT_COMMAND_1 0x36
#define MEASUREMENT_COMMAND_2 0x08
#define POLLING_INTERVAL_MS 100

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int handle, uint8_t *data);
int validate_crc(uint8_t *data);
float convert_to_flow_rate(uint16_t raw_flow);
void control_relay(int gpio, int state);
void log_flow_rates(float flow_rate1, float flow_rate2);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t *data) {
    uint8_t crc = data[2];
    uint8_t polynomial = 0x31; // CRC-8 polynomial
    uint8_t crc_calculated = 0xFF;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Convert raw data to flow rate
float convert_to_flow_rate(uint16_t raw_flow) {
    return (float)raw_flow / 120.0; // ml/min
}

// Control relay
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log flow rates
void log_flow_rates(float flow_rate1, float flow_rate2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening flow_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow_rate1, flow_rate2);
    fflush(fp);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        uint8_t sensor1_data[3];
        uint8_t sensor2_data[3];
        int bytes_read1, bytes_read2;

        // Read sensor 1
        bytes_read1 = read_sensor_data(i2c_handle1, sensor1_data);
        if (bytes_read1 != 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
            continue;
        }

        // Validate CRC for sensor 1
        if (!validate_crc(sensor1_data)) {
            fprintf(stderr, "CRC validation failed for sensor 1\n");
            continue;
        }

        // Read sensor 2
        bytes_read2 = read_sensor_data(i2c_handle2, sensor2_data);
        if (bytes_read2 != 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
            continue;
        }

        // Validate CRC for sensor 2
        if (!validate_crc(sensor2_data)) {
            fprintf(stderr, "CRC validation failed for sensor 2\n");
            continue;
        }

        // Convert raw data to flow rates
        uint16_t raw_flow1 = (sensor1_data[0] << 8) | sensor1_data[1];
        uint16_t raw_flow2 = (sensor2_data[0] << 8) | sensor2_data[1];
        float flow_rate1 = convert_to_flow_rate(raw_flow1);
        float flow_rate2 = convert_to_flow_rate(raw_flow2);

        // Control relay
        if (flow_rate1 < FLOW_THRESHOLD || flow_rate2 < FLOW_THRESHOLD) {
            control_relay(RELAY_GPIO, 1); // Energize relay
        } else {
            control_relay(RELAY_GPIO, 0); // De-energize relay
        }

        // Log flow rates
        log_flow_rates(flow_rate1, flow_rate2);

        // Sleep for polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    control_relay(RELAY_GPIO, 0); // De-energize relay on exit
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

