#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000
#define STOP_PULSE_WIDTH 0

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to read the lock button state
int read_lock_button(int gpio) {
    return gpioRead(gpio);
}

// Function to read the unlock button state
int read_unlock_button(int gpio) {
    return gpioRead(gpio);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on the button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_button_state = read_lock_button(LOCK_BUTTON_PIN);
        int unlock_button_state = read_unlock_button(UNLOCK_BUTTON_PIN);

        // Check for lock button press
        if (lock_button_state == 0) {
            printf("Lock button pressed\n");
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
            // Set servo to lock position
            if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
                fprintf(stderr, "Failed to set servo to lock position\n");
            }
            gpioDelay(10000); // Allow servo to move
            printf("Servo locked\n");
        }

        // Check for unlock button press
        if (unlock_button_state == 0) {
            printf("Unlock button pressed\n");
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
            // Set servo to unlock position
            if (set_servo_pulse_width(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
                fprintf(stderr, "Failed to set servo to unlock position\n");
            }
            gpioDelay(10000); // Allow servo to move
            printf("Servo unlocked\n");
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    // Stop the servo before exiting
    if (set_servo_pulse_width(SERVO_PIN, STOP_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to stop servo\n");
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

