#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, int duration);
void signal_handler(int signal);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Ensure LED is off initially
    control_led(0);

    return 0; // Indicate success
}

// Function to read the PIR sensor state
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0; // Indicate success
}

// Function to log events to the log file
int log_event(const char *event_type, int duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Duration: %d seconds\n", timestamp, event_type, duration);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        control_led(0); // Turn off LED
        gpioTerminate(); // Release pigpio resources
        return 1; // Exit if log file opening fails
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_pir_sensor() == 1) {
            printf("Motion detected!\n");
            log_event("Motion Detected", 0); // Log motion detection
            control_led(1); // Turn on LED
            gpioDelay(60000); // Wait for 60 seconds
            control_led(0); // Turn off LED
            log_event("Motion Ended", 60); // Log motion end
        }
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0); // Ensure LED is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

