#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define MPR121_ADDRESS 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 200

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x2B
#define MPR121_FILTERTH_H 0x2C
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_ECR 0x5E
#define MPR121_RESET 0x80

// Global variables
int i2c_fd;
bool relay_state = false; // false = OFF, true = ON

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void relay_control(bool state);
void debounce_delay();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    relay_control(false); // Turn off relay
    close(i2c_fd);
    exit(0);
}

// Initialize the MPR121 sensor
int mpr121_init() {
    // Reset the MPR121
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_RESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2B, 0x01) < 0) return -1; // MHD
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2C, 0x01) < 0) return -1; // NHD
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2D, 0x01) < 0) return -1; // NCL
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2E, 0x01) < 0) return -1; // FDL

    // Configure debounce
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5C, 0x01) < 0) return -1; // SFI
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5D, 0x01) < 0) return -1; // CDT

    // Enable auto-config
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5B, 0x01) < 0) return -1; // FFI

    // Enable all 12 electrodes
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x3F) < 0) return -1;

    return 0;
}

// Read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_l = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Control the relay
void relay_control(bool state) {
    digitalWrite(RELAY_GPIO, state ? HIGH : LOW);
    relay_state = state;
}

// Debounce delay
void debounce_delay() {
    delay(DEBOUNCE_DELAY_MS);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error: Failed to initialize MPR121 sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Set relay GPIO as output and turn it off initially
    pinMode(RELAY_GPIO, OUTPUT);
    relay_control(false);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 Relay Control Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status == -1) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Check if electrode 0 is touched
        if (touch_status & 0x01) {
            printf("Electrode 0 touched!\n");
            relay_control(!relay_state); // Toggle relay state
            debounce_delay(); // Debounce
        }

        delay(50); // Small delay to avoid busy-waiting
    }

    return 0;
}

