#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <stdarg.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 1000 // 1ms
#define MAX_PULSE_WIDTH 2000 // 2ms

int server_fd, new_socket;

// Function prototypes
void log_message(int priority, const char *format, ...);
void handle_signal(int sig);
int setup_socket(int port);
void handle_client(int client_socket);
void set_servo_angle(int angle);
int read_pir_sensor();

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void handle_signal(int sig) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "%s - ", buf);
    strftime(log_message_buffer + strlen(log_message_buffer), sizeof(log_message_buffer) - strlen(log_message_buffer), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    vsyslog(priority, format, args);

    FILE *fp = fopen("security.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s", log_message_buffer);
        vfprintf(fp, format, args);
        fprintf(fp, "\n");
        fclose(fp);
    } else {
        perror("Error opening security.log");
    }

    va_end(args);
}

// Setup socket function
int setup_socket(int port) {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_message(LOG_ERR, "Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_message(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_message(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }
    log_message(LOG_INFO, "Listening on port %d", port);
    return server_fd;
}

// Handle client connection function
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    while (program_running) {
        valread = read(client_socket, buffer, 1024);
        if (valread > 0) {
            log_message(LOG_INFO, "Received command: %s", buffer);

            if (strncmp(buffer, "set_servo", 9) == 0) {
                int angle;
                if (sscanf(buffer, "set_servo %d", &angle) == 1) {
                    if (angle >= 0 && angle <= 180) {
                        set_servo_angle(angle);
                        char response[50];
                        snprintf(response, sizeof(response), "Servo set to %d degrees", angle);
                        send(client_socket, response, strlen(response), 0);
                        log_message(LOG_INFO, "Servo set to %d degrees", angle);
                    } else {
                        log_message(LOG_ERR, "Invalid angle: %d", angle);
                        send(client_socket, "Invalid angle", strlen("Invalid angle"), 0);
                    }
                } else {
                    log_message(LOG_ERR, "Invalid command format");
                    send(client_socket, "Invalid command format", strlen("Invalid command format"), 0);
                }
            } else if (strcmp(buffer, "PIR") == 0) {
                int pir_value = read_pir_sensor();
                char response[10];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                send(client_socket, response, strlen(response), 0);
                log_message(LOG_INFO, "PIR value: %d", pir_value);
            } else {
                log_message(LOG_ERR, "Unknown command: %s", buffer);
                send(client_socket, "Unknown command", strlen("Unknown command"), 0);
            }
        } else if (valread == 0) {
            log_message(LOG_INFO, "Client disconnected");
            break;
        } else {
            perror("read");
            log_message(LOG_ERR, "Error reading from socket");
            break;
        }
    }
    close(client_socket);
}

// Set servo angle function
void set_servo_angle(int angle) {
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
    char response[50];
    snprintf(response, sizeof(response), "Servo pulse width: %d us", pulse_width);
    log_message(LOG_INFO, response);
}

// Read PIR sensor function
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    // Setup signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup socket
    server_fd = setup_socket(PORT);
    if (server_fd == -1) {
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Security system started");

    while (program_running) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            log_message(LOG_ERR, "Accept failed");
            continue; // Continue listening for new connections
        }

        log_message(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(address.sin_addr), ntohs(address.sin_port));

        handle_client(new_socket);
    }

    // Cleanup
    close(server_fd);
    gpioTerminate();
    closelog();

    return 0;
}

