void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_bh1750() {
    int result;
    unsigned char data[2];

    result = i2cWriteByte(i2c_handle, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1.0;
    }

    gpioDelay(120); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / 1.2;
}

// Control the grow light relay
void control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay
    } else {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize resources
    if (init_i2c() != 0 || init_gpio() != 0 || init_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();
        if (lux >= 0) {
            control_relay(lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

