#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <syslog.h>
#include <signal.h>
#include <getopt.h>
#include <pigpio.h>

// Configuration
#define DEFAULT_THRESHOLD 1000.0  // grams
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_DURATION 200      // milliseconds
#define NUM_HX711_READINGS 5
#define NUM_HX711_STARTUP_READINGS 10
#define MAX_DOUT_WAIT_TIME 1000 // milliseconds
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
static volatile int running = 1;
static int i2c_fd;
static float threshold = DEFAULT_THRESHOLD;
static float scale_factor = DEFAULT_SCALE_FACTOR;
static int duration = DEFAULT_DURATION;

// Function prototypes
int read_hx711(int dout_pin, int sck_pin);
float calculate_weight(int raw_value, float tare_value, float scale_factor);
int read_mpu6050_accel(int i2c_fd, float *x, float *y, float *z);
void activate_solenoid(int solenoid_pin, int duration);
void signal_handler(int signal);
int initialize_gpio(int dout_pin, int sck_pin, int solenoid_pin);
int initialize_i2c(const char *bus);
void cleanup();

// HX711 Reading Function
int read_hx711(int dout_pin, int sck_pin) {
    int32_t value = 0;
    int i;
    struct timeval start_time, current_time;
    long elapsed_time;

    // Wait for DOUT to go LOW
    gettimeofday(&start_time, NULL);
    while (gpioRead(dout_pin) == 1) {
        gettimeofday(&current_time, NULL);
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;
        if (elapsed_time > MAX_DOUT_WAIT_TIME) {
            syslog(LOG_ERR, "HX711 DOUT timeout");
            return -1; // Timeout error
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Read 24 bits
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // Clock high delay
        value = value << 1;
        if (gpioRead(dout_pin)) {
            value++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // Clock low delay
    }

    // Apply one more clock pulse to select Channel A gain 128
    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    // Convert to two's complement
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Weight Calculation Function
float calculate_weight(int raw_value, float tare_value, float scale_factor) {
    return (raw_value - tare_value) * scale_factor;
}

// MPU6050 Reading Function
int read_mpu6050_accel(int i2c_fd, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read accelerometer data
    if (read(i2c_fd, buf, 6) != 6) {
        syslog(LOG_ERR, "Failed to read accelerometer data");
        return -1;
    }

    // Combine high and low bytes
    raw_x = (buf[0] << 8) | buf[1];
    raw_y = (buf[2] << 8) | buf[3];
    raw_z = (buf[4] << 8) | buf[5];

    // Convert to g-force units (assuming sensitivity of +/- 2g)
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;

    return 0;
}

// Solenoid Activation Function
void activate_solenoid(int solenoid_pin, int duration) {
    gpioWrite(solenoid_pin, 1); // Activate solenoid
    gpioDelay(duration);
    gpioWrite(solenoid_pin, 0); // Deactivate solenoid
}

// Signal Handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// GPIO Initialization Function
int initialize_gpio(int dout_pin, int sck_pin, int solenoid_pin) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(dout_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);
    gpioSetMode(solenoid_pin, PI_OUTPUT);
    gpioWrite(solenoid_pin, 0); // Ensure solenoid is initially off

    return 0;
}

// I2C Initialization Function
int initialize_i2c(const char *bus) {
    i2c_fd = open(bus, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup Function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(25, 0); // Ensure solenoid is off
    gpioTerminate();
    close(i2c_fd);
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;
    int dout_pin = 23;
    int sck_pin = 24;
    int solenoid_pin = 25;
    float tare_value = 0.0;
    float weight_sum = 0.0;
    float accel_x, accel_y, accel_z;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (initialize_gpio(dout_pin, sck_pin, solenoid_pin) != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (initialize_i2c(I2C_BUS) != 0) {
        syslog(LOG_ERR, "I2C initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Tare the load cell
    syslog(LOG_INFO, "Taring load cell...");
    for (int i = 0; i < NUM_HX711_STARTUP_READINGS; i++) {
        int raw_value = read_hx711(dout_pin, sck_pin);
        if (raw_value == -1) {
            syslog(LOG_ERR, "HX711 read error during tare");
            cleanup();
            return EXIT_FAILURE;
        }
        tare_value += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    tare_value /= NUM_HX711_STARTUP_READINGS;
    syslog(LOG_INFO, "Tare value: %f", tare_value);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read weight
        weight_sum = 0.0;
        for (int i = 0; i < NUM_HX711_READINGS; i++) {
            int raw_value = read_hx711(dout_pin, sck_pin);
            if (raw_value == -1) {
                syslog(LOG_ERR, "HX711 read error");
                continue; // Skip to the next reading
            }
            weight_sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }
        float average_raw_value = weight_sum / NUM_HX711_READINGS;
        float weight = calculate_weight(average_raw_value, tare_value, scale_factor);

        // Read accelerometer data
        if (read_mpu6050_accel(i2c_fd, &accel_x, &accel_y, &accel_z) != 0) {
            syslog(LOG_ERR, "Failed to read accelerometer data");
        }

        // Check weight threshold and activate solenoid
        if (weight > threshold) {
            syslog(LOG_INFO, "Weight threshold exceeded: %f > %f", weight, threshold);
            activate_solenoid(solenoid_pin, duration);
        }

        syslog(LOG_INFO, "Weight: %f g, Accel: X=%.2f, Y=%.2f, Z=%.2f", weight, accel_x, accel_y, accel_z);

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

