#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define target pulse widths for each servo (microseconds)
#define SERVO1_TARGET 1000
#define SERVO2_TARGET 1500
#define SERVO3_TARGET 2000
#define SERVO4_TARGET 500
#define SERVO5_TARGET 2500

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to set the servo position
void set_servo_position(int gpio_pin, int pulse_width) {
    // Ensure pulse width is within the valid range
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    // Calculate the duty cycle (0-1000000)
    int duty_cycle = (int)(((float)pulse_width / 20000.0) * 1000000.0);

    // Set the PWM duty cycle
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set the PWM frequency for each servo
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);

    // Set the PWM range (0-1000000)
    gpioSetPWMrange(SERVO1_PIN, 1000000);
    gpioSetPWMrange(SERVO2_PIN, 1000000);
    gpioSetPWMrange(SERVO3_PIN, 1000000);
    gpioSetPWMrange(SERVO4_PIN, 1000000);
    gpioSetPWMrange(SERVO5_PIN, 1000000);

    // Set the initial servo positions
    set_servo_position(SERVO1_PIN, SERVO1_TARGET);
    set_servo_position(SERVO2_PIN, SERVO2_TARGET);
    set_servo_position(SERVO3_PIN, SERVO3_TARGET);
    set_servo_position(SERVO4_PIN, SERVO4_TARGET);
    set_servo_position(SERVO5_PIN, SERVO5_TARGET);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Wait for a short period
        usleep(100000); // 100ms
    }

    // Stop the PWM signals and release the GPIO pins
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

