#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PI Controller Gains
#define KP 0.5
#define KI 0.1

// Target RPM
#define TARGET_RPM 50.0

// Stall Detection Time (seconds)
#define STALL_DETECT_TIME 2.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 10000

// Encoder Ticks per Revolution
#define ENCODER_TICKS_PER_REV 64.0

// Global Variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
double integral_a = 0.0;
double integral_b = 0.0;
double last_error_a = 0.0;
double last_error_b = 0.0;

// Function Prototypes
void motor_a_isr(int gpio, int level, uint32_t tick, void *user);
void motor_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double pi_controller(double setpoint, double actual_value, double *integral, double *last_error, double kp, double ki);
void set_motor_speed(int motor_a_pwm, int motor_a_dir, int motor_b_pwm, int motor_b_dir, int duty_cycle_a, int duty_cycle_b);
void signal_handler(int signal);

// Encoder A Interrupt Service Routine
void motor_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    static int last_a_state = 0;
    int a_state = gpioRead(ENCODER_A_A);
    int b_state = gpioRead(ENCODER_A_B);

    if (a_state != last_a_state) {
        if (a_state == b_state) {
            encoder_a_ticks++;
        } else {
            encoder_a_ticks--;
        }
        last_a_state = a_state;
    }
}

// Encoder B Interrupt Service Routine
void motor_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    static int last_b_state = 0;
    int a_state = gpioRead(ENCODER_B_A);
    int b_state = gpioRead(ENCODER_B_B);

    if (a_state != last_b_state) {
        if (a_state == b_state) {
            encoder_b_ticks++;
        } else {
            encoder_b_ticks--;
        }
        last_b_state = a_state;
    }
}

// Calculate RPM from Encoder Ticks
double calculate_rpm(int ticks)
{
    return (double)ticks / ENCODER_TICKS_PER_REV * 60.0;
}

// PI Controller
double pi_controller(double setpoint, double actual_value, double *integral, double *last_error, double kp, double ki)
{
    double error = setpoint - actual_value;
    *integral += error;
    double output = kp * error + ki * (*integral);

    // Anti-windup clamping
    if (output > 255.0) {
        output = 255.0;
        *integral = (255.0 - kp * *last_error) / ki;
    } else if (output < 0.0) {
        output = 0.0;
        *integral = (-ki * *last_error) / ki;
    }

    *last_error = error;
    return output;
}

// Set Motor Speeds
void set_motor_speed(int motor_a_pwm, int motor_a_dir, int motor_b_pwm, int motor_b_dir, int duty_cycle_a, int duty_cycle_b)
{
    gpioPWM(motor_a_pwm, duty_cycle_a);
    gpioWrite(motor_a_dir, 1); // IN1 high
    gpioWrite(motor_b_pwm, duty_cycle_b);
    gpioWrite(motor_b_dir, 1); // IN3 high
}

// Signal Handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_motor_speed(MOTOR_A_PWM, MOTOR_A_DIR, MOTOR_B_PWM, MOTOR_B_DIR, 0, 0); // Stop motors
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Register interrupt service routines
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, motor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, motor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Stall detection variables
    time_t stall_start_a = 0;
    time_t stall_start_b = 0;
    int stall_a = 0;
    int stall_b = 0;

    // Main loop
    while (1) {
        // Calculate RPM
        double rpm_a = calculate_rpm(encoder_a_ticks);
        double rpm_b = calculate_rpm(encoder_b_ticks);

        // PI Controller
        double duty_cycle_a = pi_controller(TARGET_RPM, rpm_a, &integral_a, &last_error_a, KP, KI);
        double duty_cycle_b = pi_controller(TARGET_RPM, rpm_b, &integral_b, &last_error_b, KP, KI);

        // Clamp duty cycle
        if (duty_cycle_a > 255.0) duty_cycle_a = 255.0;
        if (duty_cycle_a < 0.0) duty_cycle_a = 0.0;
        if (duty_cycle_b > 255.0) duty_cycle_b = 255.0;
        if (duty_cycle_b < 0.0) duty_cycle_b = 0.0;

        // Set motor speeds
        set_motor_speed(MOTOR_A_PWM, MOTOR_A_DIR, MOTOR_B_PWM, MOTOR_B_DIR, (int)duty_cycle_a, (int)duty_cycle_b);

        // Stall detection
        if (rpm_a == 0.0) {
            if (!stall_a) {
                stall_start_a = time(NULL);
                stall_a = 1;
            } else {
                time_t now = time(NULL);
                if (difftime(now, stall_start_a) >= STALL_DETECT_TIME) {
                    printf("Motor A Stalled!\n");
                    stall_a = 0; // Reset stall flag after printing
                }
            }
        } else {
            stall_a = 0; // Reset stall flag if RPM is not zero
        }

        if (rpm_b == 0.0) {
            if (!stall_b) {
                stall_start_b = time(NULL);
                stall_b = 1;
            } else {
                time_t now = time(NULL);
                if (difftime(now, stall_start_b) >= STALL_DETECT_TIME) {
                    printf("Motor B Stalled!\n");
                    stall_b = 0; // Reset stall flag after printing
                }
            }
        } else {
            stall_b = 0; // Reset stall flag if RPM is not zero
        }

        // Print RPM and PWM duty cycle
        printf("Motor A RPM: %.2f, PWM: %.2f, Motor B RPM: %.2f, PWM: %.2f\n", rpm_a, duty_cycle_a, rpm_b, duty_cycle_b);

        // Reset encoder ticks
        encoder_a_ticks = 0;
        encoder_b_ticks = 0;

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

