    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Register interrupt service routines
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, motor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, motor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Stall detection variables
    time_t stall_start_a = 0;
    time_t stall_start_b = 0;
    int stall_a = 0;
    int stall_b = 0;

    // Main loop
    while (1) {
        // Calculate RPM
        double rpm_a = calculate_rpm(encoder_a_ticks);
        double rpm_b = calculate_rpm(encoder_b_ticks);

        // PI Controller
        double duty_cycle_a = pi_controller(TARGET_RPM, rpm_a, &integral_a, &last_error_a, KP, KI);
        double duty_cycle_b = pi_controller(TARGET_RPM, rpm_b, &integral_b, &last_error_b, KP, KI);

        // Clamp duty cycle
        if (duty_cycle_a > 255.0) duty_cycle_a = 255.0;
        if (duty_cycle_a < 0.0) duty_cycle_a = 0.0;
        if (duty_cycle_b > 255.0) duty_cycle_b = 255.0;
        if (duty_cycle_b < 0.0) duty_cycle_b = 0.0;

        // Set motor speeds
        set_motor_speed(MOTOR_A_PWM, MOTOR_A_DIR, MOTOR_B_PWM, MOTOR_B_DIR, (int)duty_cycle_a, (int)duty_cycle_b);

        // Stall detection
        if (rpm_a == 0.0) {
            if (!stall_a) {
                stall_start_a = time(NULL);
                stall_a = 1;
            } else {
                time_t now = time(NULL);
                if (difftime(now, stall_start_a) >= STALL_DETECT_TIME) {
                    printf("Motor A Stalled!\n");
                    stall_a = 0; // Reset stall flag after printing
                }
            }
        } else {
            stall_a = 0; // Reset stall flag if RPM is not zero
        }

        if (rpm_b == 0.0) {
            if (!stall_b) {
                stall_start_b = time(NULL);
                stall_b = 1;
            } else {
                time_t now = time(NULL);
                if (difftime(now, stall_start_b) >= STALL_DETECT_TIME) {
                    printf("Motor B Stalled!\n");
                    stall_b = 0; // Reset stall flag after printing
                }
            }
        } else {
            stall_b = 0; // Reset stall flag if RPM is not zero
        }

        // Print RPM and PWM duty cycle
        printf("Motor A RPM: %.2f, PWM: %.2f, Motor B RPM: %.2f, PWM: %.2f\n", rpm_a, duty_cycle_a, rpm_b, duty_cycle_b);

        // Reset encoder ticks
        encoder_a_ticks = 0;
        encoder_b_ticks = 0;

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

