// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYS_DUSK 45
#define HYS_DAWN 205
#define LOG_FILE "chicken_coop_log.txt"
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
float read_bh1750();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int gpio_relay;
    float dusk_threshold;
    float dawn_threshold;
    float dusk_hysteresis;
    float dawn_hysteresis;
    char *log_file_name;
} Config;

Config config = {
    I2C_BUS,
    BH1750_ADDR,
    GPIO_RELAY,
    LUX_THRESHOLD_DUSK,
    LUX_THRESHOLD_DAWN,
    HYS_DUSK,
    HYS_DAWN,
    LOG_FILE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        fprintf(stderr, "Logging initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        lux = read_bh1750();

        if (lux < 0) {
            fprintf(stderr, "Error reading BH1750 sensor\n");
        } else {
            if (lux < config.dusk_threshold && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            } else if (lux > config.dawn_threshold && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }

            log_data(lux, relay_state);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(config.gpio_relay, PI_OUTPUT);
    gpioWrite(config.gpio_relay, 0); // Ensure relay is initially off
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }
    return 0;
}

// Read BH1750 sensor value
float read_bh1750() {
    char buf[2];
    int result;
    int retries = I2C_RETRY_COUNT;

    // Send start measurement command (High Resolution Mode)
    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, 0x10); // 0x10 for high resolution mode
        if (result == 0) break; // Success
        fprintf(log_file, "Error writing to I2C device, retrying...\n");
        fflush(log_file);
        gpioDelay(I2C_RETRY_DELAY_MS); // Wait before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(log_file, "Failed to write to I2C after multiple retries\n");
        fflush(log_file);
        return -1.0; // Indicate error
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break; // Success
        fprintf(log_file, "Error reading from I2C device, retrying...\n");
        fflush(log_file);
        gpioDelay(I2C_RETRY_DELAY_MS); // Wait before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(log_file, "Failed to read from I2C after multiple retries\n");
        fflush(log_file);
        return -1.0; // Indicate error
    }

    // Convert the data
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(config.gpio_relay, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.gpio_relay, 0); // Turn off relay on exit
    gpioTerminate();
}

