#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the current relay state
static volatile int relay_state = 0;

// Function prototypes
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Release GPIO resources
        exit(0);
    }
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int current_state = gpioRead(TOUCH_SENSOR_PIN);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for debouncing
    int debounced_state = gpioRead(TOUCH_SENSOR_PIN);

    if (current_state == debounced_state) {
        return debounced_state;
    } else {
        return 0; // Return 0 if the state changed during debouncing
    }
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state(relay_state);
}

// Function to log the relay state with a timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay is now %s\n", timestamp, state ? "ON" : "OFF");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Touch-Toggled Relay Control Program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
        }
        gpioDelay(10 * 1000); // Sleep for 10 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

