#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define HYSTERESIS_THRESHOLD_HIGH 5.0
#define HYSTERESIS_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT_US 1000000 // 1 second
#define SAMPLE_INTERVAL_S 1

// Global variables
static volatile int pulse_count = 0;
static volatile int debounce_flag = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulse_count);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);
void cleanup();

// ISR function
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    if (level == PI_HIGH) // Rising edge
    {
        if (!debounce_flag)
        {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
        debounce_flag = 1;
        gpioDelay(DEBOUNCE_TIMEOUT_US); // Debounce timeout
        debounce_flag = 0;
    }
}

// Function to calculate LPM
double calculate_lpm(int pulse_count)
{
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm)
{
    static int solenoid_state = 1; // Initially open (HIGH)
    int new_state = (lpm > HYSTERESIS_THRESHOLD_HIGH) ? 0 : 1; // 0 = LOW, 1 = HIGH

    if (new_state != solenoid_state)
    {
        gpioWrite(SOLENOID_GPIO, new_state);
        solenoid_state = new_state;
        log_data(lpm, solenoid_state);
    }
}

// Function to log data to file
void log_data(double lpm, int solenoid_state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    log_data(0.0, 1); // Log solenoid open on exit
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup()
{
    gpioWrite(SOLENOID_GPIO, 1); // Set solenoid to open state
