#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVO_MIN_PULSE_WIDTH 1000
#define DEFAULT_SERVO_MAX_PULSE_WIDTH 2000
#define DEFAULT_SERVO_FREQUENCY 50
#define DEFAULT_TIMEOUT_MS 1000
#define DEFAULT_WEIGHT_THRESHOLD_MS 1000
#define DEFAULT_WEIGHT_THRESHOLD_COUNT 1000

// GPIO Pins
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

// Global Variables
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_config(float *calibration_factor, int *servo_min_pulse_width, int *servo_max_pulse_width, int *servo_frequency, int *timeout_ms, int *weight_threshold_ms, int *weight_threshold_count);
int hx711_read();
int dispense_weight(float target_weight, float calibration_factor, int servo_min_pulse_width, int servo_max_pulse_width, int servo_frequency, int timeout_ms, int weight_threshold_ms, int weight_threshold_count);
void log_event(float target_weight, float actual_weight, const char *error_message);
void signal_handler(int signal);
void cleanup();

// HX711 Read Function
int hx711_read() {
    int data = 0;
    int i;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Wait for DATA pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > DEFAULT_TIMEOUT_MS) {
            fprintf(stderr, "HX711 Timeout: DATA pin HIGH for too long.\n");
            log_event(0.0, 0.0, "HX711 Timeout: DATA pin HIGH for too long.");
            return -1; // Indicate timeout
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // 1 µs clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }

    // 25th pulse for gain setting (Channel A, gain 128)
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    data = data ^ 0x800000; // Convert to signed 24-bit integer

    return data;
}

// Dispense Weight Function
int dispense_weight(float target_weight, float calibration_factor, int servo_min_pulse_width, int servo_max_pulse_width, int servo_frequency, int timeout_ms, int weight_threshold_ms, int weight_threshold_count) {
    int i;
    int pulse_width;
    int weight_threshold_count_local = weight_threshold_count;
    int weight_threshold_ms_local = weight_threshold_ms;
    int hx711_value;
    float actual_weight;
    time_t start_time;
    time_t current_time;
    double elapsed_time;

    // Map target weight to pulse width range
    pulse_width = (int)(((target_weight / 1000.0) / 100.0) * (servo_max_pulse_width - servo_min_pulse_width) + servo_min_pulse_width);

    // Set servo pulse width
    gpioServo(SERVO_PIN, pulse_width);

    // Wait for 1 second
    gpioDelay(1000); // 1 second

    // Read load cell and calculate actual weight
    start_time = time(NULL);
    do {
        hx711_value = hx711_read();
        if (hx711_value == -1) {
            fprintf(stderr, "Error reading HX711 during dispense.\n");
            log_event(target_weight, 0.0, "Error reading HX711 during dispense.");
            return -1;
        }
        actual_weight = (float)hx711_value / calibration_factor;
        current_time = time(NULL);
        elapsed_time = difftime(current_time, start_time);
    } while (elapsed_time < 1.0);

    // Stop servo
    gpioServo(SERVO_PIN, 0);

    return (int)actual_weight;
}

// Log Event Function
void log_event(float target_weight, float actual_weight, const char *error_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n", timestamp, target_weight, actual_weight, error_message);
    fflush(log_file);
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    if (server_fd != -1) {
        close(server_fd);
    }
    if (client_fd != -1) {
        close(client_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    int servo_min_pulse_width = DEFAULT_SERVO_MIN_PULSE_WIDTH;
    int servo_max_pulse_width = DEFAULT_SERVO_MAX_PULSE_WIDTH;
    int servo_frequency = DEFAULT_SERVO_FREQUENCY;
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    int weight_threshold_ms = DEFAULT_WEIGHT_THRESHOLD_MS;
    int weight_threshold_count = DEFAULT_WEIGHT_THRESHOLD_COUNT;
    char buffer[1024];
    float target_weight;
    int actual_weight;
    int opt;

    // Read configuration from file
    if (read_config(&calibration_factor, &servo_min_pulse_width, &servo_max_pulse_width, &servo_frequency, &timeout_ms, &weight_threshold_ms, &weight_threshold_count) != 0) {
        fprintf(stderr, "Failed to read config file, using default values.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        log_event(0.0, 0.0, "Socket creation failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(12345);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        log_event(0.0, 0.0, "Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        log_event(0.0, 0.0, "Listen failed");
        cleanup();
        return 1;
    }

    printf("Listening on port 12345...\n");

    // Accept connection
    int addrlen = sizeof(address);
    client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen);
    if (client_fd < 0) {
        perror("Accept failed");
        log_event(0.0, 0.0, "Accept failed");
        cleanup();
        return 1;
    }

    printf("Connection accepted.\n");

    // Main loop
    while (!terminate) {
        // Receive target weight
        memset(buffer, 0, sizeof(buffer));
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Receive failed");
            log_event(0.0, 0.0, "Receive failed");
            break;
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            break;
        }

        target_weight = atof(buffer);

        // Dispense weight
        actual_weight = dispense_weight(target_weight, calibration_factor, servo_min_pulse_width, servo_max_pulse_width, servo_frequency, timeout_ms, weight_threshold_ms, weight_threshold_count);

        if (actual_weight == -1) {
            fprintf(stderr, "Dispense failed.\n");
            log_event(target_weight, 0.0, "Dispense failed.");
        } else {
            // Send actual weight back to client
            char response[50];
            snprintf(response, sizeof(response), "%.2f", (float)actual_weight / 1000.0); // Convert to kg
            send(client_fd, response, strlen(response), 0);
            printf("Sent actual weight: %s\n", response);
            log_event(target_weight, (float)actual_weight / 1000.0, "Dispense successful.");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Read Configuration Function
int read_config(float *calibration_factor, int *servo_min_pulse_width, int *servo_max_pulse_width, int *servo_frequency, int *timeout_ms, int *weight_threshold_ms, int *weight_threshold_count) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Config file not found, using default values.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                *calibration_factor = atof(value);
            } else if (strcmp(key, "servo_min_pulse_width") == 0) {
                *servo_min_pulse_width = atoi(value);
            } else if (strcmp(key, "servo_max_pulse_width") == 0) {
                *servo_max_pulse_width = atoi(value);
            } else if (strcmp(key, "servo_frequency") == 0) {
                *servo_frequency = atoi(value);
            } else if (strcmp(key, "timeout_ms") == 0) {
                *timeout_ms = atoi(value);
            } else if (strcmp(key, "weight_threshold_ms") == 0) {
                *weight_threshold_ms = atoi(value);
            } else if (strcmp(key, "weight_threshold_count") == 0) {
                *weight_threshold_count = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

