#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce interval (50ms)
#define DEFAULT_DEBOUNCE_INTERVAL 50

// Global variables
static volatile int running = 1;
static int debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;
static int relay_state = 0; // 0: OFF, 1: ON

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state();
void cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
}

// Log the relay state with a timestamp
void log_relay_state() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1 && strcmp(argv[1], "-d") == 0 && argc > 2) {
        char *endptr;
        debounce_interval = strtol(argv[2], &endptr, 10);
        if (*endptr != '\0' || debounce_interval <= 0) {
            fprintf(stderr, "Invalid debounce interval. Using default value.\n");
            debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Debounce interval: %d ms\n", debounce_interval);

    int last_touch_state = 1; // Initialize to a non-touching state
    time_t last_touch_time = 0;

    // Main loop
    while (running) {
        int touch_state = read_touch_sensor();

        if (touch_state == 0 && last_touch_state == 1) { // Detect rising edge (LOW to HIGH)
            time_t now = time(NULL);
            if (difftime(now, last_touch_time) * 1000 >= debounce_interval) {
                toggle_relay();
                log_relay_state();
                last_touch_time = now;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(1); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Relay control program finished.\n");
    return 0;
}

