#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>
#include <fcntl.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define INITIAL_ANGLE 90

volatile sig_atomic_t program_running = 1;
int current_angle = INITIAL_ANGLE;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping PWM and exiting.\n", signal);
}

int set_gpio_mode(int gpio, int mode) {
    int result = gpioSetMode(gpio, mode);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d mode to %d: %d\n", gpio, mode, result);
        return -1;
    }
    return 0;
}

int set_pwm_frequency(int gpio, int frequency) {
    int result = gpioSetPWMfrequency(gpio, frequency);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d to %d: %d\n", gpio, frequency, result);
        return -1;
    }
    return 0;
}

int set_pwm_range(int gpio, int range) {
    int result = gpioSetPWMrange(gpio, range);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d to %d: %d\n", gpio, range, result);
        return -1;
    }
    return 0;
}

int set_pwm_dutycycle(int gpio, int dutycycle) {
    int result = gpioPWM(gpio, dutycycle);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM dutycycle for GPIO %d to %d: %d\n", gpio, dutycycle, result);
        return -1;
    }
    return 0;
}

int map_angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    float pulse_width = (float)(angle) / (float)(MAX_ANGLE) * (float)(MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + (float)(MIN_PULSE_WIDTH);
    return (int)pulse_width;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (set_gpio_mode(GPIO_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    if (set_pwm_frequency(GPIO_PIN, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return 1;
    }

    if (set_pwm_range(GPIO_PIN, 1000) != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    struct termios term;
    int fd = fileno(stdin);

    if (tcgetattr(fd, &term) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    term.c_lflag &= ~(ICANON | ECHO);
    term.c_cc[VMIN] = 1;
    term.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &term) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (program_running) {
        int c = getchar();

        if (c == '+') {
            current_angle += 10;
            if (current_angle > MAX_ANGLE) {
                current_angle = MAX_ANGLE;
            }
        } else if (c == '-') {
            current_angle -= 10;
            if (current_angle < MIN_ANGLE) {
                current_angle = MIN_ANGLE;
            }
        } else if (c == 'q') {
            program_running = 0;
        }

        int pulse_width = map_angle_to_pulse_width(current_angle);

        if (set_pwm_dutycycle(GPIO_PIN, pulse_width) != 0) {
            program_running = 0; // Stop on error
        }

        printf("Current angle: %d degrees\n", current_angle);
    }

    // Stop PWM before exiting
    set_pwm_dutycycle(GPIO_PIN, 0);

    // Restore terminal settings
    tcsetattr(fd, TCSANOW, &term);

    gpioTerminate();
    return 0;
}

