#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME_US 2000 // 2ms
#define LOG_FILE "motor_rpm.log"

volatile sig_atomic_t program_running = 1;

// Structure to hold the last rising edge time
typedef struct {
    long long last_rising_edge;
} sensor_data_t;

sensor_data_t sensor_data = {0};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signal);
}

// Function to calculate RPM
double calculate_rpm(double time_interval_seconds, int pulse_count) {
    return (pulse_count / time_interval_seconds) * 60.0;
}

// Function to log RPM to a file
void log_rpm(double rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, rpm);
    fflush(fp);
    fclose(fp);
}

// Callback function for rising edge detection
void rising_edge_callback(int gpio, int level, uint32_t tick, void *user_data) {
    long long current_time = gpioTime(0, NULL, NULL);

    // Debounce: Check if enough time has passed since the last rising edge
    if (current_time - sensor_data.last_rising_edge > DEBOUNCE_TIME_US) {
        sensor_data.last_rising_edge = current_time;
        // Increment the pulse count (simulated, as we don't have a global counter)
        // In a real application, you would increment a global counter here.
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for rising edge detection
    gpioSetAlertFuncEx(GPIO_PIN, rising_edge_callback, NULL);

    int pulse_count = 0; // Initialize pulse count
    time_t start_time, current_time;
    double time_interval;
    double rpm;

    time(&start_time);

    while (program_running) {
        time(&current_time);
        time_interval = difftime(current_time, start_time);

        if (time_interval >= 5.0) {
            // Calculate RPM (simulated, as we don't increment pulse count in callback)
            rpm = calculate_rpm(time_interval, pulse_count);

            // Print RPM to stdout
            printf("RPM: %.2f\n", rpm);

            // Log RPM to file
            log_rpm(rpm);

            // Reset pulse count and start time for the next interval
            pulse_count = 0;
            time(&start_time);
        }

        gpioDelay(100); // Check every 100ms
    }

    // Clean up and exit
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    gpioTerminate();

    return 0;
}

