#define DEBOUNCE_DELAY_MS 50
#define CONTINUOUS_HIGH_TIMEOUT_S 10

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void handle_signal(int signal);
void log_error(const char *message);

// Signal handler function
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Error logging function
void log_error(const char *message) {
    FILE *fp = fopen("error.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Error opening error log file");
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the relay
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int relay_state = 0; // 0 = OFF, 1 = ON
    int continuous_high_count = 0;
    time_t continuous_high_start_time = 0;

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            continuous_high_count++;
            if (continuous_high_count == 1) {
                continuous_high_start_time = time(NULL);
            }

            if (relay_state == 0) {
                relay_state = 1;
                control_relay(relay_state);
                printf("Relay turned ON\n");
            }
        } else {
            continuous_high_count = 0;
            if (relay_state == 1) {
                relay_state = 0;
                control_relay(relay_state);
                printf("Relay turned OFF\n");
            }
        }

        // Check for continuous HIGH state
        if (continuous_high_count > 0) {
            time_t current_time = time(NULL);
            if (difftime(current_time, continuous_high_start_time) > CONTINUOUS_HIGH_TIMEOUT_S) {
                printf("Continuous HIGH detected for %d seconds. Forcing relay OFF.\n", CONTINUOUS_HIGH_TIMEOUT_S);
                relay_state = 0;
                control_relay(relay_state);
                continuous_high_count = 0; // Reset the counter
            }
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    // Cleanup
    control_relay(0); // Turn off relay
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

