#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18  // GPIO 18 (PWM0)
#define VALVE_ENABLE_PIN 23 // GPIO 23 (Enable/Direction)
#define FLOW_SENSOR_PIN 24 // GPIO 24 (Interrupt pin)

// Define constants
#define PULSES_PER_LITER 450.0 // Pulses per liter for YF-S201
#define PWM_RANGE 1000       // PWM range (0-1000)
#define TARGET_FLOW_RATE_MS 100 // Target flow rate sampling interval (ms)
#define FLOW_LOG_FILE "flow_log.csv"

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;
int i2c_fd;

// Function prototypes
void pulse_counter_isr(void);
double calculate_flow_rate(int pulse_count);
int set_valve_position(double flow_rate);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);
int initialize_i2c();

// Function to initialize I2C
int initialize_i2c() {
    i2c_fd = wiringPiI2CSetup(0x68); // Replace 0x68 with your sensor's I2C address
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Interrupt service routine for pulse counting
void pulse_counter_isr(void) {
    pulse_count++;
}

// Function to calculate flow rate from pulse count
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER / (TARGET_FLOW_RATE_MS / 1000.0);
}

// Function to set the valve position based on flow rate
int set_valve_position(double flow_rate) {
    double error = target_flow_rate - flow_rate;
    double output = 1.0 * error; // Proportional gain Kp = 1.0

    // Clamp the output to the range 0-255
    if (output < 0) {
        output = 0;
    } else if (output > 255) {
        output = 255;
    }

    // Set the PWM duty cycle
    int duty_cycle = (int)(output * (PWM_RANGE / 255.0)); // Scale to PWM range
    pwmWrite(VALVE_PWM_PIN, duty_cycle);

    return (int)output;
}

// Function to log data to a CSV file
void log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.6f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);

    // Stop the valve
    pwmWrite(VALVE_PWM_PIN, 0);
    digitalWrite(VALVE_ENABLE_PIN, LOW);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Cleanly exit
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_LPM>\n", argv[0]);
        return 1;
    }

    if (strncmp(argv[1], "-t", 2) != 0) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_LPM>\n", argv[0]);
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[1] + 2, &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Error: Invalid target flow rate. Must be a positive number.\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() == -1) {
        return 1;
    }

    // Set GPIO modes
    pinMode(VALVE_PWM_PIN, PWM_OUTPUT);
    pinMode(VALVE_ENABLE_PIN, OUTPUT);
    pinMode(FLOW_SENSOR_PIN, INPUT);

    // Enable the valve
    digitalWrite(VALVE_ENABLE_PIN, HIGH);

    // Set PWM range
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired PWM frequency

    // Set up interrupt for pulse counting
    if (wiringPiISR(FLOW_SENSOR_PIN, INT_EDGE_RISING, &pulse_counter_isr) < 0) {
        fprintf(stderr, "Error setting up ISR: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Reset pulse count
        int current_pulse_count = pulse_count;
        pulse_count = 0;

        // Calculate flow rate
        double flow_rate = calculate_flow_rate(current_pulse_count);

        // Set valve position
        int valve_position = set_valve_position(flow_rate);

        // Log data
        log_data(flow_rate, valve_position);

        // Wait for the next sample
        delay(TARGET_FLOW_RATE_MS);
    }

    return 0;
}

