#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz
#define SPI_MODE 0

// Define RFID tag value (example)
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag();
int verify_tag(const unsigned char *tag);
int debounce_button();
void control_locks(int lock1_state, int lock2_state);
void log_event(const char *event_description);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid_tag() {
    unsigned char buffer[10];
    int result;

    result = spiRead(spi_handle, buffer, 10);

    if (result < 0) {
        log_event("RFID read failed");
        return -1; // Indicate failure
    }

    // Check for no tag present (all zeros)
    if (buffer[0] == 0 && buffer[1] == 0 && buffer[2] == 0 && buffer[3] == 0 &&
        buffer[4] == 0 && buffer[5] == 0 && buffer[6] == 0 && buffer[7] == 0 &&
        buffer[8] == 0 && buffer[9] == 0) {
        return 0; // Indicate no tag
    }

    return 1; // Indicate success
}

// Function to verify RFID tag
int verify_tag(const unsigned char *tag) {
    return (memcmp(tag, valid_tag, 10) == 0);
}

// Function to debounce the button
int debounce_button() {
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    int last_state = 1; // Assume button is initially not pressed (pulled up)
    int current_state;
    unsigned long last_change_time = 0;
    unsigned long current_time;

    while (program_running) {
        current_state = gpioRead(BUTTON_PIN);
        current_time = gpioTick();

        if (current_state != last_state) {
            if (current_time - last_change_time > DEBOUNCE_TIME * 1000) {
                last_change_time = current_time;
                last_state = current_state;

                if (current_state == 0) { // Button pressed (active low)
                    return 1; // Indicate button press
                }
            }
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return 0; // Indicate no button press (program exiting)
}

// Function to control the locks
void control_locks(int lock1_state, int lock2_state) {
    gpioWrite(LOCK1_PIN, lock1_state);
    gpioWrite(LOCK2_PIN, lock2_state);
}

// Function to log events
void log_event(const char *event_description) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_description);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");

    // Engage locks
    control_locks(1, 1);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);

    // Set initial lock states (engaged)
    control_locks(1, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Door access control system started");

    // Main loop
    while (program_running) {
        int tag_read_result = read_rfid_tag();

        if (tag_read_result == 1) {
            unsigned char tag_data[10];
            spiRead(spi_handle, tag_data, 10);
            log_event("RFID tag read successfully");

            if (verify_tag(tag_data)) {
                log_event("Valid RFID tag detected");

                if (debounce_button()) {
                    log_event("Button pressed");
                    control_locks(0, 0); // Disengage locks
                    gpioDelay(5000);       // Wait 5 seconds
                    control_locks(1, 1); // Re-engage locks
                    log_event("Locks re-engaged");
                } else {
                    log_event("Button not pressed after tag read");
                }
            } else {
                log_event("Invalid RFID tag");
            }
        } else if (tag_read_result == 0) {
            // No tag present, do nothing
        } else {
            // RFID read failed, already logged in read_rfid_tag()
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

