#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define ENCODER1_A 5
#define ENCODER1_B 6

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define TARGET_RPM 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01

// PWM Frequency
#define PWM_FREQUENCY 100

// Global Variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
volatile int motor1_direction = 1; // 1: forward, -1: backward
volatile int motor2_direction = 1;

pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

FILE *log_file = NULL;

// Function Prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
void set_motor_speed(int motor, float speed);
float calculate_pid(float setpoint, float actual_speed, float *integral, float *previous_error);
void signal_handler(int signal);

// Encoder 1 Thread
void *encoder1_thread(void *arg) {
    while (1) {
        if (gpioRead(ENCODER1_A) != gpioRead(ENCODER1_B)) {
            if (gpioRead(ENCODER1_A) == gpioRead(ENCODER1_B)) {
                motor1_direction = 1; // Forward
            } else {
                motor1_direction = -1; // Backward
            }
            encoder1_count += motor1_direction;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

// Encoder 2 Thread
void *encoder2_thread(void *arg) {
    while (1) {
        if (gpioRead(ENCODER2_A) != gpioRead(ENCODER2_B)) {
            if (gpioRead(ENCODER2_A) == gpioRead(ENCODER2_B)) {
                motor2_direction = 1; // Forward
            } else {
                motor2_direction = -1; // Backward
            }
            encoder2_count += motor2_direction;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

// Set Motor Speed using PWM
void set_motor_speed(int motor, float speed) {
    int pwm_value;

    if (speed > 0) {
        pwm_value = (int)(speed / TARGET_RPM * 255); // Map speed to PWM range (0-255)
        if (pwm_value > 255) pwm_value = 255;
    } else {
        pwm_value = 0;
    }

    if (motor == 1) {
        gpioPWM(MOTOR1_ENA, pwm_value);
        gpioWrite(MOTOR1_IN1, 1);
        gpioWrite(MOTOR1_IN2, 0);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENB, pwm_value);
        gpioWrite(MOTOR2_IN3, 1);
        gpioWrite(MOTOR2_IN4, 0);
    }
}

// Calculate PID Output
float calculate_pid(float setpoint, float actual_speed, float *integral, float *previous_error) {
    float error = setpoint - actual_speed;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Signal Handler for Ctrl+C and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop Motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Release GPIO Lines
    gpioTerminate();

    // Close Log File
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    pthread_t encoder1_thread_id, encoder2_thread_id;
    float integral1 = 0, previous_error1 = 0;
    float integral2 = 0, previous_error2 = 0;
    float pid_output1, pid_output2;
    float actual_speed1, actual_speed2;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO Modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM Frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Open Log File
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write Header Row
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_Output,Motor2_RPM,Motor2_P,Motor2_I,Motor2_D,Motor2_Output\n");

    // Install Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create Encoder Threads
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread!\n");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread!\n");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Main Loop
    while (1) {
        // Get Current Time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read Encoder Counts
        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_count_local = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_count_local = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM (Assuming 1 pulse per revolution)
        actual_speed1 = (float)encoder1_count_local / TARGET_RPM; // RPM
        actual_speed2 = (float)encoder2_count_local / TARGET_RPM; // RPM

        // Calculate PID Outputs
        pid_output1 = calculate_pid(TARGET_RPM, actual_speed1, &integral1, &previous_error1);
        pid_output2 = calculate_pid(TARGET_RPM, actual_speed2, &integral2, &previous_error2);

        // Set Motor Speeds
        set_motor_speed(1, pid_output1);
        set_motor_speed(2, pid_output2);

        // Log Data
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, actual_speed1, KP * (TARGET_RPM - actual_speed1), KI * integral1, KD * (TARGET_RPM - actual_speed1 - (TARGET_RPM - actual_speed1)), pid_output1,
                actual_speed2, KP * (TARGET_RPM - actual_speed2), KI * integral2, KD * (TARGET_RPM - actual_speed2 - (TARGET_RPM - actual_speed2)), pid_output2);
        fflush(log_file);

        // Delay for 100ms
        gpioDelay(100);
    }

    // Cleanup (This part will not be reached in the infinite loop)
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

