#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_SOFTRESET 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status();
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        printf("Ctrl+C detected. Shutting down...\n");
    }
}

// Initialize MPR121 sensor
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        log_event("Error: Soft reset failed.");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering parameters
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_L, 0x01) < 0) {
        log_event("Error: Failed to write FILTERTH_L.");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x00) < 0) {
        log_event("Error: Failed to write FILTERTH_H.");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
