#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define valve pause durations (in seconds)
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void activate_valve(int gpio_pin, int duration_ms);
void deactivate_valve(int gpio_pin);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Deactivate both valves
    deactivate_valve(VALVE1_GPIO);
    deactivate_valve(VALVE2_GPIO);

    // Terminate the pigpio library
    gpioTerminate();

    // Exit the program
    exit(0);
}

// Function to activate a valve
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH to activate the valve
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    deactivate_valve(gpio_pin); // Deactivate the valve after the duration
}

// Function to deactivate a valve
void deactivate_valve(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO LOW to deactivate the valve
}

// Function to log an event to a file
void log_event(const char *message) {
    FILE *fp = fopen("valve_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening valve_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    // Set initial state of GPIO pins to LOW (valve closed)
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        activate_valve(VALVE1_GPIO, VALVE1_DURATION);
        log_event("Valve 1 activated for 500ms");

        // Pause for 5 seconds
        gpioDelay(VALVE1_PAUSE * 1000000); // Delay in microseconds

        // Activate Valve 2
        activate_valve(VALVE2_GPIO, VALVE2_DURATION);
        log_event("Valve 2 activated for 1000ms");

        // Pause for 10 seconds
        gpioDelay(VALVE2_PAUSE * 1000000); // Delay in microseconds
    }

    // This point is reached only if program_running is set to 0 by the signal handler
    return 0;
}

