#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define STABLE_DELAY_MS 100

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x2B
#define MPR121_FILTERTH_H 0x2C
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MODE_CONFIG 0x5B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_configure();
int mpr121_read_touch_status();
void relay_toggle(int current_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// MPR121 Initialization function
int mpr121_init() {
    int status;

    // Stop mode
    status = i2cWriteByteData(i2c_handle, MPR121_MODE_CONFIG, 0x00); // Stop mode
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_MODE_CONFIG (stop mode): %d\n", status);
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    return 0;
}

// MPR121 Configuration function
int mpr121_configure() {
    int status;

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        status = i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40); // Touch threshold
        if (status < 0) {
            fprintf(stderr, "Error writing to MPR121_TOUCHTH_%d: %d\n", i, status);
            return -1;
        }
        status = i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20); // Release threshold
        if (status < 0) {
            fprintf(stderr, "Error writing to MPR121_RELEASETH_%d: %d\n", i, status);
            return -1;
        }
    }

    // Configure filter and charge time
    status = i2cWriteByteData(i2c_handle, MPR121_FILTERTH_L, 0x01); // Filter configuration
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_FILTERTH_L: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x00); // Filter configuration
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_FILTERTH_H: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C); // Enable all electrodes
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODE_CONFIG: %d\n", status);
        return -1;
    }

    // Run mode
    status = i2cWriteByteData(i2c_handle, MPR121_MODE_CONFIG, 0x10); // Run mode
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_MODE_CONFIG (run mode): %d\n", status);
        return -1;
    }
    gpioDelay(STABLE_DELAY_MS * 1000); // 100ms delay

    return 0;
}

// MPR121 Read Touch Status function
int mpr121_read_touch_status() {
    int status;
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error reading MPR121_TOUCHSTATUS_L: %d\n", touch_status_l);
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error reading MPR121_TOUCHSTATUS_H: %d\n", touch_status_h);
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Relay Toggle function
void relay_toggle(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_GPIO, new_state);
    printf("Relay toggled to: %d\n", new_state);
}

int main() {
    int touch_status;
    int relay_state = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure MPR121
    if (mpr121_configure() != 0) {
        fprintf(stderr, "MPR121 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        touch_status = mpr121_read_touch_status();
        if (touch_status > 0) {
            relay_toggle(relay_state);
            relay_state = !relay_state; // Update relay state
        }
        gpioDelay(100 * 1000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

