    status = i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x00); // Filter configuration
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_FILTERTH_H: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C); // Enable all electrodes
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODE_CONFIG: %d\n", status);
        return -1;
    }

    // Run mode
    status = i2cWriteByteData(i2c_handle, MPR121_MODE_CONFIG, 0x10); // Run mode
    if (status < 0) {
        fprintf(stderr, "Error writing to MPR121_MODE_CONFIG (run mode): %d\n", status);
        return -1;
    }
    gpioDelay(STABLE_DELAY_MS * 1000); // 100ms delay

    return 0;
}

// MPR121 Read Touch Status function
int mpr121_read_touch_status() {
    int status;
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error reading MPR121_TOUCHSTATUS_L: %d\n", touch_status_l);
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error reading MPR121_TOUCHSTATUS_H: %d\n", touch_status_h);
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Relay Toggle function
void relay_toggle(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_GPIO, new_state);
    printf("Relay toggled to: %d\n", new_state);
}

int main() {
    int touch_status;
    int relay_state = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure MPR121
    if (mpr121_configure() != 0) {
        fprintf(stderr, "MPR121 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        touch_status = mpr121_read_touch_status();
        if (touch_status > 0) {
            relay_toggle(relay_state);
            relay_state = !relay_state; // Update relay state
        }
        gpioDelay(100 * 1000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

