#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define POLL_INTERVAL_MS 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_event(const char *event_type);
void unlock_door();
void rate_limit();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate();
}

// Log events to file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file); // Ensure immediate write to file
}

// Unlock the door
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    log_event("Door unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
}

// Rate limiting
void rate_limit() {
    log_event("Rate limiting active");
    gpioDelay(RATE_LIMIT_DURATION_S * 1000000); // Delay for rate limit duration
    log_event("Rate limiting disabled");
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    int last_state = 0;
    time_t last_motion_time = 0;

    printf("Door strike control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int current_state = gpioRead(PIR_SENSOR_PIN);

        if (current_state != last_state) {
            if (current_state == 1) {
                // Rising edge detected (motion)
                time_t now = time(NULL);
                if (difftime(now, last_motion_time) >= RATE_LIMIT_DURATION_S) {
                    unlock_door();
                    last_motion_time = now;
                } else {
                    rate_limit();
                }
            }
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll interval
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    printf("Door strike control system terminated.\n");
    return 0;
}

