#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define the range for the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define the range for the step duration in milliseconds
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the range for the PWM duty cycle
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global flag to signal program termination
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    shutdown_flag = 1;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to generate a random PWM duty cycle
int generate_duty_cycle() {
    return rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
}

// Function to generate a random step duration in milliseconds
int generate_duration() {
    return rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
}

// Function to set the PWM duty cycle for a motor
int set_motor_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to stop a motor by setting the duty cycle to 0
int stop_motor(int gpio) {
    if (set_motor_duty_cycle(gpio, 0) != 0) {
        return -1;
    }
    return 0;
}

// Function to play a single step of the haptic pattern
int play_step(int motor1_duty_cycle, int motor2_duty_cycle, int duration_ms) {
    if (set_motor_duty_cycle(MOTOR1_GPIO, motor1_duty_cycle) != 0) {
        return -1;
    }
    if (set_motor_duty_cycle(MOTOR2_GPIO, motor2_duty_cycle) != 0) {
        return -1;
    }
    gpioDelay(duration_ms * 1000); // Convert milliseconds to microseconds
    return 0;
}

// Function to generate and play a random haptic pattern
int play_pattern() {
    // Seed the random number generator
    srand(time(NULL));

    // Determine the number of steps in the pattern
    int num_steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;

    // Generate and play the pattern
    for (int i = 0; i < num_steps; ++i) {
        int motor1_duty_cycle = generate_duty_cycle();
        int motor2_duty_cycle = generate_duty_cycle();
        int duration_ms = generate_duration();

        if (play_step(motor1_duty_cycle, motor2_duty_cycle, duration_ms) != 0) {
            return -1;
        }
    }

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the motors
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for the motors
    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_GPIO, 255);
    gpioSetPWMrange(MOTOR2_GPIO, 255);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Haptic feedback program started. Press Ctrl+C to exit.\n");

    // Main loop to generate and play random patterns
    while (!shutdown_flag) {
        if (play_pattern() != 0) {
            fprintf(stderr, "Error playing pattern, exiting\n");
            break;
        }
    }

    // Graceful shutdown: stop motors and terminate pigpio
    if (stop_motor(MOTOR1_GPIO) != 0) {
        fprintf(stderr, "Error stopping motor 1 during shutdown\n");
    }
    if (stop_motor(MOTOR2_GPIO) != 0) {
        fprintf(stderr, "Error stopping motor 2 during shutdown\n");
    }
    gpioTerminate();

    printf("Haptic feedback program terminated.\n");

    return 0;
}

