#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0 // kg
#define READ_TIMEOUT_US 500000 // 0.5 seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Structure to hold calibration data
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function prototypes
int initialize_gpio();
CalibrationData load_calibration_data();
double calibrate_sensor();
double read_hx711();
double calculate_weight(double raw_value, double scale_factor, double offset);
void control_solenoid(double weight);
void log_data(double weight);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Function to load calibration data from file
CalibrationData load_calibration_data() {
    CalibrationData data = {1.0, 0.0}; // Default values
    FILE *fp = fopen(CALIBRATION_FILE, "r");

    if (fp != NULL) {
        if (fscanf(fp, "%lf %lf", &data.scale_factor, &data.offset) != 2) {
            fprintf(stderr, "Error reading calibration file, using defaults\n");
            fclose(fp);
            return data; // Return default values
        }
        fclose(fp);
    } else {
        fprintf(stderr, "Calibration file not found, using defaults\n");
    }

    return data;
}

// Function to calibrate the sensor
double calibrate_sensor() {
    double sum = 0.0;
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        sum += read_hx711();
        gpioDelay(1000); // 1 ms delay
    }
    return sum / NUM_CALIBRATION_READINGS;
}

// Function to read raw data from HX711
double read_hx711() {
    int32_t value = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Wait for data line to go low
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Short delay
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Short delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Short delay

    value = value ^ 0x800000; // Convert to signed 2's complement

    return (double)value;
}

// Function to calculate weight
double calculate_weight(double raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
        printf("Weight above threshold, engaging solenoid\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // De-engage solenoid
        printf("Weight below threshold, de-engaging solenoid\n");
    }
}

// Function to log data to file
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, weight);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
}

int main() {
    // Register signal handler
