    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, weight);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
}

int main() {
