#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define MOTOR_DURATION_S 5
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define CHECK_INTERVAL_S 60
#define MOTOR_STOP_DELAY_S 60

// Global variables
static volatile int running = 1;
static time_t last_motor_stop_time = 0;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor();
void control_motor(int start);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    int value = gpioRead(RAIN_SENSOR_PIN);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading rain sensor: %d", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce the rain sensor
int debounce_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) return -1; // Propagate error
        if (sensor_value == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count >= 3) ? 0 : 1; // Return 0 if rain detected, 1 otherwise
}

// Function to control the motor
void control_motor(int start) {
    if (start) {
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
        log_event("Motor started to close window");
    } else {
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Motor stopped");
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, stopping motor and exiting...");
    control_motor(0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    while (running) {
        // Check if enough time has passed since the last motor stop
        time_t now = time(NULL);
        if (difftime(now, last_motor_stop_time) >= MOTOR_STOP_DELAY_S) {
            int rain_detected = debounce_rain_sensor();
            if (rain_detected == 0) {
                log_event("Rain detected, starting motor");
                control_motor(1); // Start the motor
                gpioDelay(MOTOR_DURATION_S * 1000000); // Delay in microseconds
                control_motor(0); // Stop the motor
                last_motor_stop_time = now;
            } else if (rain_detected < 0) {
                syslog(LOG_ERR, "Error during rain sensor debouncing, skipping this cycle");
            }
        }
        gpioDelay(CHECK_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    return 0;
}

