#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_DURATION 5 // seconds
#define TIMEOUT_MS 100

// Global variables
static volatile int running = 1;
static float calibration_factor = 1.0; // Default calibration factor

// Function prototypes
int initialize_gpio();
int read_hx711();
float calibrate_hx711();
float calculate_weight(int raw_value);
void control_solenoid(int state);
void log_event(float weight);
void signal_handler(int signal);
int load_calibration_factor();
int save_calibration_factor(float factor);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read raw data from HX711
int read_hx711() {
    int32_t value = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for data line to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1); // 1 us delay
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to calibrate HX711
float calibrate_hx711() {
    int raw_value;
    float known_weight;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%f", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a number.\n");
        return -1.0; // Indicate error
    }

    printf("Reading raw value...");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Calibration failed due to HX711 timeout.\n");
        return -1.0; // Indicate error
    }
    printf("Raw value: %d\n", raw_value);

    calibration_factor = (float)raw_value / known_weight;

    printf("Calibration factor: %f\n", calibration_factor);

    if (save_calibration_factor(calibration_factor) != 0) {
        fprintf(stderr, "Failed to save calibration factor.\n");
    }

    return calibration_factor;
}

// Function to load calibration factor from file
int load_calibration_factor() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found. Calibrating...\n");
        return 1; // Indicate that calibration is needed
    }

    if (fscanf(fp, "%f", &calibration_factor) != 1) {
        fprintf(stderr, "Invalid calibration data in file. Calibrating...\n");
        fclose(fp);
        return 1; // Indicate that calibration is needed
    }

    fclose(fp);
    printf("Calibration factor loaded: %f\n", calibration_factor);
    return 0; // Indicate that calibration is up-to-date
}

// Function to save calibration factor to file
int save_calibration_factor(float factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return 1;
    }

    if (fprintf(fp, "%f", factor) < 0) {
        fprintf(stderr, "Error writing to calibration file\n");
        fclose(fp);
        return 1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate weight from raw value
float calculate_weight(int raw_value) {
    return (float)raw_value / calibration_factor;
}

// Function to control the solenoid
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    printf("Solenoid set to %d\n", state);
}

// Function to log events to a file
void log_event(float weight) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Load calibration factor
    if (load_calibration_factor() != 0) {
        calibrate_hx711();
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            float weight = calculate_weight(raw_value);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded!\n");
                control_solenoid(1); // Lock solenoid
                log_event(weight);
                gpioDelay(SOLENOID_DURATION * 1000); // Wait for solenoid duration
                control_solenoid(0); // Unlock solenoid
            }
        } else {
            fprintf(stderr, "Error reading HX711 data. Retrying...\n");
        }

        gpioDelay(100); // Delay between readings
    }

    return 0;
}

