        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR sensor pin as input
    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Ensure buzzer is off initially
    gpioWrite(BUZZER_PIN, 0);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate the buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    return 0;
}

// Log motion detection event
int log_motion() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    fprintf(log_file, "%s: Motion detected\n", timestamp);
    fclose(log_file);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected == 1) {
            printf("Motion detected!\n");
            log_motion();
            activate_buzzer(2000); // Activate buzzer for 2 seconds
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    return 0;
}

