#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define DEFAULT_DURATION 60

volatile sig_atomic_t program_running = 1;

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1; // Empty file or read error
    }

    fclose(fp);

    // Parse the line
    char *key = strstr(line, "duration=");
    if (key == NULL) {
        fprintf(stderr, "Error: Invalid configuration file format\n");
        return -1;
    }

    char *value = key + strlen("duration=");
    *duration = atoi(value);

    // Validate the duration
    if (*duration < 1 || *duration > 3600) {
        fprintf(stderr, "Error: Duration out of range (1-3600 seconds)\n");
        return -1;
    }

    return 0;
}

// Function to control the valve
void control_valve(int gpio_pin, int duration) {
    gpioWrite(gpio_pin, 1); // Turn valve ON (active-low)
    printf("Valve ON for %d seconds\n", duration);
    gpioDelay(duration * 1000000); // Sleep for the specified duration (microseconds)
    gpioWrite(gpio_pin, 0); // Turn valve OFF (active-low)
    printf("Valve OFF\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    int duration;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure valve is initially OFF

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read the watering duration from the configuration file
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        duration = DEFAULT_DURATION; // Use default duration if reading fails
        fprintf(stderr, "Using default duration: %d seconds\n", duration);
    }

    // Control the valve
    control_valve(GPIO_PIN, duration);

    // Cleanup and exit
    gpioWrite(GPIO_PIN, 0); // Ensure valve is OFF before exiting
    gpioTerminate();
    printf("Program terminated\n");
    return 0;
}

