#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PWM_PIN 22
#define LEFT_MOTOR_DIR_PIN 23
#define RIGHT_MOTOR_PWM_PIN 24
#define RIGHT_MOTOR_DIR_PIN 25

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

// Define base speed
#define BASE_SPEED 150

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void set_motor_speed(int motor_pin, int speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    gpioPWM(motor_pin, speed);
}

// Function to stop both motors
void stop_motors() {
    set_motor_speed(LEFT_MOTOR_PWM_PIN, 0);
    set_motor_speed(RIGHT_MOTOR_PWM_PIN, 0);
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_PWM_PIN, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(LEFT_MOTOR_PWM_PIN, PWM_RANGE);
    gpioSetPWMrange(RIGHT_MOTOR_PWM_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Determine motor speeds based on sensor readings
        int left_speed, right_speed;

        if (middle_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        // Set motor speeds
        set_motor_speed(LEFT_MOTOR_PWM_PIN, left_speed);
        set_motor_speed(RIGHT_MOTOR_PWM_PIN, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

