#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_THRESHOLD 150.0
#define RELAY_GPIO 23
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_MS 180

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int relay_gpio;
    float lux_threshold;
    char *log_file_name;
    int measurement_delay_ms;
} Config;

Config config = {
    I2C_BUS,
    BH1750_ADDR,
    RELAY_GPIO,
    LUX_THRESHOLD,
    LOG_FILE,
    MEASUREMENT_DELAY_MS
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(config.relay_gpio, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    float lux;
    int relay_state = 0; // 0 = off, 1 = on
    while (!terminate) {
        lux = read_lux();

        if (lux < 0) {
            fprintf(stderr, "Error reading lux value\n");
        } else {
            if (lux < config.lux_threshold && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
            } else if (lux >= config.lux_threshold && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
            }

            log_data(lux, relay_state);
        }

        gpioDelay(config.measurement_delay_ms * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, config.bh1750_address, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Failed to configure BH1750\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750
float read_lux() {
    int raw_value;
    float lux;

    raw_value = i2cReadWordData(i2c_handle, 0x00, config.bh1750_address);
    if (raw_value < 0) {
        fprintf(stderr, "Failed to read data from BH1750\n");
        return -1.0;
    }

    // BH1750 returns big-endian, so swap bytes
    raw_value = ((raw_value & 0xFF00) >> 8) | ((raw_value & 0x00FF) << 8);

    lux = (float)raw_value / 1.2;
    return lux;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(config.relay_gpio, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.relay_gpio, 0); // Turn off relay
    gpioTerminate();
}

