// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths for servo positions
#define LOCK_POSITION 1000  // 0 degrees
#define UNLOCK_POSITION 2000 // 180 degrees

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the servo pulse width
void set_servo_position(int gpio, int pulse_width) {
    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo pulse width to %d\n", pulse_width);
    }
}

// Function to read the lock button state
int read_lock_button(int gpio) {
    return gpioRead(gpio);
}

// Function to read the unlock button state
int read_unlock_button(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce a button press
int debounce_button(int gpio) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    return gpioRead(gpio);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read lock button state
        int lock_button_state = read_lock_button(LOCK_BUTTON_PIN);

        // Read unlock button state
        int unlock_button_state = read_unlock_button(UNLOCK_BUTTON_PIN);

        // Debounce lock button
        if (lock_button_state == 0) {
            if (debounce_button(LOCK_BUTTON_PIN) == 0) {
                set_servo_position(SERVO_PIN, LOCK_POSITION);
                printf("Lock button pressed, setting servo to lock position (%d us)\n", LOCK_POSITION);
            }
        }

        // Debounce unlock button
        if (unlock_button_state == 0) {
            if (debounce_button(UNLOCK_BUTTON_PIN) == 0) {
                set_servo_position(SERVO_PIN, UNLOCK_POSITION);
                printf("Unlock button pressed, setting servo to unlock position (%d us)\n", UNLOCK_POSITION);
            }
        }

        gpioDelay(50000); // Delay to prevent busy-waiting (50ms)
    }

    // Clean up and exit
    set_servo_position(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

