// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define motor pulse durations (in milliseconds)
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;

    // Stop the motors
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate motor 1
        if (gpioWrite(MOTOR1_GPIO, 1) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", MOTOR1_GPIO);
            program_running = 0; // Stop the loop on error
            break;
        }
        gpioDelay(MOTOR1_DURATION * 1000); // Delay for motor 1 duration (in microseconds)

        // Deactivate motor 1
        if (gpioWrite(MOTOR1_GPIO, 0) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", MOTOR1_GPIO);
            program_running = 0; // Stop the loop on error
            break;
        }

        // Activate motor 2
        if (gpioWrite(MOTOR2_GPIO, 1) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", MOTOR2_GPIO);
            program_running = 0; // Stop the loop on error
            break;
        }
        gpioDelay(MOTOR2_DURATION * 1000); // Delay for motor 2 duration (in microseconds)

        // Deactivate motor 2
        if (gpioWrite(MOTOR2_GPIO, 0) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", MOTOR2_GPIO);
            program_running = 0; // Stop the loop on error
            break;
        }
    }

    // Cleanup (in case the loop exited due to an error)
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
    gpioTerminate();

    return 0;
}

