#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <zmq.h>
#include <pigpio.h>

// Constants
#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_ADDRESS "tcp://*:5555"
#define SOUND_TOPIC "SOUND_ALERTS"
#define ALARM_TOPIC "ALARM_EVENTS"
#define DEBOUNCE_DELAY_MS 50
#define ALARM_DURATION_MS 1000

// Global variables
static volatile int running = 1;
static int sound_sensor_fd = -1;
static int alarm_led_fd = -1;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;

// Function prototypes
void signal_handler(int signal);
int setup_gpio(int gpio, int mode);
int read_gpio(int gpio);
int write_gpio(int gpio, int value);
int setup_zmq(void **context, void **publisher, void **subscriber, const char *address, const char *topic);
int publish_message(void *publisher, const char *topic, const char *message);
int subscribe_message(void *subscriber, const char *topic);
void cleanup(void);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Setup GPIO
int setup_gpio(int gpio, int mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %d\n", gpio, gpioSetMode(gpio, mode));
        return -1;
    }
    return 0;
}

// Read GPIO value
int read_gpio(int gpio) {
    return gpioRead(gpio);
}

// Write GPIO value
int write_gpio(int gpio, int value) {
    if (gpioWrite(gpio, value) != 0) {
        fprintf(stderr, "Error writing GPIO %d value: %d\n", gpio, gpioWrite(gpio, value));
        return -1;
    }
    return 0;
}

// Setup ZeroMQ
int setup_zmq(void **context, void **publisher, void **subscriber, const char *address, const char *topic) {
    *context = zmq_ctx_new();
    if (*context == NULL) {
        fprintf(stderr, "Error creating ZeroMQ context: %s\n", zmq_strerror(zmq_errno()));
        return -1;
    }

    *publisher = zmq_socket(*context, ZMQ_PUB);
    if (*publisher == NULL) {
        fprintf(stderr, "Error creating ZeroMQ publisher socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_ctx_destroy(*context);
        return -1;
    }

    *subscriber = zmq_socket(*context, ZMQ_SUB);
    if (*subscriber == NULL) {
        fprintf(stderr, "Error creating ZeroMQ subscriber socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    int rc = zmq_bind(*publisher, address);
    if (rc != 0) {
        fprintf(stderr, "Error binding ZeroMQ publisher socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    rc = zmq_connect(*subscriber, address);
    if (rc != 0) {
        fprintf(stderr, "Error connecting ZeroMQ subscriber socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    rc = zmq_setsockopt(*subscriber, ZMQ_SUBSCRIBE, topic, strlen(topic));
    if (rc != 0) {
        fprintf(stderr, "Error setting ZeroMQ subscriber option: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    return 0;
}

// Publish message
int publish_message(void *publisher, const char *topic, const char *message) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%s %s", topic, message);

    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(buffer));
    memcpy(zmq_msg_data(&zmq_message), buffer, strlen(buffer));

    int rc = zmq_msg_send(&zmq_message, publisher, 0);
    zmq_msg_close(&zmq_message);

    if (rc == -1) {
        fprintf(stderr, "Error sending message: %s\n", zmq_strerror(zmq_errno()));
        return -1;
    }

    return 0;
}

// Subscribe message
int subscribe_message(void *subscriber, const char *topic) {
    zmq_msg_t message;
    zmq_msg_init(&message);

    int rc = zmq_msg_recv(&message, subscriber, 0);
    if (rc == -1) {
        fprintf(stderr, "Error receiving message: %s\n", zmq_strerror(zmq_errno()));
        zmq_msg_close(&message);
        return -1;
    }

    char *message_data = (char *)zmq_msg_data(&message);
    int message_size = zmq_msg_size(&message);

    char *topic_ptr = strstr(message_data, topic);
    if (topic_ptr != NULL) {
        // Extract the message content after the topic
        char message_content[256];
        snprintf(message_content, sizeof(message_content), "%s", topic_ptr + strlen(topic) + 1); // +1 to skip the space after the topic

        // Process the message content (e.g., trigger the alarm)
        printf("Received alarm event: %s\n", message_content);
        write_gpio(ALARM_LED_GPIO, 1); // Turn on the LED
        gpioDelay(ALARM_DURATION_MS * 1000); // Wait for the alarm duration
        write_gpio(ALARM_LED_GPIO, 0); // Turn off the LED
    }

    zmq_msg_close(&message);
    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    if (alarm_led_fd != -1) {
        write_gpio(ALARM_LED_GPIO, 0); // Ensure LED is off
    }

    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }

    gpioTerminate();

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup GPIO pins
    if (setup_gpio(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        cleanup();
        return 1;
    }
    if (setup_gpio(ALARM_LED_GPIO, PI_OUTPUT) != 0) {
        cleanup();
        return 1;
    }

    // Setup ZeroMQ
    if (setup_zmq(&context, &publisher, &subscriber, ZMQ_ADDRESS, SOUND_TOPIC) != 0) {
        cleanup();
        return 1;
    }

    // Determine mode based on command-line argument
    if (argc > 1 && strcmp(argv[1], "alarm_node") == 0) {
        printf("Running in alarm_node mode...\n");

        // Main loop for alarm node
        while (running) {
            if (subscribe_message(subscriber, SOUND_TOPIC) != 0) {
                fprintf(stderr, "Error subscribing to messages, exiting...\n");
                break;
            }
            usleep(10000); // Check for messages every 10ms
        }
    } else {
        printf("Running in sound_sensor mode...\n");

        // Main loop for sound sensor
        while (running) {
            int sound_detected = read_gpio(SOUND_SENSOR_GPIO);
            if (sound_detected == 0) {
                printf("Sound detected!\n");
                if (publish_message(publisher, SOUND_TOPIC, "Sound Detected") != 0) {
                    fprintf(stderr, "Error publishing message, exiting...\n");
                    break;
                }
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            }
            usleep(10000); // Poll every 10ms
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

