#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define MAX_PULSES_SIZE (MAX_PULSES * sizeof(gpioPulse_t))

// NEC timing constants (in microseconds)
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_SPACE_1 1690
#define NEC_SPACE_0 560

// Global variables
static volatile int pulse_count = 0;
static gpioPulse_t pulses[MAX_PULSES];
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void alert_callback(int gpio, int level, uint32_t tick);
int decode_nec(gpioPulse_t *pulses, int pulse_count, unsigned char *address, unsigned char *command);
int validate_command(unsigned char address, unsigned char command);
int publish_mqtt(unsigned char address, unsigned char command);
void signal_handler(int signal);

// Alert callback function
void alert_callback(int gpio, int level, uint32_t tick) {
    if (pulse_count < MAX_PULSES) {
        pulses[pulse_count].gpio = gpio;
        pulses[pulse_count].level = level;
        pulses[pulse_count].tick = tick;
        pulse_count++;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow!");
        pulse_count = 0; // Reset to prevent further overflow
    }
}

// NEC decoding function
int decode_nec(gpioPulse_t *pulses, int pulse_count, unsigned char *address, unsigned char *command) {
    if (pulse_count < 34) {
        syslog(LOG_ERR, "Not enough pulses for NEC frame.");
        return -1;
    }

    int i;
    unsigned char data[4] = {0, 0, 0, 0};

    // Check header
    if (pulses[0].tick - pulses[1].tick < NEC_HEADER_MARK * 900 || pulses[0].tick - pulses[1].tick > NEC_HEADER_MARK * 1100) {
        syslog(LOG_ERR, "Invalid NEC header mark.");
        return -1;
    }
    if (pulses[1].tick - pulses[2].tick < NEC_HEADER_SPACE * 900 || pulses[1].tick - pulses[2].tick > NEC_HEADER_SPACE * 1100) {
        syslog(LOG_ERR, "Invalid NEC header space.");
        return -1;
    }

    // Decode data bits
    for (i = 0; i < 32; i++) {
        int index = 2 + (i * 2);
        if (pulses[index + 1].tick - pulses[index].tick > NEC_SPACE_1 * 800) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    *address = data[0];
    *command = data[1];

    // Validate checksum (optional)
    if ((data[2] + data[3]) & 0xFF != 0xFF) {
        syslog(LOG_WARNING, "NEC checksum failed.");
    }

    return 0;
}

// Command validation function
int validate_command(unsigned char address, unsigned char command) {
    // Implement your command validation logic here
    // For example, check if the command is within a valid range
    if (command < 0x00 || command > 0xFF) {
        syslog(LOG_WARNING, "Invalid command received.");
        return -1;
    }
    return 0;
}

// MQTT publishing function
int publish_mqtt(unsigned char address, unsigned char command) {
    char payload[50];
    int ret;

    snprintf(payload, sizeof(payload), "{\"address\": 0x%02X, \"command\": 0x%02X}", address, command);

    ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

int main() {
    int ret;
    unsigned char address, command;

    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO mode and alert function
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetAlertFunc(GPIO_PIN, alert_callback);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR decoder started");

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms

        if (pulse_count > 33) {
            if (decode_nec(pulses, pulse_count, &address, &command) == 0) {
                if (validate_command(address, command) == 0) {
                    if (publish_mqtt(address, command) != 0) {
                        syslog(LOG_ERR, "Failed to publish MQTT message.");
                    }
                }
            }
            pulse_count = 0; // Reset pulse count after decoding
        }
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

