    // Wait for measurement (180ms)
    usleep(180000); // 180ms

    // Read two bytes of data
    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return NAN;
    }

    // Convert the data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to format sensor data into a string
char* format_sensor_data(float lux_values[], int num_sensors) {
    char *buffer = malloc(256 * sizeof(char)); // Allocate memory for the string
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for sensor data string\n");
        return NULL;
    }
    buffer[0] = '\0'; // Initialize the string

    for (int i = 0; i < num_sensors; i++) {
        char sensor_str[20];
        snprintf(sensor_str, sizeof(sensor_str), "%d,%.2f", i + 1, lux_values[i]);
        strcat(buffer, sensor_str);
        if (i < num_sensors - 1) {
            strcat(buffer, ";");
        }
    }

    return buffer;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set TTL for multicast
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fds[num_sensors];
    float lux_values[num_sensors];

    // Initialize I2C devices
    for (int i = 0; i < num_sensors; i++) {
        i2c_fds[i] = init_i2c_device(sensor_addresses[i]);
        if (i2c_fds[i] < 0) {
            lux_values[i] = NAN; // Set to NaN if initialization fails
        }
    }

    // Main loop
    while (!terminate) {
        // Read lux values from each sensor
        for (int i = 0; i < num_sensors; i++) {
            if (i2c_fds[i] >= 0) {
                lux_values[i] = read_bh1750(i2c_fds[i]);
            } else {
                lux_values[i] = NAN; // Keep the previous value if initialization failed
            }
        }

        // Format sensor data
        char *sensor_data = format_sensor_data(lux_values, num_sensors);

        if (sensor_data != NULL) {
            // Send data via UDP multicast
            if (send_udp_multicast(sensor_data) != 0) {
                fprintf(stderr, "Error sending UDP multicast data\n");
            }

            free(sensor_data); // Free the allocated memory
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C file descriptors
    for (int i = 0; i < num_sensors; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }

    return 0;
}

