#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *raw_flow);
float convert_to_slpm(uint16_t raw_flow);
int log_data(float flow_rate);
void signal_handler(int signal);
