    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fclose(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    uint16_t raw_flow;
    float flow_rate;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_flow) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_flow);

            // Log data
            if (log_data(flow_rate) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000); // Wait 1 second (1000000 microseconds)
    }

    cleanup();

    return 0;
}

