#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_ID 0x70
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0x81
#define AS7341_F1DATAH 0x94
#define AS7341_F1DATAL 0x95
#define AS7341_F2DATAH 0x96
#define AS7341_F2DATAL 0x97
#define AS7341_F3DATAH 0x98
#define AS7341_F3DATAL 0x99
#define AS7341_F4DATAH 0x9A
#define AS7341_F4DATAL 0x9B
#define AS7341_F5DATAH 0x9C
#define AS7341_F5DATAL 0x9D
#define AS7341_F6DATAH 0x9E
#define AS7341_F6DATAL 0x9F
#define AS7341_F7DATAH 0xA0
#define AS7341_F7DATAL 0xA1
#define AS7341_F8DATAH 0xA2
#define AS7341_F8DATAL 0xA3
#define AS7341_CLEARDATAH 0xA4
#define AS7341_CLEARDATAL 0xA5
#define AS7341_NIRDATAH 0xA6
#define AS7341_NIRDATAL 0xA7

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_spectral_data(uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4, uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8, uint16_t *clear, uint16_t *nir);
float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8, uint16_t clear, uint16_t nir);
int log_data(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8, uint16_t clear, uint16_t nir, float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the AS7341 sensor
int initialize_sensor() {
    int status;

    // Check sensor ID
    status = i2cWriteByteData(i2c_handle, AS7341_ID, 0x00); // Dummy write to trigger read
    if (status != 0) {
        fprintf(stderr, "Error writing to ID register: %d\n", status);
        return -1;
    }
    int id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading ID register: %d\n", id);
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }
    printf("Sensor ID: 0x%02X\n", id);

    // Enable the sensor
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); // PON = 1, AEN = 1
    if (status != 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }
    printf("Sensor enabled\n");

    // Configure SMUX (e.g., 100ms integration time)
    status = i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x00); // SMUX = 000 (100ms)
    if (status != 0) {
        fprintf(stderr, "Error writing to CFG6 register: %d\n", status);
        return -1;
    }
    printf("SMUX configured\n");

    // Enable spectral measurement
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); // SP_EN = 1
    if (status != 0) {
        fprintf(stderr, "Error writing to ENABLE register to enable spectral measurement: %d\n", status);
        return -1;
    }
    printf("Spectral measurement enabled\n");

    return 0;
}

// Reads spectral data from the sensor
int read_spectral_data(uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4, uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8, uint16_t *clear, uint16_t *nir) {
    int status;

    status = i2cWriteByteData(i2c_handle, AS7341_F1DATAH, 0x00); // Dummy write to trigger read
    if (status != 0) {
        fprintf(stderr, "Error writing to F1DATAH register: %d\n", status);
        return -1;
    }

    *f1 = i2cReadWordData(i2c_handle, AS7341_F1DATAH);
    *f2 = i2cReadWordData(i2c_handle, AS7341_F2DATAH);
    *f3 = i2cReadWordData(i2c_handle, AS7341_F3DATAH);
    *f4 = i2cReadWordData(i2c_handle, AS7341_F4DATAH);
    *f5 = i2cReadWordData(i2c_handle, AS7341_F5DATAH);
    *f6 = i2cReadWordData(i2c_handle, AS7341_F6DATAH);
    *f7 = i2cReadWordData(i2c_handle, AS7341_F7DATAH);
    *f8 = i2cReadWordData(i2c_handle, AS7341_F8DATAH);
    *clear = i2cReadWordData(i2c_handle, AS7341_CLEARDATAH);
    *nir = i2cReadWordData(i2c_handle, AS7341_NIRDATAH);

    return 0;
}

// Calculates a simplified lux approximation
float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8, uint16_t clear, uint16_t nir) {
    // Simple lux approximation (replace with a more accurate model if needed)
    float lux = (float)(clear + nir) * 0.01; // Example scaling
    return lux;
}

// Logs the data to a CSV file
int log_data(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8, uint16_t clear, uint16_t nir, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
    float lux;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read spectral data
        status = read_spectral_data(&f1, &f2, &f3, &f4, &f5, &f6, &f7, &f8, &clear, &nir);
        if (status != 0) {
            fprintf(stderr, "Error reading spectral data\n");
            break; // Exit loop on error
        }

        // Calculate lux
        lux = calculate_lux(f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);

        // Log data
        status = log_data(f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);
        if (status != 0) {
            fprintf(stderr, "Error logging data\n");
            break; // Exit loop on error
        }

        printf("F1: %u, F2: %u, F3: %u, F4: %u, F5: %u, F6: %u, F7: %u, F8: %u, Clear: %u, NIR: %u, Lux: %.2f\n",
               f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

