    int id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading ID register: %d\n", id);
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }
    printf("Sensor ID: 0x%02X\n", id);

    // Enable the sensor
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); // PON = 1, AEN = 1
    if (status != 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }
    printf("Sensor enabled\n");

    // Configure SMUX (e.g., 100ms integration time)
    status = i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x00); // SMUX = 000 (100ms)
    if (status != 0) {
        fprintf(stderr, "Error writing to CFG6 register: %d\n", status);
        return -1;
    }
    printf("SMUX configured\n");

    // Enable spectral measurement
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); // SP_EN = 1
    if (status != 0) {
        fprintf(stderr, "Error writing to ENABLE register to enable spectral measurement: %d\n", status);
        return -1;
    }
    printf("Spectral measurement enabled\n");

    return 0;
}

// Reads spectral data from the sensor
int read_spectral_data(uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4, uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8, uint16_t *clear, uint16_t *nir) {
    int status;

    status = i2cWriteByteData(i2c_handle, AS7341_F1DATAH, 0x00); // Dummy write to trigger read
    if (status != 0) {
        fprintf(stderr, "Error writing to F1DATAH register: %d\n", status);
        return -1;
    }

    *f1 = i2cReadWordData(i2c_handle, AS7341_F1DATAH);
