    *f3 = i2cReadWordData(i2c_handle, AS7341_F3DATAH);
    *f4 = i2cReadWordData(i2c_handle, AS7341_F4DATAH);
    *f5 = i2cReadWordData(i2c_handle, AS7341_F5DATAH);
