    *f7 = i2cReadWordData(i2c_handle, AS7341_F7DATAH);
    *f8 = i2cReadWordData(i2c_handle, AS7341_F8DATAH);
    *clear = i2cReadWordData(i2c_handle, AS7341_CLEARDATAH);
    *nir = i2cReadWordData(i2c_handle, AS7341_NIRDATAH);

