float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8, uint16_t clear, uint16_t nir) {
    // Simple lux approximation (replace with a more accurate model if needed)
    float lux = (float)(clear + nir) * 0.01; // Example scaling
    return lux;
}

// Logs the data to a CSV file
int log_data(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4, uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8, uint16_t clear, uint16_t nir, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

