            break; // Exit loop on error
        }

        // Calculate lux
        lux = calculate_lux(f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);

        // Log data
        status = log_data(f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);
