               f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

