#include <pigpio.h>

// Default I2C address
#define DEFAULT_I2C_ADDRESS 0x1D

// Default sampling interval (seconds)
#define DEFAULT_SAMPLING_INTERVAL 1

// Default output filename
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"

// D7S register addresses (example, adjust based on datasheet)
#define D7S_REG_X_LSB 0x28
#define D7S_REG_X_MSB 0x29
#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Y_MSB 0x2B
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_Z_MSB 0x2D

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
int i2c_address = DEFAULT_I2C_ADDRESS;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *output_filename = DEFAULT_OUTPUT_FILENAME;
volatile sig_atomic_t terminate = 0;

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} AccelerationData;

// Function prototypes
int initialize_i2c(int address);
AccelerationData read_acceleration_data(int handle);
void log_data(FILE *fp, AccelerationData data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read acceleration data from the D7S sensor
AccelerationData read_acceleration_data(int handle) {
    AccelerationData data;
    char buf[6];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(handle, D7S_REG_X_LSB, buf, 6);
        if (bytes_read == 6) {
            // Combine LSB and MSB for each axis
            int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
            int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
            int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

            // Convert to g (adjust scale factor as needed)
            data.x = (float)x / 1000.0; // Example scale factor
            data.y = (float)y / 1000.0;
            data.z = (float)z / 1000.0;
            return data;
        } else {
            log_error("I2C read failed, retrying...");
            gpioDelay(10); // 10ms backoff
            retries--;
        }
    }

    // If all retries failed, log a critical error
    log_error("Critical I2C read error, exiting.");
    data.x = 0.0;
    data.y = 0.0;
    data.z = 0.0;
    return data;
}

// Log data to CSV file
void log_data(FILE *fp, AccelerationData data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written immediately
}

// Log errors to error log file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
    fprintf(stderr, "%s: %s\n", timestamp, message); // Also print to stderr
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        log_error("I2C initialization failed.");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(output_filename, "a");
    if (data_file == NULL) {
        log_error("Error opening data file!");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition... Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        AccelerationData data = read_acceleration_data(i2c_handle);
        log_data(data_file, data);
        sleep(sampling_interval);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

