#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MAX_RETRIES 3

int i2c_handle;
int udp_socket;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the BH1750 sensor
int init_bh1750() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read raw data from the BH1750 sensor
int read_bh1750(unsigned short *raw_value) {
    char config_cmd = 0x10; // Continuous high resolution mode
    char buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, &config_cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(200); // Wait for measurement (at least 180ms)

        if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert big-endian to host byte order
        *raw_value = (buffer[0] << 8) | buffer[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read from I2C device after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send lux value via UDP multicast
int send_lux_value(float lux_value) {
    struct sockaddr_in addr;
    char lux_str[20];

    snprintf(lux_str, sizeof(lux_str), "%.2f", lux_value);

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set TTL for multicast packets
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt failed");
        close(udp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned short raw_value;
    float lux_value;

    while (1) {
        // Read raw value from BH1750
        if (read_bh1750(&raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Send lux value via UDP multicast
            if (send_lux_value(lux_value) != 0) {
                fprintf(stderr, "Failed to send lux value.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    close(udp_socket);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

