const unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    time_t timestamp;
    int object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Function prototypes
int initialize_uart();
int read_uart_data(unsigned char *buffer, int max_size);
int validate_magic_word(const unsigned char *buffer);
int parse_tlv_payload(const unsigned char *buffer, int frame_size, RadarData *data);
int write_to_csv(const RadarData *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

// Read data from UART
int read_uart_data(unsigned char *buffer, int max_size) {
    int bytes_read = serRead(uart_handle, buffer, max_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Validate the magic word
int validate_magic_word(const unsigned char *buffer) {
    for (int i = 0; i < MAGIC_WORD_LENGTH; i++) {
        if (buffer[i] != magic_word[i]) {
            return 0; // Invalid magic word
        }
    }
    return 1; // Valid magic word
}

// Parse TLV payload (Placeholder implementation)
int parse_tlv_payload(const unsigned char *buffer, int frame_size, RadarData *data) {
    // This is a placeholder.  A real implementation would parse the TLV
    // structure according to the AWR1642 data format specification.
    // For this example, we'll just extract some dummy data.

    // Example: Assuming the range and velocity are at specific offsets
    // in the buffer (replace with actual offsets from the spec)
    if (frame_size >= 16) { // Ensure enough data for range and velocity
        data->range_m = *((float *)(buffer + 8)); // Example: Range at offset 8
        data->velocity_mps = *((float *)(buffer + 12)); // Example: Velocity at offset 12
        data->object_index = 1; // Example object index
        data->timestamp = time(NULL);
        return 1; // Success
    } else {
        fprintf(stderr, "Error: Insufficient data in frame for range/velocity\n");
        return 0; // Failure
    }
}

