    if (csv_file == NULL) {
        fprintf(stderr, "Error: CSV file not opened\n");
        return -1;
    }

    fprintf(csv_file, "%ld,%d,%.2f,%.2f\n", data->timestamp, data->object_index, data->range_m, data->velocity_mps);
    fflush(csv_file); // Flush to ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
        printf("UART closed\n");
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        printf("CSV file closed\n");
    }
