        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    unsigned char buffer[MAX_FRAME_SIZE];
    int bytes_read;
    RadarData radar_data;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        bytes_read = read_uart_data(buffer, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            if (validate_magic_word(buffer)) {
                if (parse_tlv_payload(buffer, bytes_read, &radar_data)) {
                    if (write_to_csv(&radar_data) != 0) {
                        fprintf(stderr, "Error writing to CSV\n");
                    }
                } else {
                    fprintf(stderr, "Error parsing TLV payload\n");
                }
            } else {
                fprintf(stderr, "Invalid magic word\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

