#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 0
#define MAX_LINE_LENGTH 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int configure_uart(int fd) {
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int read_uart_data(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select failed");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        bytes_read = read(fd, buffer, max_len);
        if (bytes_read == -1) {
            perror("read failed");
            return -1;
        }
        return bytes_read;
    }
}

int parse_radar_data(const char *line) {
    char *timestamp_str, *range_str;
    long timestamp_sec;
    double range_meters;

    if (sscanf(line, "%ld,%lf", &timestamp_sec, &range_meters) == 2) {
        if (range_meters >= 0.0 && range_meters <= 10.0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Range out of bounds: %.2f meters\n", range_meters);
            return -1; // Range out of bounds
        }
    } else {
        fprintf(stderr, "Error: Invalid data format: %s\n", line);
        return -1; // Invalid format
    }
}

int format_timestamp(long timestamp_sec, char *output_buffer, size_t buffer_size) {
    time_t timer = (time_t)timestamp_sec;
    struct tm* tm_info = localtime(&timer);

    if (strftime(output_buffer, buffer_size, "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }
    return 0;
}

int main() {
    char line_buffer[MAX_LINE_LENGTH];
    int bytes_read;
    char timestamp_str[32];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open failed");
        return EXIT_FAILURE;
    }

    // Configure UART
    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART configured successfully. Reading data...\n");

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, line_buffer, MAX_LINE_LENGTH - 1);

        if (bytes_read > 0) {
            line_buffer[bytes_read] = '\0'; // Null-terminate the buffer

            if (strchr(line_buffer, '\n') != NULL) {
                // Process the line
                if (parse_radar_data(line_buffer) == 0) {
                    long timestamp_sec;
                    double range_meters;

                    if (sscanf(line_buffer, "%ld,%lf", &timestamp_sec, &range_meters) == 2) {
                        if (format_timestamp(timestamp_sec, timestamp_str, sizeof(timestamp_str)) == 0) {
                            printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range_meters);
                        } else {
                            fprintf(stderr, "Error formatting timestamp.\n");
                        }
                    } else {
                        fprintf(stderr, "Error parsing data.\n");
                    }
                }
            } else {
                // Line not complete, accumulate in buffer
                strncat(line_buffer, line_buffer, MAX_LINE_LENGTH - strlen(line_buffer) - 1);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART.\n");
            break;
        }
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

