    signal(SIGTERM, signal_handler);

    // Open UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open failed");
        return EXIT_FAILURE;
    }

    // Configure UART
    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART configured successfully. Reading data...\n");

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, line_buffer, MAX_LINE_LENGTH - 1);

        if (bytes_read > 0) {
            line_buffer[bytes_read] = '\0'; // Null-terminate the buffer

            if (strchr(line_buffer, '\n') != NULL) {
                // Process the line
                if (parse_radar_data(line_buffer) == 0) {
                    long timestamp_sec;
                    double range_meters;

                    if (sscanf(line_buffer, "%ld,%lf", &timestamp_sec, &range_meters) == 2) {
                        if (format_timestamp(timestamp_sec, timestamp_str, sizeof(timestamp_str)) == 0) {
                            printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range_meters);
                        } else {
                            fprintf(stderr, "Error formatting timestamp.\n");
                        }
                    } else {
                        fprintf(stderr, "Error parsing data.\n");
                    }
                }
            } else {
                // Line not complete, accumulate in buffer
                strncat(line_buffer, line_buffer, MAX_LINE_LENGTH - strlen(line_buffer) - 1);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART.\n");
            break;
        }
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

