typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to read sensor data from a given GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data to the console with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

