void emergency_stop() {
    if (uart_fd != NULL) {
        if (fprintf(uart_fd, "EMERGENCY STOP!\n") < 0) {
            fprintf(stderr, "Error writing to UART device.\n");
        }
        fflush(uart_fd); // Ensure data is sent immediately
    } else {
        fprintf(stderr, "UART device not initialized.\n");
    }
}

// Signal handler function
