    printf("Caught signal %d, cleaning up...\n", signal);

    // Close UART device if it's open
    if (uart_fd != NULL) {
        fclose(uart_fd);
        uart_fd = NULL;
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open UART device
    uart_fd = fopen(UART_DEVICE, "w");
    if (uart_fd == NULL) {
        fprintf(stderr, "Error opening UART device %s\n", UART_DEVICE);
        gpioTerminate();
        return 1;
    }

    // Set baud rate
    if (setvbuf(uart_fd, NULL, _IONLY, 0) != 0) {
        fprintf(stderr, "Error setting UART buffer.\n");
        fclose(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left, middle, right);

        // Check for emergency stop condition
        if (left == 0 && middle == 0 && right == 0) {
            emergency_stop();
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

